export enum ShippingStatus {
  PENDING = 'Pending',
  SHIPPED = 'Shipped',
  RTS = 'RTS',
  CANCELLED = 'Cancelled'
}

export enum PaymentMethod {
  GCASH = 'GCash',
  TIKTOK = 'TikTok Checkout',
  GOTYME = 'GoTyme',
  SEABANK = 'SeaBank',
