import React, { useMemo } from 'react';
import { db } from '../services/dbService';
import { Order, PaymentStatus, ShippingStatus } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';

const Dashboard: React.FC = () => {
  const orders = db.getOrders();
  const products = db.getProducts();

  const stats = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const todayOrders = orders.filter(o => new Date(o.createdAt).toISOString().split('T')[0] === today);
    const totalSalesToday = todayOrders.reduce((sum, o) => sum + o.totalPrice, 0);
    const pendingPayments = orders.filter(o => o.paymentStatus !== PaymentStatus.PAID).length;
    const toShip = orders.filter(o => o.shippingStatus === ShippingStatus.PENDING).length;

    return {
      salesToday: totalSalesToday,
      ordersToday: todayOrders.length,
      pendingPayments,
      toShip
    };
  }, [orders]);

  const chartData = useMemo(() => {
    // Group last 7 days sales
    const data: Record<string, number> = {};
    for (let i = 6; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      const key = d.toLocaleDateString('en-US', { weekday: 'short' });
      data[key] = 0;
    }

    orders.forEach(o => {
      const date = new Date(o.createdAt);
      const key = date.toLocaleDateString('en-US', { weekday: 'short' });
      if (data[key] !== undefined) data[key] += o.totalPrice;
    });

    return Object.entries(data).map(([name, sales]) => ({ name, sales }));
  }, [orders]);

  return (
    <div className="space-y-6 pb-8">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Hello, Paw-ss! 🐾</h1>
          <p className="text-gray-500">Here's how your shop is doing today.</p>
        </div>
      </header>

      {/* Metric Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard label="Today's Sales" value={`₱${stats.salesToday.toLocaleString()}`} color="bg-pawPink" textColor="text-red-500" />
        <StatCard label="Orders Today" value={stats.ordersToday} color="bg-pawMint" textColor="text-green-600" />
        <StatCard label="Pending Payments" value={stats.pendingPayments} color="bg-pawPeach" textColor="text-orange-600" />
        <StatCard label="To Ship" value={stats.toShip} color="bg-pawSoftBlue" textColor="text-blue-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Sales Chart */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-pawPink">
          <h3 className="text-lg font-bold mb-4 text-gray-700">Weekly Sales</h3>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <XAxis dataKey="name" axisLine={false} tickLine={false} />
                <Tooltip 
                  contentStyle={{ borderRadius: '15px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                  cursor={{ fill: '#FFFDD0', opacity: 0.4 }}
                />
                <Bar dataKey="sales" radius={[10, 10, 0, 0]}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index % 2 === 0 ? '#FFD1DC' : '#B2F2BB'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Low Stock Alert */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-pawPink">
          <h3 className="text-lg font-bold mb-4 text-gray-700">Low Stock Alerts</h3>
          <div className="space-y-4">
            {products.filter(p => p.stock < 5).slice(0, 5).map(p => (
              <div key={p.id} className="flex items-center justify-between p-3 bg-pawCream rounded-2xl">
                <div className="flex flex-col">
                  <span className="font-semibold text-gray-800">{p.name}</span>
                  <span className="text-xs text-gray-500">{p.brand}</span>
                </div>
                <span className="px-3 py-1 bg-red-100 text-red-600 rounded-full text-xs font-bold">
                  {p.stock} left
                </span>
              </div>
            ))}
            {products.filter(p => p.stock < 5).length === 0 && (
              <div className="text-center py-10 text-gray-400">
                <p>Everything is stocked up! 🐶</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ label, value, color, textColor }: any) => (
  <div className={`${color} p-5 rounded-3xl shadow-sm transition-transform active:scale-95`}>
    <p className="text-xs font-bold text-gray-600 uppercase tracking-wider mb-1">{label}</p>
    <p className={`text-2xl font-bold ${textColor}`}>{value}</p>
  </div>
);

export default Dashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { db } from '../services/dbService';
import { Product, Customer, Order, PaymentStatus, ShippingStatus } from '../types';
import { SearchIcon, PlusIcon, PawIcon } from '../components/Icons';

const LiveSell: React.FC = () => {
  const [session, setSession] = useState(db.getSessions().find(s => s.isOpen) || null);
  const [username, setUsername] = useState('');
  const [searchProduct, setSearchProduct] = useState('');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [quantity, setQuantity] = useState(1);
  const [isFreebie, setIsFreebie] = useState(false);
  const [recentOrders, setRecentOrders] = useState<Order[]>([]);

  const products = db.getProducts();
  const customers = db.getCustomers();

  const filteredProducts = useMemo(() => {
    if (!searchProduct) return [];
    return products.filter(p => 
      p.name.toLowerCase().includes(searchProduct.toLowerCase()) ||
      p.brand.toLowerCase().includes(searchProduct.toLowerCase())
    ).slice(0, 5);
  }, [searchProduct, products]);

  const filteredCustomers = useMemo(() => {
    if (!username) return [];
    return customers.filter(c => 
      c.username.toLowerCase().includes(username.toLowerCase())
    ).slice(0, 3);
  }, [username, customers]);

  useEffect(() => {
    if (session) {
      const orders = db.getOrders().filter(o => o.sessionId === session.id);
      setRecentOrders(orders.sort((a, b) => b.createdAt - a.createdAt).slice(0, 10));
    }
  }, [session]);

  const handleStartSession = () => {
    const name = prompt('Enter Live Session Name (e.g., Sunday PM Live):');
    if (name) {
      const newSession = db.createSession(name);
      setSession(newSession);
    }
  };

  const handleAddOrder = () => {
    if (!session || !username || !selectedProduct) {
      alert('Please select a customer and product!');
      return;
    }

    const customer = db.getOrCreateCustomer(username);
    const totalPrice = isFreebie ? 0 : selectedProduct.sellingPrice * quantity;

    const newOrder: Order = {
      id: `o_${Date.now()}`,
      sessionId: session.id,
      customerId: customer.id,
      customerUsername: username,
      productId: selectedProduct.id,
      productName: selectedProduct.name,
      quantity,
      totalPrice,
      isFreebie,
      paymentStatus: isFreebie ? PaymentStatus.PAID : PaymentStatus.UNPAID,
      shippingStatus: ShippingStatus.PENDING,
      amountPaid: 0,
      createdAt: Date.now(),
    };

    db.addOrder(newOrder);
    setRecentOrders([newOrder, ...recentOrders]);

    // Quick Reset
    setSearchProduct('');
    setSelectedProduct(null);
    setQuantity(1);
    setIsFreebie(false);

    // Play sound or haptic would go here in real native app
  };

  if (!session) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[70vh] text-center px-4">
        <PawIcon className="w-20 h-20 text-pawPinkDark mb-4 opacity-50" />
        <h2 className="text-2xl font-bold text-gray-800 mb-2">Ready to go Live?</h2>
        <p className="text-gray-500 mb-6">Create a session to start encoding orders in real-time.</p>
        <button 
          onClick={handleStartSession}
          className="bg-pawPinkDark text-white px-8 py-4 rounded-3xl font-bold shadow-lg active:scale-95 transition-transform"
        >
          Start New Live Session
        </button>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 pb-20">
      {/* Encoding Panel */}
      <div className="lg:col-span-7 space-y-4">
        <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-pawPink">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-xl font-bold text-gray-800 flex items-center gap-2">
              <span className="w-3 h-3 bg-red-500 rounded-full animate-pulse"></span>
              Live: {session.name}
            </h3>
            <button 
              className="text-xs font-bold text-pawPinkDark hover:underline"
              onClick={() => {
                if (confirm('End this session?')) {
                   // Logic to close session
                }
              }}
            >
              End Session
            </button>
          </div>

          <div className="space-y-4">
            {/* Username Selection */}
            <div className="relative">
              <label className="text-xs font-bold text-gray-400 uppercase ml-2">TikTok Username</label>
              <input 
                type="text"
                placeholder="@username"
