            <button 
              key={f} 
              onClick={() => setFilter(f)}
              className={`px-4 py-2 rounded-xl text-sm font-bold transition-all ${
                filter === f ? 'bg-pawPinkDark text-white shadow-sm' : 'text-gray-500 hover:text-gray-700'
              }`}
