import React, { useState } from 'react';
import { db } from '../services/dbService';
import { Bale } from '../types';
import { PlusIcon, PawIcon } from '../components/Icons';

const Bales: React.FC = () => {
  const [bales, setBales] = useState(db.getBales());
  const products = db.getProducts();
  const orders = db.getOrders();

  const getBaleStats = (baleId: string) => {
    const baleProducts = products.filter(p => p.baleBatch === baleId);
    const baleOrders = orders.filter(o => {
        const prod = products.find(p => p.id === o.productId);
        return prod?.baleBatch === baleId;
    });
    const soldCount = baleOrders.reduce((sum, o) => sum + o.quantity, 0);
    const revenue = baleOrders.reduce((sum, o) => sum + o.totalPrice, 0);
    return { soldCount, revenue };
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-gray-800">Bale Management</h1>
        <button className="bg-pawSoftBlue text-blue-700 px-4 py-2 rounded-2xl font-bold flex items-center gap-2 text-sm shadow-sm active:scale-95 transition-transform">
          <PlusIcon className="w-4 h-4" /> Log New Bale
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {bales.map(bale => {
          const stats = getBaleStats(bale.id);
          const progress = Math.min(100, (stats.soldCount / bale.itemCount) * 100);

          return (
            <div key={bale.id} className="bg-white rounded-[2.5rem] p-6 border border-pawPink shadow-sm overflow-hidden relative">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <h3 className="text-xl font-bold text-gray-800">{bale.name}</h3>
                  <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">{bale.id} • {bale.status}</p>
                </div>
                <div className="text-right">
                  <p className="text-xs font-black text-pawPinkDark uppercase">Cost</p>
                  <p className="text-lg font-black text-gray-800">₱{bale.cost.toLocaleString()}</p>
                </div>
              </div>

              <div className="grid grid-cols-3 gap-2 mb-6">
                <div className="bg-pawCream p-3 rounded-2xl text-center">
                  <p className="text-[10px] font-black text-gray-400 uppercase">Items</p>
                  <p className="text-sm font-bold">{bale.itemCount}</p>
                </div>
                <div className="bg-pawMint p-3 rounded-2xl text-center">
                  <p className="text-[10px] font-black text-green-700 uppercase">Sold</p>
                  <p className="text-sm font-bold">{stats.soldCount}</p>
                </div>
                <div className="bg-pawSoftBlue p-3 rounded-2xl text-center">
                  <p className="text-[10px] font-black text-blue-700 uppercase">Revenue</p>
                  <p className="text-sm font-bold">₱{stats.revenue.toLocaleString()}</p>
                </div>
              </div>

              <div className="space-y-2">
                <div className="flex justify-between text-[10px] font-black text-gray-500 uppercase">
                  <span>Selling Progress</span>
                  <span>{progress.toFixed(0)}%</span>
                </div>
                <div className="w-full h-3 bg-pawCream rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-pawPinkDark transition-all duration-500" 
                    style={{ width: `${progress}%` }}
                  />
                </div>
              </div>

              <div className="mt-6 flex justify-between items-center pt-4 border-t border-pawCream">
                <div className="text-xs font-bold">
                  Profit: <span className={stats.revenue - bale.cost >= 0 ? 'text-green-500' : 'text-red-500'}>
                    ₱{(stats.revenue - bale.cost).toLocaleString()}
                  </span>
                </div>
                <button className="text-xs font-black text-pawPinkDark hover:underline">Manage Products</button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

