import React, { useState, useMemo } from 'react';
import { db } from '../services/dbService';
import { Transaction, PaymentMethod, Order } from '../types';
import { PlusIcon, PawIcon } from '../components/Icons';

const Accounting: React.FC = () => {
  const orders = db.getOrders();
  const transactions = db.getTransactions();
  const [showTxModal, setShowTxModal] = useState(false);

  const walletBalances = useMemo(() => {
    const balances: Record<string, number> = {
      'GCash': 0,
      'TikTok Checkout': 0,
      'GoTyme': 0,
      'SeaBank': 0,
      'BPI': 0,
      'Cash': 0
    };

    // Add paid orders
    orders.forEach(o => {
      if (o.paymentMethod && balances[o.paymentMethod] !== undefined) {
        balances[o.paymentMethod] += o.amountPaid;
      }
    });

    // Subtract/Add transactions
    transactions.forEach(t => {
      if (balances[t.wallet] !== undefined) {
        if (t.type === 'Expense' || t.type === 'Withdrawal') {
          balances[t.wallet] -= t.amount;
        } else if (t.type === 'Loan') {
          balances[t.wallet] += t.amount;
        }
      }
    });

    return balances;
  }, [orders, transactions]);

  // Fix: Explicitly type the reduce arguments as numbers to resolve 'unknown' type error.
  const totalCashOnHand = Object.values(walletBalances).reduce((a: number, b: number) => a + b, 0);

  const profitStats = useMemo(() => {
    const revenue = orders.reduce((sum, o) => sum + o.amountPaid, 0);
    const expenses = transactions.filter(t => t.type === 'Expense').reduce((sum, t) => sum + t.amount, 0);
    return { revenue, expenses, net: revenue - expenses };
  }, [orders, transactions]);

  const handleAddTx = (tx: Transaction) => {
    db.addTransaction(tx);
    setShowTxModal(false);
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-gray-800">Accounting</h1>
        <button 
          onClick={() => setShowTxModal(true)}
          className="bg-pawPeach text-orange-700 px-4 py-2 rounded-2xl font-bold flex items-center gap-2 text-sm shadow-sm active:scale-95 transition-transform"
        >
          <PlusIcon className="w-4 h-4" /> New Transaction
        </button>
      </div>

      {/* Financial Summary */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white p-6 rounded-[2rem] border border-pawPink shadow-sm">
          <p className="text-xs font-black text-gray-400 uppercase mb-1">Total Cash on Hand</p>
          <p className="text-3xl font-black text-gray-800">₱{totalCashOnHand.toLocaleString()}</p>
        </div>
        <div className="bg-pawMint p-6 rounded-[2rem] shadow-sm">
          <p className="text-xs font-black text-green-700 uppercase mb-1">Total Revenue</p>
          <p className="text-3xl font-black text-green-800">₱{profitStats.revenue.toLocaleString()}</p>
        </div>
        <div className="bg-red-50 p-6 rounded-[2rem] border border-red-100 shadow-sm">
          <p className="text-xs font-black text-red-700 uppercase mb-1">Total Expenses</p>
          <p className="text-3xl font-black text-red-800">₱{profitStats.expenses.toLocaleString()}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Wallet Breakdown */}
        <div className="bg-white p-6 rounded-[2.5rem] border border-pawPink">
          <h3 className="text-lg font-bold text-gray-800 mb-6">Wallets & Accounts</h3>
          <div className="grid grid-cols-2 gap-3">
            {Object.entries(walletBalances).map(([name, bal]) => (
              <div key={name} className="bg-pawCream p-4 rounded-2xl">
                <p className="text-[10px] font-black text-gray-400 uppercase">{name}</p>
                <p className="text-lg font-bold text-gray-800">₱{bal.toLocaleString()}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Recent Transactions */}
        <div className="bg-white p-6 rounded-[2.5rem] border border-pawPink">
          <h3 className="text-lg font-bold text-gray-800 mb-6">Recent Log</h3>
          <div className="space-y-3">
            {transactions.slice().reverse().slice(0, 5).map(t => (
              <div key={t.id} className="flex items-center justify-between p-3 border-b border-pawCream last:border-0">
                <div className="flex items-center gap-3">
                  <div className={`w-8 h-8 rounded-full flex items-center justify-center text-[10px] font-bold ${t.type === 'Expense' ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}>
                    {t.type.charAt(0)}
                  </div>
                  <div>
                    <p className="text-sm font-bold text-gray-800">{t.category}</p>
                    <p className="text-[10px] text-gray-400 uppercase font-bold">{t.wallet} • {new Date(t.createdAt).toLocaleDateString()}</p>
                  </div>
                </div>
                <p className={`font-bold ${t.type === 'Expense' || t.type === 'Withdrawal' ? 'text-red-500' : 'text-green-500'}`}>
                  {t.type === 'Expense' || t.type === 'Withdrawal' ? '-' : '+'}₱{t.amount}
                </p>
              </div>
            ))}
            {transactions.length === 0 && <p className="text-center text-gray-300 italic py-10">No transactions yet.</p>}
          </div>
        </div>
      </div>

      {showTxModal && <TransactionModal onClose={() => setShowTxModal(false)} onSave={handleAddTx} />}
    </div>
  );
};

