              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default LiveSell;

import React, { useState } from 'react';
import { db } from '../services/dbService';
import { Bale } from '../types';
import { PlusIcon, PawIcon } from '../components/Icons';

const Bales: React.FC = () => {
  const [bales, setBales] = useState(db.getBales());
  const [showModal, setShowModal] = useState(false);
  const products = db.getProducts();
  const orders = db.getOrders();

  const getBaleStats = (baleId: string) => {
    const baleOrders = orders.filter(o => {
        const prod = products.find(p => p.id === o.productId);
        return prod?.baleBatch === baleId;
    });
    const soldCount = baleOrders.reduce((sum, o) => sum + o.quantity, 0);
    const revenue = baleOrders.reduce((sum, o) => sum + o.totalPrice, 0);
    return { soldCount, revenue };
  };

  const handleSaveBale = (bale: Bale) => {
    db.updateBale(bale);
    setBales(db.getBales());
    setShowModal(false);
  };

  const handleDeleteBale = (id: string) => {
    if (confirm('Delete this bale record? This will not delete products assigned to it.')) {
      db.deleteBale(id);
      setBales(db.getBales());
    }
  };

  return (
    <div className="space-y-6 pb-24 px-1">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-gray-800">Bale Management</h1>
        <button 
          onClick={() => setShowModal(true)}
          className="bg-pawSoftBlue text-blue-700 px-5 py-2.5 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center gap-2 shadow-sm active:scale-95 transition-all"
        >
          <PlusIcon className="w-4 h-4" /> New Bale
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {bales.map(bale => {
          const stats = getBaleStats(bale.id);
          const progress = Math.min(100, (stats.soldCount / bale.itemCount) * 100);

          return (
            <div key={bale.id} className="bg-white rounded-[2.5rem] p-6 border border-pawPink/40 shadow-sm overflow-hidden relative group">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <h3 className="text-xl font-black text-gray-800 tracking-tight">{bale.name}</h3>
                  <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">{bale.id} • {bale.status}</p>
                </div>
                <div className="text-right">
                  <p className="text-[10px] font-black text-pawPinkDark uppercase tracking-widest">Initial Cost</p>
                  <p className="text-xl font-black text-gray-800">₱{bale.cost.toLocaleString()}</p>
                </div>
              </div>

              <div className="grid grid-cols-3 gap-3 mb-6">
                <div className="bg-pawCream/50 p-4 rounded-2xl text-center">
                  <p className="text-[9px] font-black text-gray-400 uppercase mb-1">Items</p>
                  <p className="text-lg font-black text-gray-800 leading-none">{bale.itemCount}</p>
                </div>
                <div className="bg-pawMint p-4 rounded-2xl text-center">
                  <p className="text-[9px] font-black text-green-700 uppercase mb-1">Sold</p>
                  <p className="text-lg font-black text-green-800 leading-none">{stats.soldCount}</p>
                </div>
                <div className="bg-pawSoftBlue p-4 rounded-2xl text-center">
                  <p className="text-[9px] font-black text-blue-700 uppercase mb-1">Rev</p>
                  <p className="text-lg font-black text-blue-800 leading-none">₱{stats.revenue.toLocaleString()}</p>
                </div>
              </div>

              <div className="space-y-2 mb-6">
                <div className="flex justify-between text-[10px] font-black text-gray-500 uppercase tracking-widest">
                  <span>Sold Progress</span>
                  <span>{progress.toFixed(0)}%</span>
                </div>
                <div className="w-full h-3 bg-pawCream rounded-full overflow-hidden shadow-inner">
                  <div 
                    className="h-full bg-pawPinkDark transition-all duration-700 shadow-[0_0_10px_rgba(255,183,197,0.5)]" 
                    style={{ width: `${progress}%` }}
                  />
                </div>
              </div>

              <div className="flex justify-between items-center pt-4 border-t border-pawCream">
                <div className="text-xs font-black uppercase tracking-tight">
                  Net: <span className={stats.revenue - bale.cost >= 0 ? 'text-green-600' : 'text-red-500'}>
                    ₱{(stats.revenue - bale.cost).toLocaleString()}
                  </span>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => handleDeleteBale(bale.id)} className="p-2 text-gray-300 hover:text-red-500 transition-colors">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                  </button>
                  <button className="bg-pawCream px-4 py-2 rounded-xl text-[10px] font-black text-pawPinkDark uppercase tracking-widest hover:bg-pawPink hover:text-white transition-all">Details</button>
                </div>
              </div>
            </div>
          );
        })}
        {bales.length === 0 && <p className="col-span-full text-center py-20 text-gray-300 font-bold italic">No bales logged yet.</p>}
      </div>

      {showModal && <BaleModal onClose={() => setShowModal(false)} onSave={handleSaveBale} />}
    </div>
  );
};

