import React, { useState, useMemo } from 'react';
import { db } from '../services/dbService';
import { Order, PaymentStatus, ShippingStatus, PaymentMethod } from '../types';
// Add missing CartIcon import
import { CartIcon } from '../components/Icons';

const Orders: React.FC = () => {
  const [filter, setFilter] = useState('All');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [orders, setOrders] = useState(db.getOrders());

  const filteredOrders = useMemo(() => {
    return orders.filter(o => {
      const matchesSearch = o.customerUsername.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            o.productName.toLowerCase().includes(searchTerm.toLowerCase());
      if (filter === 'All') return matchesSearch;
      if (filter === 'Unpaid') return matchesSearch && o.paymentStatus === PaymentStatus.UNPAID;
      if (filter === 'To Ship') return matchesSearch && o.shippingStatus === ShippingStatus.PENDING;
      return matchesSearch;
    }).sort((a, b) => b.createdAt - a.createdAt);
  }, [orders, filter, searchTerm]);

  const handleUpdateStatus = (order: Order) => {
    db.updateOrder(order);
    setOrders(db.getOrders());
    setSelectedOrder(null);
  };

  const handleDeleteOrder = (id: string) => {
    if (confirm('Permanently delete this order record? This will not return stock.')) {
      db.deleteOrder(id);
      setOrders(db.getOrders());
    }
  };

  return (
    <div className="space-y-6 pb-24 px-1">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h1 className="text-2xl font-bold text-gray-800">Order Management</h1>
        <div className="flex items-center bg-white p-1.5 rounded-[1.5rem] shadow-sm border border-pawPink/30 self-start">
          {['All', 'Unpaid', 'To Ship'].map(f => (
            <button 
              key={f} 
              onClick={() => setFilter(f)}
              className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${
                filter === f ? 'bg-pawPinkDark text-white shadow-md' : 'text-gray-400 hover:text-gray-600'
              }`}
            >
              {f}
            </button>
          ))}
        </div>
      </div>

      <div className="relative">
        <input 
          type="text" 
          placeholder="Search by customer or product..." 
          className="w-full bg-white border-2 border-pawPink/30 rounded-[1.5rem] p-5 shadow-sm text-gray-700 font-bold focus:border-pawPinkDark transition-all placeholder:text-gray-300"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredOrders.length === 0 ? (
          <div className="col-span-full py-20 text-center flex flex-col items-center opacity-40">
             <CartIcon className="w-16 h-16 mb-2 text-gray-300" />
             <p className="font-bold italic text-gray-400">No orders found.</p>
          </div>
        ) : (
          filteredOrders.map(order => (
            <OrderCard key={order.id} order={order} onEdit={() => setSelectedOrder(order)} onDelete={() => handleDeleteOrder(order.id)} />
          ))
        )}
      </div>

      {selectedOrder && (
        <StatusModal 
          order={selectedOrder} 
          onClose={() => setSelectedOrder(null)} 
          onSave={handleUpdateStatus}
        />
      )}
    </div>
  );
};

const OrderCard: React.FC<{ order: Order; onEdit: () => void; onDelete: () => void }> = ({ order, onEdit, onDelete }) => {
  const getStatusColor = (status: string) => {
    switch (status) {
      case PaymentStatus.PAID: return 'bg-green-100 text-green-700';
      case PaymentStatus.UNPAID: return 'bg-red-100 text-red-700';
      case ShippingStatus.SHIPPED: return 'bg-blue-100 text-blue-700';
      case ShippingStatus.PENDING: return 'bg-yellow-100 text-yellow-700';
      case ShippingStatus.CANCELLED: return 'bg-gray-200 text-gray-500';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  return (
    <div className="bg-white rounded-[2rem] p-6 border border-pawPink/40 shadow-sm hover:shadow-md transition-all group animate-fadeIn">
      <div className="flex justify-between items-start mb-5">
        <div>
          <h4 className="font-black text-gray-800 text-xl tracking-tight leading-none mb-1">@{order.customerUsername}</h4>
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{new Date(order.createdAt).toLocaleDateString()} • {new Date(order.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
        </div>
        <div className="flex flex-col gap-1.5 items-end shrink-0">
          <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-tighter ${getStatusColor(order.paymentStatus)}`}>
            {order.paymentStatus}
          </span>
          <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-tighter ${getStatusColor(order.shippingStatus)}`}>
            {order.shippingStatus}
          </span>
        </div>
      </div>

      <div className="bg-pawCream/40 p-4 rounded-2xl mb-6 shadow-inner border border-pawCream">
        <div className="flex justify-between items-center">
          <span className="text-sm font-black text-gray-600 truncate mr-3">{order.quantity}x {order.productName}</span>
          <span className="font-black text-gray-800 text-lg">₱{order.totalPrice}</span>
        </div>
        {(order.amountPaid > 0 || order.paymentStatus === PaymentStatus.PARTIAL) && (
          <div className="mt-3 text-[10px] flex justify-between text-gray-500 font-black border-t border-pawPink/30 pt-2 uppercase tracking-tighter">
            <span>Paid: ₱{order.amountPaid}</span>
            <span className="text-pawPinkDark">Balance: ₱{order.totalPrice - order.amountPaid}</span>
          </div>
        )}
      </div>

      <div className="flex gap-2">
        <button 
          onClick={onEdit}
          className="flex-1 py-3 bg-pawPinkDark text-white font-black rounded-xl text-xs uppercase tracking-widest shadow-sm active:scale-95 transition-all"
        >
          Manage
        </button>
        <button 
          onClick={onDelete}
          className="px-4 py-3 border-2 border-pawCream text-gray-300 rounded-xl hover:text-red-400 hover:border-red-100 active:scale-90 transition-all"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
        </button>
      </div>
    </div>
  );
};

const StatusModal: React.FC<{ order: Order; onClose: () => void; onSave: (order: Order) => void }> = ({ order, onClose, onSave }) => {
  const [formData, setFormData] = useState({ ...order });

