                onChange={(e) => setFormData({...formData, costPrice: Number(e.target.value)})}
                className="w-full bg-pawCream p-5 rounded-2xl border-none font-bold mt-1"
              />
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Selling Price (₱)</label>
              <input 
                type="number"
                value={formData.sellingPrice}
                onChange={(e) => setFormData({...formData, sellingPrice: Number(e.target.value)})}
                className="w-full bg-pawCream p-5 rounded-2xl border-none font-bold mt-1"
              />
            </div>
            <div className="col-span-2">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Initial Stock</label>
              <input 
                type="number"
                value={formData.stock}
                onChange={(e) => setFormData({...formData, stock: Number(e.target.value)})}
                className="w-full bg-pawCream p-5 rounded-2xl border-none font-bold mt-1"
              />
            </div>
          </div>

          <div className="flex gap-4 pt-6">
            <button onClick={onClose} className="flex-1 py-5 bg-gray-100 text-gray-400 font-black uppercase text-xs tracking-widest rounded-[1.5rem] active:scale-95 transition-all">Cancel</button>
            <button onClick={() => onSave(formData)} className="flex-1 py-5 bg-green-500 text-white font-black uppercase text-xs tracking-widest rounded-[1.5rem] shadow-lg active:scale-95 transition-all">Save Changes</button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../services/dbService';
import { Product, Order, PaymentStatus, ShippingStatus } from '../types';
import { SearchIcon, PlusIcon, PawIcon } from '../components/Icons';

const LiveSell: React.FC = () => {
  const [session, setSession] = useState(db.getSessions().find(s => s.isOpen) || null);
  const [username, setUsername] = useState('');
  const [searchProduct, setSearchProduct] = useState('');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [quantity, setQuantity] = useState(1);
  const [isFreebie, setIsFreebie] = useState(false);
  const [recentOrders, setRecentOrders] = useState<Order[]>([]);
  const [feedback, setFeedback] = useState<string | null>(null);

  const products = db.getProducts();
  const customers = db.getCustomers();

  const filteredProducts = useMemo(() => {
    if (!searchProduct || selectedProduct) return [];
    return products.filter(p => 
      p.name.toLowerCase().includes(searchProduct.toLowerCase()) ||
      p.brand.toLowerCase().includes(searchProduct.toLowerCase())
    ).slice(0, 5);
  }, [searchProduct, products, selectedProduct]);

  const filteredCustomers = useMemo(() => {
    if (!username || customers.some(c => c.username === username)) return [];
    const lower = username.toLowerCase();
    return customers.filter(c => 
      c.username.toLowerCase().includes(lower)
    ).slice(0, 3);
  }, [username, customers]);

  useEffect(() => {
    if (session) {
      const orders = db.getOrders().filter(o => o.sessionId === session.id);
      setRecentOrders(orders.sort((a, b) => b.createdAt - a.createdAt).slice(0, 10));
    }
  }, [session]);

  const handleStartSession = () => {
    const name = prompt('Enter Live Session Name (e.g., Sunday PM Live):');
    if (name) {
      const newSession = db.createSession(name);
      setSession(newSession);
    }
  };

  const handleEndSession = () => {
    if (session && confirm('Are you sure you want to END this live session? No more orders can be encoded under this session.')) {
      db.closeSession(session.id);
      setSession(null);
    }
  };

  const handleAddOrder = () => {
    if (!session || !username || !selectedProduct) {
      alert('Please select a customer and product!');
      return;
    }

    const customer = db.getOrCreateCustomer(username);
    const totalPrice = isFreebie ? 0 : selectedProduct.sellingPrice * quantity;

    const newOrder: Order = {
      id: `o_${Date.now()}`,
      sessionId: session.id,
      customerId: customer.id,
      customerUsername: username,
      productId: selectedProduct.id,
      productName: selectedProduct.name,
      quantity,
      totalPrice,
      isFreebie,
      paymentStatus: isFreebie ? PaymentStatus.PAID : PaymentStatus.UNPAID,
      shippingStatus: ShippingStatus.PENDING,
      amountPaid: 0,
      createdAt: Date.now(),
    };

    db.addOrder(newOrder);
    setRecentOrders([newOrder, ...recentOrders]);

    // UI Feedback
    setFeedback(`Order saved for @${username}!`);
    setTimeout(() => setFeedback(null), 2000);

    // Quick Reset
    setSearchProduct('');
    setSelectedProduct(null);
    setQuantity(1);
    setIsFreebie(false);
  };

  if (!session) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[70vh] text-center px-4">
        <div className="bg-pawPink/20 p-8 rounded-full mb-6">
          <PawIcon className="w-24 h-24 text-pawPinkDark opacity-80" />
        </div>
        <h2 className="text-3xl font-black text-gray-800 mb-3 uppercase tracking-tight">Time to Shine! ✨</h2>
        <p className="text-gray-500 mb-8 font-bold max-w-sm">Create a live session to start tracking your sales in real-time.</p>
        <button 
          onClick={handleStartSession}
          className="bg-pawPinkDark text-white px-12 py-6 rounded-[2.5rem] font-black uppercase tracking-widest shadow-xl active:scale-95 transition-all hover:bg-red-300 hover:shadow-pawPinkDark/40 text-lg"
        >
          Start New Live Session
        </button>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 pb-32">
      {/* Encoding Panel */}
      <div className="lg:col-span-7 space-y-6">
        <div className="bg-white p-8 rounded-[3rem] shadow-xl border-2 border-pawPink/30 relative">
          <div className="flex items-center justify-between mb-8">
            <div className="flex flex-col">
              <div className="flex items-center gap-2 mb-1">
                <span className="w-3 h-3 bg-red-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.5)]"></span>
                <span className="text-[10px] font-black text-red-500 uppercase tracking-widest">Live Now</span>
              </div>
              <h3 className="text-2xl font-black text-gray-800 uppercase tracking-tighter leading-none">
                {session.name}
              </h3>
            </div>
            <button 
              className="px-4 py-2 bg-gray-100 hover:bg-red-50 text-gray-400 hover:text-red-500 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all active:scale-90"
              onClick={handleEndSession}
            >
              End Session
            </button>
          </div>

          <div className="space-y-6">
            {/* Username Selection */}
            <div className="relative">
              <label className="text-[11px] font-black text-gray-400 uppercase ml-4 tracking-widest mb-1 block">Customer Username</label>
              <div className="flex items-center bg-pawCream rounded-[1.5rem] px-5 border-2 border-transparent focus-within:border-pawPinkDark transition-all">
                <span className="text-xl font-black text-gray-400">@</span>
                <input 
                  type="text"
                  placeholder="tiktok_username"
                  value={username}
                  onChange={(e) => setUsername(e.target.value.replace('@', ''))}
                  className="w-full bg-transparent p-4 text-xl font-black text-gray-800 placeholder:text-gray-300 border-none focus:ring-0"
                />
              </div>
              {filteredCustomers.length > 0 && (
                <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-[1.5rem] z-30 border-2 border-pawPink mt-2 p-2 overflow-hidden animate-scaleUp">
                  {filteredCustomers.map(c => (
                    <button 
                      key={c.id} 
                      onClick={() => setUsername(c.username)}
                      className="w-full text-left p-4 hover:bg-pawPink/20 rounded-2xl flex items-center justify-between transition-colors mb-1 last:mb-0"
                    >
                      <span className="font-black text-gray-800">@{c.username}</span>
                      {c.isVIP && <span className="bg-yellow-100 text-yellow-700 text-[10px] px-3 py-1 rounded-full font-black uppercase tracking-tighter">VIP</span>}
                    </button>
                  ))}
                </div>
              )}
            </div>

            {/* Product Selection */}
            <div className="relative">
              <label className="text-[11px] font-black text-gray-400 uppercase ml-4 tracking-widest mb-1 block">Selected Product</label>
              {selectedProduct ? (
                <div className="flex items-center justify-between bg-pawPink/20 p-6 rounded-[1.5rem] border-2 border-pawPinkDark animate-scaleUp shadow-inner">
                   <div className="flex flex-col">
                     <p className="font-black text-gray-800 text-xl tracking-tight">{selectedProduct.name}</p>
                     <p className="text-xs font-bold text-pawPinkDark uppercase tracking-widest">₱{selectedProduct.sellingPrice} • {selectedProduct.stock} In Stock</p>
                   </div>
                   <button 
                     onClick={() => setSelectedProduct(null)} 
                     className="bg-white px-5 py-3 rounded-2xl text-pawPinkDark font-black text-xs uppercase tracking-widest shadow-md active:scale-90 transition-transform hover:bg-pawPink hover:text-white"
                   >
                     Change
                   </button>
                </div>
              ) : (
                <div className="flex items-center bg-pawCream rounded-[1.5rem] px-5 border-2 border-transparent focus-within:border-pawPinkDark transition-all">
                  <SearchIcon className="text-gray-300 w-6 h-6" />
                  <input 
                    type="text"
                    placeholder="Search by name or brand..."
                    value={searchProduct}
                    onChange={(e) => setSearchProduct(e.target.value)}
                    className="w-full bg-transparent p-4 text-xl font-black text-gray-800 placeholder:text-gray-300 border-none focus:ring-0"
                  />
                </div>
              )}
              {filteredProducts.length > 0 && (
                <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-[1.5rem] z-30 border-2 border-pawPink mt-2 p-2 max-h-72 overflow-y-auto animate-scaleUp custom-scrollbar">
                  {filteredProducts.map(p => (
                    <button 
                      key={p.id} 
                      onClick={() => { setSelectedProduct(p); setSearchProduct(''); }}
                      className="w-full text-left p-4 hover:bg-pawPink/10 rounded-2xl flex items-center justify-between border-b last:border-0 border-pawCream transition-colors"
                    >
                      <div className="flex-1 mr-4">
                        <p className="font-black text-gray-800 text-lg leading-tight">{p.name}</p>
                        <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{p.brand} • ₱{p.sellingPrice}</p>
                      </div>
                      <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase shrink-0 ${p.stock < 5 ? 'bg-red-100 text-red-600' : 'bg-pawMint text-green-700'}`}>
                        {p.stock} left
                      </span>
                    </button>
                  ))}
                </div>
              )}
            </div>

            <div className="grid grid-cols-2 gap-4">
              {/* Quantity */}
              <div className="bg-pawSoftBlue p-2 rounded-[1.5rem] flex items-center justify-between border-2 border-pawSoftBlue/50 shadow-inner">
                <button 
                  onClick={() => setQuantity(Math.max(1, quantity - 1))} 
                  className="w-14 h-14 flex items-center justify-center bg-white rounded-2xl text-2xl font-black text-blue-600 shadow-md active:scale-90 transition-all hover:bg-blue-50"
                >
                  −
                </button>
                <div className="flex flex-col items-center">
                  <span className="text-xs font-black text-blue-400 uppercase tracking-widest">Qty</span>
                  <span className="text-3xl font-black text-gray-800 leading-none">{quantity}</span>
                </div>
                <button 
                  onClick={() => setQuantity(quantity + 1)} 
                  className="w-14 h-14 flex items-center justify-center bg-white rounded-2xl text-2xl font-black text-blue-600 shadow-md active:scale-90 transition-all hover:bg-blue-50"
                >
                  +
                </button>
              </div>

              {/* Freebie Toggle */}
              <button 
                onClick={() => setIsFreebie(!isFreebie)}
                className={`flex-col p-4 rounded-[1.5rem] font-black flex items-center justify-center gap-1 border-2 uppercase text-[10px] tracking-widest transition-all shadow-sm ${
                  isFreebie ? 'bg-pawPeach border-orange-300 text-orange-700 shadow-orange-100' : 'bg-pawCream border-transparent text-gray-400'
                }`}
              >
                <span className="text-2xl">{isFreebie ? '🎁' : '🏷️'}</span>
                <span>{isFreebie ? 'FREEBIE ON' : 'REGULAR PRICE'}</span>
              </button>
            </div>

            <button 
              onClick={handleAddOrder}
              disabled={!username || !selectedProduct}
              className={`w-full py-6 rounded-[2rem] text-xl font-black uppercase tracking-widest shadow-2xl transition-all active:scale-95 flex items-center justify-center gap-3 ${
                (!username || !selectedProduct) ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-pawPinkDark text-white hover:bg-red-300 hover:shadow-pawPinkDark/50'
              }`}
            >
              {feedback ? (
                <span className="animate-bounce">✅ {feedback}</span>
              ) : (
                <>ADD TO CART • ₱{isFreebie ? '0' : (selectedProduct?.sellingPrice || 0) * quantity}</>
              )}
            </button>
          </div>
        </div>
      </div>

      {/* Real-time Order Feed */}
      <div className="lg:col-span-5 flex flex-col h-full max-h-[85vh]">
        <h4 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4 px-4">Latest Captures</h4>
        <div className="flex-1 overflow-y-auto space-y-4 pr-2 custom-scrollbar px-1">
          {recentOrders.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-300 border-4 border-dashed border-pawPink/20 rounded-[3rem] py-20 opacity-60">
              <div className="mb-4 text-4xl">📸</div>
              <p className="font-black uppercase text-xs tracking-widest">Waiting for orders...</p>
            </div>
          ) : (
            recentOrders.map(order => (
              <div key={order.id} className="bg-white p-6 rounded-[2rem] shadow-md border-l-8 border-pawPink flex items-center justify-between transform transition-all animate-slideIn hover:translate-x-1">
                <div className="flex items-center gap-5">
                  <div className={`w-14 h-14 ${order.isFreebie ? 'bg-pawPeach text-orange-600' : 'bg-pawMint text-green-700'} rounded-2xl flex items-center justify-center font-black text-xl shadow-inner uppercase`}>
                    {order.customerUsername.charAt(0)}
                  </div>
                  <div>
                    <p className="font-black text-gray-800 text-lg leading-tight tracking-tight">@{order.customerUsername}</p>
                    <p className="text-[11px] font-bold text-gray-400 uppercase tracking-wider mt-1">{order.quantity}x {order.productName}</p>
                  </div>
                </div>
                <div className="text-right flex flex-col items-end">
                  <p className="font-black text-pawPinkDark text-xl">₱{order.totalPrice}</p>
                  {order.isFreebie && <span className="text-[8px] bg-orange-100 text-orange-600 px-2 py-1 rounded-md font-black uppercase tracking-widest mt-1">GIFT</span>}
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

