        {bales.map(bale => {
          const stats = getBaleStats(bale.id);
          const progress = Math.min(100, (stats.soldCount / bale.itemCount) * 100);
          const net = stats.revenue - bale.cost;

          return (
            <div key={bale.id} className="bg-white rounded-[3rem] p-8 border-2 border-pawPink/20 shadow-xl overflow-hidden relative group animate-fadeIn">
              <div className="flex justify-between items-start mb-8">
                <div>
                  <h3 className="text-2xl font-black text-gray-800 tracking-tighter leading-none">{bale.name}</h3>
                  <div className="flex gap-2 mt-2">
