                  <p className="text-[9px] font-black text-gray-400 uppercase mb-2 tracking-widest">Est Items</p>
                  <p className="text-xl font-black text-gray-800 leading-none">{bale.itemCount}</p>
                </div>
                <div className="bg-pawMint p-5 rounded-[1.5rem] text-center shadow-inner">
