// Summary / Packing List Modal
const SessionSummaryModal: React.FC<{ session: LiveSession; onClose: () => void }> = ({ session, onClose }) => {
  const [orders, setOrders] = useState<Order[]>([]);

  useEffect(() => {
    // Fetch orders for this specific session
    const allOrders = db.getOrders();
    setOrders(allOrders.filter(o => o.sessionId === session.id));
  }, [session]);

  const groupedOrders = useMemo(() => {
    const grouped: Record<string, Order[]> = {};
    orders.forEach(o => {
      if (!grouped[o.customerUsername]) grouped[o.customerUsername] = [];
      grouped[o.customerUsername].push(o);
    });
    return grouped;
  }, [orders]);

  const totalSales = orders.reduce((sum, o) => sum + o.totalPrice, 0);

  return (
    <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center p-0 md:p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
      <div className="bg-white w-full max-w-2xl h-[90vh] md:h-auto md:max-h-[85vh] rounded-t-[3rem] md:rounded-[3rem] overflow-hidden shadow-2xl animate-scaleUp flex flex-col">
        {/* Header */}
        <div className="bg-pawSoftBlue p-8 shrink-0">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-blue-600 font-black text-xs uppercase tracking-widest mb-1">{session.date}</p>
              <h3 className="text-2xl font-black text-gray-800 uppercase tracking-tight leading-none">{session.name}</h3>
            </div>
            <button onClick={onClose} className="bg-white/50 p-2 rounded-full hover:bg-white text-blue-900 transition-all">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          </div>
          <div className="mt-6 flex gap-4">
             <div className="bg-white/60 px-4 py-2 rounded-xl">
               <p className="text-[10px] font-black text-blue-800 uppercase tracking-widest">Total Sales</p>
               <p className="text-xl font-black text-gray-800">₱{totalSales.toLocaleString()}</p>
             </div>
             <div className="bg-white/60 px-4 py-2 rounded-xl">
               <p className="text-[10px] font-black text-blue-800 uppercase tracking-widest">Total Parcels</p>
               <p className="text-xl font-black text-gray-800">{Object.keys(groupedOrders).length}</p>
             </div>
          </div>
        </div>

        {/* Content - Packing List */}
        <div className="p-6 md:p-8 overflow-y-auto custom-scrollbar flex-1 bg-white">
          <h4 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6">Packing List (By Customer)</h4>

          {Object.keys(groupedOrders).length === 0 ? (
            <p className="text-center text-gray-400 italic">No orders found in this session.</p>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {Object.entries(groupedOrders).map(([username, items]) => {
                 const orderItems = items as Order[];
                 const customerTotal = orderItems.reduce((sum, i) => sum + i.totalPrice, 0);
                 const hasUnpaid = orderItems.some(i => i.paymentStatus !== PaymentStatus.PAID);

                 return (
                   <div key={username} className="bg-gray-50 rounded-[2rem] p-5 border border-gray-100 break-inside-avoid">
                      <div className="flex justify-between items-center mb-4 border-b border-gray-200 pb-2">
                        <div className="flex items-center gap-2">
                          <div className="w-8 h-8 bg-pawPink rounded-full flex items-center justify-center text-[10px] font-black text-pawPinkDark uppercase">
                            {username.charAt(0)}
                          </div>
                          <span className="font-black text-gray-800 text-sm">@{username}</span>
                        </div>
                        <div className="text-right">
                           <span className="block font-black text-gray-800">₱{customerTotal}</span>
                           {hasUnpaid && <span className="text-[9px] text-red-500 font-bold uppercase">Unpaid Items</span>}
                        </div>
                      </div>
                      <ul className="space-y-2">
                        {orderItems.map(item => (
                          <li key={item.id} className="flex justify-between text-xs items-center">
                            <span className="text-gray-600 font-bold w-3/4 truncate">
                              {item.quantity}x {item.productName} 
                              {item.isFreebie && <span className="ml-1 text-[8px] bg-orange-100 text-orange-600 px-1 rounded uppercase font-black">Free</span>}
                            </span>
                            <span className="text-gray-400 font-bold">₱{item.totalPrice}</span>
                          </li>
                        ))}
                      </ul>
                   </div>
                 );
              })}
            </div>
          )}
        </div>

        {/* Footer Action */}
        <div className="p-4 bg-white border-t border-gray-100">
           <button onClick={onClose} className="w-full py-4 bg-gray-100 text-gray-500 font-black uppercase text-xs tracking-widest rounded-2xl hover:bg-gray-200 transition-all">Close Review</button>
        </div>
      </div>
    </div>
  );
};

export default LiveSell;

import React, { useState, useMemo } from 'react';
import { db } from '../services/dbService';
import { Order, PaymentStatus, ShippingStatus, PaymentMethod, LiveSession } from '../types';
import { CartIcon, PlusIcon, PawIcon, SearchIcon } from '../components/Icons';

const Orders: React.FC = () => {
  const [selectedSession, setSelectedSession] = useState<LiveSession | null>(null);
  const [sessions, setSessions] = useState(db.getSessions().sort((a, b) => b.id.localeCompare(a.id))); // Newest first

  // -- Orders View State --
  const [filter, setFilter] = useState('All');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [allOrders, setAllOrders] = useState(db.getOrders());

  // Derived state: Get orders for the selected session only
  const sessionOrders = useMemo(() => {
    if (!selectedSession) return [];
    return allOrders.filter(o => o.sessionId === selectedSession.id);
  }, [allOrders, selectedSession]);

  // Derived state: Filter the session orders by status/search
  const filteredOrders = useMemo(() => {
    return sessionOrders.filter(o => {
      const matchesSearch = o.customerUsername.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            o.productName.toLowerCase().includes(searchTerm.toLowerCase());
      if (filter === 'All') return matchesSearch;
      if (filter === 'Unpaid') return matchesSearch && o.paymentStatus === PaymentStatus.UNPAID;
      if (filter === 'To Ship') return matchesSearch && o.shippingStatus === ShippingStatus.PENDING;
      return matchesSearch;
    }).sort((a, b) => b.createdAt - a.createdAt);
  }, [sessionOrders, filter, searchTerm]);

  const handleUpdateStatus = (order: Order) => {
    db.updateOrder(order);
    setAllOrders(db.getOrders()); // Refresh all orders
    setSelectedOrder(null);
  };

  const handleDeleteOrder = (id: string) => {
    if (confirm('Permanently delete this order record? This will not return stock.')) {
      db.deleteOrder(id);
      setAllOrders(db.getOrders()); // Refresh all orders
    }
  };

  // --- VIEW 1: Session Selection List ---
  if (!selectedSession) {
    return (
      <div className="space-y-6 pb-24 px-1">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Order Batches</h1>
          <p className="text-gray-500 font-bold text-sm">Select a Live Session to manage its orders.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {sessions.length === 0 ? (
             <div className="col-span-full py-20 text-center flex flex-col items-center opacity-40">
                <div className="text-6xl mb-4">📺</div>
                <p className="font-bold italic text-gray-400">No live sessions recorded yet.</p>
             </div>
          ) : (
            sessions.map(session => {
              // Calculate stats for card
              const sOrders = allOrders.filter(o => o.sessionId === session.id);
              const totalRevenue = sOrders.reduce((sum, o) => sum + o.totalPrice, 0);
              const unpaidCount = sOrders.filter(o => o.paymentStatus !== PaymentStatus.PAID).length;

              return (
                <button 
                  key={session.id}
                  onClick={() => setSelectedSession(session)}
                  className="bg-white rounded-[2.5rem] p-7 border-2 border-pawPink/30 hover:border-pawPinkDark shadow-sm hover:shadow-xl transition-all group text-left relative overflow-hidden active:scale-95"
                >
                  <div className="flex justify-between items-start mb-6 relative z-10">
                    <div>
                      <h3 className="font-black text-gray-800 text-xl tracking-tight leading-none mb-2">{session.name}</h3>
                      <p className="text-[11px] font-black text-gray-400 uppercase tracking-widest">{session.date}</p>
                    </div>
                    {session.isOpen ? (
                      <span className="bg-red-500 text-white px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest animate-pulse">Live</span>
                    ) : (
                      <span className="bg-gray-100 text-gray-500 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest">Ended</span>
                    )}
                  </div>

                  <div className="flex gap-4 relative z-10">
                    <div className="bg-pawSoftBlue px-4 py-3 rounded-2xl flex-1">
                      <p className="text-[9px] text-blue-600 font-black uppercase tracking-wider mb-1">Orders</p>
                      <p className="text-xl font-black text-gray-800">{sOrders.length}</p>
                    </div>
                    <div className="bg-pawMint px-4 py-3 rounded-2xl flex-1">
                      <p className="text-[9px] text-green-700 font-black uppercase tracking-wider mb-1">Sales</p>
                      <p className="text-xl font-black text-gray-800">₱{totalRevenue.toLocaleString()}</p>
                    </div>
                  </div>

                  {unpaidCount > 0 && (
                    <div className="mt-4 bg-red-50 px-4 py-2 rounded-xl border border-red-100 flex items-center gap-2">
                       <div className="w-2 h-2 bg-red-500 rounded-full"></div>
                       <p className="text-[10px] font-black text-red-600 uppercase tracking-wider">{unpaidCount} Pending Payments</p>
                    </div>
                  )}

                  <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-br from-pawPink/20 to-transparent rounded-bl-[100px] -mr-8 -mt-8"></div>
                </button>
              );
            })
          )}
        </div>
      </div>
    );
  }

  // --- VIEW 2: Specific Session Orders ---
  return (
    <div className="space-y-6 pb-24 px-1 animate-fadeIn">
      {/* Header & Back Button */}
      <div className="flex flex-col gap-4">
        <button 
          onClick={() => { setSelectedSession(null); setSearchTerm(''); setFilter('All'); }}
          className="self-start flex items-center gap-2 text-gray-500 hover:text-pawPinkDark font-black text-xs uppercase tracking-widest transition-colors mb-2"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" /></svg>
          Back to Sessions
        </button>

        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
             <h1 className="text-2xl font-black text-gray-800 tracking-tight">{selectedSession.name}</h1>
             <p className="text-gray-400 font-bold text-xs uppercase tracking-widest mt-1">Managing {sessionOrders.length} orders</p>
          </div>

          <div className="flex items-center bg-white p-1.5 rounded-[1.5rem] shadow-sm border border-pawPink/30 self-start">
            {['All', 'Unpaid', 'To Ship'].map(f => (
              <button 
                key={f} 
                onClick={() => setFilter(f)}
                className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${
                  filter === f ? 'bg-pawPinkDark text-white shadow-md' : 'text-gray-400 hover:text-gray-600'
                }`}
              >
                {f}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Search Bar */}
      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
          <SearchIcon className="h-5 w-5 text-gray-300" />
        </div>
        <input 
          type="text" 
          placeholder="Search items or customers in this live..." 
          className="w-full bg-white border-2 border-pawPink/30 rounded-[1.5rem] pl-12 pr-5 py-4 shadow-sm text-gray-700 font-bold focus:border-pawPinkDark transition-all placeholder:text-gray-300 outline-none"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Order Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredOrders.length === 0 ? (
          <div className="col-span-full py-20 text-center flex flex-col items-center opacity-40">
             <CartIcon className="w-16 h-16 mb-2 text-gray-300" />
             <p className="font-bold italic text-gray-400">No orders found.</p>
          </div>
        ) : (
          filteredOrders.map(order => (
            <OrderCard key={order.id} order={order} onEdit={() => setSelectedOrder(order)} onDelete={() => handleDeleteOrder(order.id)} />
          ))
        )}
      </div>

      {/* Modal Reuse */}
      {selectedOrder && (
        <StatusModal 
          order={selectedOrder} 
          onClose={() => setSelectedOrder(null)} 
          onSave={handleUpdateStatus}
        />
      )}
    </div>
  );
};

const OrderCard: React.FC<{ order: Order; onEdit: () => void; onDelete: () => void }> = ({ order, onEdit, onDelete }) => {
  const getStatusColor = (status: string) => {
    switch (status) {
      case PaymentStatus.PAID: return 'bg-green-100 text-green-700';
      case PaymentStatus.UNPAID: return 'bg-red-100 text-red-700';
      case ShippingStatus.SHIPPED: return 'bg-blue-100 text-blue-700';
      case ShippingStatus.PENDING: return 'bg-yellow-100 text-yellow-700';
      case ShippingStatus.CANCELLED: return 'bg-gray-200 text-gray-500';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  return (
    <div className="bg-white rounded-[2rem] p-6 border border-pawPink/40 shadow-sm hover:shadow-md transition-all group animate-fadeIn">
      <div className="flex justify-between items-start mb-5">
        <div>
          <h4 className="font-black text-gray-800 text-xl tracking-tight leading-none mb-1">@{order.customerUsername}</h4>
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{new Date(order.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
        </div>
        <div className="flex flex-col gap-1.5 items-end shrink-0">
          <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-tighter ${getStatusColor(order.paymentStatus)}`}>
            {order.paymentStatus}
          </span>
          <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-tighter ${getStatusColor(order.shippingStatus)}`}>
            {order.shippingStatus}
          </span>
        </div>
      </div>

      <div className="bg-pawCream/40 p-4 rounded-2xl mb-6 shadow-inner border border-pawCream">
        <div className="flex justify-between items-center">
          <span className="text-sm font-black text-gray-600 truncate mr-3">{order.quantity}x {order.productName}</span>
          <span className="font-black text-gray-800 text-lg">₱{order.totalPrice}</span>
        </div>
        {(order.amountPaid > 0 || order.paymentStatus === PaymentStatus.PARTIAL) && (
          <div className="mt-3 text-[10px] flex justify-between text-gray-500 font-black border-t border-pawPink/30 pt-2 uppercase tracking-tighter">
            <span>Paid: ₱{order.amountPaid}</span>
            <span className="text-pawPinkDark">Balance: ₱{order.totalPrice - order.amountPaid}</span>
          </div>
        )}
      </div>

      <div className="flex gap-2">
        <button 
          onClick={onEdit}
          className="flex-1 py-3 bg-pawPinkDark text-white font-black rounded-xl text-xs uppercase tracking-widest shadow-sm active:scale-95 transition-all"
        >
          Manage
        </button>
        <button 
          onClick={onDelete}
          className="px-4 py-3 border-2 border-pawCream text-gray-300 rounded-xl hover:text-red-400 hover:border-red-100 active:scale-90 transition-all"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
        </button>
      </div>
    </div>
  );
};

