import React, { useState, useMemo } from 'react';
import { db } from '../services/dbService';
import { Product, Bale } from '../types';
import { SearchIcon, PlusIcon, PawIcon } from '../components/Icons';

const Inventory: React.FC = () => {
  // State
  const [products, setProducts] = useState(db.getProducts());
  const [bales, setBales] = useState(db.getBales());
  const [selectedBale, setSelectedBale] = useState<Bale | 'unsorted' | null>(null);

  // Search & Edit State
  const [search, setSearch] = useState('');
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [showModal, setShowModal] = useState(false);

  // Derived: Filtered Products based on view (Bale or Search)
  const viewProducts = useMemo(() => {
    if (!selectedBale) return [];

    let filtered = [];
    if (selectedBale === 'unsorted') {
      // Show products that don't match any known bale ID
      const baleIds = bales.map(b => b.id);
      filtered = products.filter(p => !p.baleBatch || !baleIds.includes(p.baleBatch));
    } else {
      // Show products for specific bale
      filtered = products.filter(p => p.baleBatch === selectedBale.id);
    }

    // Apply text search on top
    if (search) {
      filtered = filtered.filter(p => 
        p.name.toLowerCase().includes(search.toLowerCase()) || 
        p.brand.toLowerCase().includes(search.toLowerCase())
      );
    }
    return filtered;
  }, [selectedBale, products, search, bales]);

  // Derived: Unsorted Count for the main dashboard
  const unsortedCount = useMemo(() => {
    const baleIds = bales.map(b => b.id);
    return products.filter(p => !p.baleBatch || !baleIds.includes(p.baleBatch)).length;
  }, [products, bales]);

  const handleSave = (product: Product) => {
    db.updateProduct(product);
    setProducts(db.getProducts());
    setShowModal(false);
    setEditingProduct(null);
  };

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to delete this product? This will not affect existing orders but will remove it from the product list.')) {
      db.deleteProduct(id);
      setProducts(db.getProducts());
    }
  };

  // --- VIEW 1: BALE SELECTION ---
  if (!selectedBale) {
    return (
      <div className="space-y-6 pb-32 px-1">
        <div className="flex flex-col gap-2 px-2">
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Inventory Groups</h1>
          <p className="text-gray-500 font-bold text-sm">Select a Bale/Batch to view its items.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 px-2">
          {bales.map(bale => {
            const itemCount = products.filter(p => p.baleBatch === bale.id).length;
            const stockCount = products.filter(p => p.baleBatch === bale.id).reduce((sum, p) => sum + p.stock, 0);

            return (
              <button 
                key={bale.id}
                onClick={() => setSelectedBale(bale)}
                className="bg-white rounded-[2.5rem] p-7 border-2 border-pawPink/30 hover:border-pawPinkDark shadow-sm hover:shadow-xl transition-all group text-left relative overflow-hidden active:scale-95"
              >
                <div className="flex justify-between items-start mb-6 relative z-10">
                  <div>
                    <span className="text-[10px] font-black uppercase text-pawPinkDark bg-pawPink/20 px-3 py-1 rounded-full mb-2 inline-block tracking-widest">
                      {bale.id}
                    </span>
                    <h3 className="font-black text-gray-800 text-xl tracking-tight leading-none mb-1">{bale.name}</h3>
                    <p className="text-[11px] font-bold text-gray-400 uppercase tracking-widest">{bale.status}</p>
                  </div>
                </div>

                <div className="flex gap-4 relative z-10">
                  <div className="bg-pawSoftBlue px-4 py-3 rounded-2xl flex-1">
                    <p className="text-[9px] text-blue-600 font-black uppercase tracking-wider mb-1">Encoded</p>
                    <p className="text-xl font-black text-gray-800">{itemCount}</p>
                  </div>
                  <div className="bg-pawMint px-4 py-3 rounded-2xl flex-1">
                    <p className="text-[9px] text-green-700 font-black uppercase tracking-wider mb-1">In Stock</p>
                    <p className="text-xl font-black text-gray-800">{stockCount}</p>
                  </div>
                </div>

                <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-br from-pawPink/20 to-transparent rounded-bl-[100px] -mr-8 -mt-8"></div>
              </button>
            );
          })}

          {/* Unsorted / General Card */}
          <button 
            onClick={() => setSelectedBale('unsorted')}
            className="bg-gray-50 rounded-[2.5rem] p-7 border-2 border-dashed border-gray-300 hover:border-gray-400 shadow-inner hover:bg-gray-100 transition-all group text-left relative active:scale-95"
          >
            <div className="flex items-center gap-3 mb-6">
              <div className="bg-gray-200 p-3 rounded-full">
                <PawIcon className="w-6 h-6 text-gray-400" />
              </div>
              <div>
                <h3 className="font-black text-gray-600 text-lg tracking-tight leading-none">General / Unsorted</h3>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">Items without ID</p>
              </div>
            </div>
            <div className="bg-white px-4 py-3 rounded-2xl inline-block border border-gray-100">
               <p className="text-[9px] text-gray-400 font-black uppercase tracking-wider mb-1">Count</p>
               <p className="text-xl font-black text-gray-600">{unsortedCount}</p>
            </div>
          </button>
        </div>

        {/* Global Add (No specific bale selected) */}
        <div className="fixed bottom-24 lg:bottom-10 right-6 lg:right-10 z-40">
           <button 
             onClick={() => { setEditingProduct(null); setShowModal(true); }}
             className="bg-pawPinkDark text-white w-16 h-16 rounded-full shadow-2xl flex items-center justify-center active:scale-90 transition-all hover:bg-red-400"
           >
             <PlusIcon className="w-8 h-8" />
           </button>
        </div>

        {showModal && (
          <ProductModal 
            product={editingProduct} 
            defaultBale="" 
            bales={bales}
            onClose={() => setShowModal(false)} 
            onSave={handleSave} 
          />
        )}
      </div>
    );
  }

  // --- VIEW 2: PRODUCT LIST (INSIDE BALE) ---
  const isUnsorted = selectedBale === 'unsorted';
  const baleTitle = isUnsorted ? 'Unsorted Items' : (selectedBale as Bale).name;
  const baleId = isUnsorted ? '' : (selectedBale as Bale).id;

  return (
    <div className="space-y-6 pb-32 px-1 animate-fadeIn">
      {/* Header & Back */}
      <div className="flex flex-col gap-4 px-2">
        <button 
          onClick={() => { setSelectedBale(null); setSearch(''); }}
          className="self-start flex items-center gap-2 text-gray-500 hover:text-pawPinkDark font-black text-xs uppercase tracking-widest transition-colors mb-2"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" /></svg>
          Back to Bales
        </button>

        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-black text-gray-800 tracking-tight">{baleTitle}</h1>
            <p className="text-gray-400 font-bold text-xs uppercase tracking-widest mt-1">
              {viewProducts.length} Items Found
            </p>
          </div>

          <button 
            onClick={() => { setEditingProduct(null); setShowModal(true); }}
            className="bg-pawMint text-green-800 px-6 py-3 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center gap-2 shadow-lg shadow-green-100 active:scale-95 transition-all hover:bg-green-300 self-start md:self-auto"
          >
            <PlusIcon className="w-4 h-4" /> Add Item Here
          </button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="px-2">
        <div className="flex items-center w-full bg-white border-2 border-pawPink/40 focus-within:border-pawPinkDark rounded-[1.5rem] px-5 py-1.5 shadow-sm transition-all group">
          <SearchIcon className="text-gray-400 group-focus-within:text-pawPinkDark w-6 h-6 flex-shrink-0 transition-colors" />
          <input 
            type="text" 
            placeholder={`Search inside ${isUnsorted ? 'list' : baleTitle}...`}
            className="w-full bg-transparent border-none p-4 text-lg font-bold text-gray-700 placeholder:text-gray-300 focus:ring-0"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          {search && (
            <button onClick={() => setSearch('')} className="text-gray-300 hover:text-gray-500 p-2">
              <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" /></svg>
            </button>
          )}
        </div>
      </div>

      {/* Products Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 px-2">
        {viewProducts.map(product => (
          <div key={product.id} className="bg-white rounded-[2.5rem] p-7 border-2 border-pawPink/20 shadow-lg hover:shadow-pawPink/20 hover:border-pawPink transition-all group animate-fadeIn">
            <div className="flex justify-between items-start mb-6">
              <div className="flex-1 mr-4">
                <span className="text-[9px] font-black uppercase text-pawPinkDark bg-pawPink/20 px-3 py-1 rounded-full mb-2 inline-block tracking-[0.15em]">
                  {product.brand || 'No Brand'}
                </span>
                <h4 className="font-black text-gray-800 text-xl leading-tight tracking-tight">{product.name}</h4>
              </div>
              <div className={`shrink-0 px-4 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest ${product.stock < 5 ? 'bg-red-100 text-red-600' : 'bg-pawMint text-green-800'}`}>
                {product.stock} left
              </div>
            </div>

            <div className="flex justify-between items-end">
              <div className="space-y-1">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Selling Price</p>
                <p className="text-3xl font-black text-gray-800">₱{product.sellingPrice}</p>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={() => handleDelete(product.id)}
                  className="p-3 bg-pawCream/40 text-gray-300 hover:text-red-500 rounded-2xl active:scale-90 transition-all border border-transparent hover:border-red-100"
