                    <span className={`text-[10px] font-black uppercase tracking-widest px-2 py-1 rounded-md ${
                        bale.status === 'Sold Out' ? 'bg-gray-200 text-gray-500' : 'bg-blue-50 text-blue-600'
                    }`}>{bale.status}</span>
                  </div>
                  <h3 className="text-2xl font-black text-gray-800 tracking-tighter leading-none">{bale.name}</h3>
                </div>
                <button onClick={() => { setSelectedBale(bale); setShowModal(true); }} className="p-2 text-gray-300 hover:text-pawPinkDark transition-colors">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                </button>
              </div>

              {/* Profit / ROI Hero Section */}
              <div className={`rounded-[2rem] p-6 mb-6 relative overflow-hidden ${isProfitable ? 'bg-pawMint' : 'bg-red-50 border border-red-100'}`}>
                <p className={`text-[10px] font-black uppercase tracking-widest mb-1 ${isProfitable ? 'text-green-800' : 'text-red-500'}`}>
