        {/* Recent Transactions */}
        <div className="bg-white p-8 rounded-[3rem] border-2 border-pawPink/20 shadow-lg flex flex-col h-[500px]">
          <div className="flex justify-between items-center mb-6 shrink-0">
             <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight">History</h3>

             {/* Category Filter */}
             <select 
               value={categoryFilter}
               onChange={(e) => setCategoryFilter(e.target.value)}
               className="bg-gray-100 text-gray-500 text-[10px] font-black uppercase tracking-widest py-2 px-3 rounded-xl border-none outline-none focus:ring-2 focus:ring-pawPink"
             >
               <option value="All">All Categories</option>
               {categories.map(c => <option key={c} value={c}>{c}</option>)}
             </select>
          </div>

          <div className="overflow-y-auto custom-scrollbar flex-1 pr-2 space-y-3">
            {filteredTransactions.map(t => (
              <div key={t.id} className="flex items-center justify-between p-4 bg-gray-50 rounded-[2rem] border border-gray-100 hover:border-pawPink transition-all">
                <div className="flex items-center gap-4">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center text-xs font-black shrink-0 ${t.type === 'Expense' ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}>
                    {t.type.charAt(0)}
                  </div>
                  <div>
                    <p className="text-sm font-black text-gray-800 leading-tight">{t.category}</p>
                    <p className="text-[10px] text-gray-400 uppercase font-bold tracking-wider">{t.wallet} • {new Date(t.createdAt).toLocaleDateString()}</p>
                    {t.note && <p className="text-[10px] text-gray-400 italic mt-0.5">"{t.note}"</p>}
                  </div>
                </div>
                <p className={`font-black text-sm whitespace-nowrap ${t.type === 'Expense' || t.type === 'Withdrawal' ? 'text-red-500' : 'text-green-500'}`}>
                  {t.type === 'Expense' || t.type === 'Withdrawal' ? '-' : '+'}₱{t.amount.toLocaleString()}
                </p>
              </div>
            ))}
            {filteredTransactions.length === 0 && (
              <div className="text-center py-20 opacity-50 flex flex-col items-center">
                 <div className="text-4xl mb-2">🧾</div>
                 <p className="font-bold text-gray-400 text-xs uppercase tracking-widest">No logs found</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {showTxModal && (
        <TransactionModal 
          categories={categories}
          onClose={() => setShowTxModal(false)} 
          onSave={handleAddTx} 
        />
      )}
    </div>
  );
};

