import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../services/dbService';
import { Bale, Order, Product } from '../types';
import { PlusIcon, PawIcon, SearchIcon, CartIcon } from '../components/Icons';

const Bales: React.FC = () => {
  const [bales, setBales] = useState(db.getBales());
  const [showModal, setShowModal] = useState(false);
  const [selectedBale, setSelectedBale] = useState<Bale | null>(null);
  const [viewingBale, setViewingBale] = useState<Bale | null>(null);

  // Fetch data for calculations
  const products = db.getProducts();
  const orders = db.getOrders();

  const getBaleStats = (baleId: string) => {
    // Find all products linked to this bale
    const baleProducts = products.filter(p => p.baleBatch === baleId);
    const baleProductIds = baleProducts.map(p => p.id);

    // Find all orders linked to those products
    const baleOrders = orders.filter(o => baleProductIds.includes(o.productId));

    // Separate Live vs Manual (Off-Live)
    const liveOrders = baleOrders.filter(o => o.sessionId !== 'OFF_LIVE');
    const manualOrders = baleOrders.filter(o => o.sessionId === 'OFF_LIVE');

    const liveSold = liveOrders.reduce((sum, o) => sum + o.quantity, 0);
    const liveRevenue = liveOrders.reduce((sum, o) => sum + o.totalPrice, 0);

    const manualSold = manualOrders.reduce((sum, o) => sum + o.quantity, 0);
    const manualRevenue = manualOrders.reduce((sum, o) => sum + o.totalPrice, 0);

    const soldCount = liveSold + manualSold;
    const revenue = liveRevenue + manualRevenue;

    return { soldCount, revenue, liveSold, liveRevenue, manualSold, manualRevenue };
  };

  // Auto-update status when Sold Out
  useEffect(() => {
    let hasUpdates = false;
    const updatedBales = bales.map(bale => {
      const stats = getBaleStats(bale.id);
      if (bale.itemCount > 0 && stats.soldCount >= bale.itemCount && bale.status !== 'Sold Out') {
        hasUpdates = true;
        const newBale: Bale = { ...bale, status: 'Sold Out' };
        db.updateBale(newBale); // Persist to DB
        return newBale;
      }
      return bale;
    });

    if (hasUpdates) {
      setBales(updatedBales);
    }
  });

  const handleSaveBale = (bale: Bale) => {
    db.updateBale(bale);
    setBales(db.getBales());
    setShowModal(false);
    setSelectedBale(null);
  };

  const handleDeleteBale = (id: string) => {
    if (confirm('Permanently remove this bale record? This will NOT delete products assigned to this batch identifier.')) {
      db.deleteBale(id);
      setBales(db.getBales());
      if (viewingBale?.id === id) setViewingBale(null);
    }
  };

  // --- DETAIL VIEW ---
  if (viewingBale) {
    return (
      <BaleDetails 
        bale={viewingBale} 
        onBack={() => setViewingBale(null)} 
        stats={getBaleStats(viewingBale.id)}
      />
    );
  }

  // --- LIST VIEW ---
  return (
    <div className="space-y-6 pb-32 px-1">
      <div className="flex items-center justify-between px-2">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Bale Track</h1>
          <p className="text-gray-500 font-bold text-sm">Monitor sales performance & ROI per sack.</p>
        </div>
        <button 
          onClick={() => { setSelectedBale(null); setShowModal(true); }}
          className="bg-pawSoftBlue text-blue-800 px-6 py-3 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center gap-2 shadow-lg shadow-blue-50 active:scale-95 transition-all hover:bg-blue-200"
        >
          <PlusIcon className="w-4 h-4" /> New Batch
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 px-2">
        {bales.map(bale => {
          const stats = getBaleStats(bale.id);
          const percentSold = bale.itemCount > 0 ? Math.min(100, (stats.soldCount / bale.itemCount) * 100) : 0;
          const netProfit = stats.revenue - bale.cost;
          const isProfitable = netProfit > 0;
          const roiPercent = bale.cost > 0 ? (netProfit / bale.cost) * 100 : 0;
          const breakEvenProgress = Math.min(100, (stats.revenue / bale.cost) * 100);

          return (
            <div 
              key={bale.id} 
              onClick={() => setViewingBale(bale)}
              className="bg-white rounded-[3rem] p-8 border-2 border-pawPink/20 shadow-xl overflow-hidden relative group animate-fadeIn hover:border-pawPinkDark transition-all cursor-pointer active:scale-[0.98]"
            >

              {/* Header */}
              <div className="flex justify-between items-start mb-6">
                <div>
                  <div className="flex items-center gap-2 mb-2">
                    <span className="text-[10px] text-white bg-gray-800 px-2 py-1 rounded-md font-black uppercase tracking-widest">{bale.id}</span>
                    <span className={`text-[10px] font-black uppercase tracking-widest px-2 py-1 rounded-md ${
                        bale.status === 'Sold Out' ? 'bg-gray-200 text-gray-500' : 'bg-blue-50 text-blue-600'
                    }`}>{bale.status}</span>
                  </div>
                  <h3 className="text-2xl font-black text-gray-800 tracking-tighter leading-none">{bale.name}</h3>
                </div>
                <button 
                  onClick={(e) => { e.stopPropagation(); setSelectedBale(bale); setShowModal(true); }} 
                  className="p-2 text-gray-300 hover:text-pawPinkDark transition-colors bg-white rounded-full shadow-sm hover:shadow-md z-10"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                </button>
              </div>

              {/* Profit / ROI Hero Section */}
              <div className={`rounded-[2rem] p-6 mb-6 relative overflow-hidden ${isProfitable ? 'bg-pawMint' : 'bg-red-50 border border-red-100'}`}>
                <div className="flex justify-between items-start mb-1">
                    <p className={`text-[10px] font-black uppercase tracking-widest ${isProfitable ? 'text-green-800' : 'text-red-500'}`}>
                      {isProfitable ? '✨ Net Profit' : '📉 Capital Recovery'}
                    </p>
                    {isProfitable && (
                        <span className="bg-white/60 px-2 py-1 rounded-lg text-[10px] font-black text-green-800 backdrop-blur-sm">
                            ROI: {roiPercent.toFixed(1)}%
                        </span>
                    )}
                </div>

                <div className="flex items-baseline gap-1">
                   <h2 className={`text-4xl font-black tracking-tighter ${isProfitable ? 'text-green-900' : 'text-red-600'}`}>
                     {isProfitable ? '+' : ''}₱{Math.abs(netProfit).toLocaleString()}
                   </h2>
                   {!isProfitable && <span className="text-xs font-bold text-red-400">needed to break even</span>}
                </div>

                {isProfitable && (
                   <div className="absolute -bottom-4 -right-4 text-green-200/40 transform rotate-12 pointer-events-none">
                      <PawIcon className="w-32 h-32" />
                   </div>
                )}

                {/* Capital Recovery Bar */}
                {!isProfitable && (
                   <div className="mt-4 w-full bg-red-200/50 h-2 rounded-full overflow-hidden">
                      <div className="h-full bg-red-500 rounded-full transition-all duration-1000" style={{ width: `${breakEvenProgress}%` }}></div>
                   </div>
                )}
              </div>

              {/* Channel Breakdown */}
              <div className="flex gap-3 mb-6">
                <div className="flex-1 bg-red-50 p-4 rounded-2xl border border-red-100/50">
                    <div className="flex items-center gap-1 mb-1">
                        <span className="w-1.5 h-1.5 rounded-full bg-red-500"></span>
                        <p className="text-[9px] font-black text-red-400 uppercase tracking-wider">Live Sales</p>
                    </div>
                    <p className="font-black text-gray-800">₱{stats.liveRevenue.toLocaleString()}</p>
                    <p className="text-[9px] text-gray-400 font-bold">{stats.liveSold} items</p>
                </div>
                <div className="flex-1 bg-blue-50 p-4 rounded-2xl border border-blue-100/50">
                    <div className="flex items-center gap-1 mb-1">
                        <span className="w-1.5 h-1.5 rounded-full bg-blue-500"></span>
                        <p className="text-[9px] font-black text-blue-400 uppercase tracking-wider">Manual</p>
                    </div>
                    <p className="font-black text-gray-800">₱{stats.manualRevenue.toLocaleString()}</p>
                    <p className="text-[9px] text-gray-400 font-bold">{stats.manualSold} items</p>
                </div>
              </div>

              {/* Stats Grid */}
              <div className="grid grid-cols-2 gap-4 mb-6">
                 {/* Capital vs Revenue */}
                 <div className="bg-pawCream/40 p-4 rounded-2xl">
                    <div className="flex justify-between items-center mb-1">
                      <span className="text-[9px] font-black text-gray-400 uppercase tracking-wider">Invested</span>
                      <span className="text-[9px] font-black text-gray-400 uppercase tracking-wider">Total Sales</span>
                    </div>
                    <div className="flex justify-between items-center">
                       <span className="font-bold text-gray-500 text-sm">₱{bale.cost.toLocaleString()}</span>
                       <span className="text-gray-300">→</span>
                       <span className="font-black text-gray-800 text-lg">₱{stats.revenue.toLocaleString()}</span>
                    </div>
                 </div>

                 {/* Item Counts */}
                 <div className="bg-pawSoftBlue/40 p-4 rounded-2xl">
                    <p className="text-[9px] font-black text-blue-400 uppercase tracking-wider mb-1">Total Items</p>
                    <div className="flex items-baseline gap-1">
                       <span className="font-black text-gray-800 text-2xl">{bale.itemCount}</span>
                       <span className="text-[10px] font-bold text-gray-400">pcs</span>
                    </div>
                 </div>
              </div>

              {/* Sales Progress Bar */}
              <div>
                <div className="flex justify-between text-[11px] font-black text-gray-500 uppercase tracking-widest mb-2">
                  <span>Sales Progress</span>
                  <span>{stats.soldCount} / {bale.itemCount} Sold ({percentSold.toFixed(0)}%)</span>
                </div>
                <div className="w-full h-5 bg-gray-100 rounded-full overflow-hidden shadow-inner border border-gray-100">
                  <div 
                    className={`h-full transition-all duration-1000 rounded-full flex items-center justify-end px-2 ${
                      percentSold >= 100 ? 'bg-green-400' : 'bg-pawPinkDark'
                    }`} 
                    style={{ width: `${percentSold}%` }}
                  >
                  </div>
                </div>
              </div>

              {/* Delete Action */}
               <button 
                 onClick={(e) => { e.stopPropagation(); handleDeleteBale(bale.id); }} 
                 className="absolute bottom-8 right-8 text-gray-200 hover:text-red-400 transition-colors p-2 z-10"
                 title="Delete Bale"
               >
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
               </button>

               <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-br from-pawPink/20 to-transparent rounded-bl-[100px] -mr-8 -mt-8 pointer-events-none"></div>
            </div>
          );
        })}
        {bales.length === 0 && (
          <div className="col-span-full py-32 text-center opacity-30 flex flex-col items-center">
             <div className="text-6xl mb-4">📦</div>
             <p className="font-black uppercase tracking-[0.3em] text-sm">No inventory batches logged</p>
          </div>
        )}
      </div>

      {showModal && <BaleModal bale={selectedBale} onClose={() => { setShowModal(false); setSelectedBale(null); }} onSave={handleSaveBale} />}
    </div>
  );
};

// --- BALE DETAILS COMPONENT ---
const BaleDetails: React.FC<{ bale: Bale; onBack: () => void; stats: any }> = ({ bale, onBack, stats }) => {
  const [searchTerm, setSearchTerm] = useState('');

  // Data Fetching
  const allOrders = useMemo(() => db.getOrders(), []);
  const allProducts = useMemo(() => db.getProducts(), []);
  const sessions = useMemo(() => db.getSessions(), []);

  // Filter for orders related to this bale
  const baleOrders = useMemo(() => {
    const productsInBale = allProducts.filter(p => p.baleBatch === bale.id).map(p => p.id);
    return allOrders.filter(o => productsInBale.includes(o.productId)).sort((a, b) => b.createdAt - a.createdAt);
  }, [allOrders, allProducts, bale.id]);

  // Filter by search
  const filteredOrders = useMemo(() => {
    return baleOrders.filter(o => 
      o.customerUsername.toLowerCase().includes(searchTerm.toLowerCase()) || 
      o.productName.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [baleOrders, searchTerm]);

  const getSessionName = (sessionId: string) => {
    if (sessionId === 'OFF_LIVE') return 'Manual / Off-Live';
    const s = sessions.find(s => s.id === sessionId);
    return s ? s.name : 'Unknown Session';
  };

  const netProfit = stats.revenue - bale.cost;
  const isProfitable = netProfit > 0;

  return (
    <div className="space-y-6 pb-32 px-1 animate-fadeIn">
      {/* Back Button */}
      <button 
        onClick={onBack}
        className="flex items-center gap-2 text-gray-500 hover:text-pawPinkDark font-black text-xs uppercase tracking-widest transition-colors mb-2 px-2"
      >
        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" /></svg>
        Back to Bale List
      </button>

      {/* Hero Stats */}
      <div className="bg-white rounded-[3rem] p-8 border-2 border-pawPink/30 shadow-lg relative overflow-hidden">
         <div className="relative z-10">
           <div className="flex items-center gap-2 mb-2">
             <span className="text-[10px] text-white bg-gray-800 px-2 py-1 rounded-md font-black uppercase tracking-widest">{bale.id}</span>
             <span className="text-[10px] font-black uppercase tracking-widest text-blue-500 bg-blue-50 px-2 py-1 rounded-md">{bale.status}</span>
           </div>
           <h1 className="text-3xl font-black text-gray-800 tracking-tighter leading-none mb-6">{bale.name}</h1>

           <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
              <div>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Total Sales</p>
                <p className="text-2xl font-black text-gray-800">₱{stats.revenue.toLocaleString()}</p>
              </div>
              <div>
                <p className={`text-[10px] font-black uppercase tracking-widest mb-1 ${isProfitable ? 'text-green-600' : 'text-red-400'}`}>Net Profit</p>
                <p className={`text-2xl font-black ${isProfitable ? 'text-green-700' : 'text-red-500'}`}>{isProfitable ? '+' : ''}₱{netProfit.toLocaleString()}</p>
              </div>
              <div>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Items Sold</p>
                <p className="text-2xl font-black text-gray-800">{stats.soldCount} <span className="text-sm text-gray-400">/ {bale.itemCount}</span></p>
              </div>
              <div>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Bale Cost</p>
                <p className="text-2xl font-black text-gray-800">₱{bale.cost.toLocaleString()}</p>
              </div>
           </div>
         </div>
         <div className="absolute top-0 right-0 w-64 h-64 bg-gradient-to-bl from-pawPink/20 to-transparent rounded-bl-[10rem] -mr-10 -mt-10 pointer-events-none"></div>
      </div>

      {/* Orders List Section */}
      <div className="px-2">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
          <h2 className="text-xl font-black text-gray-800 tracking-tight">Order History <span className="text-gray-400 text-sm">({filteredOrders.length})</span></h2>
          <div className="relative">
            <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input 
               type="text" 
               placeholder="Search orders..." 
               value={searchTerm}
               onChange={(e) => setSearchTerm(e.target.value)}
               className="pl-12 pr-4 py-3 rounded-2xl bg-white border border-gray-200 focus:border-pawPinkDark focus:ring-2 focus:ring-pawPink/20 outline-none font-bold text-sm w-full md:w-64"
            />
          </div>
        </div>

        <div className="space-y-4">
          {filteredOrders.length === 0 ? (
             <div className="bg-gray-50 rounded-[2rem] p-12 text-center border-2 border-dashed border-gray-200">
                <CartIcon className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                <p className="font-bold text-gray-400">No orders found for this bale.</p>
             </div>
          ) : (
            filteredOrders.map(order => {
               const isManual = order.sessionId === 'OFF_LIVE';
               return (
                 <div key={order.id} className="bg-white p-5 rounded-[2rem] border border-gray-100 shadow-sm hover:shadow-md transition-all flex flex-col md:flex-row md:items-center gap-4 group">
                    {/* Icon / Date */}
                    <div className="flex items-center gap-4 md:w-1/4">
