                       <p className="text-sm font-bold text-gray-600">{order.quantity}x {order.productName}</p>
                    </div>

                    {/* Price */}
                    <div className="text-right md:w-1/6">
                       <p className="font-black text-gray-800 text-xl">₱{order.totalPrice}</p>
                       {order.isFreebie && <span className="text-[9px] font-black text-orange-500 uppercase tracking-widest">Freebie</span>}
                    </div>
                 </div>
               );
            })
          )}
        </div>
      </div>
    </div>
  );
};

