                    {/* Customer & Product */}
                    <div className="flex-1">
                       <div className="flex items-center gap-2 mb-1">
                          <span className="font-black text-gray-800 text-lg">@{order.customerUsername}</span>
                          <span className={`text-[9px] px-2 py-0.5 rounded-full font-black uppercase ${order.paymentStatus === 'Paid' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{order.paymentStatus}</span>
                       </div>
                       <p className="text-sm font-bold text-gray-600">{order.quantity}x {order.productName}</p>
                    </div>

                    {/* Price */}
                    <div className="text-right md:w-1/6">
                       <p className="font-black text-gray-800 text-xl">₱{order.totalPrice}</p>
                       {order.isFreebie && <span className="text-[9px] font-black text-orange-500 uppercase tracking-widest">Freebie</span>}
                    </div>
                 </div>
               );
            })
          )}
        </div>
      </div>
    </div>
  );
};

