            >
              <option value="Ordered">Ordered 📦</option>
              <option value="Arrived">Arrived ✅</option>
              <option value="On Sale">On Sale 🔥</option>
              <option value="Sold Out">Sold Out 🏁</option>
            </select>
          </div>

          <div className="flex gap-4 pt-6">
            <button onClick={onClose} className="flex-1 py-5 bg-gray-100 text-gray-400 font-black uppercase text-xs tracking-widest rounded-3xl active:scale-95 transition-all">Cancel</button>
            <button onClick={() => onSave(formData)} className="flex-1 py-5 bg-pawSoftBlue text-blue-700 font-black uppercase text-xs tracking-widest rounded-3xl shadow-xl shadow-blue-50 active:scale-95 transition-all hover:bg-blue-300 hover:text-white">Save Batch</button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Bales;

