import React, { createContext, useContext, useState, useEffect } from 'react';
import { db } from './dbService';

interface SettingsContextType {
  logoUrl: string | null;
  updateLogo: (url: string | null) => void;
}

const SettingsContext = createContext<SettingsContextType | undefined>(undefined);

export const SettingsProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [logoUrl, setLogoUrl] = useState<string | null>(db.getSettings().logoUrl);

  const updateLogo = (url: string | null) => {
    db.updateSettings({ logoUrl: url });
    setLogoUrl(url);
  };

  return (
    <SettingsContext.Provider value={{ logoUrl, updateLogo }}>
      {children}
    </SettingsContext.Provider>
  );
};

export const useSettings = () => {
  const context = useContext(SettingsContext);
  if (!context) {
    throw new Error('useSettings must be used within a SettingsProvider');
  }
  return context;
};

