const Settings: React.FC = () => {
  const { logoUrl, updateLogo } = useSettings();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        updateLogo(base64);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleReset = () => {
    if (confirm('Revert to default logo?')) {
      updateLogo(null);
    }
  };

  return (
    <div className="space-y-6 pb-32 px-1 animate-fadeIn">
      <div className="flex flex-col gap-2 px-2">
        <h1 className="text-3xl font-black text-gray-800 tracking-tight">System Settings</h1>
        <p className="text-gray-500 font-bold text-sm">Customize your shop branding.</p>
      </div>

      <div className="bg-white rounded-[3rem] p-8 border-2 border-pawPink/30 shadow-sm mx-2">
        <div className="flex items-center gap-4 mb-6">
          <div className="bg-pawPink p-3 rounded-2xl">
            <PawIcon className="w-8 h-8 text-pawPinkDark" />
          </div>
          <div>
            <h3 className="text-xl font-black text-gray-800 tracking-tight">System Logo</h3>
            <p className="text-xs font-bold text-gray-400">Replaces all paw icons in the app.</p>
          </div>
        </div>

        <div className="flex flex-col items-center justify-center p-8 bg-gray-50 rounded-[2rem] border-2 border-dashed border-gray-300 gap-6">
          <div className="w-40 h-40 bg-white rounded-full shadow-lg flex items-center justify-center overflow-hidden border-4 border-white relative group">
             {logoUrl ? (
               <img src={logoUrl} alt="Custom Logo" className="w-full h-full object-contain" />
             ) : (
               <div className="text-center">
                 <PawIcon className="w-16 h-16 text-gray-300 mx-auto mb-2" />
                 <span className="text-[10px] uppercase font-black text-gray-300">Default</span>
               </div>
             )}
          </div>

          <div className="flex gap-3">
             <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                accept="image/*" 
                className="hidden" 
              />
             <button 
               onClick={() => fileInputRef.current?.click()}
               className="px-6 py-3 bg-pawPinkDark text-white font-black uppercase text-xs tracking-widest rounded-2xl shadow-lg shadow-pawPinkDark/30 active:scale-95 transition-all hover:bg-red-400"
             >
               Upload Logo
             </button>
             {logoUrl && (
               <button 
                 onClick={handleReset}
                 className="px-6 py-3 bg-gray-200 text-gray-500 font-black uppercase text-xs tracking-widest rounded-2xl active:scale-95 transition-all hover:bg-gray-300"
               >
                 Reset
               </button>
             )}
          </div>
          <p className="text-[10px] text-gray-400 font-bold text-center max-w-xs">
            Recommended: Transparent PNG, Square Aspect Ratio. <br/>
            This logo will appear on the Start Live screen, Sidebar, and replace Paw icons.
          </p>
        </div>
      </div>
    </div>
  );
};

