                   <button 
                     onClick={() => setSelectedProduct(null)} 
                     className="bg-white px-5 py-3 rounded-2xl text-pawPinkDark font-black text-xs uppercase tracking-widest shadow-md active:scale-90 transition-transform hover:bg-pawPink hover:text-white"
                   >
                     Change
                   </button>
                </div>
              ) : (
                <div className="flex items-center bg-pawCream rounded-[1.5rem] px-5 border-2 border-transparent focus-within:border-pawPinkDark transition-all">
