                        <input 
                            type="number"
                            value={itemPrice}
                            onChange={(e) => setItemPrice(e.target.value ? Number(e.target.value) : '')}
                            placeholder="0"
                            disabled={isFreebie}
                            className={`w-full p-4 rounded-[1.5rem] font-black text-gray-800 text-lg border-2 outline-none shadow-sm ${isFreebie ? 'bg-gray-100 border-transparent text-gray-400' : 'bg-white border-transparent focus:border-pawPinkDark'}`}
                        />
                    </div>
                    <div className="flex-1">
                         <label className="text-[11px] font-black text-gray-400 uppercase ml-3 tracking-widest block mb-1">Source Bale</label>
                         <select 
                            value={selectedBaleId}
                            onChange={(e) => setSelectedBaleId(e.target.value)}
                            className="w-full bg-white p-4 rounded-[1.5rem] font-black text-gray-800 text-lg border-2 border-transparent focus:border-pawPinkDark outline-none shadow-sm appearance-none"
                         >
                            <option value="">-- No Bale --</option>
