                                <option key={b.id} value={b.id}>{b.name}</option>
                            ))}
                         </select>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              {/* Quantity */}
              <div className="bg-pawSoftBlue p-2 rounded-[1.5rem] flex items-center justify-between border-2 border-pawSoftBlue/50 shadow-inner">
                <button onClick={() => setQuantity(Math.max(1, quantity - 1))} className="w-14 h-14 flex items-center justify-center bg-white rounded-2xl text-2xl font-black text-blue-600 shadow-md active:scale-90 transition-all hover:bg-blue-50">−</button>
                <div className="flex flex-col items-center">
                  <span className="text-xs font-black text-blue-400 uppercase tracking-widest">Qty</span>
                  <span className="text-3xl font-black text-gray-800 leading-none">{quantity}</span>
                </div>
                <button onClick={() => setQuantity(quantity + 1)} className="w-14 h-14 flex items-center justify-center bg-white rounded-2xl text-2xl font-black text-blue-600 shadow-md active:scale-90 transition-all hover:bg-blue-50">+</button>
              </div>

              {/* Freebie Toggle */}
              <button onClick={() => setIsFreebie(!isFreebie)} className={`flex-col p-4 rounded-[1.5rem] font-black flex items-center justify-center gap-1 border-2 uppercase text-[10px] tracking-widest transition-all shadow-sm ${isFreebie ? 'bg-pawPeach border-orange-300 text-orange-700 shadow-orange-100' : 'bg-pawCream border-transparent text-gray-400'}`}>
                <span className="text-2xl">{isFreebie ? '🎁' : '🏷️'}</span>
                <span>{isFreebie ? 'FREEBIE ON' : 'REGULAR PRICE'}</span>
              </button>
            </div>

            <button 
              onClick={handleAddOrder}
              disabled={!username || !itemName || (!isFreebie && !itemPrice)}
              className={`w-full py-6 rounded-[2rem] text-xl font-black uppercase tracking-widest shadow-2xl transition-all active:scale-95 flex items-center justify-center gap-3 ${(!username || !itemName || (!isFreebie && !itemPrice)) ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-pawPinkDark text-white hover:bg-red-300 hover:shadow-pawPinkDark/50'}`}
            >
              {feedback ? (
                <span className="animate-bounce">✅ {feedback}</span>
              ) : (
                <>ADD TO CART • ₱{isFreebie ? '0' : (Number(itemPrice) * quantity)}</>
              )}
            </button>
          </div>
        </div>
      </div>
      {showEndModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] overflow-hidden shadow-2xl animate-scaleUp p-8 text-center">
             <div className="bg-red-100 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6"><span className="text-4xl">🛑</span></div>
             <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight mb-2">End Live Session?</h3>
             <p className="text-gray-500 font-bold text-xs mb-8 leading-relaxed">No more orders can be encoded for this session. Are you sure you want to finish?</p>
             <div className="flex gap-4">
                <button onClick={() => setShowEndModal(false)} className="flex-1 py-4 bg-gray-100 text-gray-500 font-black uppercase text-xs tracking-widest rounded-2xl hover:bg-gray-200 transition-all">Cancel</button>
                <button onClick={confirmEndSession} className="flex-1 py-4 bg-red-500 text-white font-black uppercase text-xs tracking-widest rounded-2xl shadow-lg shadow-red-200 hover:bg-red-600 transition-all">End Live</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

