  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
      <div className="bg-white w-full max-w-md rounded-[2.5rem] overflow-hidden shadow-2xl animate-scaleUp">
        <div className="bg-pawPinkDark p-8 relative overflow-hidden">
            <div className="absolute top-0 right-0 -mt-4 -mr-4 w-24 h-24 bg-white/10 rounded-full blur-2xl"></div>
            <h3 className="text-2xl font-black text-white uppercase tracking-tight relative z-10">New Live Session</h3>
            <p className="text-white/80 font-bold text-xs uppercase mt-1 tracking-widest relative z-10">Let's get selling!</p>
        </div>
        <div className="p-8 space-y-6">
          <div>
            <label className="text-[11px] font-black text-gray-400 uppercase ml-3 tracking-widest block mb-2">Session Name</label>
            <input autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Sunday Night Live 🌙" className="w-full bg-pawCream p-5 rounded-[1.5rem] border-2 border-transparent focus:border-pawPinkDark font-bold text-gray-800 text-lg placeholder:text-gray-400 outline-none transition-all" />
          </div>
          <div className="flex gap-4 pt-2">
            <button onClick={onClose} className="flex-1 py-5 bg-gray-100 text-gray-400 font-black uppercase text-xs tracking-widest rounded-[1.5rem] active:scale-95 transition-all hover:bg-gray-200">Cancel</button>
            <button onClick={() => { if(name) onStart(name); }} disabled={!name.trim()} className="flex-1 py-5 bg-pawPinkDark text-white font-black uppercase text-xs tracking-widest rounded-[1.5rem] shadow-xl shadow-pawPinkDark/20 active:scale-95 transition-all hover:bg-red-400 disabled:opacity-50 disabled:cursor-not-allowed">Start Live</button>
          </div>
