  const isOffLive = session.id === OFF_LIVE_ID;
  const totalRevenue = orders.reduce((sum, o) => sum + o.totalPrice, 0);
  const unpaidCount = orders.filter(o => o.paymentStatus !== PaymentStatus.PAID).length;

  return (
    <button 
      onClick={onClick}
      className={`bg-white rounded-[2.5rem] p-7 border-2 ${isOffLive ? 'border-blue-200 hover:border-blue-400' : 'border-pawPink/30 hover:border-pawPinkDark'} shadow-sm hover:shadow-xl transition-all group text-left relative overflow-hidden active:scale-95 w-full`}
    >
      <div className="flex justify-between items-start mb-6 relative z-10">
        <div>
          <h3 className="font-black text-gray-800 text-xl tracking-tight leading-none mb-2">{session.name}</h3>
          <p className="text-[11px] font-black text-gray-400 uppercase tracking-widest">{session.date}</p>
        </div>
        {isOffLive ? (
           <span className="bg-blue-100 text-blue-500 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest">Manual</span>
        ) : (
          session.isOpen ? (
            <span className="bg-red-500 text-white px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest animate-pulse">Live</span>
          ) : (
            <span className="bg-gray-100 text-gray-500 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest">Ended</span>
          )
        )}
      </div>

      <div className="flex gap-4 relative z-10">
        <div className="bg-pawSoftBlue px-4 py-3 rounded-2xl flex-1">
          <p className="text-[9px] text-blue-600 font-black uppercase tracking-wider mb-1">Orders</p>
          <p className="text-xl font-black text-gray-800">{orders.length}</p>
        </div>
        <div className="bg-pawMint px-4 py-3 rounded-2xl flex-1">
          <p className="text-[9px] text-green-700 font-black uppercase tracking-wider mb-1">Sales</p>
          <p className="text-xl font-black text-gray-800">₱{totalRevenue.toLocaleString()}</p>
        </div>
      </div>

      {unpaidCount > 0 && (
        <div className="mt-4 bg-red-50 px-4 py-2 rounded-xl border border-red-100 flex items-center gap-2 relative z-10">
           <div className="w-2 h-2 bg-red-500 rounded-full"></div>
           <p className="text-[10px] font-black text-red-600 uppercase tracking-wider">{unpaidCount} Pending Payments</p>
        </div>
      )}

      <div className={`absolute top-0 right-0 w-32 h-32 bg-gradient-to-br ${isOffLive ? 'from-blue-50' : 'from-pawPink/20'} to-transparent rounded-bl-[100px] -mr-8 -mt-8`}></div>
    </button>
  );
};

const OrderCard: React.FC<{ order: GroupedOrder; onEdit: () => void; onDelete: () => void }> = ({ order, onEdit, onDelete }) => {
  const getStatusColor = (status: string) => {
    switch (status) {
      case PaymentStatus.PAID: return 'bg-green-100 text-green-700';
      case PaymentStatus.UNPAID: return 'bg-red-100 text-red-700';
      case ShippingStatus.SHIPPED: return 'bg-blue-100 text-blue-700';
      case ShippingStatus.PENDING: return 'bg-yellow-100 text-yellow-700';
      case ShippingStatus.CANCELLED: return 'bg-gray-200 text-gray-500';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  return (
    <div className="bg-white rounded-[2rem] p-6 border border-pawPink/40 shadow-sm hover:shadow-md transition-all group animate-fadeIn">
      <div className="flex justify-between items-start mb-5">
        <div>
          <h4 className="font-black text-gray-800 text-xl tracking-tight leading-none mb-1">@{order.customerUsername}</h4>
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{new Date(order.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
        </div>
        <div className="flex flex-col gap-1.5 items-end shrink-0">
          <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-tighter ${getStatusColor(order.paymentStatus)}`}>
            {order.paymentStatus}
          </span>
          <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-tighter ${getStatusColor(order.shippingStatus)}`}>
            {order.shippingStatus}
          </span>
        </div>
      </div>

      <div className="bg-pawCream/40 p-4 rounded-2xl mb-6 shadow-inner border border-pawCream relative overflow-hidden">
         {/* Group Indicator */}
         {order.quantity > 1 && (
            <div className="absolute top-0 right-0 bg-pawPinkDark text-white px-3 py-1 rounded-bl-xl text-[10px] font-black uppercase tracking-widest shadow-sm">
               Bundle
            </div>
         )}

        <div className="flex justify-between items-center relative z-10">
          <span className="text-sm font-black text-gray-600 truncate mr-3">
             <span className="text-lg text-pawPinkDark mr-1">{order.quantity}x</span> {order.productName}
          </span>
          <span className="font-black text-gray-800 text-lg">₱{order.totalPrice.toLocaleString()}</span>
        </div>
        {(order.amountPaid > 0 || order.paymentStatus === PaymentStatus.PARTIAL) && (
          <div className="mt-3 text-[10px] flex justify-between text-gray-500 font-black border-t border-pawPink/30 pt-2 uppercase tracking-tighter relative z-10">
            <span>Paid: ₱{order.amountPaid.toLocaleString()}</span>
            <span className="text-pawPinkDark">Balance: ₱{(order.totalPrice - order.amountPaid).toLocaleString()}</span>
          </div>
        )}
      </div>

      <div className="flex gap-2">
        <button 
          onClick={onEdit}
          className="flex-1 py-3 bg-pawPinkDark text-white font-black rounded-xl text-xs uppercase tracking-widest shadow-sm active:scale-95 transition-all"
        >
          Manage
        </button>
        <button 
          onClick={onDelete}
          className="px-4 py-3 border-2 border-pawCream text-gray-300 rounded-xl hover:text-red-400 hover:border-red-100 active:scale-90 transition-all"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
        </button>
      </div>
    </div>
  );
};

const StatusModal: React.FC<{ order: GroupedOrder; onClose: () => void; onSave: (order: GroupedOrder) => void }> = ({ order, onClose, onSave }) => {
  const [formData, setFormData] = useState<GroupedOrder>({ ...order });

  return (
    <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center p-0 md:p-4 bg-black/40 backdrop-blur-sm animate-fadeIn">
      <div className="bg-white w-full max-w-lg rounded-t-[3rem] md:rounded-[3rem] overflow-hidden shadow-2xl animate-scaleUp">
        <div className="bg-pawPink p-8">
          <h3 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Order Status</h3>
          <p className="text-pawPinkDark font-black text-xs uppercase tracking-widest mt-1">Customer: @{order.customerUsername}</p>
          {order.quantity > 1 && (
             <p className="text-gray-500 font-bold text-[10px] mt-2 bg-white/50 inline-block px-2 py-1 rounded-lg">
                Applying updates to {order.quantity} items
             </p>
          )}
        </div>
        <div className="p-8 space-y-5 pb-10 md:pb-8">
          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-2">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Payment Status</label>
              <select 
                value={formData.paymentStatus}
                onChange={(e) => setFormData({...formData, paymentStatus: e.target.value as PaymentStatus})}
                className="w-full bg-pawCream p-4 rounded-2xl border-none font-black mt-1 text-gray-800 appearance-none"
              >
                {Object.values(PaymentStatus).map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>

            <div className="col-span-2">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Payment Method</label>
              <select 
                value={formData.paymentMethod || ''}
                onChange={(e) => setFormData({...formData, paymentMethod: e.target.value as PaymentMethod})}
                className="w-full bg-pawCream p-4 rounded-2xl border-none font-black mt-1 text-gray-800 appearance-none"
              >
                <option value="">None Selected</option>
                {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
              </select>
            </div>

            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Amount Paid (₱)</label>
              <input 
                type="number"
                value={formData.amountPaid}
                onChange={(e) => {
                  const val = Number(e.target.value);
                  setFormData({
                    ...formData, 
                    amountPaid: val, 
                    paymentStatus: val >= formData.totalPrice ? PaymentStatus.PAID : (val > 0 ? PaymentStatus.PARTIAL : PaymentStatus.UNPAID)
                  });
                }}
                className="w-full bg-pawCream p-4 rounded-2xl border-none font-black mt-1 text-gray-800"
              />
            </div>

            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Shipping</label>
              <select 
                value={formData.shippingStatus}
                onChange={(e) => setFormData({...formData, shippingStatus: e.target.value as ShippingStatus})}
                className="w-full bg-pawCream p-4 rounded-2xl border-none font-black mt-1 text-gray-800 appearance-none"
              >
                {Object.values(ShippingStatus).map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
          </div>

          <div className="flex gap-4 pt-6">
            <button onClick={onClose} className="flex-1 py-5 bg-gray-100 text-gray-400 font-black uppercase text-xs tracking-widest rounded-3xl active:scale-95 transition-all">Cancel</button>
            <button onClick={() => onSave(formData)} className="flex-1 py-5 bg-pawPinkDark text-white font-black uppercase text-xs tracking-widest rounded-3xl shadow-lg active:scale-95 transition-all">Apply Update</button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Orders;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { db } from '../services/dbService';
import { useSettings } from '../services/SettingsContext';
import { Product, Order, PaymentStatus, ShippingStatus, LiveSession, Bale } from '../types';
import { PlusIcon, PawIcon, CartIcon } from '../components/Icons';

const OFF_LIVE_ID = 'OFF_LIVE';

// Preset prices as requested
const PRESET_PRICES = [10, 50, 80, 130, 150, 160, 170, 180, 190, 200];

interface CartItem {
  id: string; // Group ID
  price: number;
  quantity: number;
  isFreebie: boolean;
  baleId: string;
}

const LiveSell: React.FC = () => {
  const { logoUrl } = useSettings();
  const [session, setSession] = useState<LiveSession | null>(db.getSessions().find(s => s.isOpen) || null);

  // -- Form States --
  const [username, setUsername] = useState('');
  const [transactionNo, setTransactionNo] = useState(''); // New Transaction No.
  const [selectedBaleId, setSelectedBaleId] = useState<string>('');

  // -- Cart State --
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customPrice, setCustomPrice] = useState<string>('');

  const [recentOrders, setRecentOrders] = useState<Order[]>([]);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showStartModal, setShowStartModal] = useState(false);

  // History & Modals
  const [historySessions, setHistorySessions] = useState<LiveSession[]>([]);
  const [viewingSession, setViewingSession] = useState<LiveSession | null>(null);
  const [showEndModal, setShowEndModal] = useState(false);
  const [logoError, setLogoError] = useState(false);

  // Data
  const customers = db.getCustomers();
  const bales = db.getBales();
  const customPriceInputRef = useRef<HTMLInputElement>(null);

  // Reset logo error when logoUrl changes
  useEffect(() => {
    setLogoError(false);
  }, [logoUrl]);

  // Load history
  useEffect(() => {
    const allSessions = db.getSessions();
    setHistorySessions(allSessions.filter(s => !s.isOpen).sort((a, b) => b.id.localeCompare(a.id)));
  }, [session]);

  // Customer Autocomplete
  const filteredCustomers = useMemo(() => {
    if (!username || customers.some(c => c.username === username)) return [];
    const lower = username.toLowerCase();
    return customers.filter(c => 
      c.username.toLowerCase().includes(lower)
    ).slice(0, 3);
  }, [username, customers]);

  // Load Recent Orders
  useEffect(() => {
    if (session) {
      const orders = db.getOrders().filter(o => o.sessionId === session.id);
      setRecentOrders(orders.sort((a, b) => b.createdAt - a.createdAt).slice(0, 10));
    }
  }, [session]);

  // Set default bale (Find one that isn't sold out if possible)
  useEffect(() => {
    if (bales.length > 0 && !selectedBaleId) {
       // Helper to check stock locally for default selection
       const getStock = (bId: string) => {
         const allProducts = db.getProducts();
         const allOrders = db.getOrders();
         const prodIds = allProducts.filter(p => p.baleBatch === bId).map(p => p.id);
         const sold = allOrders.filter(o => prodIds.includes(o.productId)).reduce((s, o) => s + o.quantity, 0);
         const b = bales.find(bl => bl.id === bId);
         return b ? b.itemCount - sold : 0;
       };

       const onSale = bales.find(b => b.status === 'On Sale' && getStock(b.id) > 0);
       if (onSale) setSelectedBaleId(onSale.id);
       else setSelectedBaleId(bales[0].id);
    }
  }, [bales, selectedBaleId]);

  const handleStartSession = () => setShowStartModal(true);

  const handleStartOffLive = () => {
    setSession({
      id: OFF_LIVE_ID,
      name: 'Off-Live / Manual Encoding',
      date: new Date().toLocaleDateString(),
      totalSales: 0,
      totalOrders: 0,
      isOpen: true
    });
  };

  const handleCreateSession = (name: string) => {
    const newSession = db.createSession(name);
    setSession(newSession);
    setShowStartModal(false);
  };

  const handleEndSessionClick = () => {
    if (session?.id === OFF_LIVE_ID) setSession(null);
    else setShowEndModal(true);
  };

  const confirmEndSession = () => {
    if (session && session.id !== OFF_LIVE_ID) {
      db.closeSession(session.id);
      setSession(null);
      setShowEndModal(false);
    }
  };

  // --- Inventory Helper ---
  // Calculates remaining stock: (Bale Limit) - (Saved Orders) - (Current Cart)
  const getBaleRemainingStock = (baleId: string): { remaining: number; total: number; soldDb: number; inCart: number } => {
    const bale = bales.find(b => b.id === baleId);
    if (!bale) return { remaining: 0, total: 0, soldDb: 0, inCart: 0 };

    // 1. Calculate DB Sold
    const allProducts = db.getProducts();
    const allOrders = db.getOrders();
    const baleProductIds = allProducts.filter(p => p.baleBatch === baleId).map(p => p.id);

    // Sum quantities of orders linked to this bale
    const soldDb = allOrders
      .filter(o => baleProductIds.includes(o.productId))
      .reduce((sum, o) => sum + o.quantity, 0);

    // 2. Calculate Cart Pending
    const inCart = cart
      .filter(item => item.baleId === baleId)
      .reduce((sum, item) => sum + item.quantity, 0);

    const remaining = Math.max(0, bale.itemCount - soldDb - inCart);

    return { remaining, total: bale.itemCount, soldDb, inCart };
  };

  // --- Cart Functions ---

  const addToCart = (inputPrice: number, isFreebie: boolean = false) => {
    if (!selectedBaleId) {
      alert("Please select a Bale/Sack first!");
      return;
    }

    // --- STRICT INVENTORY CHECK ---
    const stock = getBaleRemainingStock(selectedBaleId);
    if (stock.remaining <= 0) {
      alert(`⚠️ BALE SOLD OUT!\n\nThis bale has ${stock.total} items.\nSold: ${stock.soldDb}\nIn Cart: ${stock.inCart}\nRemaining: 0\n\nPlease select a different bale.`);
      return;
    }

    const price = isFreebie ? 0 : inputPrice;

    setCart(prevCart => {
      // Check if item with same price and freebie status exists in the current cart (and same bale)
      const existingItemIndex = prevCart.findIndex(
        item => item.price === price && item.isFreebie === isFreebie && item.baleId === selectedBaleId
      );

      if (existingItemIndex > -1) {
        // Increment quantity
        const newCart = [...prevCart];
        newCart[existingItemIndex].quantity += 1;
        return newCart;
      } else {
        // Add new item group
        return [...prevCart, {
          id: `cart_${Date.now()}_${Math.random()}`,
          price,
          quantity: 1,
          isFreebie,
          baleId: selectedBaleId
        }];
      }
    });
    setCustomPrice(''); // clear custom input if used
  };

  const removeFromCart = (itemId: string) => {
    setCart(prevCart => {
      return prevCart.map(item => {
        if (item.id === itemId) {
           return { ...item, quantity: item.quantity - 1 };
        }
        return item;
      }).filter(item => item.quantity > 0);
    });
  };

  const handleCheckout = () => {
    if (!session || !username) {
      alert('Please enter a Customer Username!');
      return;
    }
    if (cart.length === 0) {
      alert('Cart is empty!');
      return;
    }

    // Double check inventory before final save (in case multiple devices/tabs - though local storage is sync here)
    for (const item of cart) {
       const stock = getBaleRemainingStock(item.baleId);
       // We add back item.quantity to stock.inCart because getBaleRemainingStock includes current cart. 
       // We need to check if (dbSold + cartVal) > total.
       // The helper calculates remaining correctly considering cart.
       // However, since we already added to cart, remaining shouldn't be negative.
       // If logic is correct, getBaleRemainingStock shouldn't return negative, it clamps to 0.

       // Let's do a raw check:
       const bale = bales.find(b => b.id === item.baleId);
       if (bale) {
          const allProducts = db.getProducts();
          const allOrders = db.getOrders();
          const pIds = allProducts.filter(p => p.baleBatch === bale.id).map(p => p.id);
          const dbSold = allOrders.filter(o => pIds.includes(o.productId)).reduce((s, o) => s + o.quantity, 0);

          // Get total qty of this bale in current checkout
          const totalInCurrentCart = cart.filter(c => c.baleId === item.baleId).reduce((s, c) => s + c.quantity, 0);

          if (dbSold + totalInCurrentCart > bale.itemCount) {
             alert(`❌ Checkout Failed for ${bale.name}!\n\nStock limit exceeded. Available: ${bale.itemCount - dbSold}, Trying to sell: ${totalInCurrentCart}`);
             return;
          }
       }
    }

    const customer = db.getOrCreateCustomer(username);
    const timestamp = Date.now();
    const newOrders: Order[] = [];
    let globalIndex = 0;

    // Expand grouped cart items into individual orders
    cart.forEach((item) => {
      for (let i = 0; i < item.quantity; i++) {
          const uniqueSuffix = `${globalIndex}_${i}`;

          // 1. Create Ghost Product
          const itemName = item.isFreebie ? 'Live Freebie' : `Live Item - ₱${item.price}`;
          const newProduct: Product = {
            id: `qp_${timestamp}_${uniqueSuffix}`,
            name: itemName,
            brand: 'Live Item',
            baleBatch: item.baleId,
            costPrice: 0,
            sellingPrice: item.price,
            stock: 0 
          };
          db.updateProduct(newProduct);

          // 2. Create Order
          const newOrder: Order = {
            id: `o_${timestamp}_${uniqueSuffix}`,
            sessionId: session.id,
            customerId: customer.id,
            customerUsername: username,
            productId: newProduct.id,
            productName: itemName,
            quantity: 1,
            totalPrice: item.price,
            isFreebie: item.isFreebie,
            paymentStatus: item.isFreebie ? PaymentStatus.PAID : PaymentStatus.UNPAID,
            shippingStatus: ShippingStatus.PENDING,
            amountPaid: 0,
            createdAt: timestamp,
            referenceNumber: transactionNo || undefined
          };

          db.addOrder(newOrder);
          newOrders.push(newOrder);
          globalIndex++;
      }
    });

    // Update UI
    setRecentOrders([...newOrders.reverse(), ...recentOrders]);
    setFeedback(`Saved ${globalIndex} items for @${username}!`);
    setTimeout(() => setFeedback(null), 2000);

    // Reset for next customer
    setCart([]);
    setUsername('');
    setTransactionNo('');
    // Keep Bale Selected
  };

  const cartTotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const cartItemCount = cart.reduce((sum, item) => sum + item.quantity, 0);

  const displayLogo = logoUrl || './logo.png';

  // Helper for rendering Bale Options
  const renderBaleOption = (bale: Bale) => {
    // We calculate "Db Remaining" (ignoring current cart for the label, or simpler: just DB availability)
    const stock = getBaleRemainingStock(bale.id);
    // Note: getBaleRemainingStock subtracts cart. We want to show what's generally available
    // But for the dropdown list, let's show "Db Remaining" so they know what's physically left before they started adding to cart.
    const dbRemaining = bale.itemCount - stock.soldDb;

    let label = `${bale.name} (${dbRemaining} left)`;
    if (dbRemaining <= 0) label = `🔴 SOLD OUT - ${bale.name}`;

    return <option key={bale.id} value={bale.id} disabled={dbRemaining <= 0}>{label}</option>;
  };

  // --- View: No Active Session ---
  if (!session) {
    return (
      <>
        <div className="flex flex-col items-center justify-start min-h-[80vh] px-4 animate-fadeIn pb-24">
          <div className="w-full max-w-lg text-center mt-10 mb-12">
            {!logoError ? (
              <div className="w-64 mx-auto mb-6 animate-scaleUp">
                 <img src={displayLogo} alt="Pawshionista" className="w-full h-auto object-contain drop-shadow-sm" onError={() => setLogoError(true)} />
              </div>
            ) : (
              <div className="bg-pawPink/20 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-6 animate-scaleUp">
                <PawIcon className="w-12 h-12 text-pawPinkDark opacity-100" />
              </div>
            )}
            <h2 className="text-3xl font-black text-gray-800 mb-2 uppercase tracking-tight">Time to Shine! ✨</h2>
            <p className="text-gray-400 mb-8 font-bold text-sm leading-relaxed">Start a new live to track sales, or review past sessions below to pack orders.</p>
            <div className="flex gap-4">
              <button onClick={handleStartOffLive} className="flex-1 bg-white border-2 border-pawPink/50 text-pawPinkDark py-5 rounded-[2rem] font-black uppercase tracking-widest shadow-sm active:scale-95 transition-all hover:bg-pawPink/10 text-xs flex flex-col items-center justify-center gap-1">
                <CartIcon className="w-5 h-5" /> Manual / Off-Live
              </button>
              <button onClick={handleStartSession} className="flex-[2] bg-pawPinkDark text-white py-5 rounded-[2rem] font-black uppercase tracking-widest shadow-xl shadow-pawPinkDark/30 active:scale-95 transition-all hover:bg-red-400 hover:shadow-pawPinkDark/50 text-xs flex flex-col items-center justify-center gap-1">
                <PlusIcon className="w-5 h-5" /> Start Live Session
              </button>
            </div>
          </div>
          <div className="w-full max-w-lg">
            <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4 ml-4">Past Sessions (Packing List)</h3>
            <div className="space-y-4">
              {historySessions.length === 0 ? (
                 <div className="text-center py-10 opacity-40 border-2 border-dashed border-pawPink/30 rounded-[2rem]">
                   <p className="font-bold text-gray-400 text-xs">No past sessions yet.</p>
                 </div>
              ) : (
                historySessions.map(hist => (
                  <button key={hist.id} onClick={() => setViewingSession(hist)} className="w-full bg-white p-5 rounded-[2rem] shadow-sm border border-pawPink/30 flex items-center justify-between hover:border-pawPinkDark hover:shadow-md transition-all group text-left">
                    <div>
                      <h4 className="font-black text-gray-800 text-lg group-hover:text-pawPinkDark transition-colors">{hist.name}</h4>
                      <p className="text-[11px] font-bold text-gray-400 uppercase tracking-wider">{hist.date}</p>
                    </div>
                    <div className="bg-pawCream px-4 py-2 rounded-xl"><p className="text-[10px] font-black text-gray-400 uppercase tracking-wider">Review</p></div>
                  </button>
                ))
              )}
            </div>
          </div>
        </div>
        {showStartModal && <StartSessionModal onClose={() => setShowStartModal(false)} onStart={handleCreateSession} />}
        {viewingSession && <SessionSummaryModal session={viewingSession} onClose={() => setViewingSession(null)} />}
      </>
    );
  }

  // --- View: Active Session (POS Interface) ---
  const currentBaleStats = selectedBaleId ? getBaleRemainingStock(selectedBaleId) : null;

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 pb-32 max-w-full">
      {/* Left Panel: Inputs & Buttons */}
      <div className="lg:col-span-8 space-y-6">
        <div className="bg-white p-6 rounded-[2.5rem] shadow-xl border-2 border-pawPink/30 relative">

          {/* Header */}
          <div className="flex items-center justify-between mb-6">
            <div className="flex flex-col">
              {session.id === OFF_LIVE_ID ? (
                <div className="flex items-center gap-2 mb-1">
                  <span className="w-2 h-2 bg-blue-400 rounded-full"></span>
                  <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Manual Mode</span>
                </div>
              ) : (
                <div className="flex items-center gap-2 mb-1">
                  <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>
                  <span className="text-[10px] font-black text-red-500 uppercase tracking-widest">Live Now</span>
                </div>
              )}
              <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight">{session.name}</h3>
            </div>
            <button className="px-4 py-2 bg-gray-100 hover:bg-red-50 text-gray-400 hover:text-red-500 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all" onClick={handleEndSessionClick}>
              {session.id === OFF_LIVE_ID ? 'Exit' : 'End'}
            </button>
          </div>

          {/* Customer Inputs */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
             <div className="relative">
                <label className="text-[10px] font-black text-gray-400 uppercase ml-3 tracking-widest block mb-1">Customer Username</label>
                <div className="flex items-center bg-pawCream rounded-[1.2rem] px-4 border-2 border-transparent focus-within:border-pawPinkDark transition-all">
                  <span className="text-lg font-black text-gray-400">@</span>
                  <input 
                    type="text"
                    placeholder="tiktok_user"
                    value={username}
                    onChange={(e) => setUsername(e.target.value.replace('@', ''))}
                    className="w-full bg-transparent p-3 text-lg font-black text-gray-800 placeholder:text-gray-300 border-none focus:ring-0"
                  />
                </div>
                {/* Autocomplete */}
                {filteredCustomers.length > 0 && (
                  <div className="absolute top-full left-0 right-0 bg-white shadow-xl rounded-[1rem] z-30 border-2 border-pawPink mt-1 p-1">
                    {filteredCustomers.map(c => (
                      <button key={c.id} onClick={() => setUsername(c.username)} className="w-full text-left p-3 hover:bg-pawPink/20 rounded-xl flex items-center justify-between transition-colors">
                        <span className="font-black text-gray-800 text-sm">@{c.username}</span>
                        {c.isVIP && <span className="bg-yellow-100 text-yellow-700 text-[9px] px-2 py-0.5 rounded-full font-black uppercase">VIP</span>}
                      </button>
                    ))}
                  </div>
                )}
             </div>

             <div>
                <label className="text-[10px] font-black text-gray-400 uppercase ml-3 tracking-widest block mb-1">TikTok Transaction No.</label>
                <input 
                  type="text"
                  placeholder="Order ID / Ref #"
                  value={transactionNo}
                  onChange={(e) => setTransactionNo(e.target.value)}
                  className="w-full bg-white border-2 border-gray-100 focus:border-pawPinkDark p-3 rounded-[1.2rem] text-lg font-bold text-gray-800 placeholder:text-gray-300 outline-none"
                />
             </div>
          </div>

          <div className="mb-6">
              <div className="flex justify-between items-end mb-1">
                 <label className="text-[10px] font-black text-gray-400 uppercase ml-3 tracking-widest block">Select Bale (Source)</label>
                 {currentBaleStats && (
                    <span className={`text-[10px] font-bold uppercase tracking-widest px-2 py-0.5 rounded-lg ${currentBaleStats.remaining < 5 ? 'bg-red-100 text-red-600 animate-pulse' : 'bg-green-100 text-green-700'}`}>
                       🔥 {currentBaleStats.soldDb + currentBaleStats.inCart} / {currentBaleStats.total} Sold
                    </span>
                 )}
              </div>
              <select 
                value={selectedBaleId}
                onChange={(e) => setSelectedBaleId(e.target.value)}
                className="w-full bg-pawSoftBlue/30 p-3 rounded-[1.2rem] font-bold text-gray-700 border-2 border-transparent focus:border-pawPinkDark outline-none appearance-none"
              >
                <option value="">-- Select Source Bale --</option>
                {bales.map(b => renderBaleOption(b))}
              </select>
          </div>

          <hr className="border-pawPink/20 mb-6" />

          {/* Price Buttons Grid */}
          <div>
            <label className="text-[10px] font-black text-gray-400 uppercase ml-3 tracking-widest block mb-2">Tap Price to Add</label>
            <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 gap-3 mb-4">
               {/* Freebie Button */}
               <button 
                 onClick={() => addToCart(0, true)}
                 className="aspect-square rounded-2xl bg-pawPeach text-orange-800 font-black text-sm uppercase tracking-wider shadow-sm hover:shadow-md hover:scale-105 active:scale-95 transition-all flex flex-col items-center justify-center border-2 border-orange-100"
               >
                 <span>🎁</span>
                 <span>Free</span>
               </button>

               {/* Preset Prices */}
               {PRESET_PRICES.map(price => (
                 <button
                   key={price}
                   onClick={() => addToCart(price)}
                   className="aspect-square rounded-2xl bg-white text-gray-700 font-black text-lg shadow-sm border-2 border-gray-100 hover:border-pawPinkDark hover:text-pawPinkDark hover:shadow-md active:scale-95 transition-all flex items-center justify-center"
                 >
                   {price}
                 </button>
               ))}
            </div>

            {/* Custom Price */}
            <div className="flex gap-2">
               <input 
                 ref={customPriceInputRef}
                 type="number"
                 placeholder="Custom Price"
                 value={customPrice}
                 onChange={(e) => setCustomPrice(e.target.value)}
                 onKeyDown={(e) => {
                    if (e.key === 'Enter' && customPrice) {
                        addToCart(Number(customPrice));
                    }
                 }}
                 className="flex-1 bg-gray-50 p-4 rounded-2xl font-black text-gray-800 placeholder:text-gray-300 outline-none focus:ring-2 focus:ring-pawPink"
               />
               <button 
                 onClick={() => { if(customPrice) addToCart(Number(customPrice)); }}
                 className="bg-gray-800 text-white px-6 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-gray-700 active:scale-95 transition-all"
               >
                 Add
               </button>
            </div>
          </div>
        </div>
      </div>

      {/* Right Panel: Cart & Checkout */}
      <div className="lg:col-span-4 space-y-6">
         <div className="bg-pawSoftBlue/50 p-6 rounded-[2.5rem] border-2 border-white shadow-xl h-full flex flex-col">
            <h3 className="text-lg font-black text-blue-900 uppercase tracking-tight mb-4 flex items-center gap-2">
               <CartIcon className="w-5 h-5" />
               Current Cart
            </h3>

            {/* Cart List - Receipt Style */}
            <div className="flex-1 overflow-y-auto custom-scrollbar space-y-2 min-h-[200px] mb-4 bg-white rounded-2xl p-4 shadow-inner border border-gray-100 relative">
               {/* Receipt Top Edge Decoration */}
               <div className="absolute top-0 left-0 right-0 h-1 bg-repeat-x opacity-20" style={{ backgroundImage: 'linear-gradient(to right, transparent 50%, #000 50%)', backgroundSize: '10px 1px' }}></div>

               {cart.length === 0 ? (
                 <div className="h-full flex flex-col items-center justify-center opacity-40">
                    <p className="text-sm font-bold text-blue-300 italic">Cart is empty</p>
                 </div>
               ) : (
                 cart.map((item) => (
                   <div key={item.id} className="flex justify-between items-center border-b border-dashed border-gray-200 pb-2 mb-2 last:border-0 last:mb-0 last:pb-0 animate-slideIn group">
                      <div className="flex items-center gap-3">
                         <div className="bg-pawPinkDark text-white min-w-[1.5rem] h-6 px-1.5 rounded-full flex items-center justify-center text-[10px] font-black shadow-sm">
                            {item.quantity}x
                         </div>
                         <div>
                            <p className="font-bold text-gray-800 text-sm">
                               {item.isFreebie ? 'Freebie 🎁' : `₱${item.price}`}
                            </p>
                            <p className="text-[9px] text-gray-500 font-bold uppercase tracking-wide">
                                {bales.find(b => b.id === item.baleId)?.name || 'Unknown Bale'}
                            </p>
                            <p className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">
                               Subtotal: {item.isFreebie ? '₱0' : `₱${(item.price * item.quantity).toLocaleString()}`}
                            </p>
                         </div>
                      </div>
                      <button 
                        onClick={() => removeFromCart(item.id)}
                        className="w-6 h-6 flex items-center justify-center bg-gray-100 text-gray-400 rounded-full hover:bg-red-100 hover:text-red-500 transition-colors"
                      >
                        -
                      </button>
                   </div>
                 ))
               )}
            </div>

            {/* Total */}
            <div className="bg-white rounded-2xl p-5 mb-4 shadow-sm border border-gray-100 relative overflow-hidden">
               {/* Receipt Zigzag Bottom Effect (CSS Trick) */}
               <div className="flex justify-between items-end relative z-10">
                  <span className="text-xs font-black text-gray-400 uppercase tracking-widest">Total Amount</span>
                  <span className="text-3xl font-black text-gray-800 leading-none">₱{cartTotal.toLocaleString()}</span>
               </div>
               <div className="flex justify-between items-end mt-2 relative z-10">
                  <span className="text-[10px] font-bold text-gray-300 uppercase tracking-widest">Total Items</span>
                  <span className="text-sm font-black text-gray-500">{cartItemCount} pcs</span>
               </div>
               <div className="absolute top-0 right-0 w-16 h-16 bg-gradient-to-bl from-pawPink/30 to-transparent rounded-bl-full -mr-4 -mt-4"></div>
            </div>

            {/* Checkout Button */}
            <button 
              onClick={handleCheckout}
              disabled={cart.length === 0 || !username}
              className={`w-full py-5 rounded-2xl font-black uppercase text-sm tracking-widest shadow-lg transition-all active:scale-95 ${
                 cart.length === 0 || !username 
                 ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
                 : 'bg-pawPinkDark text-white hover:bg-red-400 shadow-pawPinkDark/30'
              }`}
            >
               {feedback ? `✅ ${feedback}` : 'Save Orders'}
            </button>
         </div>
      </div>

      {showEndModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] overflow-hidden shadow-2xl animate-scaleUp p-8 text-center">
             <div className="bg-red-100 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6"><span className="text-4xl">🛑</span></div>
             <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight mb-2">End Live Session?</h3>
             <p className="text-gray-500 font-bold text-xs mb-8 leading-relaxed">No more orders can be encoded for this session.</p>
             <div className="flex gap-4">
                <button onClick={() => setShowEndModal(false)} className="flex-1 py-4 bg-gray-100 text-gray-500 font-black uppercase text-xs tracking-widest rounded-2xl hover:bg-gray-200 transition-all">Cancel</button>
                <button onClick={confirmEndSession} className="flex-1 py-4 bg-red-500 text-white font-black uppercase text-xs tracking-widest rounded-2xl shadow-lg shadow-red-200 hover:bg-red-600 transition-all">End Live</button>
             </div>
          </div>
        </div>
      )}
