               <div className="absolute top-0 left-0 right-0 h-1 bg-repeat-x opacity-20" style={{ backgroundImage: 'linear-gradient(to right, transparent 50%, #000 50%)', backgroundSize: '10px 1px' }}></div>

               {cart.length === 0 ? (
                 <div className="h-full flex flex-col items-center justify-center opacity-40">
                    <p className="text-sm font-bold text-blue-300 italic">Cart is empty</p>
                 </div>
               ) : (
                 cart.map((item) => (
                   <div key={item.id} className="flex justify-between items-center border-b border-dashed border-gray-200 pb-2 mb-2 last:border-0 last:mb-0 last:pb-0 animate-slideIn group">
                      <div className="flex items-center gap-3">
                         <div className="bg-pawPinkDark text-white min-w-[1.5rem] h-6 px-1.5 rounded-full flex items-center justify-center text-[10px] font-black shadow-sm">
                            {item.quantity}x
                         </div>
                         <div>
                            <p className="font-bold text-gray-800 text-sm">
                               {item.isFreebie ? 'Freebie 🎁' : `₱${item.price}`}
                            </p>
                            <p className="text-[9px] text-gray-500 font-bold uppercase tracking-wide">
                                {bales.find(b => b.id === item.baleId)?.name || 'Unknown Bale'}
                            </p>
                            <p className="text-[10px] text-gray-400 uppercase tracking-wider font-bold">
                               Subtotal: {item.isFreebie ? '₱0' : `₱${(item.price * item.quantity).toLocaleString()}`}
                            </p>
                         </div>
                      </div>
                      <button 
                        onClick={() => removeFromCart(item.id)}
                        className="w-6 h-6 flex items-center justify-center bg-gray-100 text-gray-400 rounded-full hover:bg-red-100 hover:text-red-500 transition-colors"
                      >
                        -
                      </button>
                   </div>
                 ))
               )}
            </div>

            {/* Total */}
            <div className="bg-white rounded-2xl p-5 mb-4 shadow-sm border border-gray-100 relative overflow-hidden">
               {/* Receipt Zigzag Bottom Effect (CSS Trick) */}
               <div className="flex justify-between items-end relative z-10">
                  <span className="text-xs font-black text-gray-400 uppercase tracking-widest">Total Amount</span>
                  <span className="text-3xl font-black text-gray-800 leading-none">₱{cartTotal.toLocaleString()}</span>
               </div>
               <div className="flex justify-between items-end mt-2 relative z-10">
                  <span className="text-[10px] font-bold text-gray-300 uppercase tracking-widest">Total Items</span>
                  <span className="text-sm font-black text-gray-500">{cartItemCount} pcs</span>
               </div>
               <div className="absolute top-0 right-0 w-16 h-16 bg-gradient-to-bl from-pawPink/30 to-transparent rounded-bl-full -mr-4 -mt-4"></div>
            </div>

            {/* Checkout Button */}
            <button 
              onClick={handleCheckout}
              disabled={cart.length === 0 || !username}
              className={`w-full py-5 rounded-2xl font-black uppercase text-sm tracking-widest shadow-lg transition-all active:scale-95 ${
                 cart.length === 0 || !username 
                 ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
                 : 'bg-pawPinkDark text-white hover:bg-red-400 shadow-pawPinkDark/30'
              }`}
            >
               {feedback ? `✅ ${feedback}` : 'Save Orders'}
            </button>
         </div>
      </div>

      {showEndModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] overflow-hidden shadow-2xl animate-scaleUp p-8 text-center">
             <div className="bg-red-100 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6"><span className="text-4xl">🛑</span></div>
             <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight mb-2">End Live Session?</h3>
             <p className="text-gray-500 font-bold text-xs mb-8 leading-relaxed">No more orders can be encoded for this session.</p>
             <div className="flex gap-4">
                <button onClick={() => setShowEndModal(false)} className="flex-1 py-4 bg-gray-100 text-gray-500 font-black uppercase text-xs tracking-widest rounded-2xl hover:bg-gray-200 transition-all">Cancel</button>
                <button onClick={confirmEndSession} className="flex-1 py-4 bg-red-500 text-white font-black uppercase text-xs tracking-widest rounded-2xl shadow-lg shadow-red-200 hover:bg-red-600 transition-all">End Live</button>
             </div>
          </div>
        </div>
      )}

      {oosModalData && (
        <OutOfStockModal 
          data={oosModalData} 
          onClose={() => setOosModalData(null)} 
        />
      )}

      {showHistory && (
        <LiveHistoryModal 
           orders={recentOrders} 
           onClose={() => setShowHistory(false)}
        />
      )}
    </div>
  );
};

