// NEW: Recent History Modal with Edit/Delete
const LiveHistoryModal: React.FC<{ orders: Order[]; onClose: () => void }> = ({ orders, onClose }) => {
  const [selectedCustomer, setSelectedCustomer] = useState<string | null>(null);
  const [localOrders, setLocalOrders] = useState(orders);

  useEffect(() => { setLocalOrders(orders) }, [orders]);

  const groupedOrders = useMemo(() => {
    const grouped: Record<string, Order[]> = {};
    localOrders.forEach(o => { if (!grouped[o.customerUsername]) grouped[o.customerUsername] = []; grouped[o.customerUsername].push(o); });
    return grouped;
  }, [localOrders]);

  const customerList = Object.keys(groupedOrders);

  // -- Action Handlers --
  const handleDeleteItem = (order: Order) => {
    if (confirm('Delete this item? Stock will be returned.')) {
        // 1. Get current data states
        const allProducts = db.getProducts();
        const allBales = db.getBales();
        const prodIndex = allProducts.findIndex(p => p.id === order.productId);

        // 2. Return Stock Logic
        if (prodIndex > -1 && !order.isFreebie) {
            allProducts[prodIndex].stock += order.quantity; // Assuming 1-to-1 generally
            // 3. Update Bale Status (if needed)
            const bale = allBales.find(b => b.id === allProducts[prodIndex].baleBatch);
            if (bale && bale.status === 'Sold Out') {
               bale.status = 'On Sale';
               db.updateBale(bale);
            }
            // Note: db.setProducts isn't exposed directly but updateProduct handles single.
            // However, we modified the array locally. We need to save it.
            // db.updateProduct overwrites using ID.
            db.updateProduct(allProducts[prodIndex]);
        }

        // 4. Delete Order
        db.deleteOrder(order.id);

        // 5. Refresh UI
        setLocalOrders(prev => prev.filter(o => o.id !== order.id));
    }
  };

  const handleEditPrice = (order: Order) => {
     const newPriceStr = prompt("Enter new price:", order.totalPrice.toString());
     if (newPriceStr) {
        const newPrice = Number(newPriceStr);
        if (!isNaN(newPrice)) {
            const updatedOrder = { ...order, totalPrice: newPrice, amountPaid: order.paymentStatus === PaymentStatus.PAID ? newPrice : order.amountPaid };
            db.updateOrder(updatedOrder);

            // Also update the hidden product price for consistency
            const products = db.getProducts();
            const p = products.find(prod => prod.id === order.productId);
            if (p) {
               p.sellingPrice = newPrice;
               db.updateProduct(p);
            }

            setLocalOrders(prev => prev.map(o => o.id === order.id ? updatedOrder : o));
        }
     }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center p-0 md:p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
      <div className="bg-white w-full max-w-2xl h-[90vh] md:h-auto md:max-h-[85vh] rounded-t-[3rem] md:rounded-[3rem] overflow-hidden shadow-2xl animate-scaleUp flex flex-col">
         {/* Header */}
         <div className="bg-gray-100 p-6 flex justify-between items-center shrink-0">
            <div>
               <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight">Recent Orders</h3>
               <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Session History & Edits</p>
            </div>
            <button onClick={onClose} className="bg-white p-2 rounded-full hover:bg-gray-200 transition-all text-gray-500">
               <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
         </div>

         <div className="flex-1 overflow-hidden flex flex-col md:flex-row">
            {/* Left: Customer List */}
            <div className={`w-full md:w-1/3 border-r border-gray-100 overflow-y-auto bg-white ${selectedCustomer ? 'hidden md:block' : 'block'}`}>
               <p className="p-4 text-[10px] font-black text-gray-400 uppercase tracking-widest bg-gray-50 sticky top-0">Customers ({customerList.length})</p>
               {customerList.length === 0 ? (
                  <p className="p-8 text-center text-gray-400 text-xs italic">No orders yet.</p>
               ) : (
                  customerList.map(username => {
                     const count = groupedOrders[username].length;
                     const total = groupedOrders[username].reduce((s,o) => s + o.totalPrice, 0);
                     return (
                        <button 
                           key={username}
                           onClick={() => setSelectedCustomer(username)}
                           className={`w-full text-left p-4 border-b border-gray-50 hover:bg-pawSoftBlue/30 transition-colors ${selectedCustomer === username ? 'bg-pawSoftBlue/50' : ''}`}
                        >
                           <p className="font-black text-gray-800 text-sm">@{username}</p>
                           <p className="text-xs text-gray-500 font-bold mt-1">{count} items • ₱{total.toLocaleString()}</p>
                        </button>
                     );
                  })
               )}
            </div>

            {/* Right: Item Detail */}
            <div className={`w-full md:w-2/3 overflow-y-auto bg-gray-50/50 ${!selectedCustomer ? 'hidden md:block' : 'block'}`}>
               {selectedCustomer ? (
                  <div className="p-4">
                     <button onClick={() => setSelectedCustomer(null)} className="md:hidden mb-4 text-xs font-black text-gray-500 uppercase tracking-widest flex items-center gap-1">
                        ← Back to List
                     </button>
                     <div className="flex justify-between items-end mb-4 px-2">
                        <h4 className="text-lg font-black text-gray-800">@{selectedCustomer}</h4>
                        <span className="text-[10px] bg-pawPinkDark text-white px-2 py-1 rounded-lg font-black uppercase">
                           Total: ₱{groupedOrders[selectedCustomer].reduce((s,o)=>s+o.totalPrice, 0).toLocaleString()}
                        </span>
                     </div>
                     <div className="space-y-3">
                        {groupedOrders[selectedCustomer].map(order => (
                           <div key={order.id} className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex justify-between items-center group">
                              <div>
                                 <p className="font-bold text-gray-800 text-sm">{order.productName}</p>
                                 <div className="flex gap-2 text-[10px] text-gray-400 font-black uppercase tracking-wider mt-1">
                                    <span>₱{order.totalPrice}</span>
                                    {order.isFreebie && <span className="text-orange-500">Freebie</span>}
                                 </div>
                              </div>
                              <div className="flex gap-2">
                                 <button onClick={() => handleEditPrice(order)} className="p-2 text-gray-400 hover:text-blue-500 hover:bg-blue-50 rounded-xl transition-all" title="Edit Price">
                                    <PencilIcon className="w-4 h-4" />
                                 </button>
                                 <button onClick={() => handleDeleteItem(order)} className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all" title="Delete Item">
                                    <TrashIcon className="w-4 h-4" />
                                 </button>
                              </div>
                           </div>
                        ))}
                     </div>
                  </div>
               ) : (
                  <div className="h-full flex flex-col items-center justify-center text-gray-300 p-8">
                     <p className="text-4xl mb-2">👈</p>
                     <p className="font-bold text-sm">Select a customer to view items</p>
                  </div>
               )}
            </div>
         </div>

         <div className="p-4 bg-white border-t border-gray-100 md:hidden">
             <button onClick={onClose} className="w-full py-4 bg-gray-100 text-gray-500 font-black uppercase text-xs tracking-widest rounded-2xl">Close History</button>
         </div>
      </div>
    </div>
  );
};

export default LiveSell;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { db } from '../services/dbService';
import { useSettings } from '../services/SettingsContext';
import { Product, Order, PaymentStatus, ShippingStatus, LiveSession, Bale } from '../types';
import { PlusIcon, PawIcon, CartIcon } from '../components/Icons';

const OFF_LIVE_ID = 'OFF_LIVE';

// Preset prices as requested
const PRESET_PRICES = [10, 50, 80, 130, 150, 160, 170, 180, 190, 200];

interface CartItem {
  id: string; // Group ID
  price: number;
  quantity: number;
  isFreebie: boolean;
  baleId: string;
}

const ClockIcon = ({ className = "w-6 h-6" }: { className?: string }) => (
  <svg className={className} fill="none" stroke="currentColor" viewBox="0 0 24 24">
