            <button onClick={onClose} className="bg-white p-2 rounded-full hover:bg-gray-200 transition-all text-gray-500">
               <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
         </div>

         <div className="flex-1 overflow-y-auto custom-scrollbar bg-white p-8 space-y-3">
            {customerList.length === 0 ? (
               <div className="text-center py-20 opacity-40 border-2 border-dashed border-gray-200 rounded-[2rem]">
                  <ClockIcon className="w-12 h-12 text-gray-300 mx-auto mb-4" />
                  <p className="font-bold text-gray-400 italic">No orders yet in this session.</p>
               </div>
            ) : (
               customerList.map(username => {
                  const count = groupedOrders[username].length;
                  const total = groupedOrders[username].reduce((s,o) => s + o.totalPrice, 0);
                  const firstItem = groupedOrders[username][0];

                  return (
                     <button 
                        key={username}
                        onClick={() => onSelectCustomer(username)}
                        className="w-full bg-white p-5 rounded-[2rem] border-2 border-pawPink/30 hover:border-pawPinkDark hover:shadow-lg transition-all group text-left relative overflow-hidden"
                     >
                        <div className="flex justify-between items-center relative z-10">
                           <div className="flex items-center gap-4">
                              <div className="w-12 h-12 bg-pawPink rounded-full flex items-center justify-center text-pawPinkDark font-black text-lg">
                                 {username.charAt(0).toUpperCase()}
                              </div>
                              <div>
                                 <h4 className="font-black text-gray-800 text-lg group-hover:text-pawPinkDark transition-colors">@{username}</h4>
                                 <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">{count} items • {new Date(firstItem.createdAt).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                              </div>
                           </div>
                           <div className="text-right">
                              <p className="font-black text-gray-800 text-xl">₱{total.toLocaleString()}</p>
                              <div className="flex items-center justify-end gap-1 text-[10px] font-black text-blue-400 uppercase tracking-widest mt-1">
                                 <EditIcon className="w-3 h-3" /> Edit
                              </div>
                           </div>
                        </div>
                     </button>
                  );
               })
            )}
         </div>

         <div className="p-6 bg-white border-t border-gray-100">
             <button onClick={onClose} className="w-full py-5 bg-gray-100 text-gray-500 font-black uppercase text-xs tracking-widest rounded-[2rem] hover:bg-gray-200 transition-all">Close History</button>
         </div>
      </div>
    </div>
  );
};

