import React, { useMemo } from 'react';
import { db } from '../services/dbService';
import { PaymentStatus, ShippingStatus } from '../types';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { BoxIcon } from '../components/Icons';

const Dashboard: React.FC = () => {
  const orders = db.getOrders();
  const products = db.getProducts();
  const bales = db.getBales();

  const stats = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const todayOrders = orders.filter(o => new Date(o.createdAt).toISOString().split('T')[0] === today);
    const totalSalesToday = todayOrders.reduce((sum, o) => sum + o.totalPrice, 0);
    const pendingPayments = orders.filter(o => o.paymentStatus !== PaymentStatus.PAID).length;
    const toShip = orders.filter(o => o.shippingStatus === ShippingStatus.PENDING).length;

    return {
      salesToday: totalSalesToday,
      ordersToday: todayOrders.length,
      pendingPayments,
      toShip
    };
  }, [orders]);

  const chartData = useMemo(() => {
    // Group last 7 days sales
    const data: Record<string, number> = {};
    for (let i = 6; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      const key = d.toLocaleDateString('en-US', { weekday: 'short' });
      data[key] = 0;
    }

    orders.forEach(o => {
      const date = new Date(o.createdAt);
      const key = date.toLocaleDateString('en-US', { weekday: 'short' });
      if (data[key] !== undefined) data[key] += o.totalPrice;
    });

    return Object.entries(data).map(([name, sales]) => ({ name, sales }));
  }, [orders]);

  // Calculate Active Bales Stats
  const activeBales = useMemo(() => {
    // Filter out 'Sold Out' bales
    return bales
      .filter(b => b.status !== 'Sold Out')
      .map(bale => {
        // Find products linked to this bale
        const baleProductIds = products.filter(p => p.baleBatch === bale.id).map(p => p.id);
        // Calculate total sold count from orders
        const soldCount = orders
          .filter(o => baleProductIds.includes(o.productId))
          .reduce((sum, o) => sum + o.quantity, 0);

        const remaining = Math.max(0, bale.itemCount - soldCount);
        const percentSold = bale.itemCount > 0 ? (soldCount / bale.itemCount) * 100 : 0;

        return {
          ...bale,
          soldCount,
          remaining,
          percentSold
        };
      })
      .sort((a, b) => a.remaining - b.remaining); // Sort by lowest stock first (priority to sell)
  }, [bales, products, orders]);

  return (
    <div className="space-y-6 pb-8">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Hello, Paw-ss! 🐾</h1>
          <p className="text-gray-500">Here's how your shop is doing today.</p>
        </div>
      </header>

      {/* Metric Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard label="Today's Sales" value={`₱${stats.salesToday.toLocaleString()}`} color="bg-pawPink" textColor="text-red-500" />
        <StatCard label="Orders Today" value={stats.ordersToday} color="bg-pawMint" textColor="text-green-600" />
        <StatCard label="Pending Payments" value={stats.pendingPayments} color="bg-pawPeach" textColor="text-orange-600" />
        <StatCard label="To Ship" value={stats.toShip} color="bg-pawSoftBlue" textColor="text-blue-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Sales Chart */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-pawPink">
          <h3 className="text-lg font-bold mb-4 text-gray-700">Weekly Sales</h3>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <XAxis dataKey="name" axisLine={false} tickLine={false} />
                <Tooltip 
                  contentStyle={{ borderRadius: '15px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                  cursor={{ fill: '#FFFDD0', opacity: 0.4 }}
                />
                <Bar dataKey="sales" radius={[10, 10, 0, 0]}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index % 2 === 0 ? '#FFD1DC' : '#B2F2BB'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Active Bales Inventory (Replaced Low Stock Alerts) */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-pawPink flex flex-col h-[380px]">
          <div className="flex items-center gap-2 mb-4 shrink-0">
             <div className="bg-pawPink/30 p-2 rounded-xl">
               <BoxIcon className="w-5 h-5 text-pawPinkDark" />
             </div>
             <div>
               <h3 className="text-lg font-bold text-gray-700 leading-none">Active Bales</h3>
               <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">Remaining items to sell</p>
             </div>
          </div>

          <div className="space-y-3 overflow-y-auto custom-scrollbar flex-1 pr-2">
            {activeBales.length > 0 ? (
              activeBales.map(b => (
                <div key={b.id} className="flex flex-col p-4 bg-pawCream rounded-2xl relative overflow-hidden group">
                  <div className="flex justify-between items-start mb-2 relative z-10">
                    <div>
                      <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded-md mb-1 inline-block ${b.status === 'On Sale' ? 'bg-green-100 text-green-600' : 'bg-blue-100 text-blue-600'}`}>
                        {b.status}
                      </span>
                      <h4 className="font-bold text-gray-800 text-sm">{b.name}</h4>
                    </div>
                    <div className="text-right">
                       <span className="block text-2xl font-black text-gray-800 leading-none">{b.remaining}</span>
                       <span className="text-[9px] font-bold text-gray-400 uppercase">Left</span>
                    </div>
                  </div>

                  {/* Progress Bar */}
                  <div className="relative z-10">
                    <div className="flex justify-between text-[9px] font-bold text-gray-400 mb-1">
                       <span>Progress</span>
                       <span>{b.soldCount} Sold ({b.percentSold.toFixed(0)}%)</span>
                    </div>
                    <div className="w-full h-2 bg-white rounded-full overflow-hidden">
                       <div 
                         className="h-full bg-pawPinkDark rounded-full transition-all duration-1000" 
                         style={{ width: `${b.percentSold}%` }}
                       ></div>
                    </div>
                  </div>

                  {/* Decorative Background */}
                  <div className="absolute top-0 right-0 w-16 h-16 bg-white/40 rounded-bl-full -mr-4 -mt-4 transition-transform group-hover:scale-150 duration-500"></div>
                </div>
              ))
            ) : (
              <div className="text-center py-10 text-gray-400 flex flex-col items-center justify-center h-full opacity-60">
                <BoxIcon className="w-12 h-12 mb-2 text-gray-300" />
                <p className="font-bold text-sm">No active bales.</p>
                <p className="text-xs">Time to restock! 🛍️</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ label, value, color, textColor }: any) => (
  <div className={`${color} p-5 rounded-3xl shadow-sm transition-transform active:scale-95`}>
    <p className="text-xs font-bold text-gray-600 uppercase tracking-wider mb-1">{label}</p>
    <p className={`text-2xl font-bold ${textColor}`}>{value}</p>
  </div>
);

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { db } from '../services/dbService';
import { Bale } from '../types';
import { PlusIcon, PawIcon } from '../components/Icons';

const Inventory: React.FC = () => {
  // State
  const [bales, setBales] = useState(db.getBales());
  const [products] = useState(db.getProducts());
  const [orders] = useState(db.getOrders());

  // Modals
  const [showModal, setShowModal] = useState(false);
  const [editingBale, setEditingBale] = useState<Bale | null>(null);

  const getBaleSoldStats = (baleId: string) => {
    // 1. Find all products associated with this Bale
    const baleProducts = products.filter(p => p.baleBatch === baleId);
    const baleProductIds = baleProducts.map(p => p.id);

    // 2. Count orders for these products
    const soldCount = orders.filter(o => baleProductIds.includes(o.productId)).reduce((sum, o) => sum + o.quantity, 0);

    return soldCount;
  };

  const handleSaveBale = (bale: Bale) => {
    db.updateBale(bale);
    setBales(db.getBales());
    setShowModal(false);
    setEditingBale(null);
  };

  return (
    <div className="space-y-6 pb-32 px-1">
      <div className="flex items-center justify-between px-2">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Inventory Batches</h1>
          <p className="text-gray-500 font-bold text-sm">Track how many items are left per sack.</p>
        </div>

        <button 
          onClick={() => { setEditingBale(null); setShowModal(true); }}
          className="bg-pawPinkDark text-white w-14 h-14 rounded-full shadow-2xl flex items-center justify-center active:scale-90 transition-all hover:bg-red-400"
        >
          <PlusIcon className="w-6 h-6" />
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 px-2">
        {bales.map(bale => {
          const soldCount = getBaleSoldStats(bale.id);
          const remaining = Math.max(0, bale.itemCount - soldCount);
          const percentSold = bale.itemCount > 0 ? (soldCount / bale.itemCount) * 100 : 0;

          return (
            <button 
              key={bale.id}
              onClick={() => { setEditingBale(bale); setShowModal(true); }}
              className="bg-white rounded-[2.5rem] p-7 border-2 border-pawPink/30 hover:border-pawPinkDark shadow-sm hover:shadow-xl transition-all group text-left relative overflow-hidden active:scale-95"
            >
              <div className="flex justify-between items-start mb-6 relative z-10">
                <div>
                  <span className="text-[10px] font-black uppercase text-pawPinkDark bg-pawPink/20 px-3 py-1 rounded-full mb-2 inline-block tracking-widest">
                    {bale.id}
                  </span>
                  <h3 className="font-black text-gray-800 text-xl tracking-tight leading-none mb-1">{bale.name}</h3>
                  <p className="text-[11px] font-bold text-gray-400 uppercase tracking-widest">{bale.status}</p>
                </div>
              </div>

              <div className="flex gap-4 relative z-10 mb-6">
                <div className="bg-pawSoftBlue px-4 py-3 rounded-2xl flex-1">
                  <p className="text-[9px] text-blue-600 font-black uppercase tracking-wider mb-1">Items Sold</p>
                  <p className="text-2xl font-black text-gray-800">{soldCount}</p>
                </div>
                <div className="bg-pawMint px-4 py-3 rounded-2xl flex-1">
                  <p className="text-[9px] text-green-700 font-black uppercase tracking-wider mb-1">Left</p>
                  <p className="text-2xl font-black text-gray-800">{remaining}</p>
                </div>
              </div>

              <div className="relative z-10">
                 <div className="flex justify-between text-[10px] font-black text-gray-400 uppercase tracking-wider mb-2">
                    <span>Progress</span>
                    <span>{percentSold.toFixed(0)}%</span>
                 </div>
                 <div className="w-full h-3 bg-gray-100 rounded-full overflow-hidden">
                    <div className="h-full bg-pawPinkDark rounded-full" style={{ width: `${percentSold}%` }}></div>
                 </div>
              </div>

              <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-br from-pawPink/20 to-transparent rounded-bl-[100px] -mr-8 -mt-8"></div>
            </button>
          );
        })}

        {bales.length === 0 && (
           <div className="col-span-full py-20 text-center opacity-40">
              <PawIcon className="w-16 h-16 text-gray-300 mx-auto mb-4" />
              <p className="font-bold text-gray-400">No Bales Added Yet</p>
           </div>
        )}
      </div>

      {showModal && (
        <BaleModal 
          bale={editingBale} 
          onClose={() => setShowModal(false)} 
          onSave={handleSaveBale} 
        />
      )}
    </div>
  );
};

