import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { Bale } from '../types';
import { PlusIcon, PawIcon } from '../components/Icons';

const Inventory: React.FC = () => {
  // State
  const [bales, setBales] = useState(db.getBales());
  const [products] = useState(db.getProducts());
  const [orders] = useState(db.getOrders());

  // Modals
  const [showModal, setShowModal] = useState(false);
  const [editingBale, setEditingBale] = useState<Bale | null>(null);

  const getBaleSoldStats = (baleId: string) => {
    // 1. Find all products associated with this Bale
    const baleProducts = products.filter(p => p.baleBatch === baleId);
    const baleProductIds = baleProducts.map(p => p.id);

    // 2. Count orders for these products
    const soldCount = orders.filter(o => baleProductIds.includes(o.productId)).reduce((sum, o) => sum + o.quantity, 0);

    return soldCount;
  };

  const handleSaveBale = (bale: Bale) => {
    db.updateBale(bale);
    setBales(db.getBales());
    setShowModal(false);
    setEditingBale(null);
  };

  return (
    <div className="space-y-6 pb-32 px-1">
