                <div className="bg-pawMint px-4 py-3 rounded-2xl flex-1">
                  <p className="text-[9px] text-green-700 font-black uppercase tracking-wider mb-1">Left</p>
                  <p className="text-2xl font-black text-gray-800">{remaining}</p>
                </div>
              </div>

              <div className="relative z-10">
                 <div className="flex justify-between text-[10px] font-black text-gray-400 uppercase tracking-wider mb-2">
                    <span>Progress</span>
