import React, { useState, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { Transaction, PaymentMethod } from '../types';
import { PlusIcon } from '../components/Icons';

const Accounting: React.FC = () => {
  const orders = db.getOrders();
  const transactions = db.getTransactions();

  // State for Filters and Categories
  const [categories, setCategories] = useState(db.getExpenseCategories());
  const [categoryFilter, setCategoryFilter] = useState('All');
  const [showTxModal, setShowTxModal] = useState(false);

  const walletBalances = useMemo(() => {
    const balances: Record<string, number> = {
      'GCash': 0,
      'TikTok Checkout': 0,
      'GoTyme': 0,
      'SeaBank': 0,
      'BPI': 0,
      'Cash': 0
    };

    // Add paid orders
    orders.forEach(o => {
      if (o.paymentMethod && balances[o.paymentMethod] !== undefined) {
        balances[o.paymentMethod] += o.amountPaid;
      }
    });

    // Subtract/Add transactions
    transactions.forEach(t => {
      if (balances[t.wallet] !== undefined) {
        if (t.type === 'Expense' || t.type === 'Withdrawal') {
          balances[t.wallet] -= t.amount;
        } else if (t.type === 'Loan') {
          balances[t.wallet] += t.amount;
        }
      }
    });

    return balances;
  }, [orders, transactions]);

  const totalCashOnHand = Object.values(walletBalances).reduce((a: number, b: number) => a + b, 0);

  const profitStats = useMemo(() => {
    const revenue = orders.reduce((sum, o) => sum + o.amountPaid, 0);
    const expenses = transactions.filter(t => t.type === 'Expense').reduce((sum, t) => sum + t.amount, 0);
    return { revenue, expenses, net: revenue - expenses };
  }, [orders, transactions]);

  const filteredTransactions = useMemo(() => {
    let txs = [...transactions].reverse();
    if (categoryFilter !== 'All') {
      txs = txs.filter(t => t.category === categoryFilter);
    }
    return txs;
  }, [transactions, categoryFilter]);

  const handleAddTx = (tx: Transaction) => {
    db.addTransaction(tx);
    db.addExpenseCategory(tx.category); // Auto-save new category if it doesn't exist
    setCategories(db.getExpenseCategories());
    setShowTxModal(false);
  };

  return (
    <div className="space-y-6 pb-32 px-1">
      <div className="flex items-center justify-between px-2">
        <h1 className="text-2xl font-black text-gray-800 tracking-tight">Accounting</h1>
        <button 
          onClick={() => setShowTxModal(true)}
          className="bg-pawPeach text-orange-800 px-5 py-3 rounded-2xl font-black flex items-center gap-2 text-xs uppercase tracking-widest shadow-lg shadow-orange-100 active:scale-95 transition-all hover:bg-orange-200"
        >
          <PlusIcon className="w-4 h-4" /> New Log
        </button>
      </div>

      {/* Financial Summary */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 px-2">
        <div className="bg-white p-6 rounded-[2.5rem] border-2 border-pawPink/30 shadow-sm">
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Total Cash on Hand</p>
          <p className="text-3xl font-black text-gray-800">₱{totalCashOnHand.toLocaleString()}</p>
        </div>
        <div className="bg-pawMint p-6 rounded-[2.5rem] shadow-sm">
          <p className="text-[10px] font-black text-green-700 uppercase tracking-widest mb-2">Total Revenue</p>
          <p className="text-3xl font-black text-green-800">₱{profitStats.revenue.toLocaleString()}</p>
        </div>
        <div className="bg-red-50 p-6 rounded-[2.5rem] border border-red-100 shadow-sm">
          <p className="text-[10px] font-black text-red-700 uppercase tracking-widest mb-2">Total Expenses</p>
          <p className="text-3xl font-black text-red-800">₱{profitStats.expenses.toLocaleString()}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 px-2">
        {/* Wallet Breakdown */}
        <div className="bg-white p-8 rounded-[3rem] border-2 border-pawPink/20 shadow-lg">
          <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight mb-6">Wallets</h3>
          <div className="grid grid-cols-2 gap-4">
            {Object.entries(walletBalances).map(([name, bal]) => (
              <div key={name} className="bg-pawCream p-5 rounded-[2rem] hover:bg-yellow-50 transition-colors">
                <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1">{name}</p>
                <p className="text-xl font-black text-gray-800">₱{bal.toLocaleString()}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Recent Transactions */}
        <div className="bg-white p-8 rounded-[3rem] border-2 border-pawPink/20 shadow-lg flex flex-col h-[500px]">
          <div className="flex justify-between items-center mb-6 shrink-0">
             <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight">History</h3>

             {/* Category Filter */}
             <select 
               value={categoryFilter}
               onChange={(e) => setCategoryFilter(e.target.value)}
               className="bg-gray-100 text-gray-500 text-[10px] font-black uppercase tracking-widest py-2 px-3 rounded-xl border-none outline-none focus:ring-2 focus:ring-pawPink"
             >
               <option value="All">All Categories</option>
               {categories.map(c => <option key={c} value={c}>{c}</option>)}
             </select>
          </div>

          <div className="overflow-y-auto custom-scrollbar flex-1 pr-2 space-y-3">
            {filteredTransactions.map(t => (
              <div key={t.id} className="flex items-center justify-between p-4 bg-gray-50 rounded-[2rem] border border-gray-100 hover:border-pawPink transition-all">
                <div className="flex items-center gap-4">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center text-xs font-black shrink-0 ${t.type === 'Expense' ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}>
                    {t.type.charAt(0)}
                  </div>
                  <div>
                    <p className="text-sm font-black text-gray-800 leading-tight">{t.category}</p>
                    <p className="text-[10px] text-gray-400 uppercase font-bold tracking-wider">{t.wallet} • {new Date(t.createdAt).toLocaleDateString()}</p>
                    {t.note && <p className="text-[10px] text-gray-400 italic mt-0.5">"{t.note}"</p>}
                  </div>
                </div>
                <p className={`font-black text-sm whitespace-nowrap ${t.type === 'Expense' || t.type === 'Withdrawal' ? 'text-red-500' : 'text-green-500'}`}>
                  {t.type === 'Expense' || t.type === 'Withdrawal' ? '-' : '+'}₱{t.amount.toLocaleString()}
                </p>
              </div>
            ))}
            {filteredTransactions.length === 0 && (
              <div className="text-center py-20 opacity-50 flex flex-col items-center">
                 <div className="text-4xl mb-2">🧾</div>
                 <p className="font-bold text-gray-400 text-xs uppercase tracking-widest">No logs found</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {showTxModal && (
        <TransactionModal 
          categories={categories}
          onClose={() => setShowTxModal(false)} 
          onSave={handleAddTx} 
        />
      )}
    </div>
  );
};

