// Summary / Packing List Modal
const SessionSummaryModal: React.FC<{ session: LiveSession; onClose: () => void }> = ({ session, onClose }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  useEffect(() => { const allOrders = db.getOrders(); setOrders(allOrders.filter(o => o.sessionId === session.id)); }, [session]);
  const groupedOrders = useMemo(() => {
    const grouped: Record<string, Order[]> = {};
    orders.forEach(o => { if (!grouped[o.customerUsername]) grouped[o.customerUsername] = []; grouped[o.customerUsername].push(o); });
    return grouped;
  }, [orders]);
  const totalSales = orders.reduce((sum, o) => sum + o.totalPrice, 0);

  return createPortal(
    <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center p-0 md:p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
      <div className="bg-white w-full max-w-2xl h-[90vh] md:h-auto md:max-h-[85vh] rounded-t-[3rem] md:rounded-[3rem] overflow-hidden shadow-2xl animate-scaleUp flex flex-col">
        <div className="bg-pawSoftBlue p-8 shrink-0">
          <div className="flex justify-between items-start">
            <div><p className="text-blue-600 font-black text-xs uppercase tracking-widest mb-1">{session.date}</p><h3 className="text-2xl font-black text-gray-800 uppercase tracking-tight leading-none">{session.name}</h3></div>
            <button onClick={onClose} className="bg-white/50 p-2 rounded-full hover:bg-white text-blue-900 transition-all"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg></button>
          </div>
          <div className="mt-6 flex gap-4">
             <div className="bg-white/60 px-4 py-2 rounded-xl"><p className="text-[10px] font-black text-blue-800 uppercase tracking-widest">Total Sales</p><p className="text-xl font-black text-gray-800">₱{totalSales.toLocaleString()}</p></div>
             <div className="bg-white/60 px-4 py-2 rounded-xl"><p className="text-[10px] font-black text-blue-800 uppercase tracking-widest">Total Parcels</p><p className="text-xl font-black text-gray-800">{Object.keys(groupedOrders).length}</p></div>
          </div>
        </div>
        <div className="p-6 md:p-8 overflow-y-auto custom-scrollbar flex-1 bg-white">
          <h4 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-6">Packing List (By Customer)</h4>
          {Object.keys(groupedOrders).length === 0 ? (<p className="text-center text-gray-400 italic">No orders found in this session.</p>) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {Object.entries(groupedOrders).map(([username, items]) => {
                 const orderItems = items as Order[];
                 const customerTotal = orderItems.reduce((sum, i) => sum + i.totalPrice, 0);
                 const hasUnpaid = orderItems.some(i => i.paymentStatus !== PaymentStatus.PAID);
                 return (
                   <div key={username} className="bg-gray-50 rounded-[2rem] p-5 border border-gray-100 break-inside-avoid">
                      <div className="flex justify-between items-center mb-4 border-b border-gray-200 pb-2">
                        <div className="flex items-center gap-2"><div className="w-8 h-8 bg-pawPink rounded-full flex items-center justify-center text-[10px] font-black text-pawPinkDark uppercase">{username.charAt(0)}</div><span className="font-black text-gray-800 text-sm">@{username}</span></div>
                        <div className="text-right"><span className="block font-black text-gray-800">₱{customerTotal}</span>{hasUnpaid && <span className="text-[9px] text-red-500 font-bold uppercase">Unpaid Items</span>}</div>
                      </div>
                      <ul className="space-y-2">
                        {orderItems.map(item => (
                          <li key={item.id} className="flex justify-between text-xs items-center">
                            <span className="text-gray-600 font-bold w-3/4 truncate">{item.quantity}x {item.productName} {item.isFreebie && <span className="ml-1 text-[8px] bg-orange-100 text-orange-600 px-1 rounded uppercase font-black">Free</span>}</span>
                            <span className="text-gray-400 font-bold">₱{item.totalPrice}</span>
                          </li>
                        ))}
                      </ul>
                   </div>
                 );
              })}
            </div>
          )}
        </div>
        <div className="p-4 bg-white border-t border-gray-100"><button onClick={onClose} className="w-full py-4 bg-gray-100 text-gray-500 font-black uppercase text-xs tracking-widest rounded-2xl hover:bg-gray-200 transition-all">Close Review</button></div>
      </div>
    </div>,
    document.body
  );
};

