                              <div>
                                 <h4 className="font-black text-gray-800 text-lg group-hover:text-pawPinkDark transition-colors">@{username}</h4>
                                 <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">{count} items • {new Date(firstItem.createdAt).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
