                  <ClockIcon className="w-3 h-3" /> Recent Orders
               </button>
            </div>

            {/* Cart List - Receipt Style */}
            <div className="flex-1 overflow-y-auto custom-scrollbar space-y-2 min-h-[200px] max-h-[50vh] mb-4 bg-white rounded-2xl p-4 shadow-inner border border-gray-100 relative">
