// NEW: Recent History Modal with Load to Cart
const LiveHistoryModal: React.FC<{ orders: Order[]; onClose: () => void; onSelectCustomer: (username: string) => void }> = ({ orders, onClose, onSelectCustomer }) => {
  const groupedOrders = useMemo(() => {
    const grouped: Record<string, Order[]> = {};
    orders.forEach(o => { if (!grouped[o.customerUsername]) grouped[o.customerUsername] = []; grouped[o.customerUsername].push(o); });
    return grouped;
  }, [orders]);

  const customerList = Object.keys(groupedOrders);

  return createPortal(
    <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center p-0 md:p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
      <div className="bg-white w-full max-w-lg h-[90vh] md:h-auto md:max-h-[85vh] rounded-t-[3rem] md:rounded-[3rem] overflow-hidden shadow-2xl animate-scaleUp flex flex-col">
         {/* Header */}
