                           <div className="flex items-center gap-4">
                              <div className="w-12 h-12 bg-pawPink rounded-full flex items-center justify-center text-pawPinkDark font-black text-lg">
                                 {username.charAt(0).toUpperCase()}
                              </div>
                              <div>
                                 <h4 className="font-black text-gray-800 text-lg group-hover:text-pawPinkDark transition-colors">@{username}</h4>
                                 <p className="text-xs text-gray-400 font-bold uppercase tracking-wider">{count} items • {new Date(firstItem.createdAt).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                              </div>
                           </div>
                           <div className="text-right">
                              <p className="font-black text-gray-800 text-xl">₱{total.toLocaleString()}</p>
                              <div className="flex items-center justify-end gap-1 text-[10px] font-black text-blue-400 uppercase tracking-widest mt-1">
                                 <EditIcon className="w-3 h-3" /> Edit
                              </div>
                           </div>
                        </div>
                     </button>
                  );
               })
            )}
         </div>

         <div className="p-6 bg-white border-t border-gray-100">
             <button onClick={onClose} className="w-full py-5 bg-gray-100 text-gray-500 font-black uppercase text-xs tracking-widest rounded-[2rem] hover:bg-gray-200 transition-all">Close History</button>
         </div>
      </div>
    </div>,
    document.body
  );
};

const ScheduleModal = ({ onClose, onSet }: { onClose: () => void, onSet: (date: Date) => void }) => {
  const [timeStr, setTimeStr] = useState('');

  // Initialize with current time + 10 mins
  useEffect(() => {
     const now = new Date();
     now.setMinutes(now.getMinutes() + 10);
     setTimeStr(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
  }, []);

  const handleQuickPick = (minutesToAdd: number) => {
    const now = new Date();
    const future = new Date(now.getTime() + minutesToAdd * 60000);
    setTimeStr(future.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }));
  };

  const handleSet8PM = () => {
     setTimeStr('20:00');
  }

  const handleConfirm = () => {
    if (!timeStr) return;
    const [h, m] = timeStr.split(':').map(Number);
    const date = new Date();
    date.setHours(h, m, 0, 0);

    // If the selected time is in the past for today, assume it's for tomorrow? 
    // Or just let it set, user might want to test.
    // Simple check: if less than now, maybe valid if user wants immediate start.

    onSet(date);
  };

  return createPortal(
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
            <div className="bg-white w-full max-w-sm rounded-[2.5rem] overflow-hidden shadow-2xl animate-scaleUp p-8 text-center">
               <div className="bg-gray-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                  <CalendarIcon className="w-8 h-8 text-black" />
               </div>
               <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight mb-2">Schedule Live</h3>
               <p className="text-gray-500 font-bold text-xs mb-6">Select a time to auto-start.</p>

               {/* Quick Picks */}
               <div className="grid grid-cols-2 gap-3 mb-6">
                  <button onClick={() => handleQuickPick(15)} className="bg-pawSoftBlue text-blue-800 py-3 rounded-xl text-xs font-black uppercase hover:bg-blue-200 transition-colors">+ 15 MINS</button>
                  <button onClick={() => handleQuickPick(30)} className="bg-pawSoftBlue text-blue-800 py-3 rounded-xl text-xs font-black uppercase hover:bg-blue-200 transition-colors">+ 30 MINS</button>
                  <button onClick={() => handleQuickPick(60)} className="bg-pawSoftBlue text-blue-800 py-3 rounded-xl text-xs font-black uppercase hover:bg-blue-200 transition-colors">+ 1 HOUR</button>
                  <button onClick={handleSet8PM} className="bg-pawPink/30 text-pawPinkDark py-3 rounded-xl text-xs font-black uppercase hover:bg-pawPink/50 transition-colors">8:00 PM</button>
               </div>

               <input 
                 type="time" 
                 className="w-full bg-gray-50 p-4 rounded-2xl font-black text-5xl text-center text-gray-800 border-2 border-gray-100 focus:border-pawPinkDark outline-none mb-8 appearance-none"
                 value={timeStr}
                 onChange={(e) => setTimeStr(e.target.value)}
               />

               <div className="flex gap-3">
                  <button onClick={onClose} className="flex-1 py-4 bg-gray-100 text-gray-500 font-black uppercase text-xs tracking-widest rounded-2xl hover:bg-gray-200 transition-all">Cancel</button>
                  <button 
                    onClick={handleConfirm}
                    className="flex-1 py-4 bg-pawPinkDark text-white font-black uppercase text-xs tracking-widest rounded-2xl shadow-lg hover:bg-red-400 transition-all"
                  >
                    Set Time
                  </button>
               </div>
            </div>
          </div>,
          document.body
  );
};

export default LiveSell;

import React, { useState, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { Order, PaymentStatus, ShippingStatus, PaymentMethod, LiveSession } from '../types';
import { CartIcon, PlusIcon, PawIcon, SearchIcon } from '../components/Icons';

const OFF_LIVE_ID = 'OFF_LIVE';

// Extend Order type to support grouping
interface GroupedOrder extends Order {
  ids: string[]; // List of all order IDs in this group
  items: Order[]; // Full order objects for breakdown
}

const Orders: React.FC = () => {
  const [selectedSession, setSelectedSession] = useState<LiveSession | null>(null);

  // -- Orders View State --
  const [filter, setFilter] = useState('All');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedOrder, setSelectedOrder] = useState<GroupedOrder | null>(null);
  const [allOrders, setAllOrders] = useState(db.getOrders());

  // Derived state: Get list of sessions including virtual off-live
  const sessions = useMemo(() => {
    const dbSessions = db.getSessions().sort((a, b) => b.id.localeCompare(a.id));
    const hasOffLive = allOrders.some(o => o.sessionId === OFF_LIVE_ID);

    if (hasOffLive) {
      const offLiveSession: LiveSession = {
        id: OFF_LIVE_ID,
        name: 'Off-Live / Manual Orders',
        date: 'Manual',
        totalSales: 0,
        totalOrders: 0,
        isOpen: true // Always treat as open
      };
      return [offLiveSession, ...dbSessions];
    }
    return dbSessions;
  }, [allOrders]);

  // Derived state: Get orders for the selected session only
  const sessionOrders = useMemo(() => {
    if (!selectedSession) return [];
    return allOrders.filter(o => o.sessionId === selectedSession.id);
  }, [allOrders, selectedSession]);

  // Derived state: Filter and Group orders
  const groupedFilteredOrders = useMemo(() => {
    // 1. First Filter
    const filtered = sessionOrders.filter(o => {
      const matchesSearch = o.customerUsername.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            o.productName.toLowerCase().includes(searchTerm.toLowerCase());
      if (filter === 'All') return matchesSearch;
      if (filter === 'Unpaid') return matchesSearch && o.paymentStatus === PaymentStatus.UNPAID;
      if (filter === 'To Ship') return matchesSearch && o.shippingStatus === ShippingStatus.PENDING;
      return matchesSearch;
    });

    // 2. Then Group BY CUSTOMER
    const groups: Record<string, GroupedOrder> = {};

    filtered.forEach(order => {
      // Key is just the username now to group all their items together
      const key = order.customerUsername;

      if (!groups[key]) {
        // Initialize group with the first order's data
        groups[key] = { 
          ...order, 
          ids: [order.id],
          items: [order]
        };
      } else {
        // Aggregate
        groups[key].quantity += order.quantity;
        groups[key].totalPrice += order.totalPrice; 
        groups[key].amountPaid += order.amountPaid;
        groups[key].ids.push(order.id);
        groups[key].items.push(order);

        // Update timestamp to latest
        if (order.createdAt > groups[key].createdAt) {
           groups[key].createdAt = order.createdAt;
        }
      }
    });

    // 3. Post-process groups to determine overall status
    const result = Object.values(groups).map(group => {
       // Determine Mixed Statuses
       const allPaid = group.items.every(i => i.paymentStatus === PaymentStatus.PAID);
       const allUnpaid = group.items.every(i => i.paymentStatus === PaymentStatus.UNPAID);
       const aggregatePaymentStatus = allPaid ? PaymentStatus.PAID : (allUnpaid ? PaymentStatus.UNPAID : PaymentStatus.PARTIAL);

       const allShipped = group.items.every(i => i.shippingStatus === ShippingStatus.SHIPPED);
       const allCancelled = group.items.every(i => i.shippingStatus === ShippingStatus.CANCELLED);
       const aggregateShippingStatus = allShipped ? ShippingStatus.SHIPPED : (allCancelled ? ShippingStatus.CANCELLED : ShippingStatus.PENDING);

       return {
         ...group,
         paymentStatus: aggregatePaymentStatus,
         shippingStatus: aggregateShippingStatus,
         productName: group.items.length > 1 ? `${group.items.length} Items (Bundle)` : group.items[0].productName
       };
    });

    // 4. Sort
    return result.sort((a, b) => b.createdAt - a.createdAt);
  }, [sessionOrders, filter, searchTerm]);

  const handleUpdateStatus = (updatedGroup: GroupedOrder) => {
    // We need to apply the changes to ALL orders in the group
    if (updatedGroup.ids && updatedGroup.ids.length > 0) {
       // Calculate payment distribution ratio
       const ratio = updatedGroup.totalPrice > 0 ? updatedGroup.amountPaid / updatedGroup.totalPrice : 0;

       updatedGroup.ids.forEach(id => {
          const originalOrder = db.getOrders().find(o => o.id === id);
          if (originalOrder) {
             originalOrder.paymentStatus = updatedGroup.paymentStatus;
             originalOrder.paymentMethod = updatedGroup.paymentMethod;
             originalOrder.shippingStatus = updatedGroup.shippingStatus;
             // Distribute the paid amount proportionally
             originalOrder.amountPaid = originalOrder.totalPrice * ratio; 

             db.updateOrder(originalOrder);
          }
       });
    }

    setAllOrders(db.getOrders()); // Refresh view
    setSelectedOrder(null);
  };

  const handleDeleteOrder = (group: GroupedOrder) => {
    if (confirm(`Delete all ${group.quantity} items for @${group.customerUsername}? This cannot be undone.`)) {
      group.ids.forEach(id => db.deleteOrder(id));
      setAllOrders(db.getOrders());
    }
  };

  // --- VIEW 1: Session Selection List ---
  if (!selectedSession) {
    const manualSession = sessions.find(s => s.id === OFF_LIVE_ID);
    const liveSessions = sessions.filter(s => s.id !== OFF_LIVE_ID);

    return (
      <div className="space-y-8 pb-24 px-1">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Order Batches</h1>
          <p className="text-gray-500 font-bold text-sm">Select a category to manage orders.</p>
        </div>

        {/* Manual / Off-Live Section */}
        {manualSession && (
          <div className="animate-fadeIn">
            <h2 className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-4 ml-2 flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-blue-400"></span>
              Manual / Off-Live
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              <SessionCard 
                session={manualSession} 
                orders={allOrders.filter(o => o.sessionId === manualSession.id)}
                onClick={() => setSelectedSession(manualSession)}
              />
            </div>
          </div>
        )}

        {/* Live Sessions Section */}
        <div className="animate-fadeIn">
           <h2 className="text-[10px] font-black text-pawPinkDark uppercase tracking-widest mb-4 ml-2 flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-pawPinkDark"></span>
              Live Session History
           </h2>
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {liveSessions.length === 0 ? (
                 <div className="col-span-full py-20 text-center flex flex-col items-center opacity-40 bg-gray-50 rounded-[2.5rem] border-2 border-dashed border-gray-200">
                    <div className="text-6xl mb-4">📺</div>
                    <p className="font-bold italic text-gray-400">No live sessions recorded yet.</p>
                 </div>
              ) : (
                liveSessions.map(session => (
                  <SessionCard 
                    key={session.id}
                    session={session} 
                    orders={allOrders.filter(o => o.sessionId === session.id)}
                    onClick={() => setSelectedSession(session)}
                  />
                ))
              )}
           </div>
        </div>
      </div>
    );
  }

  // --- VIEW 2: Specific Session Orders ---
  return (
    <div className="space-y-6 pb-24 px-1 animate-fadeIn">
      {/* Header & Back Button */}
      <div className="flex flex-col gap-4">
        <button 
          onClick={() => { setSelectedSession(null); setSearchTerm(''); setFilter('All'); }}
          className="self-start flex items-center gap-2 text-gray-500 hover:text-pawPinkDark font-black text-xs uppercase tracking-widest transition-colors mb-2"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" /></svg>
          Back to Batches
        </button>

        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
             <div className="flex items-center gap-2">
                <h1 className="text-2xl font-black text-gray-800 tracking-tight">{selectedSession.name}</h1>
                {selectedSession.id === OFF_LIVE_ID && <span className="text-[10px] bg-blue-100 text-blue-500 px-2 py-1 rounded-lg font-black uppercase tracking-widest">Manual</span>}
             </div>
             <p className="text-gray-400 font-bold text-xs uppercase tracking-widest mt-1">
               Showing {groupedFilteredOrders.length} customers
             </p>
          </div>

          <div className="flex items-center bg-white p-1.5 rounded-[1.5rem] shadow-sm border border-pawPink/30 self-start">
            {['All', 'Unpaid', 'To Ship'].map(f => (
              <button 
                key={f} 
                onClick={() => setFilter(f)}
                className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${
                  filter === f ? 'bg-pawPinkDark text-white shadow-md' : 'text-gray-400 hover:text-gray-600'
                }`}
              >
                {f}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Search Bar */}
      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
          <SearchIcon className="h-5 w-5 text-gray-300" />
        </div>
        <input 
          type="text" 
          placeholder="Search items or customers..." 
          className="w-full bg-white border-2 border-pawPink/30 rounded-[1.5rem] pl-12 pr-5 py-4 shadow-sm text-gray-700 font-bold focus:border-pawPinkDark transition-all placeholder:text-gray-300 outline-none"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Order Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {groupedFilteredOrders.length === 0 ? (
          <div className="col-span-full py-20 text-center flex flex-col items-center opacity-40">
             <CartIcon className="w-16 h-16 mb-2 text-gray-300" />
             <p className="font-bold italic text-gray-400">No customers found.</p>
          </div>
        ) : (
          groupedFilteredOrders.map(group => (
            <OrderCard 
               key={group.ids[0]} // Use first ID as key
               order={group} 
               onEdit={() => setSelectedOrder(group)} 
               onDelete={() => handleDeleteOrder(group)} 
            />
          ))
        )}
      </div>

      {/* Modal Reuse */}
      {selectedOrder && (
        <StatusModal 
          order={selectedOrder} 
          onClose={() => setSelectedOrder(null)} 
          onSave={handleUpdateStatus}
        />
      )}
    </div>
  );
};

