                      <span className="bg-white text-gray-500 text-[10px] font-bold w-6 h-6 flex items-center justify-center rounded-full shadow-sm border border-gray-100">{index + 1}</span>
                      <div className="text-xs font-bold text-gray-700">
                         {item.productName} 
                         {item.isFreebie && <span className="ml-2 bg-orange-100 text-orange-600 px-1.5 py-0.5 rounded text-[8px] uppercase font-black">Free</span>}
                      </div>
                   </div>
                   <span className="text-sm font-black text-gray-800">₱{item.totalPrice}</span>
                </div>
              ))}
              <div className="flex justify-between items-center p-3 mt-2 bg-pawCream rounded-xl border border-dashed border-pawPink/50">
                 <span className="text-xs font-black text-gray-500 uppercase">Total</span>
                 <span className="text-lg font-black text-gray-800">₱{order.totalPrice.toLocaleString()}</span>
              </div>
            </div>
          </div>

          <hr className="border-gray-100 mb-6" />

          {/* Form Controls */}
          <div className="space-y-5">
            <div className="grid grid-cols-2 gap-4">
              <div className="col-span-2">
                <label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Payment Status</label>
                <select 
                  value={formData.paymentStatus}
                  onChange={(e) => setFormData({...formData, paymentStatus: e.target.value as PaymentStatus})}
                  className="w-full bg-pawCream p-4 rounded-2xl border-none font-black mt-1 text-gray-800 appearance-none"
                >
                  {Object.values(PaymentStatus).map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>

              <div className="col-span-2">
                <label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Payment Method</label>
                <select 
                  value={formData.paymentMethod || ''}
                  onChange={(e) => setFormData({...formData, paymentMethod: e.target.value as PaymentMethod})}
                  className="w-full bg-pawCream p-4 rounded-2xl border-none font-black mt-1 text-gray-800 appearance-none"
                >
                  <option value="">None Selected</option>
                  {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>

              <div>
                <label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Amount Paid (₱)</label>
                <input 
                  type="number"
                  value={formData.amountPaid === 0 ? '' : formData.amountPaid}
                  onChange={(e) => {
                    const val = e.target.value === '' ? 0 : Number(e.target.value);
                    setFormData({
                      ...formData, 
                      amountPaid: val, 
                      paymentStatus: val >= formData.totalPrice ? PaymentStatus.PAID : (val > 0 ? PaymentStatus.PARTIAL : PaymentStatus.UNPAID)
                    });
                  }}
                  className="w-full bg-pawCream p-4 rounded-2xl border-none font-black mt-1 text-gray-800"
                />
              </div>

              <div>
                <label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Shipping</label>
                <select 
                  value={formData.shippingStatus}
                  onChange={(e) => setFormData({...formData, shippingStatus: e.target.value as ShippingStatus})}
                  className="w-full bg-pawCream p-4 rounded-2xl border-none font-black mt-1 text-gray-800 appearance-none"
                >
                  {Object.values(ShippingStatus).map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
            </div>
          </div>
        </div>

        {/* Footer Actions */}
        <div className="p-6 bg-white border-t border-gray-100 flex gap-4 shrink-0">
          <button onClick={onClose} className="flex-1 py-5 bg-gray-100 text-gray-400 font-black uppercase text-xs tracking-widest rounded-3xl active:scale-95 transition-all">Cancel</button>
          <button onClick={() => onSave(formData)} className="flex-1 py-5 bg-pawPinkDark text-white font-black uppercase text-xs tracking-widest rounded-3xl shadow-lg active:scale-95 transition-all">Update Batch</button>
        </div>
      </div>
    </div>,
    document.body
  );
};

export default Orders;

import React, { useState, useEffect, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { Bale, Order, Product } from '../types';
import { PlusIcon, PawIcon, SearchIcon, CartIcon } from '../components/Icons';

const Bales: React.FC = () => {
  const [bales, setBales] = useState(db.getBales());
  const [showModal, setShowModal] = useState(false);
  const [selectedBale, setSelectedBale] = useState<Bale | null>(null);
  const [viewingBale, setViewingBale] = useState<Bale | null>(null);
  const [statusFilter, setStatusFilter] = useState('All');

  const products = db.getProducts();
  const orders = db.getOrders();

  const getBaleStats = (baleId: string) => {
    const baleProducts = products.filter(p => p.baleBatch === baleId);
    const baleProductIds = baleProducts.map(p => p.id);
    const baleOrders = orders.filter(o => baleProductIds.includes(o.productId));
    const liveOrders = baleOrders.filter(o => o.sessionId !== 'OFF_LIVE');
    const manualOrders = baleOrders.filter(o => o.sessionId === 'OFF_LIVE');
    const liveSold = liveOrders.reduce((sum, o) => sum + o.quantity, 0);
    const liveRevenue = liveOrders.reduce((sum, o) => sum + o.totalPrice, 0);
    const manualSold = manualOrders.reduce((sum, o) => sum + o.quantity, 0);
    const manualRevenue = manualOrders.reduce((sum, o) => sum + o.totalPrice, 0);
    const soldCount = liveSold + manualSold;
    const revenue = liveRevenue + manualRevenue;
    return { soldCount, revenue, liveSold, liveRevenue, manualSold, manualRevenue };
  };

  useEffect(() => {
    let hasUpdates = false;
    const updatedBales = bales.map(bale => {
      const stats = getBaleStats(bale.id);
      if (bale.itemCount > 0 && stats.soldCount >= bale.itemCount && bale.status !== 'Sold Out') {
        hasUpdates = true;
        const newBale: Bale = { ...bale, status: 'Sold Out' };
        db.updateBale(newBale);
        return newBale;
      }
      return bale;
    });
    if (hasUpdates) setBales(updatedBales);
  });

  const filteredBales = useMemo(() => {
    if (statusFilter === 'All') return bales;
    return bales.filter(b => b.status === statusFilter);
  }, [bales, statusFilter]);

  const handleSaveBale = (bale: Bale) => {
    db.updateBale(bale);
    setBales(db.getBales());
    setShowModal(false);
    setSelectedBale(null);
  };

  const handleDeleteBale = (id: string) => {
    if (confirm('Permanently remove this bale record?')) {
      db.deleteBale(id);
      setBales(db.getBales());
      if (viewingBale?.id === id) setViewingBale(null);
    }
  };

  if (viewingBale) {
    return (
      <BaleDetails 
        bale={viewingBale} 
        onBack={() => setViewingBale(null)} 
        stats={getBaleStats(viewingBale.id)}
      />
    );
  }

  return (
    <div className="space-y-6 pb-32 px-1">
      <div className="flex items-center justify-between px-2">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Bale Track</h1>
          <p className="text-gray-500 font-bold text-sm">Monitor sales performance & ROI per sack.</p>
        </div>
        <button 
          onClick={() => { setSelectedBale(null); setShowModal(true); }}
          className="bg-pawSoftBlue text-blue-800 px-6 py-3 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center gap-2 shadow-lg shadow-blue-50 active:scale-95 transition-all hover:bg-blue-200"
        >
          <PlusIcon className="w-4 h-4" /> New Batch
        </button>
      </div>

      <div className="flex items-center gap-3 px-2 overflow-x-auto pb-2 scrollbar-hide">
         {['All', 'Ordered', 'Arrived', 'On Sale', 'Sold Out'].map(filter => (
            <button key={filter} onClick={() => setStatusFilter(filter)} className={`px-5 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap border-2 ${statusFilter === filter ? 'bg-pawPinkDark text-white border-pawPinkDark shadow-lg shadow-pawPinkDark/20' : 'bg-white border-pawPink/20 text-gray-400 hover:border-pawPinkDark hover:text-gray-600'}`}>{filter}</button>
         ))}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 px-2">
        {filteredBales.map(bale => {
          const stats = getBaleStats(bale.id);
          const percentSold = bale.itemCount > 0 ? Math.min(100, (stats.soldCount / bale.itemCount) * 100) : 0;
          const netProfit = stats.revenue - bale.cost;
          const isProfitable = netProfit > 0;
          const roiPercent = bale.cost > 0 ? (netProfit / bale.cost) * 100 : 0;
          const breakEvenProgress = Math.min(100, (stats.revenue / bale.cost) * 100);
          const unitCost = bale.itemCount > 0 ? (bale.cost / bale.itemCount) : 0;

          return (
            <div key={bale.id} onClick={() => setViewingBale(bale)} className="bg-white rounded-[3rem] p-8 border-2 border-pawPink/20 shadow-xl overflow-hidden relative group animate-fadeIn hover:border-pawPinkDark transition-all cursor-pointer active:scale-[0.98]">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <div className="flex items-center gap-2 mb-2">
                    <span className="text-[10px] text-white bg-gray-800 px-2 py-1 rounded-md font-black uppercase tracking-widest">{bale.id}</span>
                    <span className={`text-[10px] font-black uppercase tracking-widest px-2 py-1 rounded-md ${bale.status === 'Sold Out' ? 'bg-gray-200 text-gray-500' : 'bg-blue-50 text-blue-600'}`}>{bale.status}</span>
                  </div>
                  <h3 className="text-2xl font-black text-gray-800 tracking-tighter leading-none">{bale.name}</h3>
                </div>
                <button onClick={(e) => { e.stopPropagation(); setSelectedBale(bale); setShowModal(true); }} className="p-2 text-gray-300 hover:text-pawPinkDark transition-colors bg-white rounded-full shadow-sm hover:shadow-md z-10">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                </button>
              </div>

              <div className={`rounded-[2rem] p-6 mb-6 relative overflow-hidden ${isProfitable ? 'bg-pawMint' : 'bg-red-50 border border-red-100'}`}>
                <div className="flex justify-between items-start mb-1">
                    <p className={`text-[10px] font-black uppercase tracking-widest ${isProfitable ? 'text-green-800' : 'text-red-500'}`}>{isProfitable ? '✨ Net Profit' : '📉 Capital Recovery'}</p>
                    {isProfitable && <span className="bg-white/60 px-2 py-1 rounded-lg text-[10px] font-black text-green-800 backdrop-blur-sm">ROI: {roiPercent.toFixed(1)}%</span>}
                </div>
                <div className="flex items-baseline gap-1">
                   <h2 className={`text-4xl font-black tracking-tighter ${isProfitable ? 'text-green-900' : 'text-red-600'}`}>{isProfitable ? '+' : ''}₱{Math.abs(netProfit).toLocaleString()}</h2>
                   {!isProfitable && <span className="text-xs font-bold text-red-400">needed to break even</span>}
                </div>
                {!isProfitable && (
                   <div className="mt-4 w-full bg-red-200/50 h-2 rounded-full overflow-hidden">
                      <div className="h-full bg-red-500 rounded-full transition-all duration-1000" style={{ width: `${breakEvenProgress}%` }}></div>
                   </div>
                )}
              </div>

              <div className="grid grid-cols-2 gap-4 mb-6">
                 <div className="bg-pawCream/40 p-4 rounded-2xl">
                    <div className="flex justify-between items-center mb-1">
                      <span className="text-[9px] font-black text-gray-400 uppercase tracking-wider">Invested</span>
                      <span className="text-[9px] font-black text-gray-400 uppercase tracking-wider">Unit Puhunan</span>
                    </div>
                    <div className="flex justify-between items-center">
                       <span className="font-bold text-gray-500 text-sm">₱{bale.cost.toLocaleString()}</span>
                       <span className="text-gray-300">→</span>
                       <span className="font-black text-orange-600 text-lg">₱{unitCost.toFixed(2)}</span>
                    </div>
                 </div>
                 <div className="bg-pawSoftBlue/40 p-4 rounded-2xl">
                    <p className="text-[9px] font-black text-blue-400 uppercase tracking-wider mb-1">Total Items</p>
                    <div className="flex items-baseline gap-1">
                       <span className="font-black text-gray-800 text-2xl">{bale.itemCount}</span>
                       <span className="text-[10px] font-bold text-gray-400">pcs</span>
                    </div>
                 </div>
              </div>

              <div>
                <div className="flex justify-between text-[11px] font-black text-gray-500 uppercase tracking-widest mb-2">
                  <span>Sales Progress</span>
                  <span>{stats.soldCount} / {bale.itemCount} Sold ({percentSold.toFixed(0)}%)</span>
                </div>
                <div className="w-full h-5 bg-gray-100 rounded-full overflow-hidden shadow-inner border border-gray-100">
                  <div className={`h-full transition-all duration-1000 rounded-full px-2 ${percentSold >= 100 ? 'bg-green-400' : 'bg-pawPinkDark'}`} style={{ width: `${percentSold}%` }}></div>
                </div>
              </div>

               <button onClick={(e) => { e.stopPropagation(); handleDeleteBale(bale.id); }} className="absolute bottom-8 right-8 text-gray-200 hover:text-red-400 transition-colors p-2 z-10" title="Delete Bale">
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
               </button>
            </div>
          );
        })}
      </div>
      {showModal && <BaleModal bale={selectedBale} onClose={() => { setShowModal(false); setSelectedBale(null); }} onSave={handleSaveBale} />}
    </div>
  );
};

const BaleDetails: React.FC<{ bale: Bale; onBack: () => void; stats: any }> = ({ bale, onBack, stats }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const allOrders = db.getOrders();
  const allProducts = db.getProducts();
  const sessions = db.getSessions();
  const baleOrders = useMemo(() => {
    const productsInBale = allProducts.filter(p => p.baleBatch === bale.id).map(p => p.id);
    return allOrders.filter(o => productsInBale.includes(o.productId)).sort((a, b) => b.createdAt - a.createdAt);
  }, [allOrders, allProducts, bale.id]);
  const filteredOrders = useMemo(() => baleOrders.filter(o => o.customerUsername.toLowerCase().includes(searchTerm.toLowerCase()) || o.productName.toLowerCase().includes(searchTerm.toLowerCase())), [baleOrders, searchTerm]);
  const getSessionName = (sessionId: string) => sessionId === 'OFF_LIVE' ? 'Manual / Off-Live' : (sessions.find(s => s.id === sessionId)?.name || 'Unknown Session');
  const unitCost = bale.itemCount > 0 ? (bale.cost / bale.itemCount) : 0;
  const netProfit = stats.revenue - bale.cost;
  const isProfitable = netProfit > 0;

  return (
    <div className="space-y-6 pb-32 px-1 animate-fadeIn">
