import React, { useState, useEffect, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { Bale, Order, Product } from '../types';
import { PlusIcon, PawIcon, SearchIcon, CartIcon } from '../components/Icons';

const Bales: React.FC = () => {
  const [bales, setBales] = useState(db.getBales());
  const [showModal, setShowModal] = useState(false);
  const [selectedBale, setSelectedBale] = useState<Bale | null>(null);
  const [viewingBale, setViewingBale] = useState<Bale | null>(null);
  const [statusFilter, setStatusFilter] = useState('All');

  const products = db.getProducts();
  const orders = db.getOrders();

  const getBaleStats = (baleId: string) => {
    const baleProducts = products.filter(p => p.baleBatch === baleId).map(p => p.id);
    const baleOrders = orders.filter(o => baleProducts.includes(o.productId));
    const soldCount = baleOrders.reduce((sum, o) => sum + o.quantity, 0);
    const revenue = baleOrders.reduce((sum, o) => sum + o.totalPrice, 0);
    return { soldCount, revenue };
  };

  useEffect(() => {
    let hasUpdates = false;
    const updatedBales = bales.map(bale => {
      const stats = getBaleStats(bale.id);
      if (bale.itemCount > 0 && stats.soldCount >= bale.itemCount && bale.status !== 'Sold Out') {
        hasUpdates = true;
        const newBale: Bale = { ...bale, status: 'Sold Out' };
        db.updateBale(newBale);
        return newBale;
      }
      return bale;
    });
    if (hasUpdates) setBales(updatedBales);
  }, [bales, products, orders]);

  const filteredBales = useMemo(() => {
    if (statusFilter === 'All') return bales;
    return bales.filter(b => b.status === statusFilter);
  }, [bales, statusFilter]);

  const handleSaveBale = (bale: Bale) => {
    db.updateBale(bale);
    setBales(db.getBales());
    setShowModal(false);
    setSelectedBale(null);
  };

  if (viewingBale) {
    return <BaleDetails bale={viewingBale} onBack={() => setViewingBale(null)} stats={getBaleStats(viewingBale.id)} />;
  }

  return (
    <div className="space-y-6 pb-32 px-1 animate-fadeIn">
      <div className="flex items-center justify-between px-2">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Sourcing & Batches</h1>
          <p className="text-gray-500 font-bold text-sm">Monitor investment and item distribution.</p>
        </div>
        <button onClick={() => { setSelectedBale(null); setShowModal(true); }} className="bg-pawSoftBlue text-blue-800 px-6 py-3 rounded-2xl font-black uppercase text-xs tracking-widest flex items-center gap-2 transition-all active:scale-95 shadow-lg shadow-blue-50">
          <PlusIcon className="w-4 h-4" /> New Batch
        </button>
      </div>

      <div className="flex items-center gap-3 px-2 overflow-x-auto pb-2 scrollbar-hide">
         {['All', 'Ordered', 'Arrived', 'On Sale', 'Sold Out'].map(f => (
            <button key={f} onClick={() => setStatusFilter(f)} className={`px-5 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap border-2 ${statusFilter === f ? 'bg-pawPinkDark text-white border-pawPinkDark shadow-lg' : 'bg-white border-pawPink/20 text-gray-400 hover:border-pawPinkDark hover:text-gray-600'}`}>{f}</button>
         ))}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 px-2">
        {filteredBales.map(bale => {
          const stats = getBaleStats(bale.id);
          const percentSold = bale.itemCount > 0 ? Math.min(100, (stats.soldCount / bale.itemCount) * 100) : 0;
          const unitCost = bale.itemCount > 0 ? (bale.cost / bale.itemCount) : 0;
          const netProfit = stats.revenue - bale.cost;
          const isProfitable = netProfit > 0;

          return (
            <div key={bale.id} onClick={() => setViewingBale(bale)} className="bg-white rounded-[3rem] p-8 border-2 border-pawPink/20 shadow-xl overflow-hidden relative group animate-fadeIn hover:border-pawPinkDark cursor-pointer active:scale-[0.98] transition-all">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className={`text-[10px] font-black uppercase tracking-widest px-2 py-1 rounded-md mb-2 inline-block ${bale.status === 'Sold Out' ? 'bg-gray-200 text-gray-500' : 'bg-blue-50 text-blue-600'}`}>{bale.status}</span>
                  <h3 className="text-2xl font-black text-gray-800 tracking-tighter leading-none">{bale.name}</h3>
                </div>
                <button onClick={(e) => { e.stopPropagation(); setSelectedBale(bale); setShowModal(true); }} className="p-2 text-gray-300 hover:text-pawPinkDark transition-colors bg-white rounded-full shadow-sm">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                </button>
              </div>

              <div className={`rounded-[2rem] p-6 mb-6 ${isProfitable ? 'bg-pawMint' : 'bg-orange-50'}`}>
                <p className={`text-[10px] font-black uppercase tracking-widest ${isProfitable ? 'text-green-800' : 'text-orange-800'}`}>{isProfitable ? 'Current Profit' : 'Pending Capital Recovery'}</p>
                <h2 className={`text-4xl font-black tracking-tighter ${isProfitable ? 'text-green-900' : 'text-orange-900'}`}>{isProfitable ? '+' : ''}${Math.abs(netProfit).toLocaleString()}</h2>
              </div>

              <div className="grid grid-cols-2 gap-4 mb-6">
                 <div className="bg-pawCream/40 p-4 rounded-2xl">
                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-wider mb-1">Unit Break-even Cost</p>
                    <p className="font-black text-orange-600 text-xl">${unitCost.toFixed(2)}</p>
                 </div>
                 <div className="bg-pawSoftBlue/40 p-4 rounded-2xl">
                    <p className="text-[9px] font-black text-blue-400 uppercase tracking-wider mb-1">Total Items</p>
                    <p className="font-black text-gray-800 text-xl">{bale.itemCount} <span className="text-[10px]">pcs</span></p>
                 </div>
              </div>

              <div className="flex justify-between text-[11px] font-black text-gray-500 uppercase tracking-widest mb-2">
                <span>Distribution Progress</span>
                <span>{stats.soldCount} Sold ({percentSold.toFixed(0)}%)</span>
              </div>
              <div className="w-full h-4 bg-gray-100 rounded-full overflow-hidden shadow-inner border border-gray-100">
                <div className={`h-full transition-all duration-1000 rounded-full ${percentSold >= 100 ? 'bg-green-400' : 'bg-pawPinkDark'}`} style={{ width: `${percentSold}%` }}></div>
              </div>
            </div>
          );
        })}
      </div>
      {showModal && <BaleModal bale={selectedBale} onClose={() => setShowModal(false)} onSave={handleSaveBale} />}
    </div>
  );
};

