const ScheduleModal = ({ onClose, onSet }: { onClose: () => void, onSet: (date: Date) => void }) => {
  const [timeStr, setTimeStr] = useState('');
  const handleConfirm = () => {
    if (!timeStr) return;
    const [h, m] = timeStr.split(':').map(Number);
    const date = new Date();
    date.setHours(h, m, 0, 0);
    onSet(date);
  };
  return createPortal(
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
      <div className="bg-white w-full max-w-sm rounded-[2.5rem] p-8 text-center animate-scaleUp">
