         <input type="time" className="w-full bg-gray-50 p-4 rounded-2xl font-black text-5xl text-center text-gray-800 mb-8 outline-none" value={timeStr} onChange={(e) => setTimeStr(e.target.value)} />
         <div className="flex gap-3">
            <button onClick={onClose} className="flex-1 py-4 bg-gray-100 text-gray-500 font-black uppercase text-xs rounded-2xl">Cancel</button>
            <button onClick={handleConfirm} className="flex-1 py-4 bg-pawPinkDark text-white font-black uppercase text-xs rounded-2xl shadow-lg">Set Time</button>
         </div>
      </div>
    </div>, document.body
  );
};

