import React, { useMemo, useState, useEffect } from 'react';
import { db } from '../services/dbService';
import { PaymentStatus, ShippingStatus } from '../types';
import { BarChart, Bar, XAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { BoxIcon } from '../components/Icons';

const Dashboard: React.FC = () => {
  const orders = db.getOrders();
  const products = db.getProducts();
  const bales = db.getBales();
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const stats = useMemo(() => {
    const todayStr = new Date().toLocaleDateString('en-US');
    const todayOrders = orders.filter(o => new Date(o.createdAt).toLocaleDateString('en-US') === todayStr);
    const totalSalesToday = todayOrders.reduce((sum, o) => sum + o.totalPrice, 0);
    const pendingPayments = orders.filter(o => o.paymentStatus !== PaymentStatus.PAID).length;
    const toShip = orders.filter(o => o.shippingStatus === ShippingStatus.PENDING).length;
    return { salesToday: totalSalesToday, ordersToday: todayOrders.length, pendingPayments, toShip };
  }, [orders]);

  const activeBales = useMemo(() => {
    return bales.filter(b => b.status !== 'Sold Out').map(bale => {
        const baleProductIds = products.filter(p => p.baleBatch === bale.id).map(p => p.id);
        const soldCount = orders.filter(o => baleProductIds.includes(o.productId)).reduce((sum, o) => sum + o.quantity, 0);
        const remaining = Math.max(0, bale.itemCount - soldCount);
        const percentSold = bale.itemCount > 0 ? (soldCount / bale.itemCount) * 100 : 0;
        return { ...bale, soldCount, remaining, percentSold };
      }).sort((a, b) => a.remaining - b.remaining);
  }, [bales, products, orders]);

  return (
    <div className="space-y-6 pb-8 animate-fadeIn">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Shop Overview 🐾</h1>
          <p className="text-gray-500">Business performance metrics for today.</p>
        </div>
        <div className="bg-white/50 px-4 py-2 rounded-2xl border border-white shadow-sm flex flex-col items-end">
            <p className="text-xl font-black text-gray-700 leading-none">{currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
            <p className="text-[9px] font-bold text-gray-400 uppercase tracking-wider">{currentTime.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' })}</p>
        </div>
      </header>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard label="Sales Today" value={`₱${stats.salesToday.toLocaleString()}`} color="bg-pawPink" textColor="text-red-500" />
        <StatCard label="New Orders" value={stats.ordersToday} color="bg-pawMint" textColor="text-green-600" />
        <StatCard label="Pending Payment" value={stats.pendingPayments} color="bg-pawPeach" textColor="text-orange-600" />
        <StatCard label="Pending Shipment" value={stats.toShip} color="bg-pawSoftBlue" textColor="text-blue-600" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-pawPink">
          <h3 className="text-lg font-bold mb-4 text-gray-700">Stock Dispersal Tracking</h3>
          <div className="space-y-4 max-h-[300px] overflow-y-auto custom-scrollbar">
            {activeBales.length > 0 ? activeBales.map(b => (
              <div key={b.id} className="p-4 bg-pawCream rounded-2xl relative overflow-hidden group">
                <div className="flex justify-between items-center mb-2">
                   <div>
                     <span className="text-[9px] font-black uppercase bg-green-100 text-green-600 px-2 py-0.5 rounded mr-2">{b.status}</span>
                     <h4 className="font-bold text-gray-800 text-sm inline-block">{b.name}</h4>
                   </div>
                   <div className="text-right">
                      <span className="block text-xl font-black text-gray-800">{b.remaining}</span>
                      <span className="text-[9px] font-bold text-gray-400 uppercase">Items Left</span>
                   </div>
                </div>
                <div className="w-full h-2 bg-white rounded-full overflow-hidden">
                   <div className="h-full bg-pawPinkDark rounded-full" style={{ width: `${b.percentSold}%` }}></div>
                </div>
              </div>
            )) : <p className="text-center text-gray-400 py-10">No active batches found.</p>}
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ label, value, color, textColor }: any) => (
  <div className={`${color} p-5 rounded-3xl shadow-sm transition-transform active:scale-95`}>
    <p className="text-xs font-bold text-gray-600 uppercase tracking-wider mb-1">{label}</p>
    <p className={`text-2xl font-bold ${textColor}`}>{value}</p>
  </div>
);

export default Dashboard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { useSettings } from '../services/SettingsContext';
import { Product, Order, PaymentStatus, ShippingStatus, LiveSession, Bale } from '../types';
import { PlusIcon, PawIcon, CartIcon } from '../components/Icons';

const OFF_LIVE_ID = 'OFF_LIVE';
const PRESET_PRICES = [10, 50, 80, 130, 150, 160, 170, 180, 190, 200];

interface CartItem {
  id: string;
  price: number;
  quantity: number;
  isFreebie: boolean;
  baleId: string;
}

const ClockIcon = ({ className = "w-6 h-6" }: { className?: string }) => (
  <svg className={className} fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
  </svg>
);

const EditIcon = ({ className = "w-6 h-6" }: { className?: string }) => (
  <svg className={className} fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
  </svg>
);

const CalendarIcon = ({ className = "w-6 h-6" }: { className?: string }) => (
  <svg className={className} fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
  </svg>
);

const LiveSell: React.FC = () => {
  const { logoUrl } = useSettings();
  const [session, setSession] = useState<LiveSession | null>(db.getSessions().find(s => s.isOpen) || null);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [scheduledTime, setScheduledTime] = useState<Date | null>(null);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [username, setUsername] = useState('');
  const [transactionNo, setTransactionNo] = useState('');
  const [selectedBaleId, setSelectedBaleId] = useState<string>('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customPrice, setCustomPrice] = useState<string>('');
  const [recentOrders, setRecentOrders] = useState<Order[]>([]);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showStartModal, setShowStartModal] = useState(false);
  const [historySessions, setHistorySessions] = useState<LiveSession[]>([]);
  const [viewingSession, setViewingSession] = useState<LiveSession | null>(null);
  const [showEndModal, setShowEndModal] = useState(false);
  const [oosModalData, setOosModalData] = useState<{ name: string; total: number; sold: number } | null>(null);
  const [showHistory, setShowHistory] = useState(false);
  const [logoError, setLogoError] = useState(false);

  const customers = db.getCustomers();
  const bales = db.getBales();
  const customPriceInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTime(now);
      if (scheduledTime && !session) {
        if (now >= scheduledTime) {
          const timeString = scheduledTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
          handleCreateSession(`Live @ ${timeString}`);
          setScheduledTime(null);
          if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
        }
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [scheduledTime, session]);

  useEffect(() => {
    setLogoError(false);
  }, [logoUrl]);

  useEffect(() => {
    const allSessions = db.getSessions();
    const today = new Date().toLocaleDateString('en-US');
    const todaysSessions = allSessions.filter(s => 
      !s.isOpen && (s.date === today)
    ).sort((a, b) => b.id.localeCompare(a.id));
    setHistorySessions(todaysSessions);
  }, [session]);

  const filteredCustomers = useMemo(() => {
    if (!username || customers.some(c => c.username === username)) return [];
    const lower = username.toLowerCase();
    return customers.filter(c => c.username.toLowerCase().includes(lower)).slice(0, 3);
  }, [username, customers]);

  useEffect(() => {
    if (session) {
      const orders = db.getOrders().filter(o => o.sessionId === session.id);
      setRecentOrders(orders.sort((a, b) => b.createdAt - a.createdAt));
    }
  }, [session, showHistory]);

  useEffect(() => {
    if (bales.length > 0 && !selectedBaleId) {
       const getStock = (bId: string) => {
         const allProducts = db.getProducts();
         const allOrders = db.getOrders();
         const prodIds = allProducts.filter(p => p.baleBatch === bId).map(p => p.id);
         const sold = allOrders.filter(o => prodIds.includes(o.productId)).reduce((s, o) => s + o.quantity, 0);
         const b = bales.find(bl => bl.id === bId);
         return b ? b.itemCount - sold : 0;
       };
       const onSale = bales.find(b => b.status === 'On Sale' && getStock(b.id) > 0);
       if (onSale) setSelectedBaleId(onSale.id);
       else setSelectedBaleId(bales[0].id);
    }
  }, [bales, selectedBaleId]);

  const handleStartSession = () => setShowStartModal(true);

  const handleStartOffLive = () => {
    setSession({
      id: OFF_LIVE_ID,
      name: 'Manual Encoding Mode',
      date: new Date().toLocaleDateString('en-US'),
      totalSales: 0,
      totalOrders: 0,
      isOpen: true
    });
  };

  const handleCreateSession = (name: string) => {
    const newSession = db.createSession(name);
    setSession(newSession);
    setShowStartModal(false);
  };

  const handleEndSessionClick = () => {
    if (session?.id === OFF_LIVE_ID) setSession(null);
    else setShowEndModal(true);
  };

  const confirmEndSession = () => {
    if (session && session.id !== OFF_LIVE_ID) {
      db.closeSession(session.id);
      setSession(null);
      setShowEndModal(false);
    }
  };

  const handleSetSchedule = (date: Date) => {
    setScheduledTime(date);
    setShowScheduleModal(false);
  };

  const getBaleRemainingStock = (baleId: string) => {
    const bale = bales.find(b => b.id === baleId);
    if (!bale) return { remaining: 0, total: 0, soldDb: 0, inCart: 0 };
    const allProducts = db.getProducts();
    const allOrders = db.getOrders();
    const baleProductIds = allProducts.filter(p => p.baleBatch === baleId).map(p => p.id);
    const soldDb = allOrders.filter(o => baleProductIds.includes(o.productId)).reduce((sum, o) => sum + o.quantity, 0);
    const inCart = cart.filter(item => item.baleId === baleId).reduce((sum, item) => sum + item.quantity, 0);
    const remaining = Math.max(0, bale.itemCount - soldDb - inCart);
    return { remaining, total: bale.itemCount, soldDb, inCart };
  };

  const addToCart = (inputPrice: number, isFreebie: boolean = false) => {
    if (!selectedBaleId) {
      alert("Please select a Source Batch first!");
      return;
    }
    const stock = getBaleRemainingStock(selectedBaleId);
    if (stock.remaining <= 0) {
      const currentBale = bales.find(b => b.id === selectedBaleId);
      setOosModalData({ name: currentBale?.name || 'Unknown', total: stock.total, sold: stock.soldDb + stock.inCart });
      return;
    }
    const price = isFreebie ? 0 : inputPrice;
    setCart(prevCart => {
      const existingItemIndex = prevCart.findIndex(item => item.price === price && item.isFreebie === isFreebie && item.baleId === selectedBaleId);
      if (existingItemIndex > -1) {
        const newCart = [...prevCart];
        newCart[existingItemIndex].quantity += 1;
        return newCart;
      } else {
        return [...prevCart, { id: `c_${Date.now()}_${Math.random()}`, price, quantity: 1, isFreebie, baleId: selectedBaleId }];
      }
    });
    setCustomPrice('');
  };

  const removeFromCart = (itemId: string) => {
    setCart(prevCart => prevCart.map(item => item.id === itemId ? { ...item, quantity: item.quantity - 1 } : item).filter(item => item.quantity > 0));
  };

  const handleCheckout = () => {
    if (!session || !username) {
      alert('Enter customer username!');
      return;
    }
    if (cart.length === 0) return;
    const customer = db.getOrCreateCustomer(username);
    const timestamp = Date.now();
    const newOrders: Order[] = [];
    let globalIndex = 0;
    const affectedBaleIds = new Set<string>();

    cart.forEach((item) => {
      affectedBaleIds.add(item.baleId);
      for (let i = 0; i < item.quantity; i++) {
          const uniqueSuffix = `${globalIndex}_${i}`;
          const itemName = item.isFreebie ? 'Gift / Freebie' : `Live Item - ₱${item.price}`;
          const newProduct: Product = { id: `qp_${timestamp}_${uniqueSuffix}`, name: itemName, brand: 'Live', baleBatch: item.baleId, costPrice: 0, sellingPrice: item.price, stock: 0 };
          db.updateProduct(newProduct);
          const newOrder: Order = {
            id: `o_${timestamp}_${uniqueSuffix}`, sessionId: session.id, customerId: customer.id, customerUsername: username, productId: newProduct.id, productName: itemName, quantity: 1, totalPrice: item.price, isFreebie: item.isFreebie, paymentStatus: item.isFreebie ? PaymentStatus.PAID : PaymentStatus.UNPAID, shippingStatus: ShippingStatus.PENDING, amountPaid: 0, createdAt: timestamp, referenceNumber: transactionNo || undefined
          };
          db.addOrder(newOrder);
          newOrders.push(newOrder);
          globalIndex++;
      }
    });

    const freshBales = db.getBales();
    const freshProducts = db.getProducts();
    const freshOrders = db.getOrders();
    affectedBaleIds.forEach(bId => {
       const bale = freshBales.find(b => b.id === bId);
       if (bale) {
          let newStatus = (bale.status === 'Ordered' || bale.status === 'Arrived') ? 'On Sale' : bale.status;
          const pIds = freshProducts.filter(p => p.baleBatch === bId).map(p => p.id);
          const totalSold = freshOrders.filter(o => pIds.includes(o.productId)).reduce((s, o) => s + o.quantity, 0);
          if (totalSold >= bale.itemCount) newStatus = 'Sold Out';
          if (newStatus !== bale.status) db.updateBale({ ...bale, status: newStatus as any });
       }
    });

    setRecentOrders([...newOrders.reverse(), ...recentOrders]);
    setFeedback(`Recorded ${globalIndex} items for @${username}`);
    setTimeout(() => setFeedback(null), 2000);
    setCart([]);
    setUsername('');
    setTransactionNo('');
  };

  const handleRestoreCustomer = (customerUsername: string) => {
    const customerOrders = recentOrders.filter(o => o.customerUsername === customerUsername);
    if (customerOrders.length === 0) return;
    const allProducts = db.getProducts();
    const allBales = db.getBales();
    const affectedBaleIds = new Set<string>();
    const newCartItems: CartItem[] = [];

    customerOrders.forEach(order => {
        const product = allProducts.find(p => p.id === order.productId);
        if (product) {
            const baleId = product.baleBatch;
            affectedBaleIds.add(baleId);
            const existing = newCartItems.find(i => i.price === order.totalPrice && i.isFreebie === order.isFreebie && i.baleId === baleId);
            if (existing) existing.quantity += order.quantity;
            else newCartItems.push({ id: `r_${Date.now()}_${Math.random()}`, price: order.totalPrice, quantity: order.quantity, isFreebie: order.isFreebie, baleId });
            if (!order.isFreebie) { product.stock += order.quantity; db.updateProduct(product); }
            db.deleteOrder(order.id);
        }
    });
    affectedBaleIds.forEach(bId => {
        const bale = allBales.find(b => b.id === bId);
        if (bale && bale.status === 'Sold Out') { bale.status = 'On Sale'; db.updateBale(bale); }
    });
    setUsername(customerUsername);
    setTransactionNo(customerOrders.find(o => o.referenceNumber)?.referenceNumber || '');
    setCart(prev => [...prev, ...newCartItems]);
    setRecentOrders(prev => prev.filter(o => o.customerUsername !== customerUsername));
    setShowHistory(false);
  };

  const cartTotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const cartItemCount = cart.reduce((sum, item) => sum + item.quantity, 0);
  const displayLogo = logoUrl || './logo.png';

  if (!session) {
    return (
      <div className="flex flex-col items-center justify-start min-h-[80vh] px-4 animate-fadeIn pb-24">
        <div className="w-full max-w-lg text-center mt-6 mb-10">
          <div className="mb-8 flex flex-col items-center animate-scaleUp">
             <h1 className="text-6xl font-black text-gray-800 tracking-tighter leading-none font-nunito">
               {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }).replace(/\s(?:AM|PM)/, '')}
               <span className="text-lg text-pawPinkDark align-top ml-1">
                  {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }).match(/(?:AM|PM)/)?.[0]}
               </span>
             </h1>
             <p className="text-xs font-bold text-gray-400 uppercase tracking-[0.3em] mt-2">
               {currentTime.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' })}
             </p>
          </div>
          {!logoError ? (
            <div className="w-48 mx-auto mb-6">
               <img src={displayLogo} alt="Logo" className="w-full h-auto object-contain drop-shadow-sm" onError={() => setLogoError(true)} />
            </div>
          ) : (
            <div className="bg-pawPink/20 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-6">
              <PawIcon className="w-12 h-12 text-pawPinkDark opacity-100" />
            </div>
          )}
          {!scheduledTime ? (
            <>
              <h2 className="text-2xl font-black text-gray-800 mb-2 uppercase tracking-tight">Ready to Sell?</h2>
              <div className="flex gap-3">
                <button onClick={handleStartOffLive} className="flex-1 bg-white border-2 border-pawPink/50 text-pawPinkDark py-4 rounded-[2rem] font-black uppercase tracking-widest text-[10px] flex flex-col items-center justify-center gap-1">
                  <CartIcon className="w-4 h-4" /> Manual Mode
                </button>
                <button onClick={() => setShowScheduleModal(true)} className="flex-1 bg-white border-2 border-pawPink/50 text-pawPinkDark py-4 rounded-[2rem] font-black uppercase tracking-widest text-[10px] flex flex-col items-center justify-center gap-1">
                  <CalendarIcon className="w-4 h-4" /> Schedule
                </button>
                <button onClick={handleStartSession} className="flex-[2] bg-pawPinkDark text-white py-4 rounded-[2rem] font-black uppercase tracking-widest shadow-xl shadow-pawPinkDark/30 text-[10px] flex flex-col items-center justify-center gap-1">
                  <PlusIcon className="w-4 h-4" /> Live Now
                </button>
              </div>
            </>
          ) : (
            <div className="bg-pawSoftBlue/50 p-6 rounded-[2rem] border-2 border-pawSoftBlue animate-slideIn">
               <p className="text-xs font-black text-blue-400 uppercase tracking-widest mb-2">Upcoming Session</p>
               <div className="text-3xl font-black text-blue-900 mb-1">{scheduledTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div>
               <button onClick={() => setScheduledTime(null)} className="w-full py-3 bg-white text-gray-400 font-black uppercase text-xs tracking-widest rounded-xl hover:text-red-400">Cancel</button>
            </div>
          )}
        </div>
        <div className="w-full max-w-lg">
          <h3 className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4 ml-4">Closed Sessions (Today)</h3>
          <div className="space-y-4">
            {historySessions.length === 0 ? (
               <div className="text-center py-10 opacity-40 border-2 border-dashed border-pawPink/30 rounded-[2rem]">
                 <p className="font-bold text-gray-400 text-xs">No records today.</p>
               </div>
            ) : (
              historySessions.map(hist => (
                <button key={hist.id} onClick={() => setViewingSession(hist)} className="w-full bg-white p-5 rounded-[2rem] shadow-sm border border-pawPink/30 flex items-center justify-between group text-left">
                  <div>
                    <h4 className="font-black text-gray-800 text-lg group-hover:text-pawPinkDark transition-colors">{hist.name}</h4>
                    <p className="text-[11px] font-bold text-gray-400 uppercase tracking-wider">{hist.date}</p>
                  </div>
                  <div className="bg-pawCream px-4 py-2 rounded-xl text-[10px] font-black text-gray-400 uppercase tracking-wider">Review</div>
                </button>
              ))
            )}
          </div>
        </div>
        {showStartModal && <StartSessionModal onClose={() => setShowStartModal(false)} onStart={handleCreateSession} />}
        {viewingSession && <SessionSummaryModal session={viewingSession} onClose={() => setViewingSession(null)} />}
        {showScheduleModal && <ScheduleModal onClose={() => setShowScheduleModal(false)} onSet={handleSetSchedule} />}
      </div>
    );
  }

  const currentBaleStats = selectedBaleId ? getBaleRemainingStock(selectedBaleId) : null;
  const currentBale = bales.find(b => b.id === selectedBaleId);
  const breakEvenPrice = currentBale ? (currentBale.cost / currentBale.itemCount) : 0;

  return (
    <div className="grid grid-cols-1 md:grid-cols-12 gap-6 pb-32 max-w-full">
      <div className="md:col-span-7 lg:col-span-8 space-y-6">
        <div className="bg-white p-6 rounded-[2.5rem] shadow-xl border-2 border-pawPink/30 relative">
          <div className="flex items-center justify-between mb-6">
            <div className="flex flex-col">
              <div className="flex items-center gap-2 mb-1">
                <span className={`w-2 h-2 rounded-full ${session.id === OFF_LIVE_ID ? 'bg-blue-400' : 'bg-red-500 animate-pulse'}`}></span>
                <span className={`text-[10px] font-black uppercase tracking-widest ${session.id === OFF_LIVE_ID ? 'text-blue-400' : 'text-red-500'}`}>
                  {session.id === OFF_LIVE_ID ? 'Manual Mode' : 'Live Mode'}
                </span>
              </div>
              <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight">{session.name}</h3>
            </div>
            <button className="px-4 py-2 bg-gray-100 hover:bg-red-50 text-gray-400 hover:text-red-500 text-[10px] font-black uppercase tracking-widest rounded-xl" onClick={handleEndSessionClick}>
              {session.id === OFF_LIVE_ID ? 'Exit' : 'End'}
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
             <div className="relative">
                <label className="text-[10px] font-black text-gray-400 uppercase ml-3 tracking-widest block mb-1">Customer Username</label>
                <div className="flex items-center bg-pawCream rounded-[1.2rem] px-4 border-2 border-transparent focus-within:border-pawPinkDark">
                  <span className="text-lg font-black text-gray-400">@</span>
                  <input type="text" placeholder="username" value={username} onChange={(e) => setUsername(e.target.value.replace('@', ''))} className="w-full bg-transparent p-3 text-lg font-black text-gray-800 placeholder:text-gray-300 border-none focus:ring-0" />
                </div>
                {filteredCustomers.length > 0 && (
                  <div className="absolute top-full left-0 right-0 bg-white shadow-xl rounded-[1rem] z-30 border-2 border-pawPink mt-1 p-1">
                    {filteredCustomers.map(c => (
                      <button key={c.id} onClick={() => setUsername(c.username)} className="w-full text-left p-3 hover:bg-pawPink/20 rounded-xl flex items-center justify-between transition-colors">
                        <span className="font-black text-gray-800 text-sm">@{c.username}</span>
