import React, { useState, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { Order, PaymentStatus, ShippingStatus, PaymentMethod, LiveSession } from '../types';
import { CartIcon, PlusIcon, PawIcon, SearchIcon } from '../components/Icons';

const OFF_LIVE_ID = 'OFF_LIVE';

interface GroupedOrder extends Order {
  ids: string[];
  items: Order[];
}

const Orders: React.FC = () => {
  const [selectedSession, setSelectedSession] = useState<LiveSession | null>(null);
  const [filter, setFilter] = useState('All');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedOrder, setSelectedOrder] = useState<GroupedOrder | null>(null);
  const [allOrders, setAllOrders] = useState(db.getOrders());

  const sessions = useMemo(() => {
    const dbSessions = db.getSessions().sort((a, b) => b.id.localeCompare(a.id));
    const hasOffLive = allOrders.some(o => o.sessionId === OFF_LIVE_ID);
    if (hasOffLive) {
      const offLiveSession: LiveSession = {
        id: OFF_LIVE_ID, name: 'Manual Encoding Batch', date: 'Manual', totalSales: 0, totalOrders: 0, isOpen: true
      };
      return [offLiveSession, ...dbSessions];
    }
    return dbSessions;
  }, [allOrders]);

  const sessionOrders = useMemo(() => {
    if (!selectedSession) return [];
    return allOrders.filter(o => o.sessionId === selectedSession.id);
  }, [allOrders, selectedSession]);

  const groupedFilteredOrders = useMemo(() => {
    const filtered = sessionOrders.filter(o => {
      const matchesSearch = o.customerUsername.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            o.productName.toLowerCase().includes(searchTerm.toLowerCase());
      if (filter === 'All') return matchesSearch;
      if (filter === 'Unpaid') return matchesSearch && o.paymentStatus === PaymentStatus.UNPAID;
      if (filter === 'To Ship') return matchesSearch && o.shippingStatus === ShippingStatus.PENDING;
      return matchesSearch;
    });

    const groups: Record<string, GroupedOrder> = {};
    filtered.forEach(order => {
      const key = order.customerUsername;
      if (!groups[key]) {
        groups[key] = { ...order, ids: [order.id], items: [order] };
      } else {
        groups[key].quantity += order.quantity;
        groups[key].totalPrice += order.totalPrice; 
        groups[key].amountPaid += order.amountPaid;
        groups[key].ids.push(order.id);
        groups[key].items.push(order);
        if (order.createdAt > groups[key].createdAt) groups[key].createdAt = order.createdAt;
      }
    });

    return Object.values(groups).map(group => {
       const allPaid = group.items.every(i => i.paymentStatus === PaymentStatus.PAID);
       const allUnpaid = group.items.every(i => i.paymentStatus === PaymentStatus.UNPAID);
       const aggregatePaymentStatus = allPaid ? PaymentStatus.PAID : (allUnpaid ? PaymentStatus.UNPAID : PaymentStatus.PARTIAL);
       const allShipped = group.items.every(i => i.shippingStatus === ShippingStatus.SHIPPED);
       const allCancelled = group.items.every(i => i.shippingStatus === ShippingStatus.CANCELLED);
       const aggregateShippingStatus = allShipped ? ShippingStatus.SHIPPED : (allCancelled ? ShippingStatus.CANCELLED : ShippingStatus.PENDING);
       return { ...group, paymentStatus: aggregatePaymentStatus, shippingStatus: aggregateShippingStatus };
    }).sort((a, b) => b.createdAt - a.createdAt);
  }, [sessionOrders, filter, searchTerm]);

  const handleUpdateStatus = (updatedGroup: GroupedOrder) => {
    if (updatedGroup.ids && updatedGroup.ids.length > 0) {
       const ratio = updatedGroup.totalPrice > 0 ? updatedGroup.amountPaid / updatedGroup.totalPrice : 0;
       updatedGroup.ids.forEach(id => {
          const originalOrder = db.getOrders().find(o => o.id === id);
          if (originalOrder) {
             originalOrder.paymentStatus = updatedGroup.paymentStatus;
             originalOrder.paymentMethod = updatedGroup.paymentMethod;
             originalOrder.shippingStatus = updatedGroup.shippingStatus;
             originalOrder.amountPaid = originalOrder.totalPrice * ratio; 
             db.updateOrder(originalOrder);
          }
       });
    }
    setAllOrders(db.getOrders());
    setSelectedOrder(null);
  };

  const handleDeleteOrder = (group: GroupedOrder) => {
    if (confirm(`Delete batch for @${group.customerUsername}?`)) {
      group.ids.forEach(id => db.deleteOrder(id));
      setAllOrders(db.getOrders());
    }
  };

  if (!selectedSession) {
    return (
      <div className="space-y-8 pb-24 px-1 animate-fadeIn">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Order Management</h1>
          <p className="text-gray-500 font-bold text-sm">Select a batch to review orders.</p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
           {sessions.map(s => (
             <button key={s.id} onClick={() => setSelectedSession(s)} className="bg-white rounded-[2.5rem] p-7 border-2 border-pawPink/30 hover:border-pawPinkDark shadow-sm text-left group transition-all">
                <div className="flex justify-between items-start mb-6">
                   <div>
                     <h3 className="font-black text-gray-800 text-xl leading-none mb-2">{s.name}</h3>
                     <p className="text-[11px] font-black text-gray-400 uppercase tracking-widest">{s.date}</p>
                   </div>
                   {s.id === OFF_LIVE_ID && <span className="bg-blue-50 text-blue-500 px-2 py-1 rounded-md text-[9px] font-black uppercase tracking-widest">Manual</span>}
                </div>
                <div className="flex gap-4">
                   <div className="bg-pawSoftBlue p-3 rounded-2xl flex-1 text-center">
                      <p className="text-[9px] text-blue-600 font-black uppercase mb-1">Items</p>
                      <p className="text-xl font-black text-gray-800">{allOrders.filter(o => o.sessionId === s.id).length}</p>
                   </div>
                   <div className="bg-pawMint p-3 rounded-2xl flex-1 text-center">
                      <p className="text-[9px] text-green-700 font-black uppercase mb-1">Revenue</p>
                      <p className="text-xl font-black text-gray-800">₱{allOrders.filter(o => o.sessionId === s.id).reduce((sum,o) => sum + o.totalPrice, 0).toLocaleString()}</p>
                   </div>
                </div>
             </button>
           ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-24 px-1 animate-fadeIn">
      <button onClick={() => setSelectedSession(null)} className="flex items-center gap-2 text-gray-500 hover:text-pawPinkDark font-black text-xs uppercase tracking-widest transition-colors mb-2">
        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l-7-7 7-7" /></svg> Back
      </button>
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h1 className="text-2xl font-black text-gray-800 tracking-tight">{selectedSession.name}</h1>
        <div className="flex bg-white p-1 rounded-2xl shadow-sm border border-pawPink/30">
          {['All', 'Unpaid', 'To Ship'].map(f => (
            <button key={f} onClick={() => setFilter(f)} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${filter === f ? 'bg-pawPinkDark text-white' : 'text-gray-400'}`}>{f}</button>
          ))}
        </div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {groupedFilteredOrders.map(group => (
          <div key={group.ids[0]} className="bg-white rounded-[2rem] p-6 border border-pawPink/40 shadow-sm animate-fadeIn">
            <div className="flex justify-between items-start mb-4">
               <div>
