            <input type="number" value={formData.cost || ''} placeholder="Capital Cost (₱)" onChange={(e) => setFormData({...formData, cost: Number(e.target.value)})} className="w-full bg-pawCream p-4 rounded-[1.5rem] font-bold text-gray-800 outline-none" />
            <input type="number" value={formData.itemCount || ''} placeholder="Initial Item Count" onChange={(e) => setFormData({...formData, itemCount: Number(e.target.value)})} className="w-full bg-pawCream p-4 rounded-[1.5rem] font-bold text-gray-800 outline-none" />
          </div>
          <div className="bg-orange-50 p-4 rounded-2xl border border-orange-100 flex justify-between items-center">
             <span className="text-[10px] font-black text-orange-600 uppercase tracking-widest">Unit Capital per Item</span>
             <span className="font-black text-orange-800 text-lg">₱{unitCost.toFixed(2)}</span>
          </div>
          <div className="flex gap-4">
            <button onClick={onClose} className="flex-1 py-4 bg-gray-100 text-gray-400 font-black uppercase text-xs rounded-2xl">Cancel</button>
            <button onClick={() => onSave(formData)} className="flex-1 py-4 bg-pawSoftBlue text-blue-700 font-black uppercase text-xs rounded-2xl">Save Stock</button>
          </div>
        </div>
      </div>
    </div>, document.body
  );
};

