            <div className="bg-white rounded-2xl p-4 mb-4">
               <div className="flex justify-between items-end">
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Bill</span>
                  <span className="text-3xl font-black text-gray-800">₱{cartTotal.toLocaleString()}</span>
               </div>
            </div>
            <button onClick={handleCheckout} disabled={cart.length === 0 || !username} className={`w-full py-5 rounded-2xl font-black uppercase text-xs tracking-widest transition-all ${cart.length === 0 || !username ? 'bg-gray-200 text-gray-400' : 'bg-pawPinkDark text-white hover:bg-red-400 shadow-lg'}`}>
               {feedback || 'Finalize Order'}
            </button>
         </div>
      </div>

      {showStartModal && <StartSessionModal onClose={() => setShowStartModal(false)} onStart={handleCreateSession} />}
    </div>
  );
};

