import React, { useState, useEffect, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { Bale, Order, Product } from '../types';
import { PlusIcon, SearchIcon } from '../components/Icons';

const Bales: React.FC = () => {
  const [bales, setBales] = useState(db.getBales());
  const [showModal, setShowModal] = useState(false);
  const [selectedBale, setSelectedBale] = useState<Bale | null>(null);
  const [viewingBale, setViewingBale] = useState<Bale | null>(null);

  const products = db.getProducts();
  const orders = db.getOrders();

  const getBaleStats = (baleId: string) => {
    const bale = bales.find(b => b.id === baleId);
    if (!bale) return { soldCount: 0, revenue: 0, targetPrice: 0, progress: 0 };

    const baleProductIds = products.filter(p => p.baleBatch === baleId).map(p => p.id);
    const baleOrders = orders.filter(o => baleProductIds.includes(o.productId));
    const soldCount = baleOrders.reduce((sum, o) => sum + o.quantity, 0);
    const revenue = baleOrders.reduce((sum, o) => sum + o.totalPrice, 0);

    const remainingCount = Math.max(0, bale.itemCount - soldCount);
    const remainingToRecover = Math.max(0, bale.cost - revenue);
    const targetPrice = remainingCount > 0 ? (remainingToRecover / remainingCount) : 0;
    const progress = Math.min(100, (revenue / bale.cost) * 100);

    return { soldCount, revenue, targetPrice, progress, isProfitable: revenue >= bale.cost };
  };

  const handleSaveBale = (bale: Bale) => {
    db.updateBale(bale);
    setBales(db.getBales());
    setShowModal(false);
  };

  if (viewingBale) {
    const stats = getBaleStats(viewingBale.id);
    return (
      <div className="space-y-6 pb-32 px-1 animate-fadeIn">
        <button onClick={() => setViewingBale(null)} className="text-[10px] font-black uppercase text-gray-400 mb-2">← Back to List</button>
        <div className="bg-white rounded-[3rem] p-8 border-2 border-pawPink shadow-lg">
           <h1 className="text-3xl font-black text-gray-800 tracking-tight mb-6">{viewingBale.name}</h1>
           <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mb-8">
              <Metric label="Total Investment" value={`₱${viewingBale.cost.toLocaleString()}`} />
              <Metric label="Revenue To Date" value={`₱${stats.revenue.toLocaleString()}`} />
              <Metric label="Capital Recovery" value={`${stats.progress.toFixed(1)}%`} />
              <Metric label="Remaining Items" value={viewingBale.itemCount - stats.soldCount} />
           </div>

           <div className="bg-pawSoftBlue/30 rounded-[2rem] p-6 border border-white">
              <div className="flex justify-between items-center mb-4">
                 <h4 className="text-xs font-black text-blue-900 uppercase">Capital Recovery Target</h4>
                 {!stats.isProfitable && (
                   <span className="text-[10px] font-black text-orange-600 bg-orange-50 px-3 py-1 rounded-full animate-pulse">
                     ACTION REQUIRED
                   </span>
                 )}
              </div>
              <p className="text-sm text-blue-800 font-bold mb-1">
                {stats.isProfitable 
                   ? "✨ All capital recovered! Every remaining item is now pure profit." 
                   : `You still need to recover ₱${(viewingBale.cost - stats.revenue).toLocaleString()}.`}
              </p>
              {!stats.isProfitable && (
                <p className="text-lg font-black text-blue-950">
                  Target Price per Remaining Item: <span className="text-orange-600">₱{stats.targetPrice.toFixed(0)}</span>
                </p>
              )}
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-32 px-1 animate-fadeIn">
