const OFF_LIVE_ID = 'OFF_LIVE';
const PRESET_PRICES = [10, 50, 80, 130, 150, 160, 170, 180, 190, 200];

interface CartItem {
  id: string;
  price: number;
  quantity: number;
  isFreebie: boolean;
  baleId: string;
}

