           <div className="flex justify-between items-start mb-6">
              <h1 className="text-3xl font-black text-gray-800 tracking-tight leading-none">{viewingBale.name}</h1>
              <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${stats.isProfitable ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700'}`}>
                 {stats.isProfitable ? 'Profitable ✨' : 'Recovering Capital'}
              </span>
           </div>

           <div className="grid grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
              <Metric label="Investment" value={`₱${viewingBale.cost.toLocaleString()}`} />
              <Metric label="Revenue" value={`₱${stats.revenue.toLocaleString()}`} />
              <Metric label="ROI Progress" value={`${stats.progress.toFixed(1)}%`} />
              <Metric label="Units Left" value={viewingBale.itemCount - stats.soldCount} />
           </div>

           <div className="bg-pawSoftBlue/30 rounded-[2.5rem] p-7 border-2 border-white shadow-inner">
              <div className="flex justify-between items-center mb-4">
                 <h4 className="text-xs font-black text-blue-900 uppercase tracking-widest">Pricing Strategy (Dynamic)</h4>
              </div>
              <p className="text-sm text-blue-800 font-bold mb-3">
                {stats.isProfitable 
                   ? "You have fully recovered your initial investment. Every remaining item is now 100% profit!" 
                   : `To break even, you still need to recover ₱${(viewingBale.cost - stats.revenue).toLocaleString()}.`}
              </p>
              {!stats.isProfitable && (
                <div className="flex items-center gap-4 bg-white/60 p-4 rounded-2xl border border-blue-100">
                   <div className="text-2xl">🎯</div>
                   <div>
                      <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest leading-none mb-1">Target Price per Remaining Item</p>
                      <p className="text-xl font-black text-blue-950 leading-none">₱{stats.targetPrice.toFixed(0)} <span className="text-xs font-bold text-gray-400">or higher</span></p>
                   </div>
                </div>
              )}
           </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-32 px-1 animate-fadeIn">
      <div className="flex items-center justify-between px-2">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Batches & ROI</h1>
          <p className="text-gray-500 font-bold text-sm">Monitor recovery progress for each sourcing batch.</p>
        </div>
        <button onClick={() => { setSelectedBale(null); setShowModal(true); }} className="bg-pawPinkDark text-white w-14 h-14 rounded-full shadow-xl flex items-center justify-center active:scale-95 transition-all">
          <PlusIcon className="w-6 h-6" />
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 px-2">
        {bales.map(bale => {
          const stats = getBaleStats(bale.id);
          return (
            <div key={bale.id} onClick={() => setViewingBale(bale)} className="bg-white rounded-[2.5rem] p-8 border-2 border-pawPink/20 shadow-xl relative cursor-pointer group active:scale-[0.98] transition-all hover:border-pawPinkDark">
              <div className="flex justify-between items-start mb-6">
                 <div>
                   <span className="text-[10px] font-black text-blue-500 bg-blue-50 px-3 py-1 rounded-md uppercase mb-2 inline-block tracking-widest">{bale.status}</span>
                   <h3 className="text-2xl font-black text-gray-800 tracking-tighter leading-none group-hover:text-pawPinkDark transition-colors">{bale.name}</h3>
                 </div>
                 <div className="text-right">
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">ROI</p>
                    <p className={`text-xl font-black ${stats.isProfitable ? 'text-green-500' : 'text-orange-500'}`}>{stats.progress.toFixed(0)}%</p>
                 </div>
              </div>

              <div className="w-full h-3 bg-gray-100 rounded-full overflow-hidden mb-6 shadow-inner">
                 <div className={`h-full transition-all duration-1000 ${stats.isProfitable ? 'bg-green-400' : 'bg-pawPinkDark'}`} style={{ width: `${stats.progress}%` }}></div>
