import React, { useState, useEffect, useMemo, useRef } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { useSettings } from '../services/SettingsContext';
import { Product, Order, PaymentStatus, ShippingStatus, LiveSession, Bale } from '../types';
import { PlusIcon, PawIcon, CartIcon } from '../components/Icons';

const OFF_LIVE_ID = 'OFF_LIVE';
const PRESET_PRICES = [10, 50, 80, 130, 150, 160, 170, 180, 190, 200];

interface CartItem {
  id: string;
  price: number;
  quantity: number;
  isFreebie: boolean;
  baleId: string;
}

const ClockIcon = ({ className = "w-6 h-6" }: { className?: string }) => (
  <svg className={className} fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
  </svg>
);

const CalendarIcon = ({ className = "w-6 h-6" }: { className?: string }) => (
  <svg className={className} fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
  </svg>
);

const LiveSell: React.FC = () => {
  const { logoUrl } = useSettings();
  const [session, setSession] = useState<LiveSession | null>(db.getSessions().find(s => s.isOpen) || null);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [scheduledTime, setScheduledTime] = useState<Date | null>(null);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [username, setUsername] = useState('');
  const [transactionNo, setTransactionNo] = useState('');
  const [selectedBaleId, setSelectedBaleId] = useState<string>('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customPrice, setCustomPrice] = useState<string>('');
  const [recentOrders, setRecentOrders] = useState<Order[]>([]);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showStartModal, setShowStartModal] = useState(false);
  const [oosModalData, setOosModalData] = useState<{ name: string; total: number; sold: number } | null>(null);
  const [logoError, setLogoError] = useState(false);

  const customers = db.getCustomers();
  const bales = db.getBales();

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTime(now);
      if (scheduledTime && !session) {
        if (now >= scheduledTime) {
          handleCreateSession(`Live @ ${scheduledTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`);
          setScheduledTime(null);
        }
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [scheduledTime, session]);

  useEffect(() => {
    if (session) {
      const orders = db.getOrders().filter(o => o.sessionId === session.id);
      setRecentOrders(orders.sort((a, b) => b.createdAt - a.createdAt));
    }
  }, [session]);

  const filteredCustomers = useMemo(() => {
    if (!username || customers.some(c => c.username === username)) return [];
    return customers.filter(c => c.username.toLowerCase().includes(username.toLowerCase())).slice(0, 3);
  }, [username, customers]);

  // DYNAMIC BREAK-EVEN LOGIC
  const getBaleStats = (baleId: string) => {
    const bale = bales.find(b => b.id === baleId);
    if (!bale) return { remaining: 0, total: 0, sold: 0, revenue: 0, targetPrice: 0 };

    const allProducts = db.getProducts();
    const allOrders = db.getOrders();
    const baleProductIds = allProducts.filter(p => p.baleBatch === baleId).map(p => p.id);
    const baleOrders = allOrders.filter(o => baleProductIds.includes(o.productId));

    const soldInDb = baleOrders.reduce((sum, o) => sum + o.quantity, 0);
    const revenueInDb = baleOrders.reduce((sum, o) => sum + o.totalPrice, 0);

    // Include what is currently in the session cart for real-time guidance
    const inCartCount = cart.filter(item => item.baleId === baleId).reduce((sum, item) => sum + item.quantity, 0);
    const inCartRevenue = cart.filter(item => item.baleId === baleId).reduce((sum, item) => sum + (item.price * item.quantity), 0);

    const totalSoldActual = soldInDb + inCartCount;
    const totalRevenueActual = revenueInDb + inCartRevenue;
    const remaining = Math.max(0, bale.itemCount - totalSoldActual);

    // Recalculate how much each remaining item needs to be sold for to recover the initial investment
    const remainingToRecover = Math.max(0, bale.cost - totalRevenueActual);
    const targetPrice = remaining > 0 ? (remainingToRecover / remaining) : 0;

    return { remaining, total: bale.itemCount, sold: totalSoldActual, revenue: totalRevenueActual, targetPrice };
  };

  const handleCreateSession = (name: string) => {
    const newSession = db.createSession(name);
    setSession(newSession);
    setShowStartModal(false);
  };

  const addToCart = (inputPrice: number, isFreebie: boolean = false) => {
    if (!selectedBaleId) return alert("Please select a Batch first!");
    const stats = getBaleStats(selectedBaleId);
    if (stats.remaining <= 0) {
      setOosModalData({ name: bales.find(b => b.id === selectedBaleId)?.name || '', total: stats.total, sold: stats.sold });
      return;
    }
    const price = isFreebie ? 0 : inputPrice;
    setCart(prev => {
      const idx = prev.findIndex(i => i.price === price && i.isFreebie === isFreebie && i.baleId === selectedBaleId);
      if (idx > -1) {
        const next = [...prev];
        next[idx].quantity += 1;
        return next;
      }
      return [...prev, { id: `c_${Date.now()}_${Math.random()}`, price, quantity: 1, isFreebie, baleId: selectedBaleId }];
    });
    setCustomPrice('');
  };

  const handleCheckout = () => {
    if (!session || !username) return alert('Username required!');
    const customer = db.getOrCreateCustomer(username);
    const timestamp = Date.now();

    cart.forEach((item, idx) => {
      for (let i = 0; i < item.quantity; i++) {
        const pid = `qp_${timestamp}_${idx}_${i}`;
        const prod: Product = { id: pid, name: item.isFreebie ? 'Gift' : `Live Item ₱${item.price}`, brand: 'Live', baleBatch: item.baleId, costPrice: 0, sellingPrice: item.price, stock: 0 };
        db.updateProduct(prod);
        db.addOrder({
          id: `o_${timestamp}_${idx}_${i}`, sessionId: session.id, customerId: customer.id, customerUsername: username, productId: pid, productName: prod.name, quantity: 1, totalPrice: item.price, isFreebie: item.isFreebie, paymentStatus: item.isFreebie ? PaymentStatus.PAID : PaymentStatus.UNPAID, shippingStatus: ShippingStatus.PENDING, amountPaid: 0, createdAt: timestamp, referenceNumber: transactionNo || undefined
        });
      }
    });

    setCart([]);
    setUsername('');
    setTransactionNo('');
    setFeedback(`Success! Items for @${username} recorded.`);
    setTimeout(() => setFeedback(null), 2000);
  };

  const cartTotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const currentBaleStats = selectedBaleId ? getBaleStats(selectedBaleId) : null;
  const displayLogo = logoUrl || './logo.png';

  if (!session) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[70vh] px-4 animate-fadeIn">
        <div className="w-full max-w-lg text-center space-y-12">
          <div className="flex flex-col items-center animate-scaleUp">
             <h1 className="text-7xl font-black text-gray-800 tracking-tighter leading-none font-nunito">
               {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }).replace(/\s(?:AM|PM)/, '')}
               <span className="text-xl text-pawPinkDark align-top ml-1">
                  {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }).match(/(?:AM|PM)/)?.[0]}
               </span>
             </h1>
             <p className="text-xs font-bold text-gray-400 uppercase tracking-[0.4em] mt-3">
               {currentTime.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' })}
             </p>
          </div>

          {!logoError ? (
            <div className="w-48 mx-auto">
               <img src={displayLogo} alt="Logo" className="w-full h-auto object-contain drop-shadow-xl animate-pulse" onError={() => setLogoError(true)} />
            </div>
          ) : (
            <div className="bg-pawPink/20 w-32 h-32 rounded-full flex items-center justify-center mx-auto">
              <PawIcon className="w-16 h-16 text-pawPinkDark" />
            </div>
          )}

          <div className="space-y-4">
            <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Ready to sell?</h2>
            <div className="grid grid-cols-2 gap-3">
               <button 
                 onClick={() => setSession({ id: OFF_LIVE_ID, name: 'Manual Encoding', date: new Date().toLocaleDateString(), totalSales: 0, totalOrders: 0, isOpen: true })} 
                 className="bg-white border-2 border-pawPink text-pawPinkDark py-5 rounded-[2rem] font-black uppercase text-[10px] shadow-sm hover:shadow-md transition-all active:scale-95"
               >
                 Manual Mode
               </button>
               <button 
                 onClick={() => setShowScheduleModal(true)} 
                 className="bg-white border-2 border-pawPink text-pawPinkDark py-5 rounded-[2rem] font-black uppercase text-[10px] shadow-sm hover:shadow-md transition-all active:scale-95"
               >
                 Schedule Live
               </button>
               <button 
                 onClick={() => setShowStartModal(true)} 
                 className="col-span-2 bg-pawPinkDark text-white py-6 rounded-[2.5rem] font-black uppercase shadow-2xl shadow-pawPinkDark/40 text-xs tracking-widest active:scale-95 transition-all"
               >
                 <PlusIcon className="inline-block w-5 h-5 mr-2 -mt-1" /> Start Live Now
               </button>
            </div>
          </div>
        </div>
        {showStartModal && <StartSessionModal onClose={() => setShowStartModal(false)} onStart={handleCreateSession} />}
        {showScheduleModal && <ScheduleModal onClose={() => setShowScheduleModal(false)} onSet={setScheduledTime} />}
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 pb-32 max-w-full">
      <div className="lg:col-span-8 space-y-6">
        <div className="bg-white p-6 md:p-8 rounded-[2.5rem] shadow-xl border-2 border-pawPink/30 relative">
          <div className="flex justify-between items-start mb-8">
            <div>
              <div className="flex items-center gap-2 mb-1">
                <span className={`w-2 h-2 rounded-full animate-pulse ${session.id === OFF_LIVE_ID ? 'bg-blue-400' : 'bg-red-500'}`}></span>
                <span className={`text-[10px] font-black uppercase tracking-widest ${session.id === OFF_LIVE_ID ? 'text-blue-400' : 'text-red-500'}`}>
                  {session.id === OFF_LIVE_ID ? 'Manual Mode' : 'Live Session'}
                </span>
              </div>
              <h3 className="text-2xl font-black text-gray-800 uppercase leading-none tracking-tight">{session.name}</h3>
            </div>
            <button className="text-[10px] font-black text-gray-400 uppercase bg-gray-100 px-5 py-2.5 rounded-2xl hover:bg-red-50 hover:text-red-500 transition-colors" onClick={() => setSession(null)}>End Session</button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-5 mb-8">
             <div className="relative">
                <label className="text-[10px] font-black text-gray-400 uppercase ml-4 tracking-widest block mb-1">Username</label>
                <div className="flex items-center bg-pawCream rounded-[1.5rem] px-5 border-2 border-transparent focus-within:border-pawPinkDark transition-all">
                  <span className="text-xl font-black text-gray-400">@</span>
                  <input type="text" placeholder="TikTok ID" value={username} onChange={(e) => setUsername(e.target.value)} className="w-full bg-transparent p-4 text-xl font-black text-gray-800 placeholder:text-gray-300 border-none focus:ring-0" />
                </div>
                {filteredCustomers.length > 0 && (
                  <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-[1.5rem] z-30 border-2 border-pawPink mt-2 p-1 overflow-hidden animate-scaleUp">
                    {filteredCustomers.map(c => (
                      <button key={c.id} onClick={() => setUsername(c.username)} className="w-full text-left p-4 hover:bg-pawPink/20 rounded-xl font-black text-sm text-gray-700 flex justify-between">
                        <span>@{c.username}</span>
                        {c.isVIP && <span className="text-[9px] bg-yellow-100 text-yellow-600 px-2 py-0.5 rounded uppercase">VIP</span>}
                      </button>
                    ))}
                  </div>
                )}
             </div>
             <div>
                <label className="text-[10px] font-black text-gray-400 uppercase ml-4 tracking-widest block mb-1">Ref ID / Notes</label>
                <input type="text" placeholder="Optional" value={transactionNo} onChange={(e) => setTransactionNo(e.target.value)} className="w-full bg-white border-2 border-gray-100 focus:border-pawPinkDark p-4 rounded-[1.5rem] text-xl font-bold outline-none transition-all" />
             </div>
          </div>

          <div className="mb-8">
            <label className="text-[10px] font-black text-gray-400 uppercase ml-4 tracking-widest block mb-1">Inventory Source</label>
            <select value={selectedBaleId} onChange={(e) => setSelectedBaleId(e.target.value)} className="w-full bg-pawSoftBlue/40 p-4 rounded-[1.5rem] font-bold text-gray-700 outline-none border-none appearance-none cursor-pointer">
              <option value="">-- Select Active Batch --</option>
              {bales.filter(b => b.status !== 'Sold Out').map(b => <option key={b.id} value={b.id}>{b.name} ({b.itemCount} items)</option>)}
            </select>
          </div>

          <div className="border-t border-pawPink/20 pt-8">
            <div className="flex justify-between items-center mb-4">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-4">Quick Add Items</label>
              {currentBaleStats && currentBaleStats.targetPrice > 0 && (
                <div className="flex items-center gap-2">
                  <span className={`text-[10px] font-black px-4 py-1.5 rounded-full uppercase tracking-tighter shadow-sm animate-pulse ${currentBaleStats.targetPrice > 150 ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-orange-50 text-orange-600 border border-orange-100'}`}>
                    Break-even Target: ₱{currentBaleStats.targetPrice.toFixed(0)}
                  </span>
                </div>
              )}
            </div>
            <div className="grid grid-cols-4 sm:grid-cols-5 gap-3 mb-6">
               <button onClick={() => addToCart(0, true)} className="aspect-square rounded-3xl bg-pawPeach text-orange-800 font-black text-xs flex flex-col items-center justify-center border-2 border-orange-100 hover:scale-105 active:scale-95 transition-all">🎁<br/>FREE</button>
               {PRESET_PRICES.map(price => (
                 <button key={price} onClick={() => addToCart(price)} className="aspect-square rounded-3xl bg-white border-2 border-gray-100 font-black text-2xl hover:border-pawPinkDark hover:text-pawPinkDark hover:scale-105 active:scale-95 transition-all shadow-sm">
                   {price}
                 </button>
               ))}
            </div>
            <div className="flex gap-3">
               <input type="number" placeholder="Enter Custom Price" value={customPrice} onChange={(e) => setCustomPrice(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && customPrice && addToCart(Number(customPrice))} className="flex-1 bg-gray-50 p-5 rounded-[1.5rem] font-black text-xl outline-none border-2 border-transparent focus:border-pawPinkDark transition-all" />
               <button onClick={() => customPrice && addToCart(Number(customPrice))} className="bg-gray-800 text-white px-10 rounded-[1.5rem] font-black uppercase text-xs tracking-widest hover:bg-black active:scale-95 transition-all">Add</button>
            </div>
          </div>
        </div>
      </div>

      <div className="lg:col-span-4 space-y-6">
         <div className="bg-pawSoftBlue/50 p-7 rounded-[2.5rem] border-2 border-white shadow-xl flex flex-col min-h-[500px]">
            <h3 className="text-xl font-black text-blue-900 uppercase tracking-tight flex items-center gap-3 mb-5"><CartIcon className="w-6 h-6" /> Current Cart</h3>
            <div className="flex-1 overflow-y-auto custom-scrollbar space-y-3 mb-6 bg-white/70 rounded-[2rem] p-5 shadow-inner border border-white/50">
               {cart.length === 0 ? (
                 <div className="h-full flex flex-col items-center justify-center space-y-2 opacity-30">
                    <CartIcon className="w-10 h-10" />
                    <p className="text-sm font-bold italic">Cart is empty</p>
                 </div>
               ) : cart.map((item) => (
                 <div key={item.id} className="flex justify-between items-center border-b border-dashed border-blue-100 pb-3 last:border-0 last:pb-0">
                    <div className="flex items-center gap-3">
                      <div className="bg-pawPinkDark text-white w-8 h-8 rounded-full flex items-center justify-center text-[10px] font-black">{item.quantity}x</div>
                      <div>
                        <p className="font-black text-gray-800">₱{item.price}</p>
                        <p className="text-[9px] text-gray-400 font-bold uppercase truncate max-w-[120px]">{bales.find(b => b.id === item.baleId)?.name}</p>
                      </div>
                    </div>
                    <button onClick={() => setCart(prev => prev.filter(i => i.id !== item.id))} className="w-8 h-8 flex items-center justify-center bg-red-50 text-red-300 rounded-full hover:bg-red-500 hover:text-white transition-all font-bold">×</button>
                 </div>
               ))}
            </div>
            <div className="bg-white rounded-[2rem] p-6 mb-6 shadow-sm border border-blue-50 relative overflow-hidden">
               <div className="flex justify-between items-end relative z-10">
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total Bill</span>
                  <span className="text-4xl font-black text-gray-800">₱{cartTotal.toLocaleString()}</span>
               </div>
               <div className="absolute top-0 right-0 w-24 h-24 bg-pawPink/10 rounded-bl-full -mr-8 -mt-8"></div>
            </div>
            <button onClick={handleCheckout} disabled={cart.length === 0 || !username} className={`w-full py-6 rounded-[2rem] font-black uppercase text-xs tracking-widest transition-all ${cart.length === 0 || !username ? 'bg-gray-200 text-gray-400 cursor-not-allowed shadow-none' : 'bg-pawPinkDark text-white hover:bg-red-400 shadow-xl shadow-pawPinkDark/30 active:scale-95'}`}>
               {feedback || 'Finalize Order'}
            </button>
         </div>
      </div>

      {showStartModal && <StartSessionModal onClose={() => setShowStartModal(false)} onStart={handleCreateSession} />}
      {oosModalData && <OutOfStockModal data={oosModalData} onClose={() => setOosModalData(null)} />}
    </div>
  );
};

const StartSessionModal = ({ onClose, onStart }: any) => {
  const [name, setName] = useState('');
  return createPortal(
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
      <div className="bg-white w-full max-w-sm rounded-[3rem] p-8 space-y-6 animate-scaleUp shadow-2xl">
         <div className="space-y-2">
            <h3 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Session Title</h3>
            <p className="text-xs font-bold text-gray-400 uppercase tracking-wider">Name this live batch</p>
         </div>
         <input autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Monday Night Sale" className="w-full bg-gray-50 p-5 rounded-[1.5rem] font-bold text-xl outline-none border-2 border-transparent focus:border-pawPinkDark transition-all" />
         <div className="flex gap-3">
            <button onClick={onClose} className="flex-1 py-5 bg-gray-100 text-gray-400 font-black uppercase text-[10px] tracking-widest rounded-3xl">Cancel</button>
            <button onClick={() => name && onStart(name)} className="flex-1 py-5 bg-pawPinkDark text-white font-black uppercase text-[10px] tracking-widest rounded-3xl shadow-xl shadow-pawPinkDark/20">Start Now</button>
         </div>
      </div>
    </div>, document.body
  );
};

const ScheduleModal = ({ onClose, onSet }: any) => {
  const [time, setTime] = useState('');
  return createPortal(
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
      <div className="bg-white w-full max-w-sm rounded-[3rem] p-8 space-y-6 animate-scaleUp text-center shadow-2xl">
         <h3 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Set Live Reminder</h3>
         <input type="time" value={time} onChange={(e) => setTime(e.target.value)} className="bg-pawCream p-8 rounded-[2.5rem] text-5xl font-black w-full text-center outline-none border-2 border-transparent focus:border-pawPinkDark transition-all" />
         <div className="flex gap-3">
            <button onClick={onClose} className="flex-1 py-5 bg-gray-100 text-gray-400 font-black uppercase text-[10px] tracking-widest rounded-3xl">Cancel</button>
            <button onClick={() => {
              if(!time) return;
              const [h, m] = time.split(':').map(Number);
              const d = new Date(); d.setHours(h, m, 0, 0); onSet(d); onClose();
            }} className="flex-1 py-5 bg-pawPinkDark text-white font-black uppercase text-[10px] tracking-widest rounded-3xl shadow-xl shadow-pawPinkDark/20">Schedule</button>
         </div>
      </div>
    </div>, document.body
  );
};

const OutOfStockModal: React.FC<{ data: { name: string; total: number; sold: number }; onClose: () => void }> = ({ data, onClose }) => (
  createPortal(
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
      <div className="bg-white w-full max-w-sm rounded-[3rem] p-10 text-center animate-scaleUp shadow-2xl">
         <div className="bg-red-100 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-8"><span className="text-5xl">🛑</span></div>
         <h3 className="text-3xl font-black text-gray-800 uppercase tracking-tight mb-3">Sold Out!</h3>
         <p className="text-gray-500 font-bold text-sm mb-10 leading-relaxed">The batch <span className="text-red-500 font-black">"{data.name}"</span> has reached its item limit.</p>
         <button onClick={onClose} className="w-full py-5 bg-gray-800 text-white font-black uppercase text-[10px] tracking-widest rounded-3xl active:scale-95 transition-all">Understood</button>
      </div>
    </div>, document.body
  )
);

export default LiveSell;

import React, { useState, useEffect, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { useSettings } from '../services/SettingsContext';
import { Product, Order, PaymentStatus, ShippingStatus, LiveSession, Bale } from '../types';
import { PlusIcon, PawIcon, CartIcon } from '../components/Icons';

const OFF_LIVE_ID = 'OFF_LIVE';
const PRESET_PRICES = [10, 50, 80, 130, 150, 160, 170, 180, 190, 200];

interface CartItem {
  id: string;
  price: number;
  quantity: number;
  isFreebie: boolean;
  baleId: string;
}

const LiveSell: React.FC = () => {
  const { logoUrl } = useSettings();
  const [session, setSession] = useState<LiveSession | null>(db.getSessions().find(s => s.isOpen) || null);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [scheduledTime, setScheduledTime] = useState<Date | null>(null);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [username, setUsername] = useState('');
  const [transactionNo, setTransactionNo] = useState('');
  const [selectedBaleId, setSelectedBaleId] = useState<string>('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customPrice, setCustomPrice] = useState<string>('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showStartModal, setShowStartModal] = useState(false);
  const [oosModalData, setOosModalData] = useState<{ name: string; total: number; sold: number } | null>(null);
  const [todaysHistory, setTodaysHistory] = useState<LiveSession[]>([]);
  const [viewingHistory, setViewingHistory] = useState<LiveSession | null>(null);

  const customers = db.getCustomers();
  const bales = db.getBales();

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTime(now);
      if (scheduledTime && !session) {
        if (now >= scheduledTime) {
          handleCreateSession(`Live @ ${scheduledTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`);
          setScheduledTime(null);
        }
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [scheduledTime, session]);

  useEffect(() => {
    const today = new Date().toLocaleDateString('en-US');
    const allSessions = db.getSessions();
    const todayFinished = allSessions.filter(s => !s.isOpen && s.date === today).sort((a, b) => b.id.localeCompare(a.id));
    setTodaysHistory(todayFinished);
  }, [session]);

  const filteredCustomers = useMemo(() => {
    if (!username || customers.some(c => c.username === username)) return [];
    return customers.filter(c => c.username.toLowerCase().includes(username.toLowerCase())).slice(0, 3);
  }, [username, customers]);

  const getBaleStats = (baleId: string) => {
    const bale = bales.find(b => b.id === baleId);
    if (!bale) return { remaining: 0, total: 0, sold: 0, revenue: 0, targetPrice: 0 };

    const allProducts = db.getProducts();
    const allOrders = db.getOrders();
    const baleProductIds = allProducts.filter(p => p.baleBatch === baleId).map(p => p.id);
    const baleOrders = allOrders.filter(o => baleProductIds.includes(o.productId));

    const soldInDb = baleOrders.reduce((sum, o) => sum + o.quantity, 0);
    const revenueInDb = baleOrders.reduce((sum, o) => sum + o.totalPrice, 0);

    const inCartCount = cart.filter(item => item.baleId === baleId).reduce((sum, item) => sum + item.quantity, 0);
    const inCartRevenue = cart.filter(item => item.baleId === baleId).reduce((sum, item) => sum + (item.price * item.quantity), 0);

    const totalSoldActual = soldInDb + inCartCount;
    const totalRevenueActual = revenueInDb + inCartRevenue;
    const remaining = Math.max(0, bale.itemCount - totalSoldActual);
    const remainingToRecover = Math.max(0, bale.cost - totalRevenueActual);
    const targetPrice = remaining > 0 ? (remainingToRecover / remaining) : 0;

    return { remaining, total: bale.itemCount, sold: totalSoldActual, revenue: totalRevenueActual, targetPrice };
  };

  const handleCreateSession = (name: string) => {
    const newSession = db.createSession(name);
    setSession(newSession);
    setShowStartModal(false);
  };

  const handleEndSession = () => {
    if (session) {
      if (session.id !== OFF_LIVE_ID) {
        db.closeSession(session.id);
      }
      setSession(null);
    }
  };

  const addToCart = (inputPrice: number, isFreebie: boolean = false) => {
    if (!selectedBaleId) return alert("Please select a Batch first!");
    const stats = getBaleStats(selectedBaleId);
    if (stats.remaining <= 0) {
      setOosModalData({ name: bales.find(b => b.id === selectedBaleId)?.name || '', total: stats.total, sold: stats.sold });
      return;
    }
    const price = isFreebie ? 0 : inputPrice;
    setCart(prev => {
      const idx = prev.findIndex(i => i.price === price && i.isFreebie === isFreebie && i.baleId === selectedBaleId);
      if (idx > -1) {
        const next = [...prev];
        next[idx].quantity += 1;
        return next;
      }
      return [...prev, { id: `c_${Date.now()}_${Math.random()}`, price, quantity: 1, isFreebie, baleId: selectedBaleId }];
    });
    setCustomPrice('');
  };

  const handleCheckout = () => {
    if (!session || !username) return alert('Username required!');
    const customer = db.getOrCreateCustomer(username);
    const timestamp = Date.now();

    cart.forEach((item, idx) => {
      for (let i = 0; i < item.quantity; i++) {
        const pid = `qp_${timestamp}_${idx}_${i}`;
        const prod: Product = { id: pid, name: item.isFreebie ? 'Gift' : `Live Item ₱${item.price}`, brand: 'Live', baleBatch: item.baleId, costPrice: 0, sellingPrice: item.price, stock: 0 };
        db.updateProduct(prod);
        db.addOrder({
          id: `o_${timestamp}_${idx}_${i}`, sessionId: session.id, customerId: customer.id, customerUsername: username, productId: pid, productName: prod.name, quantity: 1, totalPrice: item.price, isFreebie: item.isFreebie, paymentStatus: item.isFreebie ? PaymentStatus.PAID : PaymentStatus.UNPAID, shippingStatus: ShippingStatus.PENDING, amountPaid: 0, createdAt: timestamp, referenceNumber: transactionNo || undefined
        });
      }
    });

    setCart([]);
    setUsername('');
    setTransactionNo('');
    setFeedback(`Recorded for @${username}!`);
    setTimeout(() => setFeedback(null), 2000);
  };

  const cartTotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const currentBaleStats = selectedBaleId ? getBaleStats(selectedBaleId) : null;
  const displayLogo = logoUrl || './logo.png';

  if (viewingHistory) {
    const sessionOrders = db.getOrders().filter(o => o.sessionId === viewingHistory.id);
    const total = sessionOrders.reduce((sum, o) => sum + o.totalPrice, 0);
    return (
      <div className="max-w-xl mx-auto space-y-6 animate-fadeIn pb-32">
        <button onClick={() => setViewingHistory(null)} className="text-sm font-black text-gray-800 bg-white px-6 py-3 rounded-2xl border-2 border-pawPink shadow-sm">← Back to Dashboard</button>
        <div className="bg-white p-8 rounded-[3rem] border-2 border-pawPink shadow-lg">
           <h2 className="text-3xl font-black text-gray-800 mb-2 leading-none">{viewingHistory.name}</h2>
           <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-8">{viewingHistory.date}</p>
           <div className="grid grid-cols-2 gap-4 mb-8">
              <div className="bg-pawSoftBlue p-6 rounded-[2rem]">
                 <p className="text-[10px] font-black text-blue-900 uppercase tracking-widest mb-1">Total Sales</p>
                 <p className="text-2xl font-black text-blue-950">₱{total.toLocaleString()}</p>
              </div>
              <div className="bg-pawPink/20 p-6 rounded-[2rem]">
