            </div>

            <div className="col-span-2">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-3 tracking-widest block mb-1">Category</label>
              {!isCustomCategory ? (
                <select 
                   value={formData.category}
                   onChange={(e) => {
                      if (e.target.value === '__NEW__') {
                        setIsCustomCategory(true);
                        setFormData({...formData, category: ''});
                      } else {
                        setFormData({...formData, category: e.target.value});
                      }
                   }}
                   className="w-full bg-pawCream p-4 rounded-[1.5rem] border-2 border-transparent focus:border-pawPeach font-bold text-gray-800 appearance-none outline-none"
                >
                  {categories.map(c => <option key={c} value={c}>{c}</option>)}
                  <option value="__NEW__" className="text-orange-500 font-black">+ Create New Category</option>
                </select>
              ) : (
                <div className="flex gap-2 animate-fadeIn">
                   <input 
                     autoFocus
                     value={formData.category}
                     placeholder="New Category Name..."
                     onChange={(e) => setFormData({...formData, category: e.target.value})}
                     className="w-full bg-pawCream p-4 rounded-[1.5rem] border-2 border-pawPeach font-bold text-gray-800"
                   />
                   <button 
                     onClick={() => { setIsCustomCategory(false); setFormData({...formData, category: categories[0]}); }}
                     className="px-4 bg-gray-100 text-gray-400 rounded-2xl font-black text-xs uppercase"
                   >
                     Cancel
                   </button>
                </div>
              )}
            </div>

            <div className="col-span-2">
               <label className="text-[10px] font-black text-gray-400 uppercase ml-3 tracking-widest block mb-1">Note (Optional)</label>
               <input 
                 value={formData.note}
                 placeholder="Details..."
