         <input autoFocus value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Saturday Night Sale" className="w-full bg-gray-50 p-6 rounded-[2rem] font-black text-2xl text-center text-gray-900 outline-none border-4 border-transparent focus:border-pawPinkDark transition-all shadow-inner" />
         <div className="flex gap-4">
