         <h3 className="text-4xl font-black text-gray-900 uppercase tracking-tight mb-4">Batch Empty</h3>
         <p className="text-gray-600 font-bold text-lg mb-10 leading-relaxed">The inventory for <span className="text-red-600 font-black">"{data.name}"</span> is fully dispersed.</p>
         <button onClick={onClose} className="w-full py-6 bg-gray-900 text-white font-black uppercase text-xs tracking-widest rounded-3xl active:scale-95 transition-all">Understood</button>
