import { INITIAL_PRODUCTS, INITIAL_BALES, INITIAL_CUSTOMERS } from '../db/mockData';

const STORAGE_KEYS = {
  PRODUCTS: 'paw_products',
  ORDERS: 'paw_orders',
  CUSTOMERS: 'paw_customers',
  SESSIONS: 'paw_sessions',
  BALES: 'paw_bales',
  TRANSACTIONS: 'paw_transactions',
  CATEGORIES: 'paw_categories',
  SETTINGS: 'paw_settings',
};

class DBService {
  private get<T>(key: string, defaultValue: T): T {
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : defaultValue;
  }

  private set<T>(key: string, data: T): void {
    localStorage.setItem(key, JSON.stringify(data));
  }

  // --- Settings (Logo) ---
  getSettings(): { logoUrl: string | null } {
    return this.get(STORAGE_KEYS.SETTINGS, { logoUrl: null });
  }

  updateSettings(settings: { logoUrl: string | null }): void {
    const current = this.getSettings();
    this.set(STORAGE_KEYS.SETTINGS, { ...current, ...settings });
  }

  // --- Products ---
  getProducts(): Product[] {
    return this.get(STORAGE_KEYS.PRODUCTS, INITIAL_PRODUCTS);
  }
  updateProduct(product: Product): void {
    const products = this.getProducts();
    const index = products.findIndex(p => p.id === product.id);
    if (index > -1) {
      products[index] = product;
    } else {
      products.push(product);
    }
    this.set(STORAGE_KEYS.PRODUCTS, products);
  }
  deleteProduct(id: string): void {
    const products = this.getProducts().filter(p => p.id !== id);
    this.set(STORAGE_KEYS.PRODUCTS, products);
  }

  // --- Orders ---
  getOrders(): Order[] {
    return this.get(STORAGE_KEYS.ORDERS, []);
  }
  addOrder(order: Order): void {
    const orders = this.getOrders();
    orders.push(order);
    this.set(STORAGE_KEYS.ORDERS, orders);

    // Update product stock
    if (!order.isFreebie) {
      const products = this.getProducts();
      const pIndex = products.findIndex(p => p.id === order.productId);
      if (pIndex > -1) {
        products[pIndex].stock -= order.quantity;
        this.set(STORAGE_KEYS.PRODUCTS, products);
      }
    }

    // Update customer stats
    const customer = this.getOrCreateCustomer(order.customerUsername);
    customer.orderCount += 1;
    customer.totalSpent += order.totalPrice;

    // Deduct VIP Ticket if marked in order (logic handled in view, but safety check here if needed)
    // Note: Actual decrement happens in LiveSell view before saving to avoid double counting per item

    this.updateCustomer(customer);
  }
  updateOrder(order: Order): void {
    const orders = this.getOrders();
    const index = orders.findIndex(o => o.id === order.id);
    if (index > -1) {
      const oldOrder = orders[index];
      // Handle stock return on cancel/RTS
      if ((order.shippingStatus === 'Cancelled' || order.shippingStatus === 'RTS') && 
          (oldOrder.shippingStatus !== 'Cancelled' && oldOrder.shippingStatus !== 'RTS')) {
        const products = this.getProducts();
        const pIndex = products.findIndex(p => p.id === order.productId);
        if (pIndex > -1) {
          products[pIndex].stock += order.quantity;
          this.set(STORAGE_KEYS.PRODUCTS, products);
        }
      }
      orders[index] = order;
      this.set(STORAGE_KEYS.ORDERS, orders);
    }
  }
  deleteOrder(id: string): void {
    const orders = this.getOrders().filter(o => o.id !== id);
    this.set(STORAGE_KEYS.ORDERS, orders);
  }

  // --- Customers ---
  getCustomers(): Customer[] {
    return this.get(STORAGE_KEYS.CUSTOMERS, INITIAL_CUSTOMERS);
  }
  updateCustomer(customer: Customer): void {
    const customers = this.getCustomers();
    const index = customers.findIndex(c => c.id === customer.id);
    if (index > -1) {
      customers[index] = customer;
      this.set(STORAGE_KEYS.CUSTOMERS, customers);
    }
  }
  getOrCreateCustomer(username: string): Customer {
    const customers = this.getCustomers();
    let customer = customers.find(c => c.username === username);
    if (!customer) {
      customer = {
        id: `c_${Date.now()}`,
        username,
        isVIP: false,
        vipTickets: 0,
        isBlacklisted: false,
        totalSpent: 0,
        orderCount: 0
      };
      customers.push(customer);
      this.set(STORAGE_KEYS.CUSTOMERS, customers);
    }
    // Ensure legacy customers have vipTickets field
    if (customer.vipTickets === undefined) {
        customer.vipTickets = 0;
        this.updateCustomer(customer);
    }
    return customer;
  }

  // --- Sessions ---
  getSessions(): LiveSession[] {
    return this.get(STORAGE_KEYS.SESSIONS, []);
  }
  createSession(name: string): LiveSession {
    const session: LiveSession = {
      id: `s_${Date.now()}`,
      name,
      // Use local date string instead of ISO to ensure "Today" matches user's timezone (e.g. GMT+8)
      date: new Date().toLocaleDateString('en-US'),
      totalSales: 0,
      totalOrders: 0,
      isOpen: true
    };
    const sessions = this.getSessions();
    sessions.push(session);
    this.set(STORAGE_KEYS.SESSIONS, sessions);
    return session;
  }
  closeSession(id: string): void {
    const sessions = this.getSessions();
    const idx = sessions.findIndex(s => s.id === id);
    if (idx > -1) {
      sessions[idx].isOpen = false;
      this.set(STORAGE_KEYS.SESSIONS, sessions);
    }
  }

  // --- Accounting ---
  getTransactions(): Transaction[] {
    return this.get(STORAGE_KEYS.TRANSACTIONS, []);
  }
  addTransaction(tx: Transaction): void {
    const txs = this.getTransactions();
    txs.push(tx);
    this.set(STORAGE_KEYS.TRANSACTIONS, txs);
  }

  // --- Categories ---
  getExpenseCategories(): string[] {
    const stored = this.get(STORAGE_KEYS.CATEGORIES, [
      'Inventory Restock', 
      'Shipping Fee', 
      'Packaging', 
      'Rent', 
      'Utilities', 
      'Salary', 
      'Personal Withdrawal', 
      'Loan',
      'Capital',
      'Miscellaneous'
    ]);

    // Also scan transactions for any custom categories used that aren't in stored list
    const transactions = this.getTransactions();
    const usedCategories = new Set(transactions.map(t => t.category));

    // Merge and Deduplicate
    const combined = Array.from(new Set([...stored, ...usedCategories])).filter(c => c && c.trim() !== '');
    return combined.sort();
  }

  addExpenseCategory(category: string): void {
    const categories = this.getExpenseCategories();
    // Case insensitive check could be better, but simple exact match for now
    if (!categories.includes(category) && category.trim() !== '') {
      categories.push(category);
      this.set(STORAGE_KEYS.CATEGORIES, categories.sort());
    }
  }

  // --- Bales ---
  getBales(): Bale[] {
    return this.get(STORAGE_KEYS.BALES, INITIAL_BALES);
  }
  updateBale(bale: Bale): void {
    const bales = this.getBales();
    const index = bales.findIndex(b => b.id === bale.id);
    if (index > -1) {
      bales[index] = bale;
    } else {
      bales.push(bale);
    }
    this.set(STORAGE_KEYS.BALES, bales);
  }
  deleteBale(id: string): void {
    const bales = this.getBales().filter(b => b.id !== id);
    this.set(STORAGE_KEYS.BALES, bales);
  }
}

export const db = new DBService();

import React, { useState, useEffect, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { useSettings } from '../services/SettingsContext';
import { Product, Order, PaymentStatus, ShippingStatus, LiveSession, Bale, Customer } from '../types';
import { PlusIcon, PawIcon, CartIcon } from '../components/Icons';

const OFF_LIVE_ID = 'OFF_LIVE';
const PRESET_PRICES = [10, 50, 80, 130, 150, 160, 170, 180, 190, 200];

interface CartItem {
  id: string;
  price: number;
  quantity: number;
  isFreebie: boolean;
  baleId: string;
}

const LiveSell: React.FC = () => {
  const { logoUrl } = useSettings();
  const [session, setSession] = useState<LiveSession | null>(db.getSessions().find(s => s.isOpen) || null);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [scheduledTime, setScheduledTime] = useState<Date | null>(null);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [username, setUsername] = useState('');
  const [transactionNo, setTransactionNo] = useState('');
  const [selectedBaleId, setSelectedBaleId] = useState<string>('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customPrice, setCustomPrice] = useState<string>('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showStartModal, setShowStartModal] = useState(false);
  const [oosModalData, setOosModalData] = useState<{ name: string; total: number; sold: number } | null>(null);
  const [todaysHistory, setTodaysHistory] = useState<LiveSession[]>([]);
  const [viewingHistory, setViewingHistory] = useState<LiveSession | null>(null);
  const [showSessionOrders, setShowSessionOrders] = useState(false);

  // VIP Logic
  const [showVipModal, setShowVipModal] = useState(false);
  const [useVipTicket, setUseVipTicket] = useState(false);

  const customers = db.getCustomers();
  const bales = db.getBales();

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTime(now);
      if (scheduledTime && !session) {
        if (now >= scheduledTime) {
          handleCreateSession(`Live @ ${scheduledTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`);
          setScheduledTime(null);
        }
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [scheduledTime, session]);

  useEffect(() => {
    const today = new Date().toLocaleDateString('en-US');
    const allSessions = db.getSessions();
    const todayFinished = allSessions.filter(s => !s.isOpen && s.date === today).sort((a, b) => b.id.localeCompare(a.id));
    setTodaysHistory(todayFinished);
  }, [session]);

  // Reset ticket usage when changing user
  useEffect(() => {
    setUseVipTicket(false);
  }, [username]);

  const filteredCustomers = useMemo(() => {
    if (!username || customers.some(c => c.username === username)) return [];
    return customers.filter(c => c.username.toLowerCase().includes(username.toLowerCase())).slice(0, 3);
  }, [username, customers]);

  const currentCustomer = useMemo(() => {
    return customers.find(c => c.username === username);
  }, [username, customers]);

  const getBaleStats = (baleId: string) => {
    const bale = bales.find(b => b.id === baleId);
    if (!bale) return { remaining: 0, total: 0, sold: 0, revenue: 0, targetPrice: 0 };

    const allProducts = db.getProducts();
    const allOrders = db.getOrders();
    const baleProductIds = allProducts.filter(p => p.baleBatch === baleId).map(p => p.id);
    const baleOrders = allOrders.filter(o => baleProductIds.includes(o.productId));

    const soldInDb = baleOrders.reduce((sum, o) => sum + o.quantity, 0);
    const revenueInDb = baleOrders.reduce((sum, o) => sum + o.totalPrice, 0);

    const inCartCount = cart.filter(item => item.baleId === baleId).reduce((sum, item) => sum + item.quantity, 0);
    const inCartRevenue = cart.filter(item => item.baleId === baleId).reduce((sum, item) => sum + (item.price * item.quantity), 0);

    const totalSoldActual = soldInDb + inCartCount;
    const totalRevenueActual = revenueInDb + inCartRevenue;
    const remaining = Math.max(0, bale.itemCount - totalSoldActual);
    const remainingToRecover = Math.max(0, bale.cost - totalRevenueActual);
    const targetPrice = remaining > 0 ? (remainingToRecover / remaining) : 0;

    return { remaining, total: bale.itemCount, sold: totalSoldActual, revenue: totalRevenueActual, targetPrice };
  };

  const handleCreateSession = (name: string) => {
    const newSession = db.createSession(name);
    setSession(newSession);
    setShowStartModal(false);
  };

  const handleEndSession = () => {
    if (session) {
      if (session.id !== OFF_LIVE_ID) {
        db.closeSession(session.id);
      }
      setSession(null);
    }
  };

  const addToCart = (inputPrice: number, isFreebie: boolean = false) => {
    if (!selectedBaleId) return; // Should be handled by UI hiding, but safe guard
    const stats = getBaleStats(selectedBaleId);
    if (stats.remaining <= 0) {
      setOosModalData({ name: bales.find(b => b.id === selectedBaleId)?.name || '', total: stats.total, sold: stats.sold });
      return;
    }
    const price = isFreebie ? 0 : inputPrice;
    setCart(prev => {
      const idx = prev.findIndex(i => i.price === price && i.isFreebie === isFreebie && i.baleId === selectedBaleId);
      if (idx > -1) {
        const next = [...prev];
        const existingItem = next[idx];
        // Remove item from current position
        next.splice(idx, 1);
        // Increment and move to top
        return [{ ...existingItem, quantity: existingItem.quantity + 1 }, ...next];
      }
      // New item at the top
      return [{ id: `c_${Date.now()}_${Math.random()}`, price, quantity: 1, isFreebie, baleId: selectedBaleId }, ...prev];
    });
    setCustomPrice('');
  };

  const handleAddVipTickets = (count: number) => {
    if (!username) return alert('Enter a username first');
    const customer = db.getOrCreateCustomer(username);
    const updated = { ...customer, isVIP: true, vipTickets: (customer.vipTickets || 0) + count };
    db.updateCustomer(updated);
    setFeedback(`Added ${count} tickets to @${username}`);
    setTimeout(() => setFeedback(null), 2000);
    setShowVipModal(false);
  };

  const handleCheckout = () => {
    if (!session || !username) return alert('Username required!');
    const customer = db.getOrCreateCustomer(username);
    const timestamp = Date.now();

    // Process VIP Ticket Deduction
    if (useVipTicket) {
      if (customer.vipTickets > 0) {
        customer.vipTickets -= 1;
        db.updateCustomer(customer);
      } else {
        alert('Customer has no VIP tickets left!');
        setUseVipTicket(false);
        return;
      }
    }

    cart.forEach((item, idx) => {
      for (let i = 0; i < item.quantity; i++) {
        const pid = `qp_${timestamp}_${idx}_${i}`;
        const prod: Product = { id: pid, name: item.isFreebie ? 'Gift' : `Live Item ₱${item.price}`, brand: 'Live', baleBatch: item.baleId, costPrice: 0, sellingPrice: item.price, stock: 0 };
        db.updateProduct(prod);
        db.addOrder({
          id: `o_${timestamp}_${idx}_${i}`, 
          sessionId: session.id, 
          customerId: customer.id, 
          customerUsername: username, 
          productId: pid, 
          productName: prod.name, 
          quantity: 1, 
          totalPrice: item.price, 
          isFreebie: item.isFreebie, 
          paymentStatus: item.isFreebie ? PaymentStatus.PAID : PaymentStatus.UNPAID, 
          shippingStatus: ShippingStatus.PENDING, 
          amountPaid: 0, 
          createdAt: timestamp, 
          referenceNumber: transactionNo || undefined,
          usedVipTicket: useVipTicket
        });
      }
    });

    setCart([]);
    setUsername('');
    setTransactionNo('');
    setUseVipTicket(false);
    setFeedback(`Recorded for @${username}!`);
    setTimeout(() => setFeedback(null), 2000);
  };

  const handleEditCustomer = (targetUsername: string) => {
    if (!session) return;
    const sessionOrders = db.getOrders().filter(o => o.sessionId === session.id && o.customerUsername === targetUsername);
    if (sessionOrders.length === 0) return;

    if (cart.length > 0 && username !== targetUsername) {
      if(!confirm("Your current cart is not empty. Replacing it will clear current unsaved items. Continue?")) return;
    }

    // Convert Orders back to CartItems
    const products = db.getProducts();
    const newCartItems: CartItem[] = [];
    let ticketUsed = false;

    sessionOrders.forEach(order => {
       if (order.usedVipTicket) ticketUsed = true;
       const product = products.find(p => p.id === order.productId);
       const baleId = product?.baleBatch || ''; 

       const existingIdx = newCartItems.findIndex(ci => ci.price === order.totalPrice && ci.isFreebie === order.isFreebie && ci.baleId === baleId);

       if (existingIdx > -1) {
         newCartItems[existingIdx].quantity += order.quantity;
       } else {
         newCartItems.push({
           id: `c_restored_${order.id}`,
           price: order.totalPrice, 
           quantity: order.quantity,
           isFreebie: order.isFreebie,
           baleId: baleId
         });
       }
    });

    // Restore to Cart
    setCart(newCartItems);
    setUsername(targetUsername);
    setTransactionNo(sessionOrders[0].referenceNumber || '');
    setUseVipTicket(ticketUsed);

    // If ticket was used, refund it temporarily while editing
    if (ticketUsed) {
      const cust = db.getOrCreateCustomer(targetUsername);
      cust.vipTickets += 1;
      db.updateCustomer(cust);
    }

    // Delete Orders from DB (to avoid duplicate when saved again)
    sessionOrders.forEach(o => db.deleteOrder(o.id));

    setShowSessionOrders(false);
    setFeedback(`Editing @${targetUsername}`);
    setTimeout(() => setFeedback(null), 2000);
  };

  const cartTotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const currentBaleStats = selectedBaleId ? getBaleStats(selectedBaleId) : null;
  const displayLogo = logoUrl || './logo.png';

  if (viewingHistory) {
    const sessionOrders = db.getOrders().filter(o => o.sessionId === viewingHistory.id);
    const total = sessionOrders.reduce((sum, o) => sum + o.totalPrice, 0);
    return (
      <div className="max-w-xl mx-auto space-y-6 animate-fadeIn pb-32">
        <button onClick={() => setViewingHistory(null)} className="text-sm font-black text-gray-800 bg-white px-6 py-3 rounded-2xl border-2 border-pawPink shadow-sm">← Back to Dashboard</button>
        <div className="bg-white p-8 rounded-[3rem] border-2 border-pawPink shadow-lg">
           <h2 className="text-3xl font-black text-gray-800 mb-2 leading-none">{viewingHistory.name}</h2>
           <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-8">{viewingHistory.date}</p>
           <div className="grid grid-cols-2 gap-4 mb-8">
              <div className="bg-pawSoftBlue p-6 rounded-[2rem]">
                 <p className="text-[10px] font-black text-blue-900 uppercase tracking-widest mb-1">Total Sales</p>
                 <p className="text-2xl font-black text-blue-950">₱{total.toLocaleString()}</p>
              </div>
              <div className="bg-pawPink/20 p-6 rounded-[2rem]">
                 <p className="text-[10px] font-black text-pawPinkDark uppercase tracking-widest mb-1">Items Sold</p>
                 <p className="text-2xl font-black text-pawPinkDark">{sessionOrders.length}</p>
              </div>
           </div>
           <div className="space-y-3">
              <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 px-2">Recent Transactions</h4>
              {sessionOrders.slice(0, 10).map(o => (
                <div key={o.id} className="flex justify-between items-center p-4 bg-gray-50 rounded-2xl border border-gray-100">
                   <span className="font-bold text-gray-800">@{o.customerUsername}</span>
                   <span className="font-black text-gray-950">₱{o.totalPrice}</span>
                </div>
              ))}
           </div>
        </div>
      </div>
    );
  }

  if (!session) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[70vh] px-4 animate-fadeIn pb-32">
        <div className="w-full max-w-lg text-center space-y-10">
          <div className="flex flex-col items-center animate-scaleUp">
             <h1 className="text-7xl font-black text-gray-900 tracking-tighter leading-none font-nunito">
               {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }).replace(/\s(?:AM|PM)/, '')}
               <span className="text-xl text-pawPinkDark align-top ml-1">
                  {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }).match(/(?:AM|PM)/)?.[0]}
               </span>
             </h1>
             <p className="text-[10px] font-black text-gray-900 uppercase tracking-[0.4em] mt-3">
               {currentTime.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' })}
             </p>
          </div>

          <div className="bg-white p-8 rounded-[3rem] border-2 border-pawPink shadow-xl space-y-6">
            <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Ready to Start?</h2>
            <div className="grid grid-cols-2 gap-3">
               <button onClick={() => setSession({ id: OFF_LIVE_ID, name: 'Manual Encoding', date: new Date().toLocaleDateString(), totalSales: 0, totalOrders: 0, isOpen: true })} className="bg-white border-2 border-gray-300 text-gray-900 py-5 rounded-[2rem] font-black uppercase text-[10px] shadow-sm hover:border-pawPinkDark transition-all active:scale-95">Manual Entry</button>
               <button onClick={() => setShowScheduleModal(true)} className="bg-white border-2 border-gray-300 text-gray-900 py-5 rounded-[2rem] font-black uppercase text-[10px] shadow-sm hover:border-pawPinkDark transition-all active:scale-95">Schedule</button>
               <button onClick={() => setShowStartModal(true)} className="col-span-2 bg-gray-900 text-white py-6 rounded-[2.5rem] font-black uppercase shadow-2xl text-xs tracking-widest active:scale-95 transition-all">Start Live Selling</button>
            </div>
          </div>

          {todaysHistory.length > 0 && (
            <div className="w-full text-left space-y-4">
               <h3 className="text-[11px] font-black text-gray-500 uppercase tracking-[0.2em] px-6">Completed Today</h3>
               <div className="space-y-3">
                  {todaysHistory.map(hist => (
                    <button key={hist.id} onClick={() => setViewingHistory(hist)} className="w-full bg-white/60 p-6 rounded-[2.5rem] border border-pawPink/40 flex justify-between items-center group active:scale-98 transition-all hover:bg-white hover:border-pawPink">
                       <div className="text-left">
                          <p className="font-black text-gray-900 text-lg group-hover:text-pawPinkDark">{hist.name}</p>
                          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">{hist.date}</p>
                       </div>
                       <div className="text-right">
                          <p className="text-[10px] font-black text-gray-400 uppercase">Review</p>
                          <p className="text-xs font-black text-gray-900">→</p>
                       </div>
                    </button>
                  ))}
               </div>
            </div>
          )}
        </div>
        {showStartModal && <StartSessionModal onClose={() => setShowStartModal(false)} onStart={handleCreateSession} />}
        {showScheduleModal && <ScheduleModal onClose={() => setShowScheduleModal(false)} onSet={setScheduledTime} />}
      </div>
    );
