import React, { useState, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { Order, PaymentStatus, ShippingStatus, LiveSession } from '../types';
import { CartIcon } from '../components/Icons';

const OFF_LIVE_ID = 'OFF_LIVE';

interface GroupedOrder extends Order {
  ids: string[];
  items: Order[];
  isCustomerVIP?: boolean;
}

const Orders: React.FC = () => {
  const [selectedSession, setSelectedSession] = useState<LiveSession | null>(null);
  const [filter, setFilter] = useState('All');
  const [selectedOrder, setSelectedOrder] = useState<GroupedOrder | null>(null);
  const [allOrders, setAllOrders] = useState(db.getOrders());
  const customers = db.getCustomers();

  const sessions = useMemo(() => {
    const dbSessions = db.getSessions().sort((a, b) => b.id.localeCompare(a.id));
    const hasManual = allOrders.some(o => o.sessionId === OFF_LIVE_ID);
    if (hasManual) {
      const manual: LiveSession = { id: OFF_LIVE_ID, name: 'Manual Encoding', date: 'Manual', totalSales: 0, totalOrders: 0, isOpen: true };
      return [manual, ...dbSessions];
    }
    return dbSessions;
  }, [allOrders]);

  const filteredOrders = useMemo(() => {
    if (!selectedSession) return [];
    const base = allOrders.filter(o => o.sessionId === selectedSession.id);
    const groups: Record<string, GroupedOrder> = {};

    // Create map for quick lookup
    const vipMap = new Map(customers.map(c => [c.username, c.isVIP]));

    base.forEach(o => {
      const key = o.customerUsername;
      if (!groups[key]) {
        groups[key] = { 
            ...o, 
            ids: [o.id], 
            items: [o],
            isCustomerVIP: vipMap.get(o.customerUsername) || false
        };
      } else {
        groups[key].quantity += o.quantity;
        groups[key].totalPrice += o.totalPrice;
        groups[key].amountPaid += o.amountPaid;
        groups[key].ids.push(o.id);
        groups[key].items.push(o);
      }
    });

    return Object.values(groups).filter(g => {
      if (filter === 'Unpaid') return g.paymentStatus === PaymentStatus.UNPAID;
      if (filter === 'To Ship') return g.shippingStatus === ShippingStatus.PENDING;
      return true;
    }).sort((a, b) => b.createdAt - a.createdAt);
  }, [allOrders, selectedSession, filter, customers]);

  const handleUpdate = (updated: GroupedOrder) => {
    updated.ids.forEach(id => {
       const original = db.getOrders().find(o => o.id === id);
       if (original) {
          db.updateOrder({ ...original, paymentStatus: updated.paymentStatus, shippingStatus: updated.shippingStatus, amountPaid: (updated.amountPaid / updated.quantity) });
       }
    });
    setAllOrders(db.getOrders());
    setSelectedOrder(null);
  };

  if (!selectedSession) {
    return (
      <div className="space-y-8 pb-24 px-1 animate-fadeIn">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Order Batches</h1>
          <p className="text-gray-500 font-bold text-sm">Review transactions by live session.</p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
           {sessions.map(s => (
             <button key={s.id} onClick={() => setSelectedSession(s)} className="bg-white rounded-[2.5rem] p-7 border-2 border-pawPink/30 shadow-sm text-left group transition-all">
                <h3 className="font-black text-gray-800 text-xl leading-none mb-4 group-hover:text-pawPinkDark">{s.name}</h3>
                <div className="flex gap-4">
                   <div className="bg-pawSoftBlue p-3 rounded-2xl flex-1 text-center">
                      <p className="text-[9px] text-blue-600 font-black uppercase mb-1">Items</p>
                      <p className="text-xl font-black text-gray-800">{allOrders.filter(o => o.sessionId === s.id).length}</p>
                   </div>
                   <div className="bg-pawLavender p-3 rounded-2xl flex-1 text-center">
                      <p className="text-[9px] text-purple-700 font-black uppercase mb-1">Sales</p>
                      <p className="text-xl font-black text-gray-800">₱{allOrders.filter(o => o.sessionId === s.id).reduce((sum,o) => sum + o.totalPrice, 0).toLocaleString()}</p>
                   </div>
                </div>
             </button>
           ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-24 px-1 animate-fadeIn">
      <button onClick={() => setSelectedSession(null)} className="text-[10px] font-black uppercase text-gray-400">← Back</button>
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <h1 className="text-2xl font-black text-gray-800 tracking-tight">{selectedSession.name}</h1>
        <div className="flex bg-white p-1 rounded-2xl border border-pawPink/30">
          {['All', 'Unpaid', 'To Ship'].map(f => (
            <button key={f} onClick={() => setFilter(f)} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${filter === f ? 'bg-pawPinkDark text-white' : 'text-gray-400'}`}>{f}</button>
          ))}
        </div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredOrders.map(group => (
          <div key={group.ids[0]} className="bg-white rounded-[2rem] p-6 border border-pawPink shadow-sm">
            <div className="flex justify-between items-start mb-4">
               <div>
                  <div className="flex items-center gap-2 mb-1">
                    <h4 className="font-black text-gray-800 text-xl tracking-tight leading-none">@{group.customerUsername}</h4>
                    {group.isCustomerVIP && (
                      <span className="bg-yellow-100 text-yellow-700 text-[9px] font-black px-1.5 py-0.5 rounded uppercase">VIP</span>
                    )}
                  </div>
                  <p className="text-[10px] font-black text-gray-400 uppercase">{group.items.length} items</p>
               </div>
               <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase ${group.paymentStatus === 'Paid' ? 'bg-purple-100 text-purple-700' : 'bg-red-100 text-red-700'}`}>{group.paymentStatus}</span>
            </div>
            <p className="text-2xl font-black text-gray-800 mb-6">₱{group.totalPrice.toLocaleString()}</p>
            <button onClick={() => setSelectedOrder(group)} className="w-full py-3 bg-pawPinkDark text-white font-black rounded-xl text-xs uppercase shadow-lg">Manage</button>
          </div>
        ))}
      </div>
      {selectedOrder && <StatusModal order={selectedOrder} onClose={() => setSelectedOrder(null)} onSave={handleUpdate} />}
    </div>
  );
};

const StatusModal = ({ order, onClose, onSave }: any) => {
  const [formData, setFormData] = useState({...order});
  return createPortal(
    <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center p-0 md:p-4 bg-black/40 backdrop-blur-sm animate-fadeIn">
      <div className="bg-white w-full max-w-lg rounded-t-[3rem] md:rounded-[3rem] overflow-hidden shadow-2xl animate-scaleUp">
        <div className="bg-pawPink p-8 shrink-0">
            <div className="flex items-center gap-2">
                <h3 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Order Update</h3>
            </div>
            <div className="flex items-center gap-2">
                <p className="text-pawPinkDark font-black text-xs">@{order.customerUsername}</p>
                {order.isCustomerVIP && <span className="text-[9px] font-black bg-white text-pawPinkDark px-1.5 rounded uppercase">VIP</span>}
            </div>
        </div>
        <div className="p-8 space-y-4">
           <div>
             <label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Payment Status</label>
             <select value={formData.paymentStatus} onChange={(e) => setFormData({...formData, paymentStatus: e.target.value})} className="w-full bg-pawCream p-4 rounded-2xl font-black mt-1 text-gray-800 outline-none">
               {Object.values(PaymentStatus).map(s => <option key={s} value={s}>{s}</option>)}
             </select>
           </div>
           <div>
             <label className="text-[10px] font-black text-gray-400 uppercase ml-2 tracking-widest">Shipping Status</label>
             <select value={formData.shippingStatus} onChange={(e) => setFormData({...formData, shippingStatus: e.target.value})} className="w-full bg-pawCream p-4 rounded-2xl font-black mt-1 text-gray-800 outline-none">
               {Object.values(ShippingStatus).map(s => <option key={s} value={s}>{s}</option>)}
             </select>
           </div>
           <div className="flex gap-4 pt-4">
             <button onClick={onClose} className="flex-1 py-4 bg-gray-100 text-gray-400 font-black rounded-2xl">Cancel</button>
             <button onClick={() => onSave(formData)} className="flex-1 py-4 bg-pawPinkDark text-white font-black rounded-2xl shadow-lg">Save Changes</button>
           </div>
        </div>
      </div>
    </div>, document.body
  );
};

export default Orders;

import React, { useState, useEffect, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { useSettings } from '../services/SettingsContext';
import { Product, Order, PaymentStatus, ShippingStatus, LiveSession, Bale, Customer } from '../types';
import { PlusIcon, PawIcon, CartIcon } from '../components/Icons';

const OFF_LIVE_ID = 'OFF_LIVE';
const PRESET_PRICES = [10, 50, 80, 130, 150, 160, 170, 180, 190, 200];

interface CartItem {
  id: string;
  price: number;
  quantity: number;
  isFreebie: boolean;
  baleId: string;
}

const LiveSell: React.FC = () => {
  const { logoUrl } = useSettings();
  const [session, setSession] = useState<LiveSession | null>(db.getSessions().find(s => s.isOpen) || null);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [scheduledTime, setScheduledTime] = useState<Date | null>(null);
  const [showScheduleModal, setShowScheduleModal] = useState(false);
  const [username, setUsername] = useState('');
  const [transactionNo, setTransactionNo] = useState('');
  const [selectedBaleId, setSelectedBaleId] = useState<string>('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [customPrice, setCustomPrice] = useState<string>('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showStartModal, setShowStartModal] = useState(false);
  const [oosModalData, setOosModalData] = useState<{ name: string; total: number; sold: number } | null>(null);
  const [todaysHistory, setTodaysHistory] = useState<LiveSession[]>([]);
  const [viewingHistory, setViewingHistory] = useState<LiveSession | null>(null);
  const [showSessionOrders, setShowSessionOrders] = useState(false);

  // VIP Logic
  const [useVipTicket, setUseVipTicket] = useState(false);

  // Re-fetch customers on every render to ensure fresh data after updates
  const customers = db.getCustomers();
  const bales = db.getBales();

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setCurrentTime(now);
      if (scheduledTime && !session) {
        if (now >= scheduledTime) {
          handleCreateSession(`Live @ ${scheduledTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`);
          setScheduledTime(null);
        }
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [scheduledTime, session]);

  useEffect(() => {
    const today = new Date().toLocaleDateString('en-US');
    const allSessions = db.getSessions();
    const todayFinished = allSessions.filter(s => !s.isOpen && s.date === today).sort((a, b) => b.id.localeCompare(a.id));
    setTodaysHistory(todayFinished);
  }, [session]);

  // Reset ticket usage when changing user
  useEffect(() => {
    setUseVipTicket(false);
  }, [username]);

  const filteredCustomers = useMemo(() => {
    if (!username || customers.some(c => c.username === username)) return [];
    return customers.filter(c => c.username.toLowerCase().includes(username.toLowerCase())).slice(0, 3);
  }, [username, customers]);

  const currentCustomer = useMemo(() => {
    return customers.find(c => c.username === username);
  }, [username, customers]);

  const getBaleStats = (baleId: string) => {
    const bale = bales.find(b => b.id === baleId);
    if (!bale) return { remaining: 0, total: 0, sold: 0, revenue: 0, targetPrice: 0 };

    const allProducts = db.getProducts();
    const allOrders = db.getOrders();
    const baleProductIds = allProducts.filter(p => p.baleBatch === baleId).map(p => p.id);
    const baleOrders = allOrders.filter(o => baleProductIds.includes(o.productId));

    const soldInDb = baleOrders.reduce((sum, o) => sum + o.quantity, 0);
    const revenueInDb = baleOrders.reduce((sum, o) => sum + o.totalPrice, 0);

    const inCartCount = cart.filter(item => item.baleId === baleId).reduce((sum, item) => sum + item.quantity, 0);
    const inCartRevenue = cart.filter(item => item.baleId === baleId).reduce((sum, item) => sum + (item.price * item.quantity), 0);

    const totalSoldActual = soldInDb + inCartCount;
    const totalRevenueActual = revenueInDb + inCartRevenue;
    const remaining = Math.max(0, bale.itemCount - totalSoldActual);
    const remainingToRecover = Math.max(0, bale.cost - totalRevenueActual);
    const targetPrice = remaining > 0 ? (remainingToRecover / remaining) : 0;

    return { remaining, total: bale.itemCount, sold: totalSoldActual, revenue: totalRevenueActual, targetPrice };
  };

  const handleCreateSession = (name: string) => {
    const newSession = db.createSession(name);
    setSession(newSession);
    setShowStartModal(false);
  };

  const handleEndSession = () => {
    if (session) {
      if (session.id !== OFF_LIVE_ID) {
        db.closeSession(session.id);
      }
      setSession(null);
    }
  };

  const addToCart = (inputPrice: number, isFreebie: boolean = false) => {
    if (!selectedBaleId) return; // Should be handled by UI hiding, but safe guard
    const stats = getBaleStats(selectedBaleId);
    if (stats.remaining <= 0) {
      setOosModalData({ name: bales.find(b => b.id === selectedBaleId)?.name || '', total: stats.total, sold: stats.sold });
      return;
    }
    const price = isFreebie ? 0 : inputPrice;
    setCart(prev => {
      const idx = prev.findIndex(i => i.price === price && i.isFreebie === isFreebie && i.baleId === selectedBaleId);
      if (idx > -1) {
        const next = [...prev];
        const existingItem = next[idx];
        // Remove item from current position
        next.splice(idx, 1);
        // Increment and move to top
        return [{ ...existingItem, quantity: existingItem.quantity + 1 }, ...next];
      }
      // New item at the top
      return [{ id: `c_${Date.now()}_${Math.random()}`, price, quantity: 1, isFreebie, baleId: selectedBaleId }, ...prev];
    });
    setCustomPrice('');
  };

  const handleMakeVip = () => {
    if (!username) return alert('Enter a username first');
    const customer = db.getOrCreateCustomer(username);
    const updated = { ...customer, isVIP: true, vipTickets: (customer.vipTickets || 0) + 1 };
    db.updateCustomer(updated);
    setFeedback(`VIP Ticket Added (+1)`);
    setTimeout(() => setFeedback(null), 1500);
  };

  const handleCheckout = () => {
    if (!session || !username) return alert('Username required!');
    const customer = db.getOrCreateCustomer(username);
    const timestamp = Date.now();

    // Process VIP Ticket Deduction
    if (useVipTicket) {
      if (customer.vipTickets > 0) {
        customer.vipTickets -= 1;
        db.updateCustomer(customer);
      } else {
        alert('Customer has no VIP tickets left!');
        setUseVipTicket(false);
        return;
      }
    }

    cart.forEach((item, idx) => {
      for (let i = 0; i < item.quantity; i++) {
        const pid = `qp_${timestamp}_${idx}_${i}`;
        const prod: Product = { id: pid, name: item.isFreebie ? 'Gift' : `Live Item ₱${item.price}`, brand: 'Live', baleBatch: item.baleId, costPrice: 0, sellingPrice: item.price, stock: 0 };
        db.updateProduct(prod);
        db.addOrder({
          id: `o_${timestamp}_${idx}_${i}`, 
          sessionId: session.id, 
          customerId: customer.id, 
          customerUsername: username, 
          productId: pid, 
          productName: prod.name, 
          quantity: 1, 
          totalPrice: item.price, 
          isFreebie: item.isFreebie, 
          paymentStatus: item.isFreebie ? PaymentStatus.PAID : PaymentStatus.UNPAID, 
          shippingStatus: ShippingStatus.PENDING, 
          amountPaid: 0, 
          createdAt: timestamp, 
          referenceNumber: transactionNo || undefined,
          usedVipTicket: useVipTicket
        });
      }
    });

    setCart([]);
    setUsername('');
    setTransactionNo('');
    setUseVipTicket(false);
    setFeedback(`Recorded for @${username}!`);
    setTimeout(() => setFeedback(null), 2000);
  };

  const handleEditCustomer = (targetUsername: string) => {
    if (!session) return;
    const sessionOrders = db.getOrders().filter(o => o.sessionId === session.id && o.customerUsername === targetUsername);
    if (sessionOrders.length === 0) return;

    if (cart.length > 0 && username !== targetUsername) {
      if(!confirm("Your current cart is not empty. Replacing it will clear current unsaved items. Continue?")) return;
    }

    // Convert Orders back to CartItems
    const products = db.getProducts();
    const newCartItems: CartItem[] = [];
    let ticketUsed = false;

    sessionOrders.forEach(order => {
       if (order.usedVipTicket) ticketUsed = true;
       const product = products.find(p => p.id === order.productId);
       const baleId = product?.baleBatch || ''; 

       const existingIdx = newCartItems.findIndex(ci => ci.price === order.totalPrice && ci.isFreebie === order.isFreebie && ci.baleId === baleId);

       if (existingIdx > -1) {
         newCartItems[existingIdx].quantity += order.quantity;
       } else {
         newCartItems.push({
           id: `c_restored_${order.id}`,
           price: order.totalPrice, 
           quantity: order.quantity,
           isFreebie: order.isFreebie,
           baleId: baleId
         });
       }
    });

    // Restore to Cart
    setCart(newCartItems);
    setUsername(targetUsername);
    setTransactionNo(sessionOrders[0].referenceNumber || '');
    setUseVipTicket(ticketUsed);

    // If ticket was used, refund it temporarily while editing
    if (ticketUsed) {
      const cust = db.getOrCreateCustomer(targetUsername);
      cust.vipTickets += 1;
      db.updateCustomer(cust);
    }

    // Delete Orders from DB (to avoid duplicate when saved again)
    sessionOrders.forEach(o => db.deleteOrder(o.id));

    setShowSessionOrders(false);
    setFeedback(`Editing @${targetUsername}`);
    setTimeout(() => setFeedback(null), 2000);
  };

  const cartTotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const currentBaleStats = selectedBaleId ? getBaleStats(selectedBaleId) : null;
  const displayLogo = logoUrl || './logo.png';

  if (viewingHistory) {
    const sessionOrders = db.getOrders().filter(o => o.sessionId === viewingHistory.id);
    const total = sessionOrders.reduce((sum, o) => sum + o.totalPrice, 0);
    return (
      <div className="max-w-xl mx-auto space-y-6 animate-fadeIn pb-32">
        <button onClick={() => setViewingHistory(null)} className="text-sm font-black text-gray-800 bg-white px-6 py-3 rounded-2xl border-2 border-pawPink shadow-sm">← Back to Dashboard</button>
        <div className="bg-white p-8 rounded-[3rem] border-2 border-pawPink shadow-lg">
           <h2 className="text-3xl font-black text-gray-800 mb-2 leading-none">{viewingHistory.name}</h2>
           <p className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-8">{viewingHistory.date}</p>
           <div className="grid grid-cols-2 gap-4 mb-8">
              <div className="bg-pawSoftBlue p-6 rounded-[2rem]">
                 <p className="text-[10px] font-black text-blue-900 uppercase tracking-widest mb-1">Total Sales</p>
                 <p className="text-2xl font-black text-blue-950">₱{total.toLocaleString()}</p>
              </div>
              <div className="bg-pawPink/20 p-6 rounded-[2rem]">
                 <p className="text-[10px] font-black text-pawPinkDark uppercase tracking-widest mb-1">Items Sold</p>
                 <p className="text-2xl font-black text-pawPinkDark">{sessionOrders.length}</p>
              </div>
           </div>
           <div className="space-y-3">
              <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 px-2">Recent Transactions</h4>
              {sessionOrders.slice(0, 10).map(o => (
                <div key={o.id} className="flex justify-between items-center p-4 bg-gray-50 rounded-2xl border border-gray-100">
                   <span className="font-bold text-gray-800">@{o.customerUsername}</span>
                   <span className="font-black text-gray-950">₱{o.totalPrice}</span>
                </div>
              ))}
           </div>
        </div>
      </div>
    );
  }

  if (!session) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[70vh] px-4 animate-fadeIn pb-32">
        <div className="w-full max-w-lg text-center space-y-10">
          <div className="flex flex-col items-center animate-scaleUp">
             <h1 className="text-7xl font-black text-gray-900 tracking-tighter leading-none font-nunito">
               {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }).replace(/\s(?:AM|PM)/, '')}
               <span className="text-xl text-pawPinkDark align-top ml-1">
                  {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }).match(/(?:AM|PM)/)?.[0]}
               </span>
             </h1>
             <p className="text-[10px] font-black text-gray-900 uppercase tracking-[0.4em] mt-3">
               {currentTime.toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' })}
             </p>
          </div>

          <div className="bg-white p-8 rounded-[3rem] border-2 border-pawPink shadow-xl space-y-6">
            <h2 className="text-2xl font-black text-gray-800 uppercase tracking-tight">Ready to Start?</h2>
            <div className="grid grid-cols-2 gap-3">
               <button onClick={() => setSession({ id: OFF_LIVE_ID, name: 'Manual Encoding', date: new Date().toLocaleDateString(), totalSales: 0, totalOrders: 0, isOpen: true })} className="bg-white border-2 border-gray-300 text-gray-900 py-5 rounded-[2rem] font-black uppercase text-[10px] shadow-sm hover:border-pawPinkDark transition-all active:scale-95">Manual Entry</button>
               <button onClick={() => setShowScheduleModal(true)} className="bg-white border-2 border-gray-300 text-gray-900 py-5 rounded-[2rem] font-black uppercase text-[10px] shadow-sm hover:border-pawPinkDark transition-all active:scale-95">Schedule</button>
               <button onClick={() => setShowStartModal(true)} className="col-span-2 bg-gray-900 text-white py-6 rounded-[2.5rem] font-black uppercase shadow-2xl text-xs tracking-widest active:scale-95 transition-all">Start Live Selling</button>
            </div>
          </div>

          {todaysHistory.length > 0 && (
            <div className="w-full text-left space-y-4">
               <h3 className="text-[11px] font-black text-gray-500 uppercase tracking-[0.2em] px-6">Completed Today</h3>
               <div className="space-y-3">
                  {todaysHistory.map(hist => (
                    <button key={hist.id} onClick={() => setViewingHistory(hist)} className="w-full bg-white/60 p-6 rounded-[2.5rem] border border-pawPink/40 flex justify-between items-center group active:scale-98 transition-all hover:bg-white hover:border-pawPink">
                       <div className="text-left">
                          <p className="font-black text-gray-900 text-lg group-hover:text-pawPinkDark">{hist.name}</p>
                          <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">{hist.date}</p>
                       </div>
                       <div className="text-right">
                          <p className="text-[10px] font-black text-gray-400 uppercase">Review</p>
                          <p className="text-xs font-black text-gray-900">→</p>
                       </div>
                    </button>
                  ))}
               </div>
            </div>
          )}
        </div>
        {showStartModal && <StartSessionModal onClose={() => setShowStartModal(false)} onStart={handleCreateSession} />}
        {showScheduleModal && <ScheduleModal onClose={() => setShowScheduleModal(false)} onSet={setScheduledTime} />}
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 pb-32 max-w-full">
      <div className="lg:col-span-8 space-y-6">
        <div className="bg-white p-6 md:p-8 rounded-[3rem] shadow-xl border-2 border-pawPink/40 relative">
          <div className="flex justify-between items-start mb-10">
            <div>
              <div className="flex items-center gap-2 mb-1">
                <span className={`w-2 h-2 rounded-full animate-pulse ${session.id === OFF_LIVE_ID ? 'bg-blue-600' : 'bg-red-600'}`}></span>
                <span className={`text-[10px] font-black uppercase tracking-widest ${session.id === OFF_LIVE_ID ? 'text-blue-600' : 'text-red-600'}`}>
                  {session.id === OFF_LIVE_ID ? 'Manual Mode' : 'LIVE • ON AIR'}
                </span>
              </div>
              <h3 className="text-3xl font-black text-gray-900 uppercase leading-none tracking-tight">{session.name}</h3>
            </div>
            <button className="text-[10px] font-black text-gray-900 uppercase bg-gray-100 px-6 py-3 rounded-2xl hover:bg-red-600 hover:text-white transition-all shadow-sm" onClick={handleEndSession}>End Session</button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
             <div className="relative">
                <div className="flex justify-between items-center mb-2 ml-4">
                  <label className="text-[11px] font-black text-gray-900 uppercase tracking-widest">Customer Username</label>
                  {username && (
                    <div className="flex items-center gap-2">
                      {currentCustomer && (
                        <span className="text-[10px] font-black bg-yellow-100 text-yellow-700 px-3 py-1 rounded-full uppercase shadow-sm">
                          🎫 {currentCustomer.vipTickets || 0}
                        </span>
                      )}
                      <button 
                        onClick={handleMakeVip} 
                        className="bg-gray-900 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase hover:bg-pawPinkDark transition-all shadow-sm active:scale-90 flex items-center gap-1"
                      >
                         Make VIP
                      </button>
                    </div>
                  )}
                </div>
                <div className="flex items-center bg-gray-50 rounded-[1.8rem] px-6 border-2 border-gray-100 focus-within:border-pawPinkDark transition-all shadow-inner">
                  <span className="text-xl font-black text-gray-400">@</span>
                  <input type="text" placeholder="TikTok ID" value={username} onChange={(e) => setUsername(e.target.value)} className="w-full bg-transparent p-5 text-xl font-black text-gray-900 placeholder:text-gray-300 border-none focus:ring-0" />
                </div>
                {filteredCustomers.length > 0 && (
                  <div className="absolute top-full left-0 right-0 bg-white shadow-2xl rounded-[1.8rem] z-30 border-2 border-pawPink mt-3 p-2 overflow-hidden animate-scaleUp">
                    {filteredCustomers.map(c => (
                      <button key={c.id} onClick={() => setUsername(c.username)} className="w-full text-left p-5 hover:bg-pawPink/20 rounded-2xl font-black text-sm text-gray-900 flex justify-between">
                        <span>@{c.username}</span>
                        {c.isVIP && <span className="text-[10px] bg-yellow-400 text-white px-3 py-1 rounded-full uppercase">VIP</span>}
                      </button>
                    ))}
                  </div>
                )}
             </div>
             <div>
                <label className="text-[11px] font-black text-gray-900 uppercase ml-4 tracking-widest block mb-2">Order Reference / Notes</label>
                <input type="text" placeholder="Optional" value={transactionNo} onChange={(e) => setTransactionNo(e.target.value)} className="w-full bg-gray-50 border-2 border-gray-100 focus:border-pawPinkDark p-5 rounded-[1.8rem] text-xl font-black text-gray-900 outline-none transition-all shadow-inner placeholder:text-gray-300" />
             </div>
          </div>

          <div className="mb-10">
            <label className="text-[11px] font-black text-gray-900 uppercase ml-4 tracking-widest block mb-2">Active Batch Selection</label>
            <div className="relative">
              <select value={selectedBaleId} onChange={(e) => setSelectedBaleId(e.target.value)} className="w-full bg-pawSoftBlue p-5 rounded-[1.8rem] font-black text-lg text-blue-950 outline-none border-2 border-blue-100 appearance-none cursor-pointer shadow-sm">
                <option value="">Choose Inventory Source</option>
                {bales.filter(b => b.status !== 'Sold Out').map(b => <option key={b.id} value={b.id}>{b.name} ({b.itemCount} Units Total)</option>)}
              </select>
              <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-blue-900">▼</div>
            </div>
          </div>

          <div className="border-t-2 border-pawPink/20 pt-10">
            <div className="flex justify-between items-center mb-6 px-4">
              <label className="text-[11px] font-black text-gray-900 uppercase tracking-widest">Pricing Panel</label>
              {currentBaleStats && currentBaleStats.targetPrice > 0 && selectedBaleId && (
                <div className="flex items-center gap-2">
                  <span className={`text-[11px] font-black px-5 py-2 rounded-full uppercase tracking-tighter shadow-md animate-pulse ${currentBaleStats.targetPrice > 100 ? 'bg-red-600 text-white' : 'bg-purple-500 text-white'}`}>
                    Target: ₱{currentBaleStats.targetPrice.toFixed(0)}
                  </span>
                </div>
              )}
            </div>

            {/* Locked State if No Batch Selected */}
            {!selectedBaleId ? (
              <div className="bg-gray-50 rounded-[2rem] p-12 text-center border-2 border-dashed border-gray-200 flex flex-col items-center justify-center gap-3">
                 <div className="w-12 h-12 rounded-full bg-gray-200 flex items-center justify-center text-xl animate-bounce">👆</div>
                 <p className="text-gray-400 font-black uppercase tracking-widest text-xs">Please select a Batch above to enable pricing</p>
              </div>
            ) : (
              <>
                <div className="grid grid-cols-4 sm:grid-cols-5 gap-4 mb-8">
                   <button onClick={() => addToCart(0, true)} className="aspect-square rounded-[2rem] bg-orange-100 text-orange-900 font-black text-xs flex flex-col items-center justify-center border-4 border-white shadow-lg hover:scale-105 active:scale-95 transition-all">🎁<br/>FREEBIE</button>
                   {PRESET_PRICES.map(price => (
                     <button key={price} onClick={() => addToCart(price)} className="aspect-square rounded-[2rem] bg-white border-2 border-gray-100 font-black text-2xl text-gray-900 hover:border-pawPinkDark hover:text-pawPinkDark hover:scale-105 active:scale-95 transition-all shadow-md">
                       {price}
                     </button>
                   ))}
                </div>
                <div className="flex gap-4">
                   <div className="flex-1 bg-gray-50 rounded-[1.8rem] p-1 border-2 border-gray-100 focus-within:border-pawPinkDark transition-all">
                      <input type="number" placeholder="Other Price..." value={customPrice} onChange={(e) => setCustomPrice(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && customPrice && addToCart(Number(customPrice))} className="w-full bg-transparent p-5 rounded-[1.5rem] font-black text-xl text-gray-900 outline-none" />
                   </div>
                   <button onClick={() => customPrice && addToCart(Number(customPrice))} className="bg-gray-900 text-white px-12 rounded-[1.8rem] font-black uppercase text-xs tracking-widest hover:bg-black active:scale-95 transition-all shadow-lg">Add to Cart</button>
                </div>
              </>
            )}
          </div>
        </div>
      </div>

      <div className="lg:col-span-4 space-y-6">
         <div className="bg-pawSoftBlue p-8 rounded-[3rem] border-4 border-white shadow-2xl flex flex-col h-[750px] sticky top-4">
            <div className="flex items-center justify-between mb-8 shrink-0">
               <h3 className="text-2xl font-black text-blue-950 uppercase tracking-tight flex items-center gap-4"><CartIcon className="w-8 h-8" /> Live Cart</h3>
               <button 
                 onClick={() => setShowSessionOrders(true)} 
                 className="bg-white/50 hover:bg-white text-blue-900 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-colors shadow-sm"
               >
                 📝 History / Edit
               </button>
            </div>
            <div className="flex-1 overflow-y-auto custom-scrollbar space-y-4 mb-8 bg-white/80 rounded-[2.5rem] p-6 shadow-inner border-2 border-white">
               {cart.length === 0 ? (
                 <div className="h-full flex flex-col items-center justify-center space-y-4 opacity-40">
                    <div className="text-6xl">🧺</div>
                    <p className="text-sm font-black uppercase tracking-widest text-blue-900">Cart is Empty</p>
                 </div>
               ) : cart.map((item) => (
                 <div key={item.id} className="flex justify-between items-center bg-white p-4 rounded-2xl border border-blue-50 shadow-sm animate-slideIn">
                    <div className="flex items-center gap-4">
                      <div className="bg-gray-900 text-white w-10 h-10 rounded-full flex items-center justify-center text-xs font-black">{item.quantity}x</div>
                      <div>
                        <p className="font-black text-gray-950 text-lg">₱{item.price}</p>
                        <span className="inline-block bg-purple-100 text-purple-700 px-2 py-0.5 rounded-md text-[9px] font-black uppercase tracking-wide mt-1">
                          {bales.find(b => b.id === item.baleId)?.name}
                        </span>
                      </div>
                    </div>
                    <button onClick={() => setCart(prev => prev.filter(i => i.id !== item.id))} className="w-10 h-10 flex items-center justify-center bg-red-100 text-red-600 rounded-full hover:bg-red-600 hover:text-white transition-all font-black text-xl shadow-sm">×</button>
                 </div>
               ))}
            </div>

            {/* Cart Summary & Actions */}
            <div className="bg-white rounded-[2.5rem] p-8 mb-8 shadow-md border-2 border-blue-50 relative overflow-hidden group shrink-0">
               <div className="flex justify-between items-end relative z-10 mb-4">
                  <span className="text-[11px] font-black text-gray-400 uppercase tracking-widest">Total Bill</span>
                  <span className="text-5xl font-black text-gray-900">₱{cartTotal.toLocaleString()}</span>
               </div>

               {/* VIP Ticket Toggle */}
               {currentCustomer && currentCustomer.vipTickets > 0 && (
                 <button 
                    onClick={() => setUseVipTicket(!useVipTicket)}
                    className={`w-full py-3 mb-4 rounded-xl font-black uppercase text-xs tracking-widest border-2 transition-all flex justify-center items-center gap-2 relative z-20 ${
                       useVipTicket 
                         ? 'bg-yellow-400 border-yellow-400 text-white shadow-lg' 
                         : 'bg-white border-yellow-200 text-yellow-600 hover:bg-yellow-50'
                    }`}
                  >
                     {useVipTicket ? '★ VIP Ticket Applied (-1)' : 'Use VIP Ticket'}
                 </button>
               )}

               <div className="absolute top-0 right-0 w-32 h-32 bg-pawPink/10 rounded-bl-full -mr-10 -mt-10 group-hover:scale-110 transition-transform"></div>
            </div>

            <button onClick={handleCheckout} disabled={cart.length === 0 || !username} className={`w-full py-7 rounded-[2.5rem] font-black uppercase text-sm tracking-widest transition-all shrink-0 ${cart.length === 0 || !username ? 'bg-gray-200 text-gray-400 cursor-not-allowed border-2 border-gray-100' : 'bg-pawPinkDark text-white hover:bg-red-400 shadow-2xl shadow-pawPinkDark/40 active:scale-95'}`}>
               {feedback || 'Finalize Transaction'}
            </button>
         </div>
      </div>

      {showStartModal && <StartSessionModal onClose={() => setShowStartModal(false)} onStart={handleCreateSession} />}
      {showScheduleModal && <ScheduleModal onClose={() => setShowScheduleModal(false)} onSet={setScheduledTime} />}
      {oosModalData && <OutOfStockModal data={oosModalData} onClose={() => setOosModalData(null)} />}

      {showSessionOrders && (
        <SessionOrdersModal 
          sessionId={session.id} 
          onClose={() => setShowSessionOrders(false)} 
          onEdit={handleEditCustomer}
        />
      )}
    </div>
  );
};

const SessionOrdersModal = ({ sessionId, onClose, onEdit }: { sessionId: string; onClose: () => void; onEdit: (username: string) => void }) => {
  const orders = db.getOrders().filter(o => o.sessionId === sessionId);

  const groups = useMemo(() => {
     const g: Record<string, { username: string, count: number, total: number, lastTime: number, usedVip: boolean }> = {};
     orders.forEach(o => {
        if (!g[o.customerUsername]) {
           g[o.customerUsername] = { username: o.customerUsername, count: 0, total: 0, lastTime: o.createdAt, usedVip: false };
        }
        g[o.customerUsername].count += o.quantity;
        g[o.customerUsername].total += o.totalPrice;
        g[o.customerUsername].lastTime = Math.max(g[o.customerUsername].lastTime, o.createdAt);
        if(o.usedVipTicket) g[o.customerUsername].usedVip = true;
     });
     return Object.values(g).sort((a, b) => b.lastTime - a.lastTime);
  }, [orders]);

  return createPortal(
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/70 backdrop-blur-md animate-fadeIn">
      <div className="bg-white w-full max-w-lg rounded-[3.5rem] overflow-hidden shadow-2xl animate-scaleUp flex flex-col max-h-[80vh]">
         <div className="bg-pawSoftBlue p-8 flex justify-between items-center shrink-0">
            <div>
              <h3 className="text-2xl font-black text-blue-950 uppercase tracking-tight">Recent Activity</h3>
              <p className="text-xs font-black text-blue-400 uppercase tracking-wider">Tap to Edit Order</p>
            </div>
            <button onClick={onClose} className="bg-white text-blue-900 w-10 h-10 rounded-full font-black flex items-center justify-center shadow-sm">✕</button>
         </div>
         <div className="flex-1 overflow-y-auto p-6 space-y-3 custom-scrollbar">
            {groups.length === 0 ? (
               <p className="text-center text-gray-400 font-black uppercase py-10">No orders recorded yet.</p>
            ) : groups.map(group => (
               <button 
                 key={group.username} 
                 onClick={() => onEdit(group.username)}
                 className="w-full bg-white border border-gray-100 p-5 rounded-[2rem] flex justify-between items-center shadow-sm hover:border-pawPinkDark hover:bg-pawPink/10 transition-all group"
               >
                  <div className="flex items-center gap-4 text-left">
                     <div className="w-12 h-12 rounded-full bg-pawSoftBlue text-blue-600 flex items-center justify-center font-black text-xl">
                        {group.username.charAt(0).toUpperCase()}
                     </div>
                     <div>
                        <p className="font-black text-gray-800 text-lg group-hover:text-pawPinkDark transition-colors">
                           @{group.username} 
                           {group.usedVip && <span className="ml-2 text-[8px] bg-yellow-100 text-yellow-700 px-1.5 py-0.5 rounded uppercase align-middle">Used Ticket</span>}
                        </p>
                        <p className="text-[10px] font-black text-gray-400 uppercase">{group.count} Items Encoded</p>
                     </div>
                  </div>
                  <div className="text-right">
                     <p className="font-black text-gray-950 text-xl">₱{group.total.toLocaleString()}</p>
                     <p className="text-[9px] font-black text-pawPinkDark uppercase tracking-widest">Edit &rarr;</p>
                  </div>
               </button>
            ))}
         </div>
      </div>
    </div>, document.body
  );
};

