            <button onClick={() => name && onStart(name)} className="flex-1 py-6 bg-gray-900 text-white font-black uppercase text-xs tracking-widest rounded-3xl shadow-xl">Go Live Now</button>
         </div>
      </div>
    </div>, document.body
  );
};

const ScheduleModal = ({ onClose, onSet }: any) => {
  const [time, setTime] = useState('');
  return createPortal(
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/70 backdrop-blur-md animate-fadeIn">
      <div className="bg-white w-full max-w-sm rounded-[3.5rem] p-10 space-y-8 animate-scaleUp text-center shadow-2xl border-4 border-pawPink">
         <h3 className="text-3xl font-black text-gray-900 uppercase tracking-tight">Schedule Start</h3>
         <input type="time" value={time} onChange={(e) => setTime(e.target.value)} className="bg-pawCream p-10 rounded-[2.5rem] text-6xl font-black w-full text-center outline-none border-4 border-transparent focus:border-pawPinkDark transition-all shadow-inner" />
         <div className="flex gap-4">
            <button onClick={onClose} className="flex-1 py-6 bg-gray-100 text-gray-900 font-black uppercase text-xs tracking-widest rounded-3xl">Cancel</button>
            <button onClick={() => { if(!time) return; const [h, m] = time.split(':').map(Number); const d = new Date(); d.setHours(h, m, 0, 0); onSet(d); onClose(); }} className="flex-1 py-6 bg-gray-900 text-white font-black uppercase text-xs tracking-widest rounded-3xl shadow-xl">Confirm Time</button>
         </div>
      </div>
    </div>, document.body
  );
};

const OutOfStockModal: React.FC<{ data: { name: string; total: number; sold: number }; onClose: () => void }> = ({ data, onClose }) => (
