             <input type="number" value={formData.itemCount || ''} placeholder="Item Count" onChange={(e) => setFormData({...formData, itemCount: Number(e.target.value)})} className="w-full bg-pawCream p-4 rounded-[1.5rem] font-bold outline-none border-none" />
