import React, { useState, useEffect, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { Bale, Order, Product, LiveSession, PaymentStatus } from '../types';
import { PlusIcon, SearchIcon } from '../components/Icons';

const Bales: React.FC = () => {
  const [bales, setBales] = useState(db.getBales());
  const [showModal, setShowModal] = useState(false);
  const [selectedBale, setSelectedBale] = useState<Bale | null>(null);
  const [viewingBale, setViewingBale] = useState<Bale | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Track expanded customer groups in the dispersal history
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());

  const products = db.getProducts();
  const orders = db.getOrders();
  const sessions = db.getSessions();

  const getBaleStats = (baleId: string) => {
    const bale = bales.find(b => b.id === baleId);
    if (!bale) return { soldCount: 0, revenue: 0, targetPrice: 0, progress: 0, isProfitable: false, profit: 0 };

    const baleProductIds = products.filter(p => p.baleBatch === baleId).map(p => p.id);
    const baleOrders = orders.filter(o => baleProductIds.includes(o.productId));
    const soldCount = baleOrders.reduce((sum, o) => sum + o.quantity, 0);
    const revenue = baleOrders.reduce((sum, o) => sum + o.totalPrice, 0);

    const remainingCount = Math.max(0, bale.itemCount - soldCount);
    const remainingToRecover = Math.max(0, bale.cost - revenue);
    const profit = revenue - bale.cost;

    // Suggest price for remaining items to recover all costs
    const targetPrice = remainingCount > 0 ? (remainingToRecover / remainingCount) : 0;
    const progress = Math.min(100, (revenue / bale.cost) * 100);

    return { soldCount, revenue, targetPrice, progress, isProfitable: revenue >= bale.cost, profit };
  };

  const handleSaveBale = (bale: Bale) => {
    db.updateBale(bale);
    setBales(db.getBales());
    setShowModal(false);
  };

  const toggleGroup = (username: string) => {
    const next = new Set(expandedGroups);
    if (next.has(username)) {
      next.delete(username);
    } else {
      next.add(username);
    }
    setExpandedGroups(next);
  };

  // Group orders by customer for the viewingBale
  const baleCustomerGroups = useMemo(() => {
    if (!viewingBale) return [];

    const baleProductIds = products.filter(p => p.baleBatch === viewingBale.id).map(p => p.id);
    const relevantOrders = orders.filter(o => baleProductIds.includes(o.productId));

    const groups: Record<string, { 
        username: string, 
        totalQty: number, 
        totalSpent: number, 
        paidCount: number,
        transactions: { id: string, sessionName: string, price: number, qty: number, date: string, isPaid: boolean }[] 
    }> = {};

    relevantOrders.forEach(order => {
       if (!groups[order.customerUsername]) {
          groups[order.customerUsername] = {
             username: order.customerUsername,
             totalQty: 0,
             totalSpent: 0,
             paidCount: 0,
             transactions: []
          };
       }

       const sessionName = sessions.find(s => s.id === order.sessionId)?.name || (order.sessionId === 'OFF_LIVE' ? 'Manual Encoding' : 'Unknown Session');
       const isPaid = order.paymentStatus === PaymentStatus.PAID;

       groups[order.customerUsername].totalQty += order.quantity;
       groups[order.customerUsername].totalSpent += order.totalPrice;
       if (isPaid) groups[order.customerUsername].paidCount += 1;

       groups[order.customerUsername].transactions.push({
          id: order.id,
          sessionName: sessionName,
          price: order.totalPrice,
          qty: order.quantity,
          date: new Date(order.createdAt).toLocaleDateString(),
          isPaid: isPaid
       });
    });

    return Object.values(groups)
      .filter(g => g.username.toLowerCase().includes(searchQuery.toLowerCase()))
      .sort((a, b) => b.totalSpent - a.totalSpent);

  }, [viewingBale, products, orders, sessions, searchQuery]);

  if (viewingBale) {
    const stats = getBaleStats(viewingBale.id);
    return (
      <div className="space-y-6 pb-32 px-1 animate-fadeIn">
        <button onClick={() => { setViewingBale(null); setSearchQuery(''); }} className="text-[10px] font-black uppercase text-gray-400 mb-2 hover:text-pawPinkDark transition-colors">← Back to Batches</button>
        <div className="bg-white rounded-[3rem] p-8 border-2 border-pawPink shadow-lg space-y-8">

           {/* Header & Stats */}
           <div>
              <div className="flex justify-between items-start mb-6">
                 <h1 className="text-3xl font-black text-gray-800 tracking-tight leading-none">{viewingBale.name}</h1>
                 <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${stats.isProfitable ? 'bg-purple-100 text-purple-700' : 'bg-orange-100 text-orange-700'}`}>
                    {stats.isProfitable ? 'Profitable ✨' : 'Recovering Capital'}
                 </span>
              </div>

              <div className="grid grid-cols-2 lg:grid-cols-5 gap-6 mb-8">
                 <Metric label="Investment" value={`₱${viewingBale.cost.toLocaleString()}`} />
                 <Metric label="Revenue" value={`₱${stats.revenue.toLocaleString()}`} />

                 {/* Profit Metric */}
                 <div className={`p-4 rounded-2xl border-2 flex flex-col justify-center ${stats.isProfitable ? 'bg-green-50 border-green-100' : 'bg-orange-50 border-orange-100'}`}>
                    <p className={`text-[9px] font-black uppercase tracking-widest mb-1 leading-none ${stats.isProfitable ? 'text-green-600' : 'text-orange-600'}`}>
                        {stats.isProfitable ? 'Net Profit' : 'Deficit'}
                    </p>
                    <p className={`text-xl font-black leading-none ${stats.isProfitable ? 'text-green-700' : 'text-orange-700'}`}>
                        {stats.profit > 0 ? '+' : ''}₱{stats.profit.toLocaleString()}
                    </p>
                 </div>

                 <Metric label="ROI %" value={`${stats.progress.toFixed(1)}%`} />
                 <Metric label="Units Left" value={viewingBale.itemCount - stats.soldCount} />
              </div>

              <div className="bg-pawSoftBlue/30 rounded-[2.5rem] p-7 border-2 border-white shadow-inner">
                 <div className="flex justify-between items-center mb-4">
                    <h4 className="text-xs font-black text-blue-900 uppercase tracking-widest">Pricing Strategy (Dynamic)</h4>
                 </div>
                 <p className="text-sm text-blue-800 font-bold mb-3">
                   {stats.isProfitable 
                      ? "You have fully recovered your initial investment. Every remaining item is now 100% profit!" 
                      : `To break even, you still need to recover ₱${(viewingBale.cost - stats.revenue).toLocaleString()}.`}
                 </p>
                 {!stats.isProfitable && (
                   <div className="flex items-center gap-4 bg-white/60 p-4 rounded-2xl border border-blue-100">
                      <div className="text-2xl">🎯</div>
                      <div>
                         <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest leading-none mb-1">Target Price per Remaining Item</p>
                         <p className="text-xl font-black text-blue-950 leading-none">₱{stats.targetPrice.toFixed(0)} <span className="text-xs font-bold text-gray-400">or higher</span></p>
                      </div>
                   </div>
                 )}
              </div>
           </div>

           {/* Order Breakdown Section */}
           <div>
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
                <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight">Dispersal History</h3>
                <div className="relative w-full md:w-64">
                    <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                    <input 
                      type="text" 
                      placeholder="Search Customer..." 
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      className="w-full bg-gray-50 pl-10 pr-4 py-3 rounded-2xl font-bold text-sm text-gray-800 outline-none focus:ring-2 focus:ring-pawPink"
                    />
                </div>
              </div>

              <div className="space-y-4">
                 {baleCustomerGroups.length === 0 ? (
                    <div className="text-center py-10 opacity-50 bg-gray-50 rounded-[2rem] border-2 border-dashed border-gray-200">
                       <p className="font-bold text-gray-400 text-sm uppercase tracking-widest">No items sold yet</p>
                    </div>
                 ) : (
                    baleCustomerGroups.map(group => {
                       const isExpanded = expandedGroups.has(group.username);
                       const allPaid = group.paidCount === group.transactions.length;

                       return (
                       <div key={group.username} className="bg-white border-2 border-gray-100 rounded-[2rem] shadow-sm hover:border-pawPink transition-all overflow-hidden">
                          {/* Customer Header - Clickable for Accordion */}
                          <div 
                             onClick={() => toggleGroup(group.username)}
                             className="p-5 flex justify-between items-center cursor-pointer hover:bg-gray-50 transition-colors"
                          >
                             <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-full bg-pawPink text-pawPinkDark flex items-center justify-center font-black text-xs">
                                   {group.username.charAt(0).toUpperCase()}
                                </div>
                                <div>
                                   <p className="font-black text-gray-800 text-lg leading-none">@{group.username}</p>
                                   <div className="flex gap-2 mt-1">
                                      <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">{group.transactions.length} items</p>
                                      {allPaid ? (
                                         <span className="text-[9px] font-black bg-green-100 text-green-700 px-2 rounded uppercase tracking-wider">Fully Paid</span>
                                      ) : group.paidCount > 0 ? (
                                         <span className="text-[9px] font-black bg-orange-100 text-orange-700 px-2 rounded uppercase tracking-wider">Partial</span>
                                      ) : (
                                         <span className="text-[9px] font-black bg-red-100 text-red-700 px-2 rounded uppercase tracking-wider">Unpaid</span>
                                      )}
                                   </div>
                                </div>
                             </div>
                             <div className="flex items-center gap-4">
                                <div className="text-right">
                                   <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Total</p>
                                   <p className="text-xl font-black text-gray-800">₱{group.totalSpent.toLocaleString()}</p>
                                </div>
                                <span className={`text-gray-300 transform transition-transform ${isExpanded ? 'rotate-180' : ''}`}>▼</span>
                             </div>
                          </div>

                          {/* Transaction Details - Collapsible */}
                          {isExpanded && (
                            <div className="bg-gray-50 border-t border-dashed border-gray-200 p-4 space-y-2 animate-fadeIn">
                               <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 px-2">Order Breakdown</p>
                               {group.transactions.map(tx => (
                                  <div key={tx.id} className="flex justify-between items-center text-xs font-bold text-gray-600 px-2 py-1 hover:bg-white rounded-lg transition-colors">
                                     <div className="flex items-center gap-2">
                                        <span className={`w-2 h-2 rounded-full ${tx.isPaid ? 'bg-green-400' : 'bg-red-400'}`}></span>
                                        <span className="text-gray-800">{tx.qty}x Item</span>
                                        <span className="text-gray-400 font-normal">from</span>
                                        <span className="bg-white px-2 py-0.5 rounded border border-gray-200 text-[10px] uppercase tracking-wide text-gray-500">{tx.sessionName}</span>
                                     </div>
                                     <div className="flex items-center gap-3">
                                        <span className={`text-[9px] uppercase font-black ${tx.isPaid ? 'text-green-600' : 'text-red-500'}`}>
                                           {tx.isPaid ? 'Paid' : 'Unpaid'}
                                        </span>
                                        <span>₱{tx.price.toLocaleString()}</span>
                                     </div>
                                  </div>
                               ))}
                            </div>
                          )}
                       </div>
                       );
                    })
                 )}
              </div>
           </div>

        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-32 px-1 animate-fadeIn">
      <div className="flex items-center justify-between px-2">
