  const getBaleStats = (baleId: string) => {
    const bale = bales.find(b => b.id === baleId);
    if (!bale) return { soldCount: 0, revenue: 0, targetPrice: 0, progress: 0, isProfitable: false, profit: 0 };

    const baleProductIds = products.filter(p => p.baleBatch === baleId).map(p => p.id);
    const baleOrders = orders.filter(o => baleProductIds.includes(o.productId));
    const soldCount = baleOrders.reduce((sum, o) => sum + o.quantity, 0);
    const revenue = baleOrders.reduce((sum, o) => sum + o.totalPrice, 0);

    const remainingCount = Math.max(0, bale.itemCount - soldCount);
    const remainingToRecover = Math.max(0, bale.cost - revenue);
    const profit = revenue - bale.cost;

    // Suggest price for remaining items to recover all costs
    const targetPrice = remainingCount > 0 ? (remainingToRecover / remainingCount) : 0;
    const progress = Math.min(100, (revenue / bale.cost) * 100);

    return { soldCount, revenue, targetPrice, progress, isProfitable: revenue >= bale.cost, profit };
  };

  const handleSaveBale = (bale: Bale) => {
    db.updateBale(bale);
    setBales(db.getBales());
    setShowModal(false);
  };

  const toggleGroup = (username: string) => {
    const next = new Set(expandedGroups);
    if (next.has(username)) {
      next.delete(username);
    } else {
      next.add(username);
    }
    setExpandedGroups(next);
  };

  // Group orders by customer for the viewingBale
  const baleCustomerGroups = useMemo(() => {
    if (!viewingBale) return [];

    const baleProductIds = products.filter(p => p.baleBatch === viewingBale.id).map(p => p.id);
    const relevantOrders = orders.filter(o => baleProductIds.includes(o.productId));

    const groups: Record<string, { 
        username: string, 
        totalQty: number, 
        totalSpent: number, 
        paidCount: number,
        transactions: { id: string, sessionName: string, price: number, qty: number, date: string, isPaid: boolean }[] 
    }> = {};

    relevantOrders.forEach(order => {
       if (!groups[order.customerUsername]) {
          groups[order.customerUsername] = {
             username: order.customerUsername,
             totalQty: 0,
             totalSpent: 0,
             paidCount: 0,
             transactions: []
          };
       }

       const sessionName = sessions.find(s => s.id === order.sessionId)?.name || (order.sessionId === 'OFF_LIVE' ? 'Manual Encoding' : 'Unknown Session');
       const isPaid = order.paymentStatus === PaymentStatus.PAID;

       groups[order.customerUsername].totalQty += order.quantity;
       groups[order.customerUsername].totalSpent += order.totalPrice;
       if (isPaid) groups[order.customerUsername].paidCount += 1;

       groups[order.customerUsername].transactions.push({
          id: order.id,
          sessionName: sessionName,
          price: order.totalPrice,
          qty: order.quantity,
          date: new Date(order.createdAt).toLocaleDateString(),
          isPaid: isPaid
       });
    });

    return Object.values(groups)
      .filter(g => g.username.toLowerCase().includes(searchQuery.toLowerCase()))
      .sort((a, b) => b.totalSpent - a.totalSpent);

  }, [viewingBale, products, orders, sessions, searchQuery]);

  if (viewingBale) {
    const stats = getBaleStats(viewingBale.id);
    return (
      <div className="space-y-6 pb-32 px-1 animate-fadeIn">
        <button onClick={() => { setViewingBale(null); setSearchQuery(''); }} className="text-[10px] font-black uppercase text-gray-400 mb-2 hover:text-pawPinkDark transition-colors">← Back to Batches</button>
        <div className="bg-white rounded-[3rem] p-8 border-2 border-pawPink shadow-lg space-y-8">

           {/* Header & Stats */}
           <div>
              <div className="flex justify-between items-start mb-6">
                 <h1 className="text-3xl font-black text-gray-800 tracking-tight leading-none">{viewingBale.name}</h1>
                 <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${stats.isProfitable ? 'bg-purple-100 text-purple-700' : 'bg-orange-100 text-orange-700'}`}>
                    {stats.isProfitable ? 'Profitable ✨' : 'Recovering Capital'}
                 </span>
              </div>

              <div className="grid grid-cols-2 lg:grid-cols-5 gap-6 mb-8 items-stretch">
                 <Metric label="Investment" value={`₱${viewingBale.cost.toLocaleString()}`} />
                 <Metric label="Revenue" value={`₱${stats.revenue.toLocaleString()}`} />

                 {/* Profit Metric */}
                 <div className={`p-4 rounded-2xl border-2 flex flex-col justify-center ${stats.isProfitable ? 'bg-green-50 border-green-100' : 'bg-orange-50 border-orange-100'}`}>
                    <p className={`text-[9px] font-black uppercase tracking-widest mb-1 leading-none ${stats.isProfitable ? 'text-green-600' : 'text-orange-600'}`}>
                        {stats.isProfitable ? 'Net Profit' : 'Deficit'}
                    </p>
                    <p className={`text-xl font-black leading-none ${stats.isProfitable ? 'text-green-700' : 'text-orange-700'}`}>
                        {stats.profit > 0 ? '+' : ''}₱{stats.profit.toLocaleString()}
                    </p>
                 </div>

                 <Metric label="ROI %" value={`${stats.progress.toFixed(1)}%`} />
                 <Metric label="Units Left" value={viewingBale.itemCount - stats.soldCount} />
              </div>

              <div className="bg-pawSoftBlue/30 rounded-[2.5rem] p-7 border-2 border-white shadow-inner">
                 <div className="flex justify-between items-center mb-4">
                    <h4 className="text-xs font-black text-blue-900 uppercase tracking-widest">Pricing Strategy (Dynamic)</h4>
                 </div>
                 <p className="text-sm text-blue-800 font-bold mb-3">
                   {stats.isProfitable 
                      ? "You have fully recovered your initial investment. Every remaining item is now 100% profit!" 
                      : `To break even, you still need to recover ₱${(viewingBale.cost - stats.revenue).toLocaleString()}.`}
                 </p>
                 {!stats.isProfitable && (
                   <div className="flex items-center gap-4 bg-white/60 p-4 rounded-2xl border border-blue-100">
                      <div className="text-2xl">🎯</div>
                      <div>
                         <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest leading-none mb-1">Target Price per Remaining Item</p>
                         <p className="text-xl font-black text-blue-950 leading-none">₱{stats.targetPrice.toFixed(0)} <span className="text-xs font-bold text-gray-400">or higher</span></p>
                      </div>
                   </div>
                 )}
              </div>
           </div>

           {/* Order Breakdown Section */}
           <div>
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
                <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight">Dispersal History</h3>
                <div className="relative w-full md:w-64">
                    <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
                    <input 
                      type="text" 
                      placeholder="Search Customer..." 
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      className="w-full bg-gray-50 pl-10 pr-4 py-3 rounded-2xl font-bold text-sm text-gray-800 outline-none focus:ring-2 focus:ring-pawPink"
                    />
                </div>
              </div>

              <div className="space-y-4">
                 {baleCustomerGroups.length === 0 ? (
                    <div className="text-center py-10 opacity-50 bg-gray-50 rounded-[2rem] border-2 border-dashed border-gray-200">
                       <p className="font-bold text-gray-400 text-sm uppercase tracking-widest">No items sold yet</p>
                    </div>
                 ) : (
                    baleCustomerGroups.map(group => {
                       const isExpanded = expandedGroups.has(group.username);
                       const allPaid = group.paidCount === group.transactions.length;

                       return (
                       <div key={group.username} className="bg-white border-2 border-gray-100 rounded-[2rem] shadow-sm hover:border-pawPink transition-all overflow-hidden">
                          {/* Customer Header - Clickable for Accordion */}
                          <div 
                             onClick={() => toggleGroup(group.username)}
                             className="p-5 flex justify-between items-center cursor-pointer hover:bg-gray-50 transition-colors"
                          >
                             <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-full bg-pawPink text-pawPinkDark flex items-center justify-center font-black text-xs">
                                   {group.username.charAt(0).toUpperCase()}
                                </div>
                                <div>
                                   <p className="font-black text-gray-800 text-lg leading-none">@{group.username}</p>
                                   <div className="flex gap-2 mt-1">
                                      <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">{group.transactions.length} items</p>
                                      {allPaid ? (
                                         <span className="text-[9px] font-black bg-green-100 text-green-700 px-2 rounded uppercase tracking-wider">Fully Paid</span>
                                      ) : group.paidCount > 0 ? (
                                         <span className="text-[9px] font-black bg-orange-100 text-orange-700 px-2 rounded uppercase tracking-wider">Partial</span>
                                      ) : (
                                         <span className="text-[9px] font-black bg-red-100 text-red-700 px-2 rounded uppercase tracking-wider">Unpaid</span>
                                      )}
                                   </div>
                                </div>
                             </div>
                             <div className="flex items-center gap-4">
                                <div className="text-right">
                                   <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Total</p>
                                   <p className="text-xl font-black text-gray-800">₱{group.totalSpent.toLocaleString()}</p>
                                </div>
                                <span className={`text-gray-300 transform transition-transform ${isExpanded ? 'rotate-180' : ''}`}>▼</span>
                             </div>
                          </div>

                          {/* Transaction Details - Collapsible */}
                          {isExpanded && (
                            <div className="bg-gray-50 border-t border-dashed border-gray-200 p-4 space-y-2 animate-fadeIn">
                               <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 px-2">Order Breakdown</p>
                               {group.transactions.map(tx => (
                                  <div key={tx.id} className="flex justify-between items-center text-xs font-bold text-gray-600 px-2 py-1 hover:bg-white rounded-lg transition-colors">
                                     <div className="flex items-center gap-2">
                                        <span className={`w-2 h-2 rounded-full ${tx.isPaid ? 'bg-green-400' : 'bg-red-400'}`}></span>
                                        <span className="text-gray-800">{tx.qty}x Item</span>
                                        <span className="text-gray-400 font-normal">from</span>
                                        <span className="bg-white px-2 py-0.5 rounded border border-gray-200 text-[10px] uppercase tracking-wide text-gray-500">{tx.sessionName}</span>
                                     </div>
                                     <div className="flex items-center gap-3">
                                        <span className={`text-[9px] uppercase font-black ${tx.isPaid ? 'text-green-600' : 'text-red-500'}`}>
                                           {tx.isPaid ? 'Paid' : 'Unpaid'}
                                        </span>
                                        <span>₱{tx.price.toLocaleString()}</span>
                                     </div>
                                  </div>
                               ))}
                            </div>
                          )}
                       </div>
                       );
                    })
                 )}
              </div>
           </div>

        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 pb-32 px-1 animate-fadeIn">
      <div className="flex items-center justify-between px-2">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Batches & ROI</h1>
          <p className="text-gray-500 font-bold text-sm">Monitor recovery progress for each sourcing batch.</p>
        </div>
        <button onClick={() => { setSelectedBale(null); setShowModal(true); }} className="bg-pawPinkDark text-white w-14 h-14 rounded-full shadow-xl flex items-center justify-center active:scale-95 transition-all">
          <PlusIcon className="w-6 h-6" />
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 px-2">
        {bales.map(bale => {
          const stats = getBaleStats(bale.id);
          return (
            <div key={bale.id} onClick={() => { setViewingBale(bale); setSearchQuery(''); }} className="bg-white rounded-[2.5rem] p-8 border-2 border-pawPink/20 shadow-xl relative cursor-pointer group active:scale-[0.98] transition-all hover:border-pawPinkDark">
              <div className="flex justify-between items-start mb-6">
                 <div>
                   <span className="text-[10px] font-black text-blue-500 bg-blue-50 px-3 py-1 rounded-md uppercase mb-2 inline-block tracking-widest">{bale.status}</span>
                   <h3 className="text-2xl font-black text-gray-800 tracking-tighter leading-none group-hover:text-pawPinkDark transition-colors">{bale.name}</h3>
                 </div>
                 <div className="text-right">
                    <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">ROI</p>
                    <p className={`text-xl font-black ${stats.isProfitable ? 'text-purple-500' : 'text-orange-500'}`}>{stats.progress.toFixed(0)}%</p>
                    <p className={`text-[10px] font-bold mt-1 ${stats.isProfitable ? 'text-green-600' : 'text-red-400'}`}>
                        {stats.profit > 0 ? '+' : ''}₱{stats.profit.toLocaleString()}
                    </p>
                 </div>
              </div>

              <div className="mb-6">
                 <div className="flex justify-between items-end mb-1 px-1">
                    <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Recovery</span>
                    <span className={`text-[10px] font-black ${stats.isProfitable ? 'text-purple-500' : 'text-orange-500'}`}>
                       {stats.progress.toFixed(0)}%
                    </span>
                 </div>
                 <div className="w-full h-3 bg-gray-100 rounded-full overflow-hidden shadow-inner">
                    <div className={`h-full transition-all duration-1000 ${stats.isProfitable ? 'bg-purple-400' : 'bg-pawPinkDark'}`} style={{ width: `${stats.progress}%` }}></div>
                 </div>
              </div>

              <div className="flex justify-between items-end border-t border-dashed border-gray-100 pt-4">
                 <div>
                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Investment</p>
                    <p className="font-bold text-gray-700">₱{bale.cost.toLocaleString()}</p>
                 </div>
                 <div className="text-right">
                    <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Leftovers</p>
                    <p className="font-bold text-gray-700">{bale.itemCount - stats.soldCount} units</p>
                 </div>
              </div>
            </div>
          );
        })}
      </div>
      {showModal && <BaleModal bale={selectedBale} onClose={() => setShowModal(false)} onSave={handleSaveBale} />}
    </div>
  );
};

const Metric = ({ label, value }: any) => (
  <div className="p-4 rounded-2xl border-2 border-transparent flex flex-col justify-center">
    <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1 leading-none">{label}</p>
    <p className="text-xl font-black text-gray-800 leading-none">{value}</p>
  </div>
);

const BaleModal = ({ onClose, onSave, bale }: any) => {
  const [formData, setFormData] = useState<Bale>(bale || { id: `B${Date.now()}`, name: '', status: 'Ordered', cost: 0, itemCount: 0 });
  const unitCost = formData.itemCount > 0 ? (formData.cost / formData.itemCount) : 0;

  return createPortal(
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
      <div className="bg-white w-full max-w-sm rounded-[2.5rem] overflow-hidden shadow-2xl animate-scaleUp">
        <div className="pt-8 pb-4 px-8 text-center">
           <h3 className="text-xl font-black text-gray-800 uppercase tracking-tight">
            {bale ? 'Edit Batch' : 'New Batch'}
           </h3>
           <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">Stock Inventory Management</p>
        </div>

        <div className="p-6 space-y-4">
          {/* Name */}
          <div className="bg-gray-50 rounded-2xl px-4 py-2 border-2 border-transparent focus-within:border-pawPinkDark transition-all">
             <label className="text-[9px] font-black text-gray-400 uppercase tracking-wider block">Batch Name</label>
             <input 
               autoFocus 
               value={formData.name} 
               placeholder="Batch Title" 
               onChange={(e) => setFormData({...formData, name: e.target.value})} 
               className="w-full bg-transparent font-black text-gray-800 text-lg outline-none placeholder:text-gray-300" 
             />
          </div>

          <div className="flex gap-3">
             {/* Cost */}
             <div className="flex-1 bg-gray-50 rounded-2xl px-4 py-2 border-2 border-transparent focus-within:border-pawPinkDark transition-all">
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-wider block">Capital (₱)</label>
                <input 
                  type="number" 
                  value={formData.cost === 0 ? '' : formData.cost} 
                  placeholder="0" 
                  onChange={(e) => setFormData({...formData, cost: Number(e.target.value)})} 
                  className="w-full bg-transparent font-black text-gray-800 text-lg outline-none placeholder:text-gray-300" 
                />
             </div>
             {/* Items */}
             <div className="flex-1 bg-gray-50 rounded-2xl px-4 py-2 border-2 border-transparent focus-within:border-pawPinkDark transition-all">
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-wider block">Items</label>
                <input 
                  type="number" 
                  value={formData.itemCount === 0 ? '' : formData.itemCount} 
                  placeholder="0" 
                  onChange={(e) => setFormData({...formData, itemCount: Number(e.target.value)})} 
                  className="w-full bg-transparent font-black text-gray-800 text-lg outline-none placeholder:text-gray-300" 
                />
             </div>
          </div>

          {/* Unit Cost Display */}
          <div className="flex justify-between items-center px-4 py-3 bg-pawSoftBlue/30 rounded-2xl border border-blue-100">
             <span className="text-[10px] font-black text-blue-800 uppercase tracking-widest">Est. Unit Cost</span>
             <span className="font-black text-blue-900 text-lg">₱{unitCost.toFixed(2)}</span>
          </div>

          {/* Status Selection */}
           <div className="flex gap-2 justify-center py-2 flex-wrap">
             {['Ordered', 'Arrived', 'On Sale', 'Sold Out'].map(s => (
                <button
                  key={s}
                  onClick={() => setFormData({...formData, status: s as any})}
                  className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-wider border transition-all ${
                     formData.status === s 
                       ? 'bg-gray-800 text-white border-gray-800' 
                       : 'bg-white text-gray-400 border-gray-200 hover:border-gray-400'
                  }`}
                >
                  {s}
                </button>
             ))}
          </div>

          <div className="flex gap-3 pt-2">
            <button onClick={onClose} className="flex-1 py-3 bg-white border-2 border-gray-100 text-gray-400 font-black rounded-2xl uppercase text-[10px] tracking-widest hover:bg-gray-50">Cancel</button>
            <button onClick={() => onSave(formData)} className="flex-1 py-3 bg-pawPinkDark text-white font-black rounded-2xl shadow-lg uppercase text-[10px] tracking-widest hover:bg-red-400">Save Batch</button>
          </div>
        </div>
      </div>
    </div>, document.body
  );
};

export default Bales;

import React, { useState, useEffect } from 'react';
import { useSettings } from '../services/SettingsContext';
import { HomeIcon, CartIcon, PlusIcon, SearchIcon, UserIcon, PawIcon, CogIcon, MenuIcon, ChartIcon, BoxIcon } from './Icons';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  onTabChange: (tab: string) => void;
}

const Layout: React.FC<LayoutProps> = ({ children, activeTab, onTabChange }) => {
  const { logoUrl } = useSettings();
  const [logoError, setLogoError] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Fallback logo path
  const displayLogo = logoUrl || './logo.png';

  // Reset error state when logo changes so we try to load the new one
  useEffect(() => {
    setLogoError(false);
  }, [logoUrl]);

  // Handle mobile nav click
  const handleMobileNavClick = (tab: string) => {
    onTabChange(tab);
    setIsMobileMenuOpen(false);
  };

  return (
    <div className="flex flex-col min-h-screen pb-24 lg:pb-0 lg:pl-64">
      {/* Sidebar for Desktop */}
      <aside className="hidden lg:flex flex-col w-64 fixed left-0 top-0 bottom-0 bg-white border-r border-pawPink shadow-sm z-50">
        <div className="p-6 flex justify-center items-center min-h-[80px]">
          {!logoError ? (
            <img 
              src={displayLogo} 
              alt="Pawshionista" 
              className="w-40 h-auto object-contain transition-transform hover:scale-105 cursor-pointer"
              onClick={() => onTabChange('dashboard')}
              onError={() => setLogoError(true)} 
            />
          ) : (
            <div className="flex items-center gap-2 cursor-pointer" onClick={() => onTabChange('dashboard')}>
              <PawIcon className="w-8 h-8 text-pawPinkDark" />
              <h1 className="text-xl font-bold text-gray-800 tracking-tight">Pawshionista</h1>
            </div>
          )}
        </div>

        <nav className="flex-1 px-4 py-2 space-y-1 overflow-y-auto custom-scrollbar">
          <NavItem active={activeTab === 'dashboard'} onClick={() => onTabChange('dashboard')} icon={<HomeIcon />} label="Dashboard" />
          <NavItem active={activeTab === 'livesell'} onClick={() => onTabChange('livesell')} icon={<PlusIcon />} label="Live Mode" />
          <NavItem active={activeTab === 'orders'} onClick={() => onTabChange('orders')} icon={<CartIcon />} label="Orders" />

          {/* Swapped Inventory & Bales */}
          <NavItem active={activeTab === 'inventory'} onClick={() => onTabChange('inventory')} icon={<BoxIcon />} label="Bales" />
          <NavItem active={activeTab === 'bales'} onClick={() => onTabChange('bales')} icon={<SearchIcon />} label="Inventory" />

          <NavItem active={activeTab === 'customers'} onClick={() => onTabChange('customers')} icon={<UserIcon />} label="Customers" />
          <NavItem active={activeTab === 'accounting'} onClick={() => onTabChange('accounting')} icon={<ChartIcon />} label="Accounting" />
        </nav>

        <div className="p-4 border-t border-pawPink/20">
           <NavItem active={activeTab === 'settings'} onClick={() => onTabChange('settings')} icon={<CogIcon />} label="Settings" />
        </div>
      </aside>

      {/* Mobile Header (Sticky Top) */}
      <header className="lg:hidden bg-white/90 backdrop-blur-md sticky top-0 z-40 border-b border-pawPink/30 px-4 py-3 flex justify-center shadow-sm">
         {!logoError ? (
            <img 
              src={displayLogo} 
              alt="Pawshionista" 
              className="h-8 w-auto object-contain cursor-pointer"
              onClick={() => handleMobileNavClick('dashboard')}
              onError={() => setLogoError(true)} 
            />
          ) : (
            <div className="flex items-center gap-2 cursor-pointer" onClick={() => handleMobileNavClick('dashboard')}>
              <PawIcon className="w-6 h-6 text-pawPinkDark" />
              <h1 className="text-lg font-bold text-gray-800 tracking-tight">Pawshionista</h1>
            </div>
          )}
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-7xl mx-auto w-full px-4 pt-6 md:px-8">
        {children}
      </main>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div 
          className="lg:hidden fixed inset-0 z-[60] bg-black/40 backdrop-blur-sm animate-fadeIn"
          onClick={() => setIsMobileMenuOpen(false)}
        >
          <div 
            className="absolute bottom-24 right-4 w-56 bg-white rounded-3xl shadow-2xl p-3 animate-scaleUp flex flex-col gap-1 border border-pawPink/30"
            onClick={(e) => e.stopPropagation()} // Prevent closing when clicking inside menu
          >
             <p className="px-4 py-2 text-[10px] font-black text-gray-400 uppercase tracking-widest">More Options</p>
             <MobileMenuLink active={activeTab === 'customers'} onClick={() => handleMobileNavClick('customers')} icon={<UserIcon />} label="Customers" />

             {/* Bales tab (now Inventory in menu) */}
             <MobileMenuLink active={activeTab === 'bales'} onClick={() => handleMobileNavClick('bales')} icon={<SearchIcon />} label="Inventory" />

             <MobileMenuLink active={activeTab === 'accounting'} onClick={() => handleMobileNavClick('accounting')} icon={<ChartIcon />} label="Accounting" />
