import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { Bale } from '../types';
import { PlusIcon, PawIcon } from '../components/Icons';

const Inventory: React.FC = () => {
  const [bales, setBales] = useState(db.getBales());
  const products = db.getProducts();
  const orders = db.getOrders();
  const [showModal, setShowModal] = useState(false);
  const [editingBale, setEditingBale] = useState<Bale | null>(null);

  const getBaleStats = (baleId: string, cost: number) => {
    const baleProductIds = products.filter(p => p.baleBatch === baleId).map(p => p.id);
    const baleOrders = orders.filter(o => baleProductIds.includes(o.productId));
    const soldCount = baleOrders.reduce((sum, o) => sum + o.quantity, 0);
    const revenue = baleOrders.reduce((sum, o) => sum + o.totalPrice, 0);
    return { soldCount, revenue, isProfitable: revenue >= cost };
  };

  const handleSaveBale = (bale: Bale) => {
    db.updateBale(bale);
    setBales(db.getBales());
    setShowModal(false);
    setEditingBale(null);
  };

  return (
    <div className="space-y-6 pb-32 px-1 animate-fadeIn">
      <div className="flex items-center justify-between px-2">
        <div>
          <h1 className="text-3xl font-black text-gray-800 tracking-tight">Bales & Stock</h1>
          <p className="text-gray-500 font-bold text-sm">Monitor available items and dispersed stock.</p>
        </div>
        <button onClick={() => { setEditingBale(null); setShowModal(true); }} className="bg-pawPinkDark text-white w-14 h-14 rounded-full shadow-2xl flex items-center justify-center transition-all active:scale-90 hover:bg-red-400">
          <PlusIcon className="w-6 h-6" />
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 px-2">
        {bales.map(bale => {
          const stats = getBaleStats(bale.id, bale.cost);
          const remaining = Math.max(0, bale.itemCount - stats.soldCount);
          const percentSold = bale.itemCount > 0 ? (stats.soldCount / bale.itemCount) * 100 : 0;
          const unitCost = bale.itemCount > 0 ? (bale.cost / bale.itemCount) : 0;

          return (
            <button key={bale.id} onClick={() => { setEditingBale(bale); setShowModal(true); }} className="bg-white rounded-[2.5rem] p-7 border-2 border-pawPink/30 hover:border-pawPinkDark shadow-sm hover:shadow-xl group text-left relative overflow-hidden transition-all active:scale-95 w-full">
              <div className="mb-4 relative z-10">
                <div className="flex justify-between items-start mb-2">
                   <span className="text-[10px] font-black uppercase text-pawPinkDark bg-pawPink/20 px-3 py-1 rounded-full tracking-widest">{bale.id}</span>
                   {stats.isProfitable && (
                     <span className="text-[10px] font-black uppercase text-green-700 bg-green-100 px-3 py-1 rounded-full tracking-widest shadow-sm">Profitable 💰</span>
                   )}
                </div>
                <h3 className="font-black text-gray-800 text-xl leading-none mb-1">{bale.name}</h3>
                <p className="text-[11px] font-bold text-gray-400 uppercase tracking-widest">{bale.status}</p>
              </div>

              <div className="bg-orange-50 px-4 py-3 rounded-2xl mb-4 border border-orange-100/50 flex justify-between items-center">
                 <p className="text-[9px] text-orange-600 font-black uppercase tracking-wider">Unit Cost (Capital)</p>
                 <p className="text-xl font-black text-orange-800">₱{unitCost.toFixed(2)}</p>
              </div>

              <div className="flex gap-4 relative z-10 mb-6">
                <div className="bg-pawSoftBlue px-4 py-3 rounded-2xl flex-1 text-center">
                  <p className="text-[9px] text-blue-600 font-black uppercase mb-1">Dispersed</p>
                  <p className="text-2xl font-black text-gray-800">{stats.soldCount}</p>
                </div>
                <div className="bg-pawLavender px-4 py-3 rounded-2xl flex-1 text-center">
                  <p className="text-[9px] text-purple-700 font-black uppercase mb-1">Remaining</p>
                  <p className="text-2xl font-black text-gray-800">{remaining}</p>
                </div>
              </div>

              <div className="relative z-10">
                 <div className="flex justify-between items-center mb-1 px-1">
                    <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Progress</span>
                    <span className={`text-[10px] font-black uppercase ${stats.isProfitable ? 'text-green-600' : 'text-pawPinkDark'}`}>
                       {percentSold.toFixed(1)}% Sold
                    </span>
                 </div>
                 <div className="w-full h-3 bg-gray-100 rounded-full overflow-hidden">
                    <div className={`h-full rounded-full transition-all duration-1000 ${stats.isProfitable ? 'bg-green-400' : 'bg-pawPinkDark'}`} style={{ width: `${percentSold}%` }}></div>
                 </div>
              </div>
            </button>
          );
        })}
      </div>

      {showModal && <BaleModal bale={editingBale} onClose={() => setShowModal(false)} onSave={handleSaveBale} />}
    </div>
  );
};

