interface HistoryGroup {
  sessionId: string;
  sessionName: string;
  date: number;
  totalItems: number;
  totalAmount: number;
  paymentStatus: PaymentStatus;
  items: string[];
}

const CustomerHistoryModal: React.FC<{ customer: Customer; onClose: () => void }> = ({ customer, onClose }) => {
  const orders = db.getOrders();
  const sessions = db.getSessions();

  const history = useMemo(() => {
     const userOrders = orders.filter(o => o.customerUsername === customer.username);

     // Group by Session ID to make it readable
     const groups: Record<string, HistoryGroup> = {};

     userOrders.forEach(order => {
        if (!groups[order.sessionId]) {
           const session = sessions.find(s => s.id === order.sessionId);
           const name = session ? session.name : (order.sessionId === 'OFF_LIVE' ? 'Manual Encoding' : 'Unknown Session');

           groups[order.sessionId] = {
              sessionId: order.sessionId,
              sessionName: name,
              date: order.createdAt,
              totalItems: 0,
              totalAmount: 0,
              paymentStatus: order.paymentStatus, // simplified assumption
              items: [] // List of product names if needed, but we'll stick to summary
           };
        }
        groups[order.sessionId].totalItems += order.quantity;
        groups[order.sessionId].totalAmount += order.totalPrice;
        // Keep latest date for sorting
        if (order.createdAt > groups[order.sessionId].date) {
            groups[order.sessionId].date = order.createdAt;
        }
        // If any item is Paid, reflect somewhat in UI, but this is an aggregation. 
        // Better logic: if user orders filter logic in Orders.tsx is usually granular.
     });

     return Object.values(groups).sort((a, b) => b.date - a.date);
  }, [customer, orders, sessions]);

  return createPortal(
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-fadeIn">
      <div className="bg-white w-full max-w-lg rounded-[2.5rem] overflow-hidden shadow-2xl animate-scaleUp flex flex-col max-h-[85vh]">
        <div className="bg-pawSoftBlue p-8 shrink-0 relative">
           <button onClick={onClose} className="absolute top-6 right-6 bg-white/50 hover:bg-white text-blue-900 w-10 h-10 rounded-full font-black flex items-center justify-center transition-all">✕</button>

           <div className="flex items-center gap-4 mb-2">
             <div className="w-14 h-14 rounded-full bg-white text-blue-600 flex items-center justify-center font-black text-xl shadow-sm">
                {customer.username.charAt(0).toUpperCase()}
             </div>
             <div>
                <h3 className="text-xl font-black text-blue-950 uppercase tracking-tight">Purchase History</h3>
                <p className="text-blue-800 font-bold">@{customer.username}</p>
             </div>
           </div>

           <div className="flex gap-4 mt-6">
              <div className="bg-white/60 rounded-xl p-3 flex-1">
                 <p className="text-[9px] font-black text-blue-900 uppercase tracking-widest">Lifetime Spend</p>
                 <p className="text-lg font-black text-blue-950">₱{customer.totalSpent.toLocaleString()}</p>
              </div>
              <div className="bg-white/60 rounded-xl p-3 flex-1">
                 <p className="text-[9px] font-black text-blue-900 uppercase tracking-widest">Total Orders</p>
                 <p className="text-lg font-black text-blue-950">{customer.orderCount}</p>
              </div>
           </div>
        </div>

        <div className="p-6 overflow-y-auto custom-scrollbar space-y-3">
           {history.length === 0 ? (
              <div className="text-center py-10 opacity-50">
                 <p className="font-bold text-gray-400 text-xs uppercase tracking-widest">No history recorded</p>
              </div>
           ) : history.map((session) => (
              <div key={session.sessionId} className="bg-white border-2 border-gray-100 p-5 rounded-[2rem] hover:border-pawPink transition-all group">
                 <div className="flex justify-between items-start mb-2">
                    <div>
                       <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">
                         {new Date(session.date).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' })}
                       </p>
                       <h4 className="font-black text-gray-800 text-lg leading-tight group-hover:text-pawPinkDark transition-colors">
                          {session.sessionName}
                       </h4>
                    </div>
                    <span className="bg-gray-50 text-gray-500 text-[10px] font-black px-2 py-1 rounded-lg uppercase">
                       {session.totalItems} Items
                    </span>
                 </div>

                 <div className="flex justify-between items-end mt-4 pt-3 border-t border-dashed border-gray-100">
                    <span className="text-[10px] font-black text-gray-300 uppercase tracking-widest">Total Amount</span>
                    <span className="text-xl font-black text-gray-800">₱{session.totalAmount.toLocaleString()}</span>
                 </div>
              </div>
           ))}
        </div>
      </div>
    </div>, document.body
  );
};

