       });

       transactions.filter(t => t.type === 'Expense').forEach(t => {
          const d = new Date(t.createdAt);
          if (d.getFullYear() === now.getFullYear()) {
             const mIdx = d.getMonth();
             dataPoints[mIdx].profit -= t.amount;
          }
       });
    }

    return dataPoints;
