                 <h3 className="text-lg font-black text-gray-800 tracking-tight">Financial Performance</h3>
              </div>

              <div className="flex gap-3 flex-wrap justify-end">
                  {/* Metric Toggle */}
                  <div className="flex bg-gray-50 p-1 rounded-xl border border-gray-100">
                    {(['Revenue', 'Profit', 'Combined'] as MetricFilter[]).map((m) => (
                      <button 
                        key={m} 
