                 {(metricFilter === 'Profit' || metricFilter === 'Combined') && (
                    <Bar dataKey="profit" name="Net Profit" fill="#A78BFA" radius={[4, 4, 0, 0]} barSize={20}>
                        {chartData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={entry.profit >= 0 ? '#8B5CF6' : '#F87171'} />
