            )) : <p className="text-center text-gray-400 py-10 font-bold text-xs uppercase">No active batches found.</p>}
          </div>
        </div>

      </div>
    </div>
  );
};

const StatCard = ({ label, value, color, textColor, subValue }: any) => (
