    const now = new Date();
    let dataPoints: any[] = [];

    if (chartFilter === 'Today') {
       // Hourly breakdown (00 - 23)
       dataPoints = Array.from({ length: 24 }, (_, i) => ({
          name: i === 0 ? '12MN' : i === 12 ? '12NN' : i > 12 ? `${i-12}PM` : `${i}AM`,
