             if (dataPoints[dayIdx]) {
                dataPoints[dayIdx].sales += o.totalPrice;
                dataPoints[dayIdx].profit += (o.totalPrice - itemCOGS);
             }
          }
       });

       transactions.filter(t => t.type === 'Expense').forEach(t => {
