           <div className="flex justify-center gap-6 mt-4">
              <button 
                onClick={() => handleToggle('Profit')}
                className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-widest transition-all ${
                  (metricMode === 'Profit' || metricMode === 'Combined') ? 'opacity-100' : 'opacity-40 grayscale'
                }`}
              >
                 <span className="w-3 h-3 rounded-full bg-[#8B5CF6]"></span>
                 Net Profit
              </button>

              <button 
                onClick={() => handleToggle('Revenue')}
                className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-widest transition-all ${
                  (metricMode === 'Revenue' || metricMode === 'Combined') ? 'opacity-100' : 'opacity-40 grayscale'
                }`}
              >
                 <span className="w-3 h-3 rounded-full bg-[#FFB7C5]"></span>
                 Revenue
              </button>
           </div>
        </div>

        {/* Stock Dispersal - Sidebar */}
        <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-pawPink/40">
          <h3 className="text-lg font-black mb-4 text-gray-800 tracking-tight flex items-center gap-2">
             <BoxIcon className="w-5 h-5 text-gray-400"/>
             Stock Dispersal
          </h3>
          <div className="space-y-4 max-h-[300px] overflow-y-auto custom-scrollbar pr-2">
            {activeBales.length > 0 ? activeBales.map(b => (
              <div key={b.id} className="p-4 bg-pawCream/50 rounded-2xl relative overflow-hidden group border border-transparent hover:border-pawPink transition-all">
                <div className="flex justify-between items-center mb-2">
                   <div>
                     <span className="text-[9px] font-black uppercase bg-white text-gray-500 px-2 py-0.5 rounded mr-2 border border-gray-100">{b.status}</span>
                     <h4 className="font-bold text-gray-800 text-sm inline-block">{b.name}</h4>
                   </div>
                   <div className="text-right">
                      <span className="block text-xl font-black text-gray-800">{b.remaining}</span>
