           >
             <PlusIcon className="w-8 h-8" />
           </button>
        </div>

        {/* Inventory tab (now Bales in bottom nav) */}
        <MobileNavItem active={activeTab === 'inventory'} onClick={() => handleMobileNavClick('inventory')} icon={<BoxIcon />} />

        {/* More/Menu Button */}
        <MobileNavItem 
          active={['customers', 'bales', 'accounting', 'settings', 'reports'].includes(activeTab) || isMobileMenuOpen} 
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)} 
          icon={<MenuIcon />} 
        />
