                  className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-wider border transition-all ${
                     formData.status === s 
                       ? 'bg-gray-800 dark:bg-gray-600 text-white border-gray-800 dark:border-gray-600' 
                       : 'bg-white dark:bg-gray-700 text-gray-400 dark:text-gray-400 border-gray-200 dark:border-gray-600 hover:border-gray-400'
                  }`}
