          <div className="flex gap-3 pt-2">
            <button onClick={onClose} className="flex-1 py-3 bg-white dark:bg-gray-700 border-2 border-gray-100 dark:border-gray-600 text-gray-400 dark:text-gray-300 font-black rounded-2xl uppercase text-[10px] tracking-widest hover:bg-gray-50 dark:hover:bg-gray-600">Cancel</button>
