          <div className="flex gap-3 pt-4">
            <button onClick={onClose} className="flex-1 py-4 bg-white dark:bg-gray-700 border-2 border-gray-100 dark:border-gray-600 text-gray-400 dark:text-gray-300 font-black rounded-2xl uppercase text-[10px] tracking-widest hover:bg-gray-50 dark:hover:bg-gray-600">Cancel</button>
            <button onClick={() => onSave(formData)} className="flex-1 py-4 bg-pawPinkDark text-white font-black rounded-2xl shadow-lg uppercase text-[10px] tracking-widest hover:bg-red-400">Save Batch</button>
          </div>
