    </div>, document.body
  );
};

export default Bales;

import { Product, Order, Customer, LiveSession, Bale, Transaction, PaymentStatus, ShippingStatus } from '../types';
import { INITIAL_PRODUCTS, INITIAL_BALES, INITIAL_CUSTOMERS } from '../db/mockData';

const STORAGE_KEYS = {
  PRODUCTS: 'paw_products',
  ORDERS: 'paw_orders',
  CUSTOMERS: 'paw_customers',
  SESSIONS: 'paw_sessions',
  BALES: 'paw_bales',
  TRANSACTIONS: 'paw_transactions',
  CATEGORIES: 'paw_categories',
  SETTINGS: 'paw_settings',
};

class DBService {
  private get<T>(key: string, defaultValue: T): T {
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : defaultValue;
  }

  private set<T>(key: string, data: T): void {
    localStorage.setItem(key, JSON.stringify(data));
  }

  // --- Settings (Logo & Dark Mode) ---
  getSettings(): { logoUrl: string | null; isDarkMode: boolean } {
    return this.get(STORAGE_KEYS.SETTINGS, { logoUrl: null, isDarkMode: false });
  }

  updateSettings(settings: Partial<{ logoUrl: string | null; isDarkMode: boolean }>): void {
    const current = this.getSettings();
    this.set(STORAGE_KEYS.SETTINGS, { ...current, ...settings });
  }

  // --- Products ---
  getProducts(): Product[] {
    return this.get(STORAGE_KEYS.PRODUCTS, INITIAL_PRODUCTS);
  }
  updateProduct(product: Product): void {
    const products = this.getProducts();
    const index = products.findIndex(p => p.id === product.id);
    if (index > -1) {
      products[index] = product;
    } else {
      products.push(product);
    }
    this.set(STORAGE_KEYS.PRODUCTS, products);
  }
  deleteProduct(id: string): void {
    const products = this.getProducts().filter(p => p.id !== id);
    this.set(STORAGE_KEYS.PRODUCTS, products);
  }

  // --- Orders ---
  getOrders(): Order[] {
    return this.get(STORAGE_KEYS.ORDERS, []);
  }

  addOrder(order: Order): void {
    const orders = this.getOrders();
    orders.push(order);
    this.set(STORAGE_KEYS.ORDERS, orders);

    // Update product stock
    let baleIdToUpdate: string | null = null;

    if (!order.isFreebie) {
      const products = this.getProducts();
      const pIndex = products.findIndex(p => p.id === order.productId);
      if (pIndex > -1) {
        products[pIndex].stock -= order.quantity;
        this.set(STORAGE_KEYS.PRODUCTS, products);
        baleIdToUpdate = products[pIndex].baleBatch;
      }
    } else {
       // Even if freebie, we might want to check which bale it came from to update stats
       const products = this.getProducts();
       const product = products.find(p => p.id === order.productId);
       if (product) baleIdToUpdate = product.baleBatch;
    }

    // Update customer stats
    const customer = this.getOrCreateCustomer(order.customerUsername);
    customer.orderCount += 1;
    customer.totalSpent += order.totalPrice;
    this.updateCustomer(customer);

    // Auto-update Bale Status (On Sale / Sold Out)
    if (baleIdToUpdate) {
      this.refreshBaleStatus(baleIdToUpdate);
    }
  }

  updateOrder(order: Order): void {
    const orders = this.getOrders();
    const index = orders.findIndex(o => o.id === order.id);
    if (index > -1) {
      const oldOrder = orders[index];
      let baleIdToUpdate: string | null = null;

      // Handle stock return on cancel/RTS
      if ((order.shippingStatus === ShippingStatus.CANCELLED || order.shippingStatus === ShippingStatus.RTS) && 
          (oldOrder.shippingStatus !== ShippingStatus.CANCELLED && oldOrder.shippingStatus !== ShippingStatus.RTS)) {
        const products = this.getProducts();
        const pIndex = products.findIndex(p => p.id === order.productId);
        if (pIndex > -1) {
          products[pIndex].stock += order.quantity;
          this.set(STORAGE_KEYS.PRODUCTS, products);
          baleIdToUpdate = products[pIndex].baleBatch;
        }
      }

      orders[index] = order;
      this.set(STORAGE_KEYS.ORDERS, orders);

      // Trigger status refresh if stock changed via cancellation
      if (baleIdToUpdate) {
        this.refreshBaleStatus(baleIdToUpdate);
      }
    }
  }

  deleteOrder(id: string): void {
    const orders = this.getOrders();
    const order = orders.find(o => o.id === id);
    let baleIdToUpdate: string | null = null;

    if (order) {
       const products = this.getProducts();
       const product = products.find(p => p.id === order.productId);
       if (product) baleIdToUpdate = product.baleBatch;
    }

    const newOrders = orders.filter(o => o.id !== id);
    this.set(STORAGE_KEYS.ORDERS, newOrders);

    if (baleIdToUpdate) {
      this.refreshBaleStatus(baleIdToUpdate);
    }
  }

  // --- Customers ---
  getCustomers(): Customer[] {
    return this.get(STORAGE_KEYS.CUSTOMERS, INITIAL_CUSTOMERS);
  }
  updateCustomer(customer: Customer): void {
    const customers = this.getCustomers();
    const index = customers.findIndex(c => c.id === customer.id);
    if (index > -1) {
      customers[index] = customer;
      this.set(STORAGE_KEYS.CUSTOMERS, customers);
    }
  }
  getOrCreateCustomer(username: string): Customer {
    const customers = this.getCustomers();
    let customer = customers.find(c => c.username === username);
    if (!customer) {
      customer = {
        id: `c_${Date.now()}`,
        username,
        isVIP: false,
        vipTickets: 0,
        isBlacklisted: false,
        totalSpent: 0,
        orderCount: 0
      };
      customers.push(customer);
      this.set(STORAGE_KEYS.CUSTOMERS, customers);
    }
    // Ensure legacy customers have vipTickets field
    if (customer.vipTickets === undefined) {
        customer.vipTickets = 0;
        this.updateCustomer(customer);
    }
    return customer;
  }

  // --- Sessions ---
  getSessions(): LiveSession[] {
    return this.get(STORAGE_KEYS.SESSIONS, []);
  }
  createSession(name: string): LiveSession {
    const session: LiveSession = {
      id: `s_${Date.now()}`,
      name,
      // Use local date string instead of ISO to ensure "Today" matches user's timezone (e.g. GMT+8)
      date: new Date().toLocaleDateString('en-US'),
      totalSales: 0,
      totalOrders: 0,
      isOpen: true
    };
    const sessions = this.getSessions();
    sessions.push(session);
    this.set(STORAGE_KEYS.SESSIONS, sessions);
    return session;
  }
  closeSession(id: string): void {
    const sessions = this.getSessions();
    const idx = sessions.findIndex(s => s.id === id);
    if (idx > -1) {
      sessions[idx].isOpen = false;
      this.set(STORAGE_KEYS.SESSIONS, sessions);
    }
  }

  // --- Accounting ---
  getTransactions(): Transaction[] {
    return this.get(STORAGE_KEYS.TRANSACTIONS, []);
  }
  addTransaction(tx: Transaction): void {
    const txs = this.getTransactions();
    txs.push(tx);
    this.set(STORAGE_KEYS.TRANSACTIONS, txs);
  }

  // --- Categories ---
  getExpenseCategories(): string[] {
    const stored = this.get(STORAGE_KEYS.CATEGORIES, [
      'Inventory Restock', 
      'Shipping Fee', 
      'Packaging', 
      'Rent', 
      'Utilities', 
      'Salary', 
      'Personal Withdrawal', 
      'Loan',
      'Capital',
      'Miscellaneous'
    ]);

    // Also scan transactions for any custom categories used that aren't in stored list
    const transactions = this.getTransactions();
    const usedCategories = new Set(transactions.map(t => t.category));

    // Merge and Deduplicate
    const combined = Array.from(new Set([...stored, ...usedCategories])).filter(c => c && c.trim() !== '');
    return combined.sort();
  }

  addExpenseCategory(category: string): void {
    const categories = this.getExpenseCategories();
    // Case insensitive check could be better, but simple exact match for now
    if (!categories.includes(category) && category.trim() !== '') {
      categories.push(category);
      this.set(STORAGE_KEYS.CATEGORIES, categories.sort());
    }
  }

  // --- Bales ---
  getBales(): Bale[] {
    return this.get(STORAGE_KEYS.BALES, INITIAL_BALES);
  }
  updateBale(bale: Bale): void {
    const bales = this.getBales();
    const index = bales.findIndex(b => b.id === bale.id);
    if (index > -1) {
      bales[index] = bale;
    } else {
      bales.push(bale);
    }
    this.set(STORAGE_KEYS.BALES, bales);
  }
  deleteBale(id: string): void {
    const bales = this.getBales().filter(b => b.id !== id);
    this.set(STORAGE_KEYS.BALES, bales);
  }

  // --- Helper: Auto Status Update ---
  private refreshBaleStatus(baleId: string): void {
    const bales = this.getBales();
    const index = bales.findIndex(b => b.id === baleId);
    if (index === -1) return;

    const bale = bales[index];

    // Calculate stats
    const products = this.getProducts();
    const baleProductIds = products.filter(p => p.baleBatch === baleId).map(p => p.id);
    const orders = this.getOrders();
    const soldCount = orders
      .filter(o => baleProductIds.includes(o.productId) && o.shippingStatus !== ShippingStatus.CANCELLED)
      .reduce((sum, o) => sum + o.quantity, 0);

    let newStatus = bale.status;

    // Logic 1: Auto "Sold Out" if fully depleted
    if (soldCount >= bale.itemCount && bale.itemCount > 0) {
      newStatus = 'Sold Out';
    } 
    // Logic 2: Auto "On Sale" if sales started (and not sold out)
    // Applies if current status is 'Ordered' or 'Arrived', OR if it was 'Sold Out' but stock returned
    else if (soldCount > 0 && soldCount < bale.itemCount) {
      if (bale.status === 'Ordered' || bale.status === 'Arrived' || bale.status === 'Sold Out') {
        newStatus = 'On Sale';
      }
    }

    if (newStatus !== bale.status) {
      bales[index].status = newStatus;
      this.set(STORAGE_KEYS.BALES, bales);
    }
  }
}

export const db = new DBService();

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { db } from '../services/dbService';
import { Bale, PaymentStatus, ShippingStatus } from '../types';
import { PlusIcon, PawIcon, SearchIcon } from '../components/Icons';

const Inventory: React.FC = () => {
  const [bales, setBales] = useState(db.getBales());
  const [filterStatus, setFilterStatus] = useState<'Active' | 'Completed'>('Active');
  const [searchQuery, setSearchQuery] = useState('');

  const products = db.getProducts();
  const orders = db.getOrders();
  const [showModal, setShowModal] = useState(false);
  const [editingBale, setEditingBale] = useState<Bale | null>(null);

  const getBaleStats = (baleId: string, cost: number) => {
    const baleProductIds = products.filter(p => p.baleBatch === baleId).map(p => p.id);
    const baleOrders = orders.filter(o => baleProductIds.includes(o.productId));
    const soldCount = baleOrders.reduce((sum, o) => sum + o.quantity, 0);
    const revenue = baleOrders.reduce((sum, o) => sum + o.totalPrice, 0);
    return { soldCount, revenue, isProfitable: revenue >= cost };
  };

  const handleSaveBale = (bale: Bale) => {
    db.updateBale(bale);
    setBales(db.getBales());
    setShowModal(false);
    setEditingBale(null);
  };

  const isBaleFullyPaid = (baleId: string) => {
    const baleProductIds = products.filter(p => p.baleBatch === baleId).map(p => p.id);
    const baleOrders = orders.filter(o => baleProductIds.includes(o.productId) && o.shippingStatus !== ShippingStatus.CANCELLED);

    // If no sales yet, it's technically "paid" (no debt), but status won't be Sold Out usually.
    if (baleOrders.length === 0) return true;

    return baleOrders.every(o => o.paymentStatus === PaymentStatus.PAID);
  };

  const filteredBales = bales.filter(b => {
    const fullyPaid = isBaleFullyPaid(b.id);
    let matchesStatus = false;

    if (filterStatus === 'Active') {
        // Show if NOT Sold Out OR (Sold Out but still has Unpaid orders)
        matchesStatus = b.status !== 'Sold Out' || !fullyPaid;
    } else {
        // Show only if Sold Out AND Fully Paid
        matchesStatus = b.status === 'Sold Out' && fullyPaid;
    }

    const matchesSearch = b.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          b.id.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesStatus && matchesSearch;
  });

  return (
    <div className="space-y-6 pb-32 px-1 animate-fadeIn">
      <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-4 px-2">
        <div>
          <h1 className="text-3xl font-black text-gray-800 dark:text-white tracking-tight">Bales & Stock</h1>
          <p className="text-gray-500 dark:text-gray-400 font-bold text-sm">Monitor available items and dispersed stock.</p>
        </div>

        <div className="flex flex-col md:flex-row gap-3">
           {/* Search Bar */}
           <div className="relative w-full md:w-64">
              <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
              <input 
                type="text" 
                placeholder="Search batch..." 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-white dark:bg-gray-800 pl-10 pr-4 py-3 rounded-2xl font-bold text-sm text-gray-800 dark:text-white outline-none focus:ring-2 focus:ring-pawPink shadow-sm border-2 border-transparent focus:border-pawPink transition-all"
              />
           </div>

           <div className="flex items-center gap-3">
             {/* Filter Toggle */}
             <div className="bg-gray-100 dark:bg-gray-700 p-1.5 rounded-2xl flex items-center shadow-inner flex-1 md:flex-none">
                <button 
                  onClick={() => setFilterStatus('Active')}
                  className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${filterStatus === 'Active' ? 'bg-white dark:bg-gray-600 text-pawPinkDark shadow-sm' : 'text-gray-400 dark:text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'}`}
                >
                  Active
                </button>
                <button 
                  onClick={() => setFilterStatus('Completed')}
                  className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${filterStatus === 'Completed' ? 'bg-white dark:bg-gray-600 text-pawPinkDark shadow-sm' : 'text-gray-400 dark:text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'}`}
                >
                  Completed
                </button>
             </div>

             <button onClick={() => { setEditingBale(null); setShowModal(true); }} className="bg-pawPinkDark text-white w-14 h-14 rounded-full shadow-2xl flex items-center justify-center transition-all active:scale-90 hover:bg-red-400 shrink-0">
               <PlusIcon className="w-6 h-6" />
             </button>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 px-2">
        {filteredBales.length === 0 ? (
           <div className="col-span-full py-20 text-center opacity-50">
              <p className="text-4xl mb-2">📦</p>
              <p className="text-sm font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest">
