       if (curr.id.startsWith('B')) {
           const num = parseInt(curr.id.substring(1));
           return !isNaN(num) && num > acc ? num : acc;
       }
       return acc;
    }, 0);
    return `B${String(max + 1).padStart(3, '0')}`;
