               <button 
                  onClick={handleCopyInvoice} 
                  disabled={cart.length === 0}
                  className="w-full py-4 rounded-[2.5rem] bg-gray-100 dark:bg-gray-600 text-gray-600 dark:text-gray-200 font-black uppercase text-xs tracking-widest hover:bg-gray-200 dark:hover:bg-gray-500 transition-all active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
               >
                  📋 Copy Invoice
               </button>
               <button onClick={handleCheckout} disabled={cart.length === 0 || !username} className={`w-full py-7 rounded-[2.5rem] font-black uppercase text-sm tracking-widest transition-all shrink-0 ${cart.length === 0 || !username ? 'bg-gray-200 dark:bg-gray-700 text-gray-400 dark:text-gray-500 cursor-not-allowed border-2 border-gray-100 dark:border-gray-600' : 'bg-pawPinkDark text-white hover:bg-red-400 shadow-2xl shadow-pawPinkDark/40 active:scale-95'}`}>
                  {feedback || 'Finalize Transaction'}
               </button>
            </div>
         </div>
      </div>

      {showStartModal && <StartSessionModal onClose={() => setShowStartModal(false)} onStart={handleCreateSession} />}
      {showScheduleModal && <ScheduleModal onClose={() => setShowScheduleModal(false)} onSet={setScheduledTime} />}
      {oosModalData && <OutOfStockModal data={oosModalData} onClose={() => setOosModalData(null)} />}

      {showSessionOrders && (
        <SessionOrdersModal 
          sessionId={session.id} 
          onClose={() => setShowSessionOrders(false)} 
          onEdit={handleEditCustomer}
        />
      )}

      {showEndConfirmation && (
         <EndSessionModal 
            onClose={() => setShowEndConfirmation(false)} 
            onConfirm={confirmEndSession} 
            isManual={session.id === OFF_LIVE_ID}
         />
      )}

      {finishedSessionData && (
         <SessionSummaryModal 
            data={finishedSessionData}
            onClose={finalizeSessionClose}
         />
      )}
    </div>
  );
};

