                        }`}
                      >
                         {useVipTicket ? '★ VIP Ticket Applied (-1)' : 'Use VIP Ticket'}
                     </button>

                     {useVipTicket && (
                        <div className="bg-yellow-50 dark:bg-yellow-900/20 rounded-xl p-3 border-2 border-yellow-100 dark:border-yellow-700 animate-scaleUp space-y-2">
