                    {group.isCustomerVIP && (
                      <span className="bg-yellow-100 dark:bg-yellow-900/30 text-yellow-700 dark:text-yellow-400 text-[9px] font-black px-2 py-0.5 rounded uppercase tracking-wider">VIP</span>
                    )}
                    <p className="text-[10px] font-black text-gray-400 dark:text-gray-500 uppercase bg-gray-50 dark:bg-gray-700 px-2 py-0.5 rounded">{group.items.length} items</p>
