                       <AreaChart data={analytics.sales.trend} margin={{top:10, right:10, left:-20, bottom:0}}>
                          <defs>
                             <linearGradient id="salesGradient" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#F472B6" stopOpacity={0.8}/>
