                       </AreaChart>
                    </ResponsiveContainer>
                 </div>
              </div>

              {/* Pie Chart */}
              <div className="bg-white dark:bg-gray-800 p-6 rounded-[2.5rem] shadow-sm border border-pawPink/20 dark:border-gray-700 h-[400px] flex flex-col">
