        {/* Right: Audit Log & Info */}
        <div className="w-full md:w-80 bg-gray-50 dark:bg-gray-900 border-l border-gray-100 dark:border-gray-700 p-6 flex flex-col">
            {/* Balance Card */}
            {remainingBalance > 0 && (
