            return (
              <div key={device.id} className={`bg-white dark:bg-gray-800 rounded-[2rem] p-6 border-2 shadow-sm transition-all ${device.status === 'blocked' ? 'opacity-70 border-gray-200 dark:border-gray-700' : device.status === 'pending' ? 'border-orange-200 dark:border-orange-800 bg-orange-50 dark:bg-orange-900/10' : 'border-pawPink/30 dark:border-gray-700'}`}>
                 <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
                    <div className="flex items-center gap-4">
                       <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-2xl shrink-0 ${device.type === 'Mobile' ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-500' : 'bg-purple-50 dark:bg-purple-900/30 text-purple-500'}`}>
                          {device.type === 'Mobile' ? <DevicePhoneIcon /> : <DeviceDesktopIcon />}
                       </div>

                       <div className="flex-1">
                          {editingId === device.id ? (
                             <div className="flex gap-2 mb-1">
                                <input 
                                  value={editName} 
                                  onChange={(e) => setEditName(e.target.value)} 
                                  className="bg-gray-100 dark:bg-gray-700 px-3 py-1 rounded-lg font-black text-gray-800 dark:text-white outline-none border border-pawPink"
                                  autoFocus
                                />
                                <button onClick={() => handleRename(device.id)} className="text-[10px] bg-pawPinkDark text-white px-3 rounded-lg font-bold uppercase">Save</button>
                             </div>
                          ) : (
                             <div className="flex items-center gap-2 mb-1">
                                <h3 className="text-lg font-black text-gray-800 dark:text-white leading-none">{device.name}</h3>
                                <button onClick={() => startEdit(device)} className="text-gray-300 hover:text-gray-500 dark:text-gray-600 dark:hover:text-gray-400">✏️</button>
                                {isCurrent && <span className="bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300 text-[9px] font-black px-2 py-0.5 rounded uppercase">This Device</span>}
                             </div>
                          )}

                          <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs font-bold text-gray-400 dark:text-gray-500">
                             <span className="flex items-center gap-1">🌐 {device.ip_address}</span>
                             <span className="flex items-center gap-1">📍 {device.location}</span>
                             <span className="flex items-center gap-1">💻 {device.os} ({device.browser})</span>
                          </div>
                          <p className="text-[10px] text-gray-300 dark:text-gray-600 mt-1 uppercase font-bold tracking-wider">Last Active: {new Date(device.last_active).toLocaleString()}</p>
                       </div>
                    </div>

                    <div className="flex items-center gap-3 w-full lg:w-auto">
                       {device.status === 'pending' && (
                          <div className="flex gap-2 w-full lg:w-auto">
                             <button onClick={() => handleStatusChange(device, 'blocked')} className="flex-1 lg:flex-none px-6 py-3 bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-300 rounded-xl font-black uppercase text-[10px] tracking-widest hover:bg-red-200 transition-colors">Block</button>
                             <button onClick={() => handleStatusChange(device, 'approved')} className="flex-1 lg:flex-none px-6 py-3 bg-green-500 text-white rounded-xl font-black uppercase text-[10px] tracking-widest shadow-lg hover:bg-green-600 transition-colors">Approve</button>
                          </div>
                       )}

                       {device.status === 'approved' && (
                          <button onClick={() => handleStatusChange(device, 'blocked')} className="w-full lg:w-auto px-6 py-3 bg-gray-100 dark:bg-gray-700 text-gray-400 dark:text-gray-400 hover:bg-red-100 hover:text-red-500 dark:hover:bg-red-900/30 dark:hover:text-red-300 rounded-xl font-black uppercase text-[10px] tracking-widest transition-colors">
                             Block Access
                          </button>
                       )}

                       {device.status === 'blocked' && (
                          <button onClick={() => handleStatusChange(device, 'approved')} className="w-full lg:w-auto px-6 py-3 bg-gray-100 dark:bg-gray-700 text-gray-400 dark:text-gray-400 hover:bg-green-100 hover:text-green-600 dark:hover:bg-green-900/30 dark:hover:text-green-300 rounded-xl font-black uppercase text-[10px] tracking-widest transition-colors">
                             Unblock
                          </button>
                       )}
                    </div>
                 </div>
              </div>
            );
        })}
      </div>
    </div>
  );
};

