import React, { useState, useEffect } from 'react';
import { useSettings } from './services/SettingsContext';
import { db } from './services/dbService';
import { deviceService } from './services/deviceService';
import { Device } from './types';
import Layout from './components/Layout';
import Dashboard from './views/Dashboard';
import LiveSell from './views/LiveSell';
import Orders from './views/Orders';
import Inventory from './views/Inventory';
import Customers from './views/Customers';
import Accounting from './views/Accounting';
import Bales from './views/Bales';
import Settings from './views/Settings';
import Reports from './views/Reports';
import DeviceManagement from './views/DeviceManagement';
import { PawIcon, ShieldIcon } from './components/Icons';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isLoading, setIsLoading] = useState(true);
  const [currentDevice, setCurrentDevice] = useState<Device | null>(null);
  const [checkStatus, setCheckStatus] = useState<'checking' | 'approved' | 'pending' | 'blocked' | 'error'>('checking');
  const [justApproved, setJustApproved] = useState(false);

  // Use hook to get logo and refresh capabilities
  const { logoUrl, refreshSettings } = useSettings();
  const displayLogo = logoUrl || './logo.png';

  // 1. Initial Check
  useEffect(() => {
    const initApp = async () => {
      const device = await deviceService.registerOrCheckDevice();
      setCurrentDevice(device);

      if (device) {
          if (device.status === 'approved') {
              setCheckStatus('approved');
              // Sync and then refresh settings context
              await db.syncWithSupabase();
              refreshSettings();
          } else if (device.status === 'blocked') {
              setCheckStatus('blocked');
          } else {
              setCheckStatus('pending');
          }
      } else {
          setCheckStatus('error');
      }
      setIsLoading(false);
    };
    initApp();
  }, [refreshSettings]);

  // 2. Polling for Approval (Auto-Refresh)
  useEffect(() => {
    let interval: any;

    if (checkStatus === 'pending') {
      interval = setInterval(async () => {
        const device = await deviceService.registerOrCheckDevice();
        if (device) {
          if (device.status === 'approved') {
            // Sync First, Then Refresh, Then Show Modal
            await db.syncWithSupabase();
            refreshSettings();

            setJustApproved(true); 
            setCheckStatus('approved');
            // Removed auto-timeout so user can click the button
          } else if (device.status === 'blocked') {
            setCheckStatus('blocked');
          }
        }
      }, 3000); // Check every 3 seconds
    }

    return () => clearInterval(interval);
  }, [checkStatus, refreshSettings]);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'livesell': return <LiveSell />;
      case 'orders': return <Orders />;
      case 'inventory': return <Inventory />;
      case 'customers': return <Customers />;
      case 'accounting': return <Accounting />;
      case 'bales': return <Bales />;
      case 'reports': return <Reports />;
      case 'devices': return <DeviceManagement />;
      case 'settings': return <Settings />;
      default: return <Dashboard />;
    }
  };

  // --- 1. ERROR STATE ---
  if (checkStatus === 'error') {
     return (
       <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex flex-col items-center justify-center p-6 text-center">
         <div className="bg-white dark:bg-gray-800 p-8 rounded-[3rem] shadow-2xl animate-scaleUp max-w-sm border-4 border-red-200">
            <div className="w-20 h-20 bg-red-50 rounded-full flex items-center justify-center mx-auto mb-6">
                <ShieldIcon className="w-10 h-10 text-red-400" />
            </div>
            <h1 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tight">System Error</h1>
            <p className="text-gray-500 dark:text-gray-400 font-bold text-sm mt-2">Could not verify device security.</p>
            <button onClick={() => window.location.reload()} className="w-full mt-6 py-4 bg-pawPinkDark hover:bg-red-400 text-white font-black uppercase text-xs tracking-widest rounded-2xl transition-all shadow-lg">
                Retry Connection
            </button>
         </div>
      </div>
     );
  }

  // --- 2. BLOCKED STATE ---
  if (checkStatus === 'blocked') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-6 text-center">
         <div className="bg-white p-8 rounded-[3rem] shadow-2xl animate-scaleUp max-w-sm border-4 border-red-500">
            <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-6 text-4xl">🚫</div>
            <h1 className="text-2xl font-black text-gray-900 uppercase tracking-tight">Access Denied</h1>
            <p className="text-gray-500 font-bold text-sm mt-2">This device has been blocked by the administrator.</p>
            <div className="mt-6 p-4 bg-gray-50 rounded-2xl text-xs font-mono break-all text-gray-400">
                ID: {currentDevice?.device_id}
            </div>
         </div>
      </div>
    );
  }

  // --- 3. PENDING STATE ---
  if (checkStatus === 'pending') {
    return (
      <div className="min-h-screen bg-pawPink dark:bg-gray-900 flex flex-col items-center justify-center p-6 text-center">
         <div className="bg-white dark:bg-gray-800 p-8 rounded-[3rem] shadow-2xl animate-scaleUp max-w-sm border-4 border-orange-300 relative overflow-hidden">
            {/* Loading Pulse */}
            <div className="absolute top-0 left-0 w-full h-1 bg-orange-100">
               <div className="h-full bg-orange-400 animate-[loading_2s_ease-in-out_infinite]"></div>
            </div>

            <div className="w-20 h-20 bg-orange-100 rounded-full flex items-center justify-center mx-auto mb-6">
                <ShieldIcon className="w-10 h-10 text-orange-500 animate-pulse" />
            </div>
            <h1 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Device Pending</h1>
            <p className="text-gray-500 dark:text-gray-400 font-bold text-sm mt-2">Waiting for admin approval...</p>
            <p className="text-xs text-orange-500 font-bold mt-1 animate-pulse">Auto-refreshing status...</p>

            <div className="mt-8 space-y-2 text-left bg-gray-50 dark:bg-gray-700 p-4 rounded-2xl">
                <div className="flex justify-between text-xs font-bold border-b border-gray-200 dark:border-gray-600 pb-2">
                    <span className="text-gray-400 uppercase">Device</span>
                    <span className="text-gray-800 dark:text-gray-200">{currentDevice?.name}</span>
                </div>
                <div className="flex justify-between text-xs font-bold border-b border-gray-200 dark:border-gray-600 pb-2 pt-2">
                    <span className="text-gray-400 uppercase">IP</span>
                    <span className="text-gray-800 dark:text-gray-200">{currentDevice?.ip_address}</span>
                </div>
                <div className="flex justify-between text-xs font-bold pt-2">
                    <span className="text-gray-400 uppercase">Location</span>
                    <span className="text-gray-800 dark:text-gray-200">{currentDevice?.location}</span>
                </div>
            </div>
         </div>
      </div>
    );
  }

  // --- 4. LOADING STATE ---
  if (isLoading) {
    return (
      <div className="min-h-screen bg-pawPink dark:bg-gray-900 flex flex-col items-center justify-center p-4 space-y-4">
         <div className="bg-white dark:bg-gray-800 p-8 rounded-[3rem] shadow-2xl animate-scaleUp flex flex-col items-center">
            <PawIcon className="w-20 h-20 text-pawPinkDark mb-4 animate-bounce" />
            <h1 className="text-2xl font-black text-gray-800 dark:text-white tracking-tight">Pawshionista</h1>
            <p className="text-gray-400 dark:text-gray-500 font-bold uppercase tracking-widest text-xs mt-2">Verifying Device...</p>
         </div>
      </div>
    );
  }

  // --- 5. APPROVED SUCCESS OVERLAY (CUTE VERSION) ---
  if (justApproved) {
     return (
       <div className="fixed inset-0 z-[999] bg-pawPink/90 backdrop-blur-md flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
          <div className="bg-white dark:bg-gray-800 p-10 rounded-[3.5rem] shadow-2xl animate-scaleUp max-w-sm w-full border-4 border-white dark:border-gray-700 relative overflow-hidden">

             {/* Cute Background Blobs */}
             <div className="absolute -top-10 -right-10 w-32 h-32 bg-pawPink rounded-full opacity-50 blur-2xl animate-pulse"></div>
             <div className="absolute -bottom-10 -left-10 w-32 h-32 bg-purple-200 rounded-full opacity-50 blur-2xl animate-pulse"></div>

             <div className="relative z-10 flex flex-col items-center">
                <div className="w-28 h-28 bg-white dark:bg-gray-700 rounded-full flex items-center justify-center mb-6 animate-bounce shadow-md p-4">
                    <img 
                      src={displayLogo} 
                      alt="Logo" 
                      className="w-full h-full object-contain" 
                      onError={(e) => {
                         e.currentTarget.style.display='none'; 
                         if (e.currentTarget.parentElement) e.currentTarget.parentElement.innerHTML='<span class="text-5xl">🐾</span>';
                      }} 
                    />
                </div>

                <h1 className="text-3xl font-black text-gray-800 dark:text-white uppercase tracking-tight mb-2">You're In!</h1>
                <p className="text-gray-500 dark:text-gray-400 font-bold text-sm mb-8">Device successfully connected.</p>

                <button 
                  onClick={() => setJustApproved(false)}
                  className="w-full bg-pawPinkDark text-white py-4 rounded-2xl font-black uppercase text-xs tracking-widest shadow-lg transform transition-transform hover:scale-105 active:scale-95 hover:bg-red-400"
                >
                    Let's Sell! ✨
                </button>
             </div>
          </div>
       </div>
     );
  }

  // --- 6. MAIN APP ---
  // Note: SettingsProvider is now at index.tsx level
  return (
    <Layout 
      activeTab={activeTab} 
      onTabChange={setActiveTab}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { deviceService } from '../services/deviceService';
import { Device } from '../types';
import { DevicePhoneIcon, DeviceDesktopIcon, SearchIcon, ShieldIcon } from '../components/Icons';

const DeviceManagement: React.FC = () => {
  const [devices, setDevices] = useState<Device[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  // Edit State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');

  // Delete State
  const [deviceToDelete, setDeviceToDelete] = useState<Device | null>(null);

  const currentDeviceId = deviceService.getDeviceId();

  useEffect(() => {
    loadDevices();
    const interval = setInterval(loadDevices, 10000); // Poll every 10s for new devices
    return () => clearInterval(interval);
  }, []);

  const loadDevices = async () => {
    const data = await deviceService.getAllDevices();
    if (data) setDevices(data);
    setLoading(false);
  };

  const handleStatusChange = async (device: Device, newStatus: 'approved' | 'blocked') => {
    if (device.device_id === currentDeviceId && newStatus === 'blocked') {
        if(!confirm("⚠️ WARNING: You are about to block THIS device. You will lose access immediately. Are you sure?")) return;
    }

    // Optimistic Update
    setDevices(prev => prev.map(d => d.id === device.id ? { ...d, status: newStatus } : d));

    try {
        await deviceService.updateDeviceStatus(device.id, newStatus);
        loadDevices();
    } catch (error) {
        alert("Failed to update status.");
        loadDevices();
    }
  };

  const handleRename = async (id: string) => {
    if (!editName.trim()) return;
    await deviceService.renameDevice(id, editName);
    setEditingId(null);
    loadDevices();
  };

  const startEdit = (device: Device) => {
    setEditingId(device.id);
    setEditName(device.name);
  };

  const handleDeleteClick = (device: Device) => {
      if (device.device_id === currentDeviceId) {
          alert("You cannot delete the device you are currently using.");
          return;
      }
      setDeviceToDelete(device);
  };

  const confirmDelete = async () => {
      if (deviceToDelete) {
          // Optimistic update
          setDevices(prev => prev.filter(d => d.id !== deviceToDelete.id));
          setDeviceToDelete(null);

          try {
            await deviceService.deleteDevice(deviceToDelete.id);
          } catch (e) {
            loadDevices(); // Revert on error
          }
      }
  };

  const filtered = devices.filter(d => 
    d.name?.toLowerCase().includes(search.toLowerCase()) || 
    d.ip_address?.includes(search) || 
    d.location?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6 pb-32 px-1 animate-fadeIn">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 px-2">
        <div>
           <h1 className="text-3xl font-black text-gray-800 dark:text-white tracking-tight flex items-center gap-3">
             <ShieldIcon className="w-8 h-8 text-pawPinkDark" />
             Device Security
           </h1>
           <p className="text-gray-500 dark:text-gray-400 font-bold text-sm">Approve, block, or delete devices accessing your system.</p>
        </div>

        <div className="relative w-full md:w-64">
           <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
           <input 
             type="text" 
             placeholder="Search devices..." 
             value={search}
             onChange={(e) => setSearch(e.target.value)}
             className="w-full bg-white dark:bg-gray-800 pl-10 pr-4 py-3 rounded-2xl font-bold text-sm text-gray-800 dark:text-white outline-none focus:ring-2 focus:ring-pawPink shadow-sm border-2 border-transparent focus:border-pawPink transition-all"
           />
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4 px-2">
        {loading ? (
           <p className="text-center text-gray-400 font-bold py-10">Loading devices...</p>
        ) : filtered.length === 0 ? (
           <div className="text-center py-20 opacity-50">
              <p className="text-4xl mb-2">📱</p>
              <p className="font-bold text-gray-400 text-sm uppercase tracking-widest">No devices found</p>
           </div>
        ) : filtered.map(device => {
            const isCurrent = device.device_id === currentDeviceId;

            return (
              <div key={device.id} className={`bg-white dark:bg-gray-800 rounded-[2rem] p-6 border-2 shadow-sm transition-all ${device.status === 'blocked' ? 'opacity-70 border-gray-200 dark:border-gray-700' : device.status === 'pending' ? 'border-orange-200 dark:border-orange-800 bg-orange-50 dark:bg-orange-900/10' : 'border-pawPink/30 dark:border-gray-700'}`}>
                 <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
                    <div className="flex items-center gap-4 w-full md:w-auto">
                       <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-2xl shrink-0 ${device.type === 'Mobile' ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-500' : 'bg-purple-50 dark:bg-purple-900/30 text-purple-500'}`}>
                          {device.type === 'Mobile' ? <DevicePhoneIcon /> : <DeviceDesktopIcon />}
                       </div>

                       <div className="flex-1 min-w-0">
                          {editingId === device.id ? (
                             <div className="flex flex-col sm:flex-row gap-2 mb-1">
                                <input 
                                  value={editName} 
                                  onChange={(e) => setEditName(e.target.value)} 
                                  className="bg-gray-100 dark:bg-gray-700 px-4 py-2 rounded-xl font-black text-gray-800 dark:text-white outline-none border-2 border-pawPink w-full sm:w-64 text-sm"
                                  autoFocus
                                  placeholder="Enter device name..."
                                />
                                <div className="flex gap-2">
                                  <button onClick={() => handleRename(device.id)} className="text-[10px] bg-pawPinkDark text-white px-4 py-2 rounded-xl font-bold uppercase shadow-md hover:bg-red-400 transition-colors">Save</button>
                                  <button onClick={() => setEditingId(null)} className="text-[10px] bg-gray-200 dark:bg-gray-700 text-gray-500 px-4 py-2 rounded-xl font-bold uppercase hover:bg-gray-300 transition-colors">Cancel</button>
                                </div>
                             </div>
                          ) : (
                             <div className="flex items-center gap-2 mb-1 flex-wrap">
                                <h3 className="text-lg font-black text-gray-800 dark:text-white leading-none truncate max-w-[200px]">{device.name}</h3>

                                {isCurrent && <span className="bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300 text-[9px] font-black px-2 py-0.5 rounded uppercase">This Device</span>}
                                <span className={`text-[9px] font-black px-2 py-0.5 rounded uppercase ${device.status === 'approved' ? 'bg-green-100 text-green-600' : device.status === 'blocked' ? 'bg-red-100 text-red-600' : 'bg-orange-100 text-orange-600'}`}>
                                   {device.status}
                                </span>
                             </div>
                          )}

                          <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs font-bold text-gray-400 dark:text-gray-500 mt-1">
                             <span className="flex items-center gap-1">🌐 {device.ip_address}</span>
                             <span className="flex items-center gap-1">📍 {device.location}</span>
                             <span className="flex items-center gap-1">💻 {device.os} • {device.browser}</span>
                          </div>
                          <p className="text-[10px] text-gray-300 dark:text-gray-600 mt-2 uppercase font-bold tracking-wider">
                              Last Active: {new Date(device.last_active).toLocaleString()}
                          </p>
                       </div>
                    </div>

                    <div className="flex flex-wrap items-center gap-3 w-full lg:w-auto mt-2 lg:mt-0 justify-end">
                       {/* PENDING ACTIONS */}
                       {device.status === 'pending' && (
                          <div className="flex gap-2 w-full lg:w-auto">
                             <button onClick={() => handleDeleteClick(device)} className="w-10 h-10 flex items-center justify-center bg-gray-100 dark:bg-gray-700 text-gray-400 hover:bg-red-100 hover:text-red-500 rounded-2xl transition-all">🗑️</button>
                             <button onClick={() => handleStatusChange(device, 'blocked')} className="flex-1 lg:flex-none px-6 py-3 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-300 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-red-100 transition-colors">Block</button>
                             <button onClick={() => handleStatusChange(device, 'approved')} className="flex-1 lg:flex-none px-6 py-3 bg-green-500 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-lg hover:bg-green-600 transition-colors animate-pulse">Approve</button>
                          </div>
                       )}

                       {/* APPROVED ACTIONS */}
                       {device.status === 'approved' && (
                          <div className="flex gap-2 w-full lg:w-auto">
                             <button onClick={() => startEdit(device)} className="w-10 h-10 flex items-center justify-center bg-pawSoftBlue dark:bg-blue-900/30 text-blue-600 rounded-2xl hover:bg-blue-100 transition-all shadow-sm" title="Edit Name">✏️</button>

                             <button onClick={() => handleStatusChange(device, 'blocked')} className="flex-1 lg:flex-none px-5 py-3 bg-gray-100 dark:bg-gray-700 text-gray-500 dark:text-gray-400 hover:bg-red-100 hover:text-red-500 dark:hover:bg-red-900/30 dark:hover:text-red-300 rounded-2xl font-black uppercase text-[10px] tracking-widest transition-colors">
                                Block
                             </button>

                             {!isCurrent && (
                                <button onClick={() => handleDeleteClick(device)} className="w-10 h-10 flex items-center justify-center bg-gray-100 dark:bg-gray-700 text-gray-400 hover:bg-red-100 hover:text-red-500 rounded-2xl transition-all" title="Delete Device">🗑️</button>
                             )}
                          </div>
                       )}

                       {/* BLOCKED ACTIONS */}
                       {device.status === 'blocked' && (
                          <div className="flex gap-2 w-full lg:w-auto">
                             {!isCurrent && (
                                <button onClick={() => handleDeleteClick(device)} className="w-10 h-10 flex items-center justify-center bg-gray-100 dark:bg-gray-700 text-gray-400 hover:bg-red-100 hover:text-red-500 rounded-2xl transition-all">🗑️</button>
                             )}
                             <button onClick={() => handleStatusChange(device, 'approved')} className="flex-1 lg:flex-none px-6 py-3 bg-white border-2 border-green-100 text-green-600 dark:bg-gray-700 dark:border-green-900 dark:text-green-400 hover:bg-green-50 hover:border-green-200 rounded-2xl font-black uppercase text-[10px] tracking-widest transition-colors shadow-sm">
                                Unblock
                             </button>
                          </div>
                       )}
                    </div>
                 </div>
              </div>
            );
        })}
      </div>

      {deviceToDelete && (
          <DeleteConfirmationModal 
             deviceName={deviceToDelete.name} 
             onClose={() => setDeviceToDelete(null)} 
             onConfirm={confirmDelete} 
          />
      )}
    </div>
  );
};

const DeleteConfirmationModal: React.FC<{ deviceName: string; onClose: () => void; onConfirm: () => void }> = ({ deviceName, onClose, onConfirm }) => {
    return createPortal(
      <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/70 backdrop-blur-md animate-fadeIn">
        <div className="bg-white dark:bg-gray-800 w-full max-w-sm rounded-[3.5rem] p-10 text-center animate-scaleUp shadow-2xl border-4 border-red-500">
           <div className="bg-red-100 dark:bg-red-900/30 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-6"><span className="text-5xl">🗑️</span></div>
           <h3 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tight mb-2">
              Remove Device?
           </h3>
           <p className="text-gray-500 dark:text-gray-400 font-bold text-sm mb-8 leading-relaxed">
              Are you sure you want to permanently delete <span className="text-red-600 dark:text-red-400">"{deviceName}"</span>? They will need to request access again.
