               <div>
                  <div className="flex items-center gap-2 mb-1">
                    <div className="w-8 h-8 rounded-full bg-pawSoftBlue dark:bg-blue-900/30 text-blue-600 dark:text-blue-300 flex items-center justify-center font-black text-xs">
