                        <p className="text-lg font-black text-purple-950 dark:text-purple-100">₱{sessionTotal.toLocaleString()}</p>
                     </div>
                  </div>
               </button>
             );
           })}
        </div>
      </div>
    );
  }

  // --- VIEW: ORDER DETAILS (Inside a Session) ---
  return (
