                        <button onClick={() => setCart(prev => prev.filter(i => i.id !== item.id))} className="w-8 h-8 flex items-center justify-center bg-red-50 dark:bg-red-900/30 text-red-600 dark:text-red-300 rounded-full hover:bg-red-600 hover:text-white transition-all font-black text-lg shadow-sm">×</button>
